              "fontWeight": "400"
            }
          ]
        },
        {
          "fontFamily": "'Roboto', 'Helvetica Neue', Arial, sans-serif",
          "name": "Roboto",
          "slug": "roboto",
          "fontFace": [
            {
              "fontFamily": "Roboto",
              "fontStyle": "normal",
              "fontWeight": "400"
            },
            {
              "fontFamily": "Roboto",
              "fontStyle": "normal",
              "fontWeight": "700"
            }
          ]
        }
      ],
      "fontSizes": [
        { "name": "Small", "slug": "small", "size": "0.875rem" },
        { "name": "Medium", "slug": "medium", "size": "1rem" },
