    $out = array();
    $out['breadcrumbs'] = isset($input['breadcrumbs']) && $input['breadcrumbs'] ? '1' : '0';
    $out['logo_align'] = in_array($input['logo_align'], array('left','center','right')) ? $input['logo_align'] : 'left';
    $out['logo_width'] = intval($input['logo_width']) > 0 ? intval($input['logo_width']) : 160;
    $allowed_fonts = array('open-sans','playfair-display','roboto','montserrat','lato','trebuchet-ms');
    $out['body_font'] = in_array($input['body_font'], $allowed_fonts) ? $input['body_font'] : 'open-sans';
    $out['heading_font'] = in_array($input['heading_font'], $allowed_fonts) ? $input['heading_font'] : 'playfair-display';
    return $out;
}

