function abundantthought_get_google_font_url() {
    $opts = abundantthought_get_options();

    $font_pairs = array(
        'open-sans' => 'Open+Sans:300,300i,400,400i,600,600i,700,700i,800,800i',
        'playfair-display' => 'Playfair+Display:400,400i,500,500i,600,600i,700,700i,800,800i,900,900i',
        'roboto' => 'Roboto:100,100i,300,300i,400,400i,500,500i,700,700i,900,900i',
        'montserrat' => 'Montserrat:100,100i,200,200i,300,300i,400,400i,500,500i,600,600i,700,700i,800,800i,900,900i',
        'lato' => 'Lato:100,100i,300,300i,400,400i,700,700i,900,900i',
        'trebuchet-ms' => '' // System font, no need to load
    );

    $fonts_to_load = array();

    // Add body font if it's a Google Font
    $body_font = $opts['body_font'];
    if (isset($font_pairs[$body_font]) && !empty($font_pairs[$body_font])) {
        $fonts_to_load[] = $font_pairs[$body_font];
    }

    // Add heading font if it's different and a Google Font
    $heading_font = $opts['heading_font'];
    if ($heading_font !== $body_font && isset($font_pairs[$heading_font]) && !empty($font_pairs[$heading_font])) {
        $fonts_to_load[] = $font_pairs[$heading_font];
    }

    if (!empty($fonts_to_load)) {
        return 'https://fonts.googleapis.com/css?family=' . implode('|', $fonts_to_load) . '&display=swap';
    }

    return '';
}

