        $opts = abundantthought_get_options();
        $global = $opts['breadcrumbs'] === '1';

        if (! $post_id) $post_id = get_the_ID();
        if (! $post_id) return (bool) $global;

        $override = get_post_meta($post_id, '_abundant_breadcrumbs_override', true);
        if ($override === 'show') return true;
        if ($override === 'hide') return false;
        return (bool) $global;
