    private function get_google_fonts_url() {
        $font_map = array(
            'open-sans' => 'Open+Sans:300,400,600,700',
            'playfair-display' => 'Playfair+Display:400,700,900',
            'roboto' => 'Roboto:300,400,500,700',
            'montserrat' => 'Montserrat:300,400,600,700',
            'lato' => 'Lato:300,400,700'
        );

        $fonts = array();
        $body_font = $this->settings['typography']['bodyFont'];
        $heading_font = $this->settings['typography']['headingFont'];

        if ($body_font !== 'system' && isset($font_map[$body_font])) {
            $fonts[] = $font_map[$body_font];
        }

        if ($heading_font !== 'system' && $heading_font !== $body_font && isset($font_map[$heading_font])) {
            $fonts[] = $font_map[$heading_font];
        }

        if (!empty($fonts)) {
            return 'https://fonts.googleapis.com/css?family=' . implode('|', $fonts) . '&display=swap';
        }

        return '';
    }

