<?php

class AT_CSS_Generator {

    public static function init() {
        add_action('wp_head', array(__CLASS__, 'output_css'));
    }

    public static function generate_css($settings) {
        $css = "
        :root {
            --at-primary: {$settings['colors']['primary']};
            --at-secondary: {$settings['colors']['secondary']};
            --at-accent: {$settings['colors']['accent']};
            --at-text: {$settings['colors']['text']};
            --at-bg: {$settings['colors']['background']};
            --at-base-size: {$settings['typography']['baseSize']}px;
        }

        body {
            font-size: var(--at-base-size);
            color: var(--at-text);
            background: var(--at-bg);
            font-family: " . self::get_font_family($settings['typography']['bodyFont']) . ";
        }

        h1, h2, h3, h4, h5, h6 {
            font-family: " . self::get_font_family($settings['typography']['headingFont']) . ";
            color: var(--at-primary);
        }

        .site-container {
            max-width: {$settings['layout']['siteWidth']}px;
        }

        .site-content {
            max-width: {$settings['layout']['contentWidth']}px;
        }

        .site-header {
            " . self::get_header_styles($settings['header']) . "
        }

        .custom-logo {
            max-width: {$settings['header']['logoWidth']}px;
        }
        ";

        return self::minify_css($css);
    }

    private static function get_font_family($font) {
        $fonts = array(
            'system' => 'system-ui, -apple-system, sans-serif',
            'open-sans' => '"Open Sans", sans-serif',
            'playfair-display' => '"Playfair Display", serif',
            'roboto' => 'Roboto, sans-serif',
            'montserrat' => 'Montserrat, sans-serif',
            'lato' => 'Lato, sans-serif'
        );

        return isset($fonts[$font]) ? $fonts[$font] : $fonts['system'];
    }

    private static function get_header_styles($header_settings) {
        $styles = array();

        if ($header_settings['sticky']) {
            $styles[] = 'position: sticky; top: 0; z-index: 1000;';
        }

        return implode(' ', $styles);
    }

    private static function minify_css($css) {
        $css = preg_replace('/\s+/', ' ', $css);
        $css = preg_replace('/\/\*.*?\*\//', '', $css);
        $css = trim($css);
        return $css;
    }

    public static function output_css() {
        $settings = get_option('at_builder_settings', array());
        if (!empty($settings)) {
            echo '<style id="at-dynamic-styles">' . self::generate_css($settings) . '</style>';
        }
    }
}
