<?php

class AT_Version_Control {

    public static function init() {
        add_action('wp_ajax_at_builder_save_revision', array(__CLASS__, 'ajax_save_revision'));
        add_action('wp_ajax_at_builder_restore_revision', array(__CLASS__, 'ajax_restore_revision'));
    }

    public static function save_revision($settings, $comment = '', $author_id = null) {
        if (!$author_id) {
            $author_id = get_current_user_id();
        }

        $revisions = get_option('at_builder_revisions', array());
        $revision_id = uniqid('rev_');

        $revisions[$revision_id] = array(
            'id' => $revision_id,
            'timestamp' => time(),
            'settings' => $settings,
            'author' => get_userdata($author_id)->display_name,
            'author_id' => $author_id,
            'comment' => sanitize_text_field($comment)
        );

        // Keep only last 20 revisions
        if (count($revisions) > 20) {
            $revisions = array_slice($revisions, -20, 20, true);
        }

        update_option('at_builder_revisions', $revisions);
        return $revision_id;
    }

    public static function get_revisions() {
        $revisions = get_option('at_builder_revisions', array());
        return array_reverse($revisions); // Show newest first
    }

    public static function get_revision($revision_id) {
        $revisions = get_option('at_builder_revisions', array());
        return isset($revisions[$revision_id]) ? $revisions[$revision_id] : null;
    }

    public static function ajax_save_revision() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        $settings = $_POST['settings'];
        $comment = sanitize_text_field($_POST['comment']);

        $revision_id = self::save_revision($settings, $comment);

        wp_send_json_success(array(
            'revision_id' => $revision_id,
            'message' => 'Revision saved successfully'
        ));
    }

    public static function ajax_restore_revision() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        $revision_id = sanitize_text_field($_POST['revision_id']);
        $revision = self::get_revision($revision_id);

        if ($revision) {
            update_option('at_builder_settings', $revision['settings']);
            wp_send_json_success('Settings restored from revision');
        } else {
            wp_send_json_error('Revision not found');
        }
    }
}
