// AbundantThought Theme Builder Vue.js Application
document.addEventListener('DOMContentLoaded', function() {
    if (typeof Vue === 'undefined') {
        console.error('Vue.js is not loaded');
        return;
    }

    new Vue({
        el: '#at-theme-builder',
        data: {
            settings: atBuilderData.settings,
            revisions: atBuilderData.revisions,
            currentView: 'desktop',
            previewUrl: atBuilderData.previewUrl,
            iframeLoaded: false,
            saving: false,
            showImport: false,
            importData: '',
            revisionComment: '',
            currentRevision: null
        },
        methods: {
            saveChanges() {
                this.saving = true;

                jQuery.ajax({
                    url: atBuilderData.ajaxurl,
                    type: 'POST',
                    data: {
                        action: 'at_builder_save',
                        nonce: atBuilderData.nonce,
                        settings: this.settings
                    },
                    success: (response) => {
                        this.saving = false;
                        if (response.success) {
                            this.showNotice('Settings saved successfully!', 'success');
                            // Refresh iframe to show changes
                            document.querySelector('.at-preview-container iframe').contentWindow.location.reload();
                        } else {
                            this.showNotice('Error saving settings: ' + response.data, 'error');
                        }
                    },
                    error: () => {
                        this.saving = false;
                        this.showNotice('Error saving settings', 'error');
                    }
                });
            },

            exportSettings() {
                jQuery.ajax({
                    url: atBuilderData.ajaxurl,
                    type: 'POST',
                    data: {
                        action: 'at_builder_export',
                        nonce: atBuilderData.nonce
                    },
                    success: (response) => {
                        if (response.success) {
                            // Create download link
                            const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(response.data);
                            const downloadAnchorNode = document.createElement('a');
                            downloadAnchorNode.setAttribute("href", dataStr);
                            downloadAnchorNode.setAttribute("download", "abundantthought-settings.json");
                            document.body.appendChild(downloadAnchorNode);
                            downloadAnchorNode.click();
                            downloadAnchorNode.remove();
                            this.showNotice('Settings exported successfully!', 'success');
                        }
                    }
                });
            },

            importSettings() {
                if (!this.importData) {
                    this.showNotice('Please paste export data', 'error');
                    return;
                }

                jQuery.ajax({
                    url: atBuilderData.ajaxurl,
                    type: 'POST',
                    data: {
                        action: 'at_builder_import',
                        nonce: atBuilderData.nonce,
                        import_data: this.importData
                    },
                    success: (response) => {
                        if (response.success) {
                            this.showImport = false;
                            this.importData = '';
                            this.showNotice('Settings imported successfully!', 'success');
                            // Reload page to reflect changes
                            location.reload();
                        } else {
                            this.showNotice('Error importing settings: ' + response.data, 'error');
                        }
                    }
                });
            },

            saveRevision() {
                if (!this.revisionComment) {
                    this.showNotice('Please enter a revision comment', 'error');
                    return;
                }

                jQuery.ajax({
                    url: atBuilderData.ajaxurl,
                    type: 'POST',
                    data: {
                        action: 'at_builder_save_revision',
                        nonce: atBuilderData.nonce,
                        settings: this.settings,
                        comment: this.revisionComment
                    },
                    success: (response) => {
                        if (response.success) {
                            this.revisionComment = '';
                            this.revisions.unshift(response.data);
                            this.showNotice('Revision saved successfully!', 'success');
                        }
                    }
                });
            },

            restoreRevision(revisionId) {
                if (!confirm('Are you sure you want to restore this revision? Current changes will be lost.')) {
                    return;
                }

                jQuery.ajax({
                    url: atBuilderData.ajaxurl,
                    type: 'POST',
                    data: {
                        action: 'at_builder_restore_revision',
                        nonce: atBuilderData.nonce,
                        revision_id: revisionId
                    },
                    success: (response) => {
                        if (response.success) {
                            this.showNotice('Revision restored successfully!', 'success');
                            // Reload page to reflect changes
                            location.reload();
                        }
                    }
                });
            },

            formatDate(timestamp) {
                return new Date(timestamp * 1000).toLocaleString();
            },

            showNotice(message, type = 'info') {
                // Create notice element
                const notice = document.createElement('div');
                notice.className = `notice notice-${type} is-dismissible`;
                notice.innerHTML = `<p>${message}</p>`;

                // Add to page
                const header = document.querySelector('.at-builder-header');
                header.parentNode.insertBefore(notice, header.nextSibling);

                // Auto-remove after 5 seconds
                setTimeout(() => {
                    if (notice.parentNode) {
                        notice.parentNode.removeChild(notice);
                    }
                }, 5000);
            }
        },

        watch: {
            settings: {
                handler: function(newSettings) {
                    // Debounced auto-save could be implemented here
                },
                deep: true
            }
        }
    });
});
