// Live preview functionality
jQuery(document).ready(function($) {
    // Listen for storage events from parent window (builder)
    window.addEventListener('storage', function(e) {
        if (e.key === 'at_builder_settings') {
            const settings = JSON.parse(e.newValue);
            applySettings(settings);
        }
    });

    // Also listen for message events (cross-tab communication)
    window.addEventListener('message', function(e) {
        if (e.data && e.data.type === 'at_builder_update') {
            applySettings(e.data.settings);
        }
    });

    function applySettings(settings) {
        // Update CSS variables
        const root = document.documentElement;
        root.style.setProperty('--at-primary', settings.colors.primary);
        root.style.setProperty('--at-secondary', settings.colors.secondary);
        root.style.setProperty('--at-accent', settings.colors.accent);
        root.style.setProperty('--at-text', settings.colors.text);
        root.style.setProperty('--at-bg', settings.colors.background);
        root.style.setProperty('--at-base-size', settings.typography.baseSize + 'px');

        // Update container widths
        $('.site-container').css('max-width', settings.layout.siteWidth + 'px');
        $('.site-content').css('max-width', settings.layout.contentWidth + 'px');

        // Update header styles
        if (settings.header.sticky) {
            $('.site-header').addClass('sticky-header');
        } else {
            $('.site-header').removeClass('sticky-header');
        }

        // Update logo size
        $('.custom-logo').css('max-width', settings.header.logoWidth + 'px');
    }

    // Notify parent window that preview is ready
    if (window.parent !== window) {
        window.parent.postMessage({ type: 'at_preview_ready' }, '*');
    }
});
