// Real-time preview functionality
methods: {
    updatePreview() {
        // Debounced preview updates
        clearTimeout(this.previewTimeout);
        this.previewTimeout = setTimeout(() => {
            this.sendToPreview(this.settings);
        }, 300);
    },

    sendToPreview(settings) {
        // Send to iframe
        const iframe = document.querySelector('.at-preview-container iframe');
        if (iframe && iframe.contentWindow) {
            iframe.contentWindow.postMessage({
                type: 'at_builder_update',
                settings: settings
            }, '*');
        }

        // Also store in localStorage for cross-tab communication
        localStorage.setItem('at_builder_settings', JSON.stringify(settings));
    },

    applyPreset(preset) {
        this.settings.colors = { ...this.settings.colors, ...preset.colors };
        this.updatePreview();
    }
},

watch: {
    settings: {
        handler: function(newSettings) {
            this.updatePreview();
        },
        deep: true
    }
},

