## 6. Enhanced Live Preview JS (`assets/js/live-preview.js`)

```javascript
// Enhanced real-time preview
jQuery(document).ready(function($) {
    function applySettings(settings) {
        // Update CSS variables in real-time
        const root = document.documentElement;

        // Colors
        Object.keys(settings.colors).forEach(key => {
            root.style.setProperty('--at-' + key, settings.colors[key]);
        });

        // Typography
        root.style.setProperty('--at-base-size', settings.typography.baseSize + 'px');
        root.style.setProperty('--at-body-font', getFontFamily(settings.typography.bodyFont));
        root.style.setProperty('--at-heading-font', getFontFamily(settings.typography.headingFont));

        // Font sizes
        ['h1', 'h2', 'h3', 'h4', 'h5', 'h6'].forEach(heading => {
            root.style.setProperty('--at-' + heading + '-size', settings.typography[heading + 'Size'] + 'px');
        });

        // Layout
        $('.site-container').css('max-width', settings.layout.siteWidth + 'px');
        $('.site-content').css('max-width', settings.layout.contentWidth + 'px');

        // Update menu styles
        $('.main-navigation').css({
            'font-size': settings.menus.header.fontSize + 'px',
            'font-weight': settings.menus.header.fontWeight
        });

        // Show/hide elements based on settings
        settings.header.showSearch ? $('.header-search').show() : $('.header-search').hide();
    }

    function getFontFamily(fontKey) {
        const fontMap = {
            'open-sans': '"Open Sans", sans-serif',
            'playfair-display': '"Playfair Display", serif',
            // ... other fonts
        };
        return fontMap[fontKey] || 'system-ui, sans-serif';
    }

    // Listen for real-time updates
    window.addEventListener('message', function(e) {
        if (e.data && e.data.type === 'at_builder_update') {
            applySettings(e.data.settings);
        }
    });

    // Apply initial settings
    if (typeof atBuilderSettings !== 'undefined') {
        applySettings(atBuilderSettings);
    }
});
