```php
<?php

class AT_Theme_Exporter {

    public static function export_theme($theme_name) {
        $settings = get_option('at_builder_settings', array());
        $export_data = array(
            'theme' => array(
                'name' => $theme_name,
                'version' => '1.0.0',
                'description' => 'Theme exported from AbundantThought Builder',
                'settings' => $settings
            ),
            'templates' => self::export_templates(),
            'styles' => AT_CSS_Generator::generate_css($settings)
        );

        return self::create_theme_package($export_data);
    }

    private static function create_theme_package($data) {
        $theme_dir = WP_CONTENT_DIR . '/themes/' . sanitize_title($data['theme']['name']);

        // Create theme directory
        wp_mkdir_p($theme_dir);

        // Create style.css
        $style_css = self::generate_style_css($data['theme']);
        file_put_contents($theme_dir . '/style.css', $style_css);

        // Create functions.php with settings
        $functions_php = self::generate_functions_php($data);
        file_put_contents($theme_dir . '/functions.php', $functions_php);

        return $theme_dir;
    }
}
```

