## 10. Enhanced JavaScript with New Features

### Animation Builder JS (`assets/js/animation-builder.js`):
```javascript
class ATAnimationBuilder {
    constructor() {
        this.presets = this.getAnimationPresets();
    }

    getAnimationPresets() {
        return {
            'fadeIn': {
                name: 'Fade In',
                keyframes: `@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }`,
                duration: 0.6
            },
            'slideUp': {
                name: 'Slide Up', 
                keyframes: `@keyframes slideUp { from { transform: translateY(30px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }`,
                duration: 0.8
            }
        };
    }

    applyAnimation(element, animationName) {
        const preset = this.presets[animationName];
        if (preset) {
            element.style.animation = `${animationName} ${preset.duration}s ease-out`;
        }
    }
}
```

### SEO Analyzer JS (`assets/js/seo-analyzer.js`):
```javascript
class ATSEOAnalyzer {
    async analyzePage() {
        const analysis = {
            score: 0,
            recommendations: [],
            issues: []
        };

        // Check heading structure
        analysis.recommendations.push(...this.checkHeadingStructure());

        // Check image optimization
        analysis.recommendations.push(...this.checkImages());

        // Calculate score
        analysis.score = this.calculateScore(analysis);

        return analysis;
    }

    checkHeadingStructure() {
        const recommendations = [];
        const headings = document.querySelectorAll('h1, h2, h3, h4, h5, h6');

        if (headings.length === 0) {
            recommendations.push({
                id: 'no-headings',
                message: 'Add heading tags to improve SEO',
                priority: 'high'
            });
        }

        return recommendations;
    }
}
```

