            ],

            headingSizes: ['h1', 'h2', 'h3', 'h4', 'h5', 'h6'],

            // SEO Data
            seoScore: 85,
            seoRecommendations: [
                { id: 1, message: 'Optimize images for faster loading', fixed: false },
                { id: 2, message: 'Add meta description to pages', fixed: true },
                { id: 3, message: 'Improve heading structure', fixed: false },
                { id: 4, message: 'Enable lazy loading for images', fixed: true }
            ],

            // Widget Areas
            newWidgetArea: {
                name: '',
                description: ''
            },
            widgetAreas: [
                { id: 'sidebar-1', name: 'Main Sidebar', description: 'Primary sidebar area' },
                { id: 'footer-1', name: 'Footer Widgets', description: 'Footer widget area' }
            ],

            // Templates
            templates: [
                {
                    id: 'header-modern',
                    name: 'Modern Header',
                    description: 'Clean header with centered navigation',
                    type: 'header'
                },
                {
                    id: 'header-minimal',
                    name: 'Minimal Header',
