                },
                {
                    id: 'footer-simple',
                    name: 'Simple Footer',
                    description: 'Clean footer with copyright',
                    type: 'footer'
                }
            ]
        },
        computed: {
            seoScoreLevel() {
                if (this.seoScore >= 80) return 'good';
                if (this.seoScore >= 60) return 'average';
                return 'poor';
            }
        },
        methods: {
