    public static function get_google_fonts_url($font_families = array()) {
        $settings = get_option('at_builder_settings', array());

        // If no specific fonts provided, use settings
        if (empty($font_families)) {
            $body_font = isset($settings['typography']['bodyFont']) ? $settings['typography']['bodyFont'] : 'open-sans';
            $heading_font = isset($settings['typography']['headingFont']) ? $settings['typography']['headingFont'] : 'playfair-display';
            $menu_font = isset($settings['typography']['menuFont']) ? $settings['typography']['menuFont'] : 'open-sans';

            $font_families = array_unique(array($body_font, $heading_font, $menu_font));
        }

        $fonts = self::get_available_fonts();
        $google_fonts = array();

        foreach ($font_families as $font_key) {
            if (isset($fonts[$font_key]) && $fonts[$font_key]['google']) {
                $font = $fonts[$font_key];
                $weights = implode(',', $font['weights']);
                $google_fonts[] = str_replace(' ', '+', $font['name']) . ':' . $weights;
            }
        }

        if (!empty($google_fonts)) {
            $font_url = add_query_arg(array(
                'family' => implode('|', $google_fonts),
                'display' => 'swap'
            ), 'https://fonts.googleapis.com/css');

            return $font_url;
        }

        return '';
    }

