    public function enqueue_admin_assets($hook) {
        if (strpos($hook, 'abundantthought-builder') === false) return;

        // Enqueue Vue.js from CDN if not already loaded
        if (!wp_script_is('vue', 'registered')) {
            wp_register_script('vue', 'https://cdn.jsdelivr.net/npm/vue@2.6.14/dist/vue.js', array(), '2.6.14', true);
        }

        wp_enqueue_script('vue');
        wp_enqueue_script('at-builder', AT_BUILDER_ASSETS_URL . 'js/builder.js', array('vue', 'jquery'), AT_BUILDER_VERSION, true);
        wp_enqueue_style('at-builder', AT_BUILDER_ASSETS_URL . 'css/builder.css', array(), AT_BUILDER_VERSION);

        // Localize script data
        wp_localize_script('at-builder', 'atBuilderData', array(
            'ajaxurl' => admin_url('admin-ajax.php'),
            'nonce' => wp_create_nonce('at_builder_nonce'),
            'settings' => $this->settings,
            'previewUrl' => home_url('/?at_builder_preview=1'),
            'revisions' => class_exists('AT_Version_Control') ? AT_Version_Control::get_revisions() : array()
        ));
    }

