    public function get_settings() {
        return $this->settings;
    }

    public function ajax_export_settings() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        $settings = $this->get_settings();
        $export_data = array(
            'version' => AT_BUILDER_VERSION,
            'export_date' => current_time('mysql'),
            'settings' => $settings
        );

        wp_send_json_success(json_encode($export_data));
    }

    public function ajax_import_settings() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        $import_data = json_decode(stripslashes($_POST['import_data']), true);

        if ($import_data && isset($import_data['settings'])) {
            $sanitized_settings = $this->sanitize_settings($import_data['settings']);
            update_option('at_builder_settings', $sanitized_settings);
            wp_send_json_success('Settings imported successfully');
        }

        wp_send_json_error('Invalid import data');
    }

    public function ajax_save_revision() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        if (!class_exists('AT_Version_Control')) {
            wp_send_json_error('Version control not available');
        }

        $settings = $_POST['settings'];
        $comment = sanitize_text_field($_POST['comment']);

        $revision_id = AT_Version_Control::save_revision($settings, $comment);

        wp_send_json_success(array(
            'revision_id' => $revision_id,
            'message' => 'Revision saved successfully'
        ));
    }

    public function ajax_restore_revision() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        if (!class_exists('AT_Version_Control')) {
            wp_send_json_error('Version control not available');
        }

        $revision_id = sanitize_text_field($_POST['revision_id']);
        $revision = AT_Version_Control::get_revision($revision_id);

        if ($revision) {
            update_option('at_builder_settings', $revision['settings']);
            wp_send_json_success('Settings restored from revision');
        } else {
            wp_send_json_error('Revision not found');
        }
    }
