<?php

class AT_CSS_Generator {

    public static function init() {
        add_action('wp_head', array(__CLASS__, 'output_css'));
    }

    public static function generate_css($settings) {
        if (empty($settings)) return '';

        $css = "
        :root {
            --at-primary: {$settings['colors']['primary']};
            --at-secondary: {$settings['colors']['secondary']};
            --at-bg: {$settings['colors']['background']};
            --at-text: {$settings['colors']['text']};
        }

        body {
            font-size: {$settings['typography']['baseSize']}px;
            color: var(--at-text);
            background: var(--at-bg);
        }

        .site-container {
            max-width: {$settings['layout']['siteWidth']}px;
            margin: 0 auto;
        }

        .sticky-header {
            position: sticky;
            top: 0;
            z-index: 1000;
        }
        ";

        return self::minify_css($css);
    }

    private static function minify_css($css) {
        $css = preg_replace('/\s+/', ' ', $css);
        $css = preg_replace('/\/\*.*?\*\//', '', $css);
        return trim($css);
    }

    public static function output_css() {
        $settings = get_option('at_builder_settings', array());
        if (!empty($settings)) {
            echo '<style id="at-dynamic-styles">' . self::generate_css($settings) . '</style>';
        }
    }
}
