    public static function save_revision($settings, $comment = '', $author_id = null) {
        if (!$author_id) {
            $author_id = get_current_user_id();
        }

        $revisions = get_option('at_builder_revisions', array());
        $revision_id = uniqid('rev_');

        $revisions[$revision_id] = array(
            'id' => $revision_id,
            'timestamp' => time(),
            'settings' => $settings,
            'author' => get_userdata($author_id)->display_name,
            'author_id' => $author_id,
            'comment' => sanitize_text_field($comment)
        );

        // Keep only last 20 revisions
        if (count($revisions) > 20) {
            $revisions = array_slice($revisions, -20, 20, true);
        }

        update_option('at_builder_revisions', $revisions);
        return $revision_id;
    }

    public static function get_revisions() {
        $revisions = get_option('at_builder_revisions', array());
        return array_reverse($revisions);
    }

    public static function get_revision($revision_id) {
        $revisions = get_option('at_builder_revisions', array());
        return isset($revisions[$revision_id]) ? $revisions[$revision_id] : null;
    }
}
