```php
<?php

class AT_Font_Manager {

    public static function init() {
        add_action('wp_enqueue_scripts', array(__CLASS__, 'enqueue_google_fonts'));
    }

    public static function enqueue_google_fonts() {
        $settings = get_option('at_builder_settings', array());
        if (empty($settings)) return;

        $font_url = self::get_google_fonts_url();
        if (!empty($font_url)) {
            wp_enqueue_style('at-google-fonts', $font_url, array(), null);
        }
    }

    public static function get_google_fonts_url() {
        $settings = get_option('at_builder_settings', array());
        if (empty($settings)) return '';

        $body_font = $settings['typography']['bodyFont'];
        $heading_font = $settings['typography']['headingFont'];

        $font_map = array(
            'open-sans' => 'Open+Sans:300,400,600,700',
            'playfair-display' => 'Playfair+Display:400,700,900',
            'roboto' => 'Roboto:300,400,500,700',
            'montserrat' => 'Montserrat:300,400,600,700',
            'lato' => 'Lato:300,400,700'
        );

        $fonts_to_load = array();

        if ($body_font !== 'system' && isset($font_map[$body_font])) {
            $fonts_to_load[] = $font_map[$body_font];
        }

        if ($heading_font !== 'system' && $heading_font !== $body_font && isset($font_map[$heading_font])) {
            $fonts_to_load[] = $font_map[$heading_font];
        }

        if (!empty($fonts_to_load)) {
            return 'https://fonts.googleapis.com/css?family=' . implode('|', $fonts_to_load) . '&display=swap';
        }

        return '';
    }
}
