                        settings: this.settings
                    },
                    success: (response) => {
                        this.saving = false;
                        if (response.success) {
                            this.showSaveMessage('Settings saved successfully!', 'success');
                            // Update preview immediately after save
                            this.updatePreview();
                        } else {
                            this.showSaveMessage('Error saving settings: ' + response.data, 'error');
                        }
                    },
                    error: (xhr, status, error) => {
                        this.saving = false;
                        this.showSaveMessage('Error saving settings: ' + error, 'error');
                        console.error('Save error:', error);
                    }
                });
            },

            showSaveMessage(message, type = 'info') {
