            restoreRevision(revisionId) {
                if (!confirm('Are you sure you want to restore this revision? Current changes will be lost.')) {
                    return;
                }

                jQuery.ajax({
                    url: atBuilderData.ajaxurl,
                    type: 'POST',
                    data: {
                        action: 'at_builder_restore_revision',
                        nonce: atBuilderData.nonce,
                        revision_id: revisionId
                    },
                    success: (response) => {
                        if (response.success) {
                            this.showSaveMessage('Revision restored successfully!', 'success');
                            location.reload();
                        }
                    }
                });
            },

            formatDate(timestamp) {
