    exit;
}

// Define plugin constants
define('AT_BUILDER_VERSION', '3.0.2');
define('AT_BUILDER_PATH', plugin_dir_path(__FILE__));
define('AT_BUILDER_URL', plugin_dir_url(__FILE__));
define('AT_BUILDER_ASSETS_URL', AT_BUILDER_URL . 'assets/');

final class AbundantThought_Theme_Builder {

    private static $instance = null;
    private $settings = array();
    private $is_preview = false;
    private $components_loaded = false;

    public static function get_instance() {
        if (null === self::$instance) {
            self::$instance = new self();
        }
        return self::$instance;
    }

    private function __construct() {
        // Load dependencies first
        $this->load_dependencies();

        // Then initialize hooks
        $this->init_hooks();
    }

    private function load_dependencies() {
        $include_files = array(
            'class-css-generator.php',
            'class-template-manager.php',
            'class-version-control.php',
            'class-export-import.php',
            'class-layout-builder.php',
            'class-font-manager.php',
            'class-template-library.php',
            'class-animation-builder.php',
            'class-widget-manager.php',
            'class-seo-optimizer.php',
            'class-performance-monitor.php',
            'class-ab-testing.php',
            'class-theme-exporter.php'
        );

        foreach ($include_files as $file) {
            $file_path = AT_BUILDER_PATH . 'includes/' . $file;
            if (file_exists($file_path)) {
                require_once $file_path;
            } else {
                error_log('AbundantThought Builder: Missing file - ' . $file);
            }
        }

        $this->components_loaded = true;
    }

    private function init_hooks() {
        add_action('init', array($this, 'init'));
        add_action('admin_menu', array($this, 'add_admin_menus'));
        add_action('wp_ajax_at_builder_save', array($this, 'ajax_save_settings'));
        add_action('wp_ajax_at_builder_export', array($this, 'ajax_export_settings'));
        add_action('wp_ajax_at_builder_import', array($this, 'ajax_import_settings'));
        add_action('wp_ajax_at_builder_save_revision', array($this, 'ajax_save_revision'));
        add_action('wp_ajax_at_builder_restore_revision', array($this, 'ajax_restore_revision'));

        // Frontend hooks
        add_action('wp_enqueue_scripts', array($this, 'enqueue_frontend_assets'));
        add_action('wp_head', array($this, 'output_dynamic_css'));
        add_action('template_redirect', array($this, 'handle_live_preview'));

        // Admin hooks
        add_action('admin_enqueue_scripts', array($this, 'enqueue_admin_assets'));

        // Only replace block editor if components loaded successfully
        if ($this->components_loaded) {
            add_filter('use_block_editor_for_post_type', array($this, 'disable_block_editor'), 10, 2);
            add_action('edit_form_after_title', array($this, 'render_visual_editor'));
        }
    }

    public function init() {
        // Load settings
        $this->settings = get_option('at_builder_settings', $this->get_default_settings());
        $this->is_preview = isset($_GET['at_builder_preview']) && current_user_can('edit_theme_options');

        // Initialize components only if they loaded successfully
        if ($this->components_loaded) {
            $this->initialize_components();
        }
    }

    private function initialize_components() {
        // Safely initialize each component with error handling
        try {
            if (class_exists('AT_CSS_Generator')) {
                AT_CSS_Generator::init();
            }
            if (class_exists('AT_Template_Manager')) {
                AT_Template_Manager::init();
            }
            if (class_exists('AT_Version_Control')) {
                AT_Version_Control::init();
            }
            // Note: Other components are initialized on-demand
        } catch (Exception $e) {
            error_log('AbundantThought Builder Component Error: ' . $e->getMessage());
        }
    }

    public function add_admin_menus() {
        add_theme_page(
            __('Theme Builder', 'abundantthought-builder'),
