    // AJAX handlers
    public function ajax_save_settings() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        $settings = $_POST['settings'];
        $sanitized_settings = $this->sanitize_settings($settings);

        update_option('at_builder_settings', $sanitized_settings);

        wp_send_json_success('Settings saved');
    }

    private function sanitize_settings($settings) {
        return array(
            'layout' => array(
                'siteWidth' => absint($settings['layout']['siteWidth']),
                'contentWidth' => absint($settings['layout']['contentWidth'])
            ),
            'colors' => array(
                'primary' => sanitize_hex_color($settings['colors']['primary']),
                'secondary' => sanitize_hex_color($settings['colors']['secondary']),
                'background' => sanitize_hex_color($settings['colors']['background']),
                'text' => sanitize_hex_color($settings['colors']['text'])
            ),
            'typography' => array(
                'baseSize' => absint($settings['typography']['baseSize']),
                'bodyFont' => sanitize_text_field($settings['typography']['bodyFont']),
                'headingFont' => sanitize_text_field($settings['typography']['headingFont'])
            ),
            'header' => array(
                'layout' => sanitize_text_field($settings['header']['layout']),
                'sticky' => (bool)$settings['header']['sticky'],
                'logoWidth' => absint($settings['header']['logoWidth'])
            ),
            'footer' => array(
                'columns' => absint($settings['footer']['columns']),
                'widgets' => (bool)$settings['footer']['widgets']
            )
        );
    }

    private function get_default_settings() {
        return array(
            'layout' => array(
                'siteWidth' => 1200,
                'contentWidth' => 800
            ),
            'colors' => array(
                'primary' => '#2c5530',
                'secondary' => '#4a7c59',
                'background' => '#ffffff',
                'text' => '#333333'
            ),
            'typography' => array(
                'baseSize' => 16,
                'bodyFont' => 'open-sans',
                'headingFont' => 'playfair-display'
            ),
            'header' => array(
                'layout' => 'standard',
                'sticky' => true,
                'logoWidth' => 200
            ),
            'footer' => array(
                'columns' => 3,
                'widgets' => true
            )
        );
    }

    public function get_settings() {
        return $this->settings;
    }

    public function ajax_export_settings() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        $settings = $this->get_settings();
        $export_data = array(
            'version' => AT_BUILDER_VERSION,
            'export_date' => current_time('mysql'),
            'settings' => $settings
        );

        wp_send_json_success(json_encode($export_data));
    }

    public function ajax_import_settings() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        $import_data = json_decode(stripslashes($_POST['import_data']), true);

        if ($import_data && isset($import_data['settings'])) {
            $sanitized_settings = $this->sanitize_settings($import_data['settings']);
            update_option('at_builder_settings', $sanitized_settings);
            wp_send_json_success('Settings imported successfully');
        }

        wp_send_json_error('Invalid import data');
    }

    public function ajax_save_revision() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        if (!class_exists('AT_Version_Control')) {
            wp_send_json_error('Version control not available');
        }

        $settings = $_POST['settings'];
        $comment = sanitize_text_field($_POST['comment']);

        $revision_id = AT_Version_Control::save_revision($settings, $comment);

        wp_send_json_success(array(
            'revision_id' => $revision_id,
            'message' => 'Revision saved successfully'
        ));
    }

    public function ajax_restore_revision() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        if (!class_exists('AT_Version_Control')) {
            wp_send_json_error('Version control not available');
        }

        $revision_id = sanitize_text_field($_POST['revision_id']);
        $revision = AT_Version_Control::get_revision($revision_id);

        if ($revision) {
            update_option('at_builder_settings', $revision['settings']);
            wp_send_json_success('Settings restored from revision');
        } else {
            wp_send_json_error('Revision not found');
        }
    }
