        ?>
        <script>
        // Listen for settings updates from builder
        window.addEventListener('message', function(e) {
            if (e.data.type === 'at_settings_update') {
                applySettings(e.data.settings);
            }
        });

        function applySettings(settings) {
            // Apply color settings
            if (settings.colors) {
                document.documentElement.style.setProperty('--at-primary', settings.colors.primary);
                document.documentElement.style.setProperty('--at-bg', settings.colors.background);
                document.documentElement.style.setProperty('--at-text', settings.colors.text);
            }

            // Apply typography
            if (settings.typography) {
                document.body.style.fontSize = settings.typography.baseSize + 'px';
            }

            // Apply header settings
            if (settings.header) {
                const header = document.querySelector('.site-header, header');
                if (header) {
                    if (settings.header.sticky) {
                        header.classList.add('sticky-header');
                    } else {
                        header.classList.remove('sticky-header');
                    }

                    const logo = header.querySelector('.custom-logo, .site-logo img');
                    if (logo) {
                        logo.style.maxWidth = settings.header.logoWidth + 'px';
