    // AJAX handler
    public function ajax_save_settings() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        $settings = $_POST['settings'];
        $sanitized_settings = $this->sanitize_settings($settings);

        update_option('at_builder_settings', $sanitized_settings);

        wp_send_json_success('Settings saved');
    }

    private function sanitize_settings($settings) {
        return array(
            'colors' => array(
                'primary' => sanitize_hex_color($settings['colors']['primary']),
                'background' => sanitize_hex_color($settings['colors']['background']),
                'text' => sanitize_hex_color($settings['colors']['text'])
            ),
            'typography' => array(
                'baseSize' => absint($settings['typography']['baseSize']),
                'bodyFont' => sanitize_text_field($settings['typography']['bodyFont'])
            ),
            'header' => array(
                'sticky' => (bool)$settings['header']['sticky'],
                'logoWidth' => absint($settings['header']['logoWidth'])
            )
        );
    }

    private function get_default_settings() {
        return array(
            'colors' => array(
                'primary' => '#2c5530',
                'background' => '#ffffff',
                'text' => '#333333'
            ),
            'typography' => array(
                'baseSize' => 16,
                'bodyFont' => 'system'
            ),
            'header' => array(
                'sticky' => true,
                'logoWidth' => 200
            )
        );
    }

    public function get_settings() {
        return $this->settings;
    }
