    /**
     * Get font family CSS value
     */
    private function get_font_family($font_key) {
        $fonts = array(
            'system' => 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
            'open-sans' => '"Open Sans", sans-serif',
            'roboto' => 'Roboto, sans-serif',
            'montserrat' => 'Montserrat, sans-serif',
            'playfair-display' => '"Playfair Display", serif',
        );
        return isset($fonts[$font_key]) ? $fonts[$font_key] : $fonts['system'];
    }

    /**
     * Enqueue Google Fonts if needed
     */
    public function enqueue_assets() {
        $font_family = get_theme_mod('at_font_family', 'system');

        if ($font_family !== 'system') {
            $font_url = $this->get_google_font_url($font_family);
            if ($font_url) {
                wp_enqueue_style('abundantthought-google-fonts', $font_url, array(), null);
            }
        }
    }

    /**
     * Get Google Fonts URL
     */
    private function get_google_font_url($font_family) {
        $font_map = array(
            'open-sans' => 'Open+Sans:300,400,600,700',
            'roboto' => 'Roboto:300,400,500,700',
            'montserrat' => 'Montserrat:300,400,600,700',
            'playfair-display' => 'Playfair+Display:400,700,900',
        );

        if (isset($font_map[$font_family])) {
            return 'https://fonts.googleapis.com/css?family=' . $font_map[$font_family] . '&display=swap';
        }

        return false;
    }

