     * Output advanced CSS
     */
    public function output_advanced_css() {
        $bg_type = get_theme_mod('at_bg_type', 'color');
        $gradient_settings = json_decode(get_theme_mod('at_gradient_settings', '{}'), true);
        $typography_settings = json_decode(get_theme_mod('at_typography_settings', '{}'), true);
        $spacing_matrix = json_decode(get_theme_mod('at_spacing_matrix', '{}'), true);
        $animation_settings = json_decode(get_theme_mod('at_animation_settings', '{}'), true);
        $shadow_settings = json_decode(get_theme_mod('at_shadow_settings', '{}'), true);
        ?>
        <style id="abundantthought-advanced-css">
            <?php $this->output_color_system(); ?>
            <?php $this->output_typography_system($typography_settings); ?>
            <?php $this->output_spacing_system($spacing_matrix); ?>
            <?php $this->output_background_system($bg_type, $gradient_settings); ?>
            <?php $this->output_animation_system($animation_settings); ?>
            <?php $this->output_shadow_system($shadow_settings); ?>
        </style>
        <?php
    }

    private function output_color_system() {
        $colors = array('primary', 'secondary', 'accent', 'success', 'warning', 'error');
        echo ":root {\n";
        foreach ($colors as $color) {
            $value = get_theme_mod("at_color_{$color}", '#2c5530');
            echo "  --at-{$color}: {$value};\n";
        }
        echo "}\n";

        // Color applications
        echo "a { color: var(--at-primary); }\n";
        echo "a:hover { color: var(--at-secondary); }\n";
        echo ".button { background: var(--at-primary); }\n";
        echo ".button:hover { background: var(--at-secondary); }\n";
    }

    private function output_typography_system($settings) {
        if (!$settings) return;

        $body_font = $this->get_font_family($settings['body_font'] ?? 'system');
        $heading_font = $this->get_font_family($settings['heading_font'] ?? 'playfair-display');

        echo "body { font-family: {$body_font}; ";
        echo "font-size: " . ($settings['base_size'] ?? '16') . "px; ";
        echo "line-height: " . ($settings['line_height'] ?? '1.6') . "; ";
        echo "letter-spacing: " . ($settings['letter_spacing'] ?? '0') . "px; ";
        echo "text-transform: " . ($settings['text_transform'] ?? 'none') . "; }\n";

        echo "h1, h2, h3, h4, h5, h6 { font-family: {$heading_font}; }\n";

        // Heading sizes
        $headings = array('h1', 'h2', 'h3', 'h4', 'h5', 'h6');
        foreach ($headings as $heading) {
            $size = get_theme_mod("at_{$heading}_size");
            if ($size) echo "{$heading} { font-size: {$size}px; }\n";
        }
    }

    private function output_spacing_system($settings) {
        if (!$settings) return;

        $sections = array('header', 'content', 'sidebar', 'footer');
        foreach ($sections as $section) {
            $padding = get_theme_mod("at_{$section}_padding");
            if ($padding) echo ".{$section} { padding: {$padding}; }\n";
        }
    }

    private function output_background_system($bg_type, $gradient_settings) {
        if ($bg_type === 'gradient' && $gradient_settings) {
            $start = $gradient_settings['start'] ?? '#2c5530';
            $end = $gradient_settings['end'] ?? '#4a7c59';
            $angle = $gradient_settings['angle'] ?? '135';
            echo "body { background: linear-gradient({$angle}deg, {$start}, {$end}); }\n";
        } elseif ($bg_type === 'color') {
            $color = get_theme_mod('at_color_primary', '#2c5530');
            echo "body { background: {$color}; }\n";
        }
    }

    private function output_animation_system($settings) {
        if (!$settings) return;

        if (($settings['page_load'] ?? 'none') !== 'none') {
            echo ".at-animate { animation-duration: 0.6s; animation-fill-mode: both; }\n";
            echo ".at-fade-in { animation-name: atFadeIn; }\n";
            echo ".at-slide-up { animation-name: atSlideUp; }\n";

            echo "@keyframes atFadeIn { from { opacity: 0; } to { opacity: 1; } }\n";
            echo "@keyframes atSlideUp { from { transform: translateY(30px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }\n";
        }
    }

    private function output_shadow_system($settings) {
        if (!$settings) return;

        if (isset($settings['button'])) echo ".button { box-shadow: {$settings['button']}; }\n";
        if (isset($settings['card'])) echo ".card, .widget { box-shadow: {$settings['card']}; }\n";
        if (isset($settings['header'])) echo ".site-header { box-shadow: {$settings['header']}; }\n";
    }

    private function get_font_family($font_key) {
        $fonts = array(
            'system' => 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
            'open-sans' => '"Open Sans", sans-serif',
            'roboto' => 'Roboto, sans-serif',
            'montserrat' => 'Montserrat, sans-serif',
            'playfair-display' => '"Playfair Display", serif',
        );
        return $fonts[$font_key] ?? $fonts['system'];
    }

    public function enqueue_assets() {
        // Enqueue Google Fonts
        $typography_settings = json_decode(get_theme_mod('at_typography_settings', '{}'), true);
        $body_font = $typography_settings['body_font'] ?? 'system';
        $heading_font = $typography_settings['heading_font'] ?? 'playfair-display';

        $font_url = $this->get_google_font_url($body_font, $heading_font);
        if ($font_url) {
            wp_enqueue_style('abundantthought-google-fonts', $font_url, array(), null);
        }

        // Enqueue animation CSS
        wp_enqueue_style('abundantthought-animations', 
            plugin_dir_url(__FILE__) . 'assets/animations.css', array(), '1.0.0');
    }

    private function get_google_font_url($body_font, $heading_font) {
        $font_map = array(
            'open-sans' => 'Open+Sans:300,400,600,700',
            'roboto' => 'Roboto:300,400,500,700',
            'montserrat' => 'Montserrat:300,400,600,700',
            'playfair-display' => 'Playfair+Display:400,700,900',
        );

        $fonts = array();
        if ($body_font !== 'system' && isset($font_map[$body_font])) {
            $fonts[] = $font_map[$body_font];
        }
        if ($heading_font !== 'system' && $heading_font !== $body_font && isset($font_map[$heading_font])) {
            $fonts[] = $font_map[$heading_font];
        }

        if (!empty($fonts)) {
            return 'https://fonts.googleapis.com/css?family=' . implode('|', $fonts) . '&display=swap';
        }

        return false;
    }

    public function live_preview_js() {
        wp_enqueue_script('abundantthought-advanced-preview', 
            plugin_dir_url(__FILE__) . 'assets/advanced-preview.js', 
            array('jquery', 'customize-preview'), '1.0.0', true);
    }
}

