                'open-sans': '"Open Sans", sans-serif',
                'roboto': 'Roboto, sans-serif',
                'montserrat': 'Montserrat, sans-serif'
            };
            return fonts[fontKey] || fonts.system;
        }
    });

    // Logo Width
    wp.customize('at_logo_width', function(value) {
        value.bind(function(to) {
            $('.custom-logo').css('max-width', to + 'px');
        });
    });

    // Sticky Header
    wp.customize('at_sticky_header', function(value) {
        value.bind(function(to) {
            var header = $('.site-header');
            var bgColor = wp.customize('at_background_color').get();

            if (to) {
                header.css({
                    'position': 'sticky',
                    'top': '0',
                    'z-index': '1000',
                    'background-color': bgColor
                });
            } else {
                header.css({
                    'position': '',
                    'top': '',
                    'z-index': '',
                    'background-color': ''
                });
            }
        });
    });

})(jQuery);
