    public function save_design() {
        check_ajax_referer('at_builder_nonce', 'nonce');

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Unauthorized');
        }

        $design = $_POST['design'];
        update_option('at_design_settings', $design);

        wp_send_json_success('Design saved successfully');
    }

    public function get_design() {
        check_ajax_referer('at_builder_nonce', 'nonce');
        wp_send_json_success(get_option('at_design_settings', array()));
    }

    public function output_design_css() {
        $design = get_option('at_design_settings');
        if (!$design) return;

        echo '<style id="at-design-output">';
        echo $this->generate_css($design);
        echo '</style>';
    }

    private function generate_css($design) {
        $css = ":root {\n";
        foreach ($design['colors'] as $key => $value) {
            $css .= "  --at-{$key}: {$value};\n";
        }
        $css .= "}\n\n";

        $css .= "body {\n";
        $css .= "  font-size: {$design['typography']['baseSize']}px;\n";
        $css .= "  font-family: " . $this->get_font_family($design['typography']['bodyFont']) . ";\n";
        $css .= "  line-height: {$design['typography']['lineHeight']};\n";
        $css .= "  color: var(--at-text);\n";
        $css .= "  background: var(--at-background);\n";
        $css .= "}\n\n";

        $css .= "h1, h2, h3, h4, h5, h6 {\n";
        $css .= "  font-family: " . $this->get_font_family($design['typography']['headingFont']) . ";\n";
        $css .= "}\n\n";

        $css .= ".site-container {\n";
        $css .= "  max-width: {$design['layout']['siteWidth']}px;\n";
        $css .= "}\n\n";

        if ($design['header']['sticky']) {
            $css .= ".site-header {\n";
            $css .= "  position: sticky;\n";
            $css .= "  top: 0;\n";
            $css .= "  z-index: 1000;\n";
            $css .= "}\n\n";
        }

        return $css;
    }

    private function get_font_family($font) {
        $fonts = array(
            'system' => 'system-ui, sans-serif',
            'open-sans' => '"Open Sans", sans-serif',
            'roboto' => 'Roboto, sans-serif',
            'montserrat' => 'Montserrat, sans-serif',
            'playfair-display' => '"Playfair Display", serif'
        );
        return $fonts[$font] ?? $fonts['system'];
    }
}

