    private function sanitize_design($design) {
        if (!is_array($design)) {
            return array();
        }

        $sanitized = array();

        // Sanitize colors
        if (isset($design['colors']) && is_array($design['colors'])) {
            foreach ($design['colors'] as $key => $color) {
                $sanitized['colors'][$key] = sanitize_hex_color($color);
            }
        }

        // Sanitize typography
        if (isset($design['typography']) && is_array($design['typography'])) {
            $sanitized['typography'] = array(
                'baseSize' => absint($design['typography']['baseSize']),
                'bodyFont' => sanitize_text_field($design['typography']['bodyFont']),
                'headingFont' => sanitize_text_field($design['typography']['headingFont']),
                'lineHeight' => floatval($design['typography']['lineHeight'])
            );
        }

        // Sanitize header settings
        if (isset($design['header']) && is_array($design['header'])) {
            $sanitized['header'] = array(
                'sticky' => !empty($design['header']['sticky']),
                'logoWidth' => absint($design['header']['logoWidth']),
                'height' => absint($design['header']['height']),
                'menuAlignment' => sanitize_text_field($design['header']['menuAlignment'])
            );
        }

        // Sanitize layout settings
        if (isset($design['layout']) && is_array($design['layout'])) {
            $sanitized['layout'] = array(
                'siteWidth' => absint($design['layout']['siteWidth']),
                'contentWidth' => absint($design['layout']['contentWidth'])
            );
        }

        return $sanitized;
    }

