        <script>
        // Listen for design updates from builder
        window.addEventListener('message', function(event) {
            if (event.data.type === 'at_design_update') {
                applyDesign(event.data.design);
            }
        });

        function applyDesign(design) {
            console.log('Applying design:', design);

            // Apply colors
            if (design.colors) {
                document.documentElement.style.setProperty('--at-primary', design.colors.primary);
                document.documentElement.style.setProperty('--at-secondary', design.colors.secondary);
                document.documentElement.style.setProperty('--at-background', design.colors.background);
                document.documentElement.style.setProperty('--at-text', design.colors.text);
            }

            // Apply typography
            if (design.typography) {
                document.body.style.fontSize = design.typography.baseSize + 'px';
                document.body.style.lineHeight = design.typography.lineHeight;
                document.body.style.fontFamily = getFontFamily(design.typography.bodyFont);

                // Apply heading font
                var headings = document.querySelectorAll('h1, h2, h3, h4, h5, h6');
                headings.forEach(function(heading) {
                    heading.style.fontFamily = getFontFamily(design.typography.headingFont);
                });
            }

            // Apply header settings
            if (design.header) {
                var header = document.querySelector('.site-header, header');
                if (header) {
                    // Sticky header
                    if (design.header.sticky) {
                        header.style.position = 'sticky';
                        header.style.top = '0';
                        header.style.zIndex = '1000';
                    } else {
                        header.style.position = '';
                        header.style.top = '';
                        header.style.zIndex = '';
                    }

                    // Logo width
                    var logo = header.querySelector('.custom-logo, .site-logo img, .logo img');
                    if (logo) {
                        logo.style.maxWidth = design.header.logoWidth + 'px';
                    }

                    // Header height
                    header.style.minHeight = design.header.height + 'px';

                    // Menu alignment
                    var menu = header.querySelector('.main-navigation, .nav-menu, .menu');
                    if (menu) {
                        menu.style.justifyContent = getMenuAlignment(design.header.menuAlignment);
                    }
                }
            }

            // Apply layout
            if (design.layout) {
                var containers = document.querySelectorAll('.site-container, .container, .wrap');
                containers.forEach(function(container) {
                    container.style.maxWidth = design.layout.siteWidth + 'px';
                });

                var content = document.querySelectorAll('.site-content, .entry-content, .content');
                content.forEach(function(area) {
                    area.style.maxWidth = design.layout.contentWidth + 'px';
                });
            }
        }

        function getFontFamily(fontKey) {
            var fonts = {
                'system': 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
                'open-sans': '"Open Sans", sans-serif',
                'roboto': 'Roboto, sans-serif',
                'montserrat': 'Montserrat, sans-serif',
                'playfair-display': '"Playfair Display", serif'
            };
            return fonts[fontKey] || fonts.system;
        }

        function getMenuAlignment(alignment) {
            var alignments = {
                'left': 'flex-start',
                'center': 'center',
                'right': 'flex-end'
            };
            return alignments[alignment] || 'flex-end';
        }

        // Apply initial design if available
        var initialDesign = <?php echo wp_json_encode($design); ?>;
        if (Object.keys(initialDesign).length > 0) {
