        computed: {
            previewStyle() {
                const styles = {
                    desktop: { width: '100%', height: '600px' },
                    tablet: { width: '768px', height: '600px' },
                    mobile: { width: '375px', height: '600px' }
                };
                return styles[this.deviceView] || styles.desktop;
            }
        },

        methods: {
            updatePreview() {
                if (!this.previewLoaded) return;

                console.log('Updating preview with:', this.design);

                // Send design to preview iframe
                const iframe = document.querySelector('.at-preview-frame');
                if (iframe && iframe.contentWindow) {
                    try {
                        iframe.contentWindow.postMessage({
                            type: 'at_design_update',
                            design: this.design
                        }, '*');
                    } catch (e) {
                        console.error('Error sending to preview:', e);
                    }
                }
            },

            onPreviewLoad() {
                this.previewLoaded = true;
                console.log('Preview loaded, applying design...');
                // Give the iframe a moment to fully initialize
                setTimeout(() => {
                    this.updatePreview();
                }, 500);
            },

            saveDesign() {
                this.saving = true;
                this.saveMessage = 'Saving design...';

                jQuery.ajax({
                    url: atBuilderData.ajaxurl,
                    type: 'POST',
                    data: {
                        action: 'at_save_design',
                        nonce: atBuilderData.nonce,
                        design: this.design
                    },
                    success: (response) => {
                        this.saving = false;
                        this.saveMessage = '✅ Design saved successfully!';
                        this.saveStatus = 'success';
                        setTimeout(() => { this.saveMessage = ''; }, 3000);
                    },
                    error: (xhr, status, error) => {
                        this.saving = false;
                        this.saveMessage = '❌ Error saving design: ' + error;
                        this.saveStatus = 'error';
                        console.error('Save error:', error);
                        setTimeout(() => { this.saveMessage = ''; }, 5000);
                    }
                });
            },

            applyColorPreset(preset) {
                this.design.colors = { ...preset.colors };
                this.updatePreview();
                this.showNotification(`🎨 Applied ${preset.name} color scheme`);
            },

            presetStyle(preset) {
                return {
                    background: `linear-gradient(135deg, ${preset.colors.primary} 0%, ${preset.colors.secondary} 100%)`,
                    border: `2px solid ${preset.colors.primary}`
                };
            },

            resetToDefaults() {
                if (confirm('Are you sure you want to reset all settings to defaults?')) {
                    this.design = {
                        colors: {
                            primary: '#2c5530',
                            secondary: '#4a7c59',
                            background: '#ffffff',
                            text: '#333333',
                            accent: '#d4a574'
                        },
                        typography: {
                            baseSize: 16,
                            bodyFont: 'system',
                            headingFont: 'playfair-display',
                            lineHeight: 1.6,
                            letterSpacing: 0,
                            textTransform: 'none'
                        },
                        header: {
                            sticky: true,
                            logoWidth: 200,
                            height: 80,
                            menuAlignment: 'right',
                            background: '#ffffff',
                            showSearch: true
                        },
                        layout: {
                            siteWidth: 1200,
                            contentWidth: 800,
                            sidebar: 'right',
                            containerPadding: '40px'
                        }
                    };
                    this.updatePreview();
                    this.showNotification('🔄 Reset to defaults');
                }
            },

            copyCSS() {
                const css = this.generateCSS();
                navigator.clipboard.writeText(css).then(() => {
                    this.showNotification('📋 CSS copied to clipboard!');
                }).catch(() => {
                    this.showNotification('❌ Failed to copy CSS');
                });
            },

            generateCSS() {
                let css = '/* AbundantThought Generated CSS */\n\n';
                css += ':root {\n';
                for (const [key, value] of Object.entries(this.design.colors)) {
                    css += `  --at-${key}: ${value};\n`;
                }
                css += '}\n\n';

                css += `body {\n`;
                css += `  font-size: ${this.design.typography.baseSize}px;\n`;
                css += `  font-family: ${this.getFontFamily(this.design.typography.bodyFont)};\n`;
                css += `  line-height: ${this.design.typography.lineHeight};\n`;
                css += `  color: var(--at-text);\n`;
                css += `  background: var(--at-background);\n`;
                css += `}\n\n`;

                css += `h1, h2, h3, h4, h5, h6 {\n`;
                css += `  font-family: ${this.getFontFamily(this.design.typography.headingFont)};\n`;
                css += `}\n\n`;

                css += `.site-container {\n`;
                css += `  max-width: ${this.design.layout.siteWidth}px;\n`;
                css += `}\n\n`;

                if (this.design.header.sticky) {
                    css += `.site-header {\n`;
                    css += `  position: sticky;\n`;
                    css += `  top: 0;\n`;
                    css += `  z-index: 1000;\n`;
                    css += `}\n\n`;
                }

                return css;
            },

            getFontFamily(font) {
                const fonts = {
                    'system': 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
                    'open-sans': '"Open Sans", sans-serif',
                    'roboto': 'Roboto, sans-serif',
                    'montserrat': 'Montserrat, sans-serif',
                    'playfair-display': '"Playfair Display", serif'
                };
                return fonts[font] || fonts.system;
            },

            exportDesign() {
                const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(this.design, null, 2));
                const downloadAnchorNode = document.createElement('a');
                downloadAnchorNode.setAttribute("href", dataStr);
                downloadAnchorNode.setAttribute("download", "abundantthought-design.json");
                document.body.appendChild(downloadAnchorNode);
                downloadAnchorNode.click();
                downloadAnchorNode.remove();

                this.showNotification('💾 Design exported!');
            },

            showNotification(message) {
                this.saveMessage = message;
                this.saveStatus = 'success';
                setTimeout(() => { this.saveMessage = ''; }, 3000);
            }
        },

        watch: {
            // Watch all design changes for real-time updates
            design: {
                handler: function() {
                    this.updatePreview();
                },
                deep: true
            }
        },

        mounted() {
