class AbundantThought_Visual_Builder {

    public function __construct() {
        add_action('admin_menu', array($this, 'add_admin_menu'));
        add_action('admin_enqueue_scripts', array($this, 'enqueue_admin_scripts'));
        add_action('wp_ajax_at_save_design', array($this, 'save_design'));
        add_action('wp_ajax_at_get_design', array($this, 'get_design'));
        add_action('wp_head', array($this, 'output_design_css'));
        add_action('template_redirect', array($this, 'handle_preview'));

        register_activation_hook(__FILE__, array($this, 'activate'));
    }

    public function activate() {
        if (!get_option('at_design_settings')) {
            $default_design = array(
                'colors' => array(
                    'primary' => '#2c5530',
                    'secondary' => '#4a7c59',
                    'background' => '#ffffff',
                    'text' => '#333333',
                    'accent' => '#d4a574'
                ),
                'typography' => array(
                    'baseSize' => 16,
                    'bodyFont' => 'system',
                    'headingFont' => 'playfair-display',
                    'lineHeight' => 1.6
                ),
                'header' => array(
                    'sticky' => true,
                    'logoWidth' => 200,
                    'height' => 80,
                    'menuAlignment' => 'right'
                ),
                'layout' => array(
                    'siteWidth' => 1200,
                    'contentWidth' => 800
                )
            );
            update_option('at_design_settings', $default_design);
        }
    }

    public function add_admin_menu() {
        add_menu_page(
            'Visual Builder',
            'Visual Builder',
            'edit_theme_options',
            'abundantthought-visual-builder',
            array($this, 'admin_page'),
            'dashicons-art',
            61
        );
    }

    public function enqueue_admin_scripts($hook) {
        if ($hook !== 'toplevel_page_abundantthought-visual-builder') {
            return;
        }

        wp_enqueue_script('vue', 'https://cdn.jsdelivr.net/npm/vue@2.6.14/dist/vue.js', array(), '2.6.14', true);
        wp_enqueue_script('jquery');

        wp_enqueue_script(
            'at-builder-js',
            plugin_dir_url(__FILE__) . 'builder.js',
            array('vue', 'jquery'),
            '1.0.0',
            true
        );

        wp_enqueue_style(
            'at-builder-css',
            plugin_dir_url(__FILE__) . 'builder.css',
            array(),
            '1.0.0'
        );

        wp_localize_script('at-builder-js', 'atBuilderData', array(
            'ajaxurl' => admin_url('admin-ajax.php'),
            'nonce' => wp_create_nonce('at_builder_nonce'),
            'siteurl' => home_url('/'),
            'design' => get_option('at_design_settings', array())
        ));
    }

    public function admin_page() {
        ?>
        <div class="wrap">
            <h1>AbundantThought Visual Builder</h1>
            <div id="at-visual-builder">
                <div class="at-loading">
                    <div class="at-spinner"></div>
                    <p>Loading Visual Builder...</p>
                </div>
