    public function save_design() {
        if (!wp_verify_nonce($_POST['nonce'], 'at_builder_nonce')) {
            wp_send_json_error('Security check failed');
        }

        if (!current_user_can('edit_theme_options')) {
            wp_send_json_error('Insufficient permissions');
        }

        $design = $this->sanitize_design($_POST['design']);
        update_option('at_design_settings', $design);

        wp_send_json_success('Design saved');
    }

    public function get_design() {
        if (!wp_verify_nonce($_POST['nonce'], 'at_builder_nonce')) {
            wp_send_json_error('Security check failed');
        }

        $design = get_option('at_design_settings', array());
        wp_send_json_success($design);
    }

    private function sanitize_design($design) {
        if (!is_array($design)) {
            return array();
        }

        $sanitized = array();

        if (isset($design['colors']) && is_array($design['colors'])) {
            foreach ($design['colors'] as $key => $color) {
                $sanitized['colors'][$key] = sanitize_hex_color($color);
            }
        }

        if (isset($design['typography']) && is_array($design['typography'])) {
            $sanitized['typography'] = array(
                'baseSize' => absint($design['typography']['baseSize']),
                'bodyFont' => sanitize_text_field($design['typography']['bodyFont']),
                'headingFont' => sanitize_text_field($design['typography']['headingFont']),
                'lineHeight' => floatval($design['typography']['lineHeight'])
            );
        }

        if (isset($design['header']) && is_array($design['header'])) {
            $sanitized['header'] = array(
                'sticky' => !empty($design['header']['sticky']),
                'logoWidth' => absint($design['header']['logoWidth']),
                'height' => absint($design['header']['height']),
                'menuAlignment' => sanitize_text_field($design['header']['menuAlignment'])
            );
        }

        if (isset($design['layout']) && is_array($design['layout'])) {
            $sanitized['layout'] = array(
                'siteWidth' => absint($design['layout']['siteWidth']),
                'contentWidth' => absint($design['layout']['contentWidth'])
            );
        }

        return $sanitized;
    }

    public function output_design_css() {
        $design = get_option('at_design_settings');
        if (empty($design)) {
            return;
        }

        echo '<style id="at-design-css">';
        echo ':root {';
        if (isset($design['colors'])) {
            foreach ($design['colors'] as $key => $value) {
                echo '--at-' . esc_attr($key) . ': ' . esc_attr($value) . ';';
            }
        }
        echo '}';

        if (isset($design['typography'])) {
            echo 'body {';
            echo 'font-size: ' . absint($design['typography']['baseSize']) . 'px;';
            echo 'line-height: ' . floatval($design['typography']['lineHeight']) . ';';
            echo '}';
        }
        echo '</style>';
    }

    public function handle_preview() {
        if (isset($_GET['at_preview']) && current_user_can('edit_theme_options')) {
            add_action('wp_head', array($this, 'add_preview_scripts'));
        }
    }

    public function add_preview_scripts() {
        $design = get_option('at_design_settings', array());
        ?>
        <script>
        window.addEventListener('message', function(event) {
            if (event.data.type === 'at_design_update') {
                applyDesign(event.data.design);
            }
        });

        function applyDesign(design) {
            if (design.colors) {
                document.documentElement.style.setProperty('--at-primary', design.colors.primary);
                document.documentElement.style.setProperty('--at-secondary', design.colors.secondary);
                document.documentElement.style.setProperty('--at-background', design.colors.background);
                document.documentElement.style.setProperty('--at-text', design.colors.text);
            }

            if (design.typography) {
                document.body.style.fontSize = design.typography.baseSize + 'px';
                document.body.style.lineHeight = design.typography.lineHeight;
            }
        }

        var initialDesign = <?php echo wp_json_encode($design); ?>;
        if (Object.keys(initialDesign).length > 0) {
            applyDesign(initialDesign);
        }
        </script>
        <?php
    }
}

new AbundantThought_Visual_Builder();
