            saving: false,
            saveMessage: '',
            previewUrl: atBuilderData.siteurl + '?at_preview=1&t=' + Date.now(),
            previewLoaded: false,
            design: {
                colors: {
                    primary: '#2c5530',
                    secondary: '#4a7c59',
                    background: '#ffffff',
                    text: '#333333',
                    accent: '#d4a574'
                },
                typography: {
                    baseSize: 16,
                    bodyFont: 'system',
                    headingFont: 'playfair-display',
                    lineHeight: 1.6
                },
                header: {
                    sticky: true,
                    logoWidth: 200,
                    height: 80,
                    menuAlignment: 'right'
                },
                layout: {
                    siteWidth: 1200,
                    contentWidth: 800
                }
            },
            colorPresets: [
                {
                    name: 'Nature',
                    colors: { primary: '#2c5530', secondary: '#4a7c59', background: '#ffffff', text: '#333333', accent: '#d4a574' }
                },
                {
                    name: 'Ocean', 
                    colors: { primary: '#2563eb', secondary: '#3b82f6', background: '#f8fafc', text: '#1e293b', accent: '#60a5fa' }
                }
            ]
        },
        methods: {
            updatePreview() {
                if (!this.previewLoaded) return;

                const iframe = document.querySelector('.at-preview-frame');
                if (iframe && iframe.contentWindow) {
                    iframe.contentWindow.postMessage({
                        type: 'at_design_update',
                        design: this.design
                    }, '*');
                }
            },
            onPreviewLoad() {
                this.previewLoaded = true;
                setTimeout(() => this.updatePreview(), 500);
            },
            saveDesign() {
                this.saving = true;
                this.saveMessage = 'Saving design...';

                $.ajax({
                    url: atBuilderData.ajaxurl,
                    type: 'POST',
                    data: {
                        action: 'at_save_design',
                        nonce: atBuilderData.nonce,
                        design: this.design
                    },
                    success: (response) => {
                        this.saving = false;
                        this.saveMessage = 'Design saved successfully!';
                        setTimeout(() => { this.saveMessage = ''; }, 3000);
                    },
                    error: (xhr, status, error) => {
                        this.saving = false;
                        this.saveMessage = 'Error saving design';
                        setTimeout(() => { this.saveMessage = ''; }, 5000);
                    }
                });
            },
            applyColorPreset(preset) {
                this.design.colors = { ...preset.colors };
                this.updatePreview();
            }
        },
        mounted() {
            if (atBuilderData.design && Object.keys(atBuilderData.design).length > 0) {
                this.design = { ...this.design, ...atBuilderData.design };
            }
        },
        template: `
            <div class="at-builder">
                <div class="at-controls-panel">
                    <div class="at-tabs">
                        <button v-for="tab in ['colors', 'typography', 'header', 'layout']" 
                                :key="tab"
                                :class="['at-tab', { active: activeTab === tab }]"
                                @click="activeTab = tab">
                            {{ tab.charAt(0).toUpperCase() + tab.slice(1) }}
                        </button>
                    </div>

                    <div v-if="activeTab === 'colors'" class="at-control-group">
                        <h3>Colors</h3>
                        <div class="at-control" v-for="(value, key) in design.colors" :key="key">
                            <label>{{ key.charAt(0).toUpperCase() + key.slice(1) }}</label>
                            <input type="color" v-model="design.colors[key]" @input="updatePreview">
                            <span class="at-value">{{ design.colors[key] }}</span>
                        </div>
                    </div>

                    <div class="at-actions">
                        <button class="at-btn at-btn-primary" @click="saveDesign" :disabled="saving">
                            {{ saving ? 'Saving...' : 'Save Design' }}
                        </button>
                    </div>

                    <div v-if="saveMessage" class="at-save-notice">
