### Core Plugin Class (`includes/class-plugin.php`):

```php
<?php
/**
 * Main plugin class
 */
class ABUNDANTTHOUGHT_Plugin {

	/**
	 * Plugin instance
	 */
	private static $instance = null;

	/**
	 * Get plugin instance
	 */
	public static function instance() {
		if ( is_null( self::$instance ) ) {
			self::$instance = new self();
		}
		return self::$instance;
	}

	/**
	 * Constructor
	 */
	private function __construct() {
		$this->includes();
		$this->init_hooks();
	}

	/**
	 * Include required files
	 */
	private function includes() {
		require_once ABUNDANTTHOUGHT_INCLUDES_PATH . 'class-admin.php';
		require_once ABUNDANTTHOUGHT_INCLUDES_PATH . 'class-preview.php';
		require_once ABUNDANTTHOUGHT_INCLUDES_PATH . 'class-ajax.php';
	}

	/**
	 * Initialize hooks
	 */
	private function init_hooks() {
		add_action( 'plugins_loaded', array( $this, 'load_textdomain' ) );

		// Initialize components
		ABUNDANTTHOUGHT_Admin::instance();
		ABUNDANTTHOUGHT_Preview::instance();
		ABUNDANTTHOUGHT_AJAX::instance();
	}

	/**
	 * Load plugin textdomain
	 */
	public function load_textdomain() {
		load_plugin_textdomain(
			'abundantthought',
			false,
			dirname( ABUNDANTTHOUGHT_PLUGIN_BASE ) . '/languages'
		);
	}
}
