		add_action( 'wp_ajax_at_get_design', array( $this, 'get_design' ) );
	}

	public function save_design() {
		// Verify nonce
		if ( ! wp_verify_nonce( $_POST['nonce'], 'abundantthought_nonce' ) ) {
			wp_send_json_error( __( 'Security check failed', 'abundantthought' ) );
		}

		// Check capabilities
		if ( ! current_user_can( 'edit_theme_options' ) ) {
			wp_send_json_error( __( 'Insufficient permissions', 'abundantthought' ) );
		}

		// Sanitize and save
		$design = $this->sanitize_design( $_POST['design'] );
		update_option( 'at_design_settings', $design );

		wp_send_json_success( __( 'Design saved', 'abundantthought' ) );
	}

	public function get_design() {
		// Verify nonce
		if ( ! wp_verify_nonce( $_POST['nonce'], 'abundantthought_nonce' ) ) {
			wp_send_json_error( __( 'Security check failed', 'abundantthought' ) );
		}

		$design = get_option( 'at_design_settings', array() );
		wp_send_json_success( $design );
	}

