                    name: 'Nature',
                    colors: {
                        primary: '#2c5530',
                        secondary: '#4a7c59',
                        background: '#ffffff',
                        text: '#333333',
                        accent: '#d4a574'
                    }
                },
                {
                    name: 'Ocean',
                    colors: {
                        primary: '#2563eb',
                        secondary: '#3b82f6',
                        background: '#f8fafc',
                        text: '#1e293b',
                        accent: '#60a5fa'
                    }
                },
                {
                    name: 'Sunset',
                    colors: {
                        primary: '#ea580c',
                        secondary: '#f97316',
                        background: '#fff7ed',
                        text: '#431407',
