                        this.saveMessage = 'Error saving design: ' + error;
                        this.saveStatus = 'error';
                        setTimeout(() => { this.saveMessage = ''; }, 5000);
                    }
                });
            },
            applyColorPreset(preset) {
                this.design.colors = { ...preset.colors };
                this.updatePreview();
            },
            presetStyle(preset) {
                return {
                    background: `linear-gradient(135deg, ${preset.colors.primary} 0%, ${preset.colors.secondary} 100%)`,
                    border: `2px solid ${preset.colors.primary}`
                };
            },
            resetToDefaults() {
                if (confirm('Are you sure you want to reset all settings to defaults?')) {
                    this.design = {
                        colors: {
                            primary: '#2c5530',
                            secondary: '#4a7c59',
                            background: '#ffffff',
                            text: '#333333',
                            accent: '#d4a574'
                        },
                        typography: {
                            baseSize: 16,
                            bodyFont: 'system',
                            headingFont: 'playfair-display',
                            lineHeight: 1.6,
                            letterSpacing: 0,
                            textTransform: 'none'
                        },
                        header: {
                            sticky: true,
                            logoWidth: 200,
                            height: 80,
                            menuAlignment: 'right',
                            background: '#ffffff',
                            showSearch: true
                        },
                        layout: {
                            siteWidth: 1200,
                            contentWidth: 800,
                            sidebar: 'right',
                            containerPadding: '40px'
                        }
                    };
                    this.updatePreview();
                }
            },
            getFontFamily(font) {
                const fonts = {
                    'system': 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
                    'open-sans': '"Open Sans", sans-serif',
                    'roboto': 'Roboto, sans-serif',
                    'montserrat': 'Montserrat, sans-serif',
                    'playfair-display': '"Playfair Display", serif'
                };
                return fonts[font] || fonts.system;
            }
        },
        watch: {
            design: {
                handler: function() {
                    this.updatePreview();
                },
                deep: true
            }
        },
        mounted() {
            // Load saved design if exists
            if (atBuilderData.design && Object.keys(atBuilderData.design).length > 0) {
                this.design = { ...this.design, ...atBuilderData.design };
            }

            console.log('AbundantThought Visual Builder loaded successfully!');
        }
    });
});
