            $normalized_widgets[] = [
                'type' => $type,
                'data' => $widget['data']
            ];
        }

        update_post_meta($post_id, '_at_builder_content', json_encode($normalized_widgets));
        wp_send_json_success(['message' => 'Content saved successfully']);
    }

