    public function ajax_save_content() {
        // Verify nonce for security
        if (!wp_verify_nonce($_POST['nonce'], 'at_save_content')) {
            wp_send_json_error('Security verification failed');
        }

        if (!current_user_can('edit_post', $_POST['post_id'])) {
            wp_send_json_error('Permission denied');
        }

        $post_id = intval($_POST['post_id']);
        $content = wp_unslash($_POST['content']); // JSON string

        // Convert widget types from 'heading-widget' to 'heading' for PHP processing
        $widgets = json_decode($content, true);
        $normalized_widgets = [];

        foreach ($widgets as $widget) {
            $type = str_replace('-widget', '', $widget['type']);
            $normalized_widgets[] = [
                'type' => $type,
                'data' => $widget['data']
            ];
        }

        update_post_meta($post_id, '_at_builder_content', json_encode($normalized_widgets));
        wp_send_json_success(['message' => 'Content saved successfully']);
    }

