## 🎨 **1. Block Editor Controls** (`blocks/ebook-offer/edit.js`)

```javascript
(function(){
    const { 
        useSelect, 
        useDispatch 
    } = wp.data;

    const {
        PanelBody,
        SelectControl,
        RangeControl,
        TextControl,
        Spinner,
        Placeholder,
        __experimentalInputControl: InputControl
    } = wp.components;

    const {
        InspectorControls,
        useBlockProps
    } = wp.blockEditor;

    const {
        useEffect,
        useState
    } = wp.element;

    const { __ } = wp.i18n;

    wp.blocks.registerBlockType('abundantthought/ebook-offer', {
        // ... your existing block.json config
        edit: function(props) {
            const { attributes, setAttributes } = props;
            const { mode, ebookId, ids, interval, animation, buttonText } = attributes;

            const [allEbooks, setAllEbooks] = useState([]);
            const [isLoading, setIsLoading] = useState(true);

            // Get ebooks from WordPress
            const ebooks = useSelect((select) => {
                return select('core').getEntityRecords('postType', 'ebooks', {
                    per_page: -1,
                    status: 'publish'
                });
            }, []);

            // Update local state when ebooks are loaded
            useEffect(() => {
                if (ebooks) {
                    setAllEbooks(ebooks);
                    setIsLoading(false);
                }
            }, [ebooks]);

            // Get the selected ebook for single mode
            const selectedEbook = useSelect((select) => {
                if (mode === 'single' && ebookId) {
                    return select('core').getEntityRecords('postType', 'ebooks', {
                        include: [ebookId],
                        per_page: 1
                    })?.[0];
                }
                return null;
            }, [mode, ebookId]);

            // Get selected ebooks for rotate mode
            const selectedEbooks = useSelect((select) => {
                if (mode === 'rotate' && ids && ids.length > 0) {
                    return select('core').getEntityRecords('postType', 'ebooks', {
                        include: ids,
                        per_page: ids.length,
                        orderby: 'include'
                    }) || [];
                }
                return [];
            }, [mode, ids]);

            const blockProps = useBlockProps();

            // Handle ebook selection for single mode
            const handleEbookChange = (value) => {
                setAttributes({ ebookId: parseInt(value) || 0 });
            };

            // Handle multiple ebook selection for rotate mode
            const handleEbooksChange = (selectedIds) => {
                setAttributes({ ids: selectedIds.map(id => parseInt(id)) });
            };

            // Render block preview
            const renderPreview = () => {
                if (isLoading) {
                    return (
                        <Placeholder>
                            <Spinner />
                            {__('Loading e-books...', 'abundantthought-ebooks')}
                        </Placeholder>
                    );
                }

                if (mode === 'single' && selectedEbook) {
                    return (
                        <div className="at-ebook-preview">
                            <h4>{__('Single E-Book Preview:', 'abundantthought-ebooks')}</h4>
                            <div className="at-ebook-preview-item">
                                <strong>{selectedEbook.title.rendered}</strong>
                                {selectedEbook.excerpt?.raw && (
                                    <p>{selectedEbook.excerpt.raw.substring(0, 100)}...</p>
                                )}
                            </div>
                        </div>
                    );
                }

                if (mode === 'rotate' && selectedEbooks.length > 0) {
                    return (
                        <div className="at-ebook-preview">
                            <h4>{__('Rotating E-Books Preview:', 'abundantthought-ebooks')}</h4>
                            {selectedEbooks.map(ebook => (
                                <div key={ebook.id} className="at-ebook-preview-item">
                                    <strong>{ebook.title.rendered}</strong>
                                    {ebook.excerpt?.raw && (
                                        <p>{ebook.excerpt.raw.substring(0, 80)}...</p>
                                    )}
                                </div>
                            ))}
                            <p><em>{__('Rotation interval:', 'abundantthought-ebooks')} {interval / 1000}s</em></p>
                        </div>
                    );
                }

                return (
                    <Placeholder 
                        icon="book"
                        label={__('E-Book Offer', 'abundantthought-ebooks')}
                    >
                        {__('Configure your e-book offer block using the settings in the sidebar.', 'abundantthought-ebooks')}
                    </Placeholder>
                );
            };

            return (
                <>
                    <InspectorControls>
                        <PanelBody title={__('E-Book Settings', 'abundantthought-ebooks')} initialOpen={true}>
                            <SelectControl
                                label={__('Display Mode', 'abundantthought-ebooks')}
                                value={mode}
                                options={[
                                    { label: __('Single E-Book', 'abundantthought-ebooks'), value: 'single' },
                                    { label: __('Rotating E-Books', 'abundantthought-ebooks'), value: 'rotate' },
                                ]}
                                onChange={(value) => setAttributes({ mode: value })}
                            />

                            {mode === 'single' && (
                                <SelectControl
                                    label={__('Select E-Book', 'abundantthought-ebooks')}
                                    value={ebookId}
                                    options={[
                                        { label: __('-- Select an E-Book --', 'abundantthought-ebooks'), value: 0 },
                                        ...allEbooks.map(ebook => ({
                                            label: ebook.title.rendered,
                                            value: ebook.id
                                        }))
                                    ]}
                                    onChange={handleEbookChange}
                                />
                            )}

                            {mode === 'rotate' && (
                                <SelectControl
                                    label={__('Select E-Books', 'abundantthought-ebooks')}
                                    value={ids}
                                    multiple
                                    options={allEbooks.map(ebook => ({
                                        label: ebook.title.rendered,
                                        value: ebook.id
                                    }))}
                                    onChange={handleEbooksChange}
                                />
                            )}

                            {mode === 'rotate' && (
                                <RangeControl
                                    label={__('Rotation Interval (seconds)', 'abundantthought-ebooks')}
                                    value={interval / 1000}
                                    onChange={(value) => setAttributes({ interval: value * 1000 })}
                                    min={3}
                                    max={30}
                                    step={1}
                                />
                            )}

                            <SelectControl
                                label={__('Animation', 'abundantthought-ebooks')}
                                value={animation}
                                options={[
                                    { label: __('Fade', 'abundantthought-ebooks'), value: 'fade' },
                                    { label: __('Slide', 'abundantthought-ebooks'), value: 'slide' },
                                    { label: __('None', 'abundantthought-ebooks'), value: 'none' },
                                ]}
                                onChange={(value) => setAttributes({ animation: value })}
                            />

                            <TextControl
                                label={__('Button Text', 'abundantthought-ebooks')}
                                value={buttonText}
                                onChange={(value) => setAttributes({ buttonText: value })}
                                placeholder={__('Download', 'abundantthought-ebooks')}
                            />
                        </PanelBody>
                    </InspectorControls>

                    <div {...blockProps}>
                        {renderPreview()}
                    </div>
                </>
            );
        },

        save: function() {
            return null; // Uses render.php
        }
    });
})();
```

