function at_ebooks_custom_column_content($column, $post_id) {
    switch ($column) {
        case 'featured_image':
            if (has_post_thumbnail($post_id)) {
                $image = get_the_post_thumbnail($post_id, array(60, 80), array('style' => 'max-height:80px;width:auto;'));
