                echo '<a href="' . esc_url($cta_url) . '" target="_blank" style="word-break:break-all;font-size:12px;">' . esc_html($cta_url) . '</a>';
                echo '<br><small style="color:#46b450;">✓ ' . __('Configured', 'abundantthought-ebooks') . '</small>';
            } else {
                echo '<span style="color:#ccc;font-style:italic;">' . __('Not set', 'abundantthought-ebooks') . '</span>';
