            break;

        case 'shortcode':
            echo '<code style="font-size:11px;background:#f6f7f7;padding:2px 4px;border-radius:3px;">';
            echo '[ebook_offer id="' . $post_id . '"]';
            echo '</code>';
            echo '<br><small style="color:#666;">' . __('Copy this shortcode', 'abundantthought-ebooks') . '</small>';
            break;
    }
}

