```php
<?php
if (!defined('ABSPATH')) exit;

class AT_Performance_Optimizer {

    public static function init() {
        add_action('wp_enqueue_scripts', array(__CLASS__, 'optimize_asset_loading'));
        add_filter('script_loader_tag', array(__CLASS__, 'add_async_defer'), 10, 2);
        add_action('save_post_ebooks', array(__CLASS__, 'clear_ebook_cache'), 10, 3);
    }

    public static function optimize_asset_loading() {
        // Only load CSS when needed
        if (!has_block('abundantthought/ebook-offer')) {
            return;
        }

        // Use minified assets in production
        $suffix = (defined('SCRIPT_DEBUG') && SCRIPT_DEBUG) ? '' : '.min';

        wp_enqueue_style(
            'at-ebook-offer', 
            AT_EBOOKS_URL . 'assets/css/ebook-offer' . $suffix . '.css', 
            array(), 
            '1.2.0'
        );

        wp_enqueue_script(
            'at-ebook-offer-view',
            AT_EBOOKS_URL . 'assets/js/ebook-offer-view' . $suffix . '.js',
            array(),
            '1.2.0',
            true
        );

        // Add lazy loading for images
        wp_add_inline_script('at-ebook-offer-view', '
            document.addEventListener("DOMContentLoaded", function() {
                if ("IntersectionObserver" in window) {
                    const ebookImages = document.querySelectorAll(".at-ebook-media img");
                    const imageObserver = new IntersectionObserver((entries) => {
                        entries.forEach(entry => {
                            if (entry.isIntersecting) {
                                const img = entry.target;
                                img.src = img.dataset.src;
                                imageObserver.unobserve(img);
                            }
                        });
                    });

                    ebookImages.forEach(img => {
                        img.dataset.src = img.src;
                        img.src = "data:image/svg+xml,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 300 400\'%3E%3C/svg%3E";
                        imageObserver.observe(img);
                    });
                }
            });
        ');
    }

    public static function add_async_defer($tag, $handle) {
        if ('at-ebook-offer-view' === $handle) {
            return str_replace(' src', ' defer src', $tag);
        }
        return $tag;
    }

    public static function clear_ebook_cache($post_id, $post, $update) {
        // Clear any transient caches when e-books are updated
        if (wp_is_post_revision($post_id)) {
            return;
        }

        delete_transient('at_popular_ebooks');
        delete_transient('at_recent_ebooks');

        AT_Error_Handler::log_event('E-book cache cleared for post ' . $post_id);
    }

    public static function get_ebooks_cached($args = array()) {
        $defaults = array(
            'post_type' => 'ebooks',
            'posts_per_page' => 10,
            'post_status' => 'publish'
        );

        $args = wp_parse_args($args, $defaults);
        $transient_key = 'at_ebooks_' . md5(serialize($args));

        $ebooks = get_transient($transient_key);

        if (false === $ebooks) {
            $ebooks = get_posts($args);
            set_transient($transient_key, $ebooks, HOUR_IN_SECONDS); // Cache for 1 hour
        }

        return $ebooks;
    }
}

// Initialize performance optimizations
AT_Performance_Optimizer::init();
