```php
<?php
if (!defined('ABSPATH')) exit;

class AT_Workflow_Tools {

    public static function init() {
        add_action('admin_init', array(__CLASS__, 'add_quick_actions'));
        add_filter('bulk_actions-edit-ebooks', array(__CLASS__, 'add_bulk_actions'));
        add_filter('handle_bulk_actions-edit-ebooks', array(__CLASS__, 'handle_bulk_actions'), 10, 3);
        add_action('admin_notices', array(__CLASS__, 'bulk_action_notices'));
    }

    public static function add_quick_actions() {
        add_filter('post_row_actions', array(__CLASS__, 'add_row_actions'), 10, 2);
    }

    public static function add_row_actions($actions, $post) {
        if ($post->post_type !== 'ebooks') {
            return $actions;
        }

        // Add duplicate action
        $actions['duplicate'] = sprintf(
            '<a href="%s" aria-label="%s">%s</a>',
            wp_nonce_url(admin_url('admin-post.php?action=at_duplicate_ebook&post=' . $post->ID), 'at_duplicate_ebook_' . $post->ID),
            esc_attr__('Duplicate this e-book', 'abundantthought-ebooks'),
            esc_html__('Duplicate', 'abundantthought-ebooks')
        );

        return $actions;
    }

    public static function add_bulk_actions($actions) {
        $actions['duplicate_ebooks'] = __('Duplicate', 'abundantthought-ebooks');
        $actions['reset_download_counts'] = __('Reset Download Counts', 'abundantthought-ebooks');
        return $actions;
    }

    public static function handle_bulk_actions($redirect_to, $doaction, $post_ids) {
        switch ($doaction) {
            case 'duplicate_ebooks':
                $duplicated = 0;
                foreach ($post_ids as $post_id) {
                    if (self::duplicate_ebook($post_id)) {
                        $duplicated++;
                    }
                }
                $redirect_to = add_query_arg('duplicated_ebooks', $duplicated, $redirect_to);
                break;

            case 'reset_download_counts':
                $reset = 0;
                foreach ($post_ids as $post_id) {
                    delete_post_meta($post_id, '_download_count');
                    delete_post_meta($post_id, '_last_download');
                    $reset++;
                }
                $redirect_to = add_query_arg('reset_download_counts', $reset, $redirect_to);
                break;
        }

        return $redirect_to;
    }

    public static function bulk_action_notices() {
        if (!empty($_REQUEST['duplicated_ebooks'])) {
            $count = intval($_REQUEST['duplicated_ebooks']);
            printf(
                '<div class="notice notice-success is-dismissible"><p>%s</p></div>',
                sprintf(_n('%d e-book duplicated.', '%d e-books duplicated.', $count, 'abundantthought-ebooks'), $count)
            );
        }

        if (!empty($_REQUEST['reset_download_counts'])) {
            $count = intval($_REQUEST['reset_download_counts']);
            printf(
                '<div class="notice notice-success is-dismissible"><p>%s</p></div>',
                sprintf(_n('Download count reset for %d e-book.', 'Download counts reset for %d e-books.', $count, 'abundantthought-ebooks'), $count)
            );
        }
    }

    public static function duplicate_ebook($post_id) {
        $post = get_post($post_id);

        if (!$post || $post->post_type !== 'ebooks') {
            return false;
        }

        $new_post = array(
            'post_title' => $post->post_title . ' (Copy)',
            'post_content' => $post->post_content,
            'post_excerpt' => $post->post_excerpt,
            'post_status' => 'draft',
            'post_type' => 'ebooks'
        );

        $new_post_id = wp_insert_post($new_post);

        if ($new_post_id) {
            // Copy meta data
            $meta_data = get_post_meta($post_id);
            foreach ($meta_data as $key => $values) {
                if ($key === '_download_count' || $key === '_last_download') {
                    continue; // Don't copy download stats
                }
                foreach ($values as $value) {
                    update_post_meta($new_post_id, $key, maybe_unserialize($value));
                }
            }

            // Copy taxonomy
            $taxonomies = get_object_taxonomies($post->post_type);
            foreach ($taxonomies as $taxonomy) {
                $post_terms = wp_get_object_terms($post_id, $taxonomy, array('fields' => 'slugs'));
                wp_set_object_terms($new_post_id, $post_terms, $taxonomy, false);
            }

            AT_Error_Handler::log_event('E-book duplicated: ' . $post_id . ' -> ' . $new_post_id);
            return true;
        }

        return false;
    }
}

// Handle duplicate action
add_action('admin_post_at_duplicate_ebook', function() {
