### **5. Error Handler & Maintenance** (`includes/error-handler.php`)
```php
<?php
if (!defined('ABSPATH')) exit;

class AT_Error_Handler {

    const LOG_FILE = 'abundantthought-ebooks.log';

    public static function init() {
        add_action('admin_init', array(__CLASS__, 'check_system_health'));
        register_activation_hook(__FILE__, array(__CLASS__, 'activation_check'));
        register_deactivation_hook(__FILE__, array(__CLASS__, 'deactivation_cleanup'));
    }

    public static function log_event($message, $level = 'info') {
        if (!defined('AT_EBOOKS_DEBUG') || !AT_EBOOKS_DEBUG) {
            return;
        }

        $log_entry = sprintf(
            "[%s] %s: %s\n",
            current_time('mysql'),
            strtoupper($level),
            $message
        );

        $log_file = WP_CONTENT_DIR . '/' . self::LOG_FILE;

        // Ensure we don't create huge log files
        if (file_exists($log_file) && filesize($log_file) > 1048576) { // 1MB
            file_put_contents($log_file, ''); // Clear log
        }

        file_put_contents($log_file, $log_entry, FILE_APPEND | LOCK_EX);
    }

    public static function check_system_requirements() {
        $errors = array();

        // Check PHP version
        if (version_compare(PHP_VERSION, '7.4', '<')) {
            $errors[] = 'PHP 7.4 or higher is required.';
        }

        // Check WordPress version
        if (version_compare(get_bloginfo('version'), '5.8', '<')) {
            $errors[] = 'WordPress 5.8 or higher is required for full block editor support.';
        }

        return $errors;
    }

    public static function check_system_health() {
        // Run weekly health checks
        $last_check = get_option('at_ebooks_last_health_check', 0);

        if (time() - $last_check > WEEK_IN_SECONDS) {
            self::perform_health_check();
            update_option('at_ebooks_last_health_check', time());
        }
    }

    public static function perform_health_check() {
        $issues = array();

        // Check if e-books post type is registered
        if (!post_type_exists('ebooks')) {
            $issues[] = 'E-books post type not registered properly.';
        }

        // Check for orphaned meta data
        $orphaned_meta = self::find_orphaned_meta();
        if ($orphaned_meta > 0) {
            $issues[] = "Found {$orphaned_meta} orphaned meta records.";
        }

        // Log health check results
        if (empty($issues)) {
            self::log_event('System health check passed');
        } else {
            self::log_event('System health check issues: ' . implode(', ', $issues), 'warning');
        }

        return $issues;
    }

    public static function find_orphaned_meta() {
        global $wpdb;

        $count = $wpdb->get_var("
            SELECT COUNT(*) 
            FROM {$wpdb->postmeta} pm 
            LEFT JOIN {$wpdb->posts} p ON pm.post_id = p.ID 
            WHERE p.ID IS NULL 
            AND pm.meta_key LIKE '%ebook%'
        ");

        return intval($count);
    }

    public static function activation_check() {
        $errors = self::check_system_requirements();

        if (!empty($errors)) {
            deactivate_plugins(plugin_basename(__FILE__));
            wp_die(
                '<p>' . implode('</p><p>', $errors) . '</p>' .
                '<a href="' . admin_url('plugins.php') . '">Return to plugins page</a>'
            );
        }

        // Set default options
        update_option('at_ebooks_total_downloads', 0);
        update_option('at_ebooks_last_health_check', time());

        self::log_event('Plugin activated');
    }

    public static function deactivation_cleanup() {
        // Clear scheduled tasks
        wp_clear_scheduled_hook('at_ebooks_daily_maintenance');

        // Don't delete data - just clean up transients
        delete_transient('at_popular_ebooks');
        delete_transient('at_recent_ebooks');

        self::log_event('Plugin deactivated');
    }

    public static function display_admin_notices() {
        $errors = self::check_system_requirements();

        if (!empty($errors)) {
            foreach ($errors as $error) {
                printf(
                    '<div class="notice notice-error"><p>%s: %s</p></div>',
                    __('AbundantThought E-Books', 'abundantthought-ebooks'),
                    $error
                );
            }
        }
    }
}

// Initialize error handler
AT_Error_Handler::init();

// Display admin notices
add_action('admin_notices', array('AT_Error_Handler', 'display_admin_notices'));
```

