### **7. Updated JavaScript with Download Tracking** (`assets/js/ebook-offer-view.js`)
```javascript
(function(){
    // Utility function for element selection
    const $$ = (s, c=document) => Array.from(c.querySelectorAll(s));

    // Track downloads
    const trackDownload = (ebookId) => {
        if (typeof fetch === 'function') {
            fetch(ajaxurl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: `action=at_track_download&ebook_id=${ebookId}`
            }).catch(err => {
                console.log('AT E-Books: Download tracking failed', err);
            });
        }
    };

    // Initialize e-book offers
    $$('.at-ebook-offer').forEach(root => {
        const mode = root.dataset.mode || 'rotate';
        const interval = parseInt(root.dataset.interval || '7000', 10);
        const animation = root.dataset.animation || 'fade';
        const items = Array.from(root.querySelectorAll('.at-ebook-item'));

        // Add download tracking to buttons
        const downloadButtons = root.querySelectorAll('.at-ebook-btn');
        downloadButtons.forEach(btn => {
            const ebookId = btn.closest('.at-ebook-item')?.id.replace('ebook-', '');
            if (ebookId) {
                btn.addEventListener('click', () => trackDownload(ebookId));
            }
        });

        // Single mode or insufficient items
        if (mode === 'single' || items.length < 2) {
            items.forEach((it, idx) => {
                it.classList.toggle('is-active', idx === 0);
            });
            return;
        }

        // Rotating mode
        let i = 0;
        items.forEach((it, idx) => it.classList.toggle('is-active', idx === 0));

        const rotationInterval = setInterval(() => {
            items[i].classList.remove('is-active');
            i = (i + 1) % items.length;
            items[i].classList.add('is-active');
        }, interval);

        // Pause rotation on hover
        root.addEventListener('mouseenter', () => {
            clearInterval(rotationInterval);
        });

        root.addEventListener('mouseleave', () => {
            clearInterval(rotationInterval);
            rotationInterval = setInterval(() => {
                items[i].classList.remove('is-active');
                i = (i + 1) % items.length;
                items[i].classList.add('is-active');
            }, interval);
        });

        // Cleanup on element removal
        const observer = new MutationObserver((mutations) => {
            mutations.forEach((mutation) => {
                if (mutation.removedNodes) {
                    mutation.removedNodes.forEach((node) => {
                        if (node === root) {
                            clearInterval(rotationInterval);
                            observer.disconnect();
                        }
                    });
                }
            });
        });

        observer.observe(document.body, { childList: true, subtree: true });
    });

    // Log initialization for debugging
    if (typeof console !== 'undefined') {
        console.log('AT E-Books: Frontend initialized');
    }
})();
```

