// Shortcode support
add_shortcode('ebook_offer', function($atts) {
    $atts = shortcode_atts(array(
        'mode' => 'single',
        'id' => 0,
        'ids' => '',
        'interval' => 7000,
        'animation' => 'fade',
        'button_text' => 'Download'
    ), $atts);

    $block_attributes = array(
        'mode' => $atts['mode'],
        'ebookId' => intval($atts['id']),
        'interval' => intval($atts['interval']),
        'animation' => $atts['animation'],
        'buttonText' => $atts['button_text'],
        'ids' => !empty($atts['ids']) ? array_map('intval', explode(',', $atts['ids'])) : array()
    );

    ob_start();
    global $at_ebook_shortcode_attrs;
    $at_ebook_shortcode_attrs = $block_attributes;
    include AT_EBOOKS_DIR . 'blocks/ebook-offer/render.php';
    return ob_get_clean();
});

