// Track downloads for analytics - NEW
add_action('wp_ajax_at_track_download', 'at_track_download');
add_action('wp_ajax_nopriv_at_track_download', 'at_track_download');
function at_track_download() {
    $ebook_id = intval($_POST['ebook_id'] ?? 0);
    if ($ebook_id) {
        AT_Simple_Analytics::track_download($ebook_id);
    }
    wp_die();
} // <-- This closes the at_track_download function

