  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  text-align: center;
  margin: var(--menu-margin, 0);
  padding: var(--menu-padding, 0);

  /* Dual Border Controls */
  border-top: var(--menu-border-top-width, 0) var(--menu-border-top-style, none) var(--menu-border-top-color, transparent);
  border-bottom: var(--menu-border-bottom-width, 0) var(--menu-border-bottom-style, none) var(--menu-border-bottom-color, transparent);
}

/* Make ALL potential menu selectors horizontal */
