<?php
/**
 * Functions and definitions for Abundant Thought 2025 v5.0
 */

if ( ! isset( $content_width ) ) {
    $content_width = 900;
}

/**
 * Theme setup and WordPress features activation
 */
function abundant_thought_2025_v5_0_setup() {
    load_theme_textdomain( 'abundant-thought-2025-v5-0', get_template_directory() . '/languages' );

    // Core supports
    add_theme_support( 'automatic-feed-links' );
    add_theme_support( 'title-tag' );
    add_theme_support( 'post-thumbnails' );
    add_theme_support( 'custom-header' );
    add_theme_support( 'custom-background' );
    add_theme_support(
        'html5',
        array( 'search-form', 'comment-form', 'comment-list', 'gallery', 'caption', 'style', 'script' )
    );
    add_theme_support( 'custom-logo', array(
        'height'      => 80,
        'width'       => 240,
        'flex-height' => true,
        'flex-width'  => true,
    ) );

    // Gutenberg & block editor features
    add_theme_support( 'widgets-block-editor' );
    add_theme_support( 'wp-block-styles' );
    add_theme_support( 'responsive-embeds' );
    add_theme_support( 'align-wide' );

    add_editor_style( 'assets/css/theme.css' );

    // Navigation menus
    register_nav_menus( array(
        'primary' => __( 'Primary Menu', 'abundant-thought-2025-v5-0' ),
        'footer'  => __( 'Footer Menu',  'abundant-thought-2025-v5-0' ),
    ) );
}
add_action( 'after_setup_theme', 'abundant_thought_2025_v5_0_setup' );

/**
 * Enqueue scripts and styles for the front end
 */
function abundant_thought_2025_v5_0_scripts() {
    // Main stylesheet - CORRECTLY enqueuing style.css
    wp_enqueue_style(
        'abundant-thought-2025-v5-0-style',
        get_stylesheet_uri(), // This loads style.css from theme root
        array(),
        '5.0'
    );

    // Theme JS (if present)
    if ( file_exists( get_template_directory() . '/assets/js/theme.js' ) ) {
        wp_enqueue_script(
            'abundant-thought-2025-v5-0-scripts',
            get_template_directory_uri() . '/assets/js/theme.js',
            array( 'jquery' ),
            '5.0',
            true
        );
    }

    // Comments support
    if ( is_singular() && comments_open() && get_option( 'thread_comments' ) ) {
        wp_enqueue_script( 'comment-reply' );
    }
}
add_action( 'wp_enqueue_scripts', 'abundant_thought_2025_v5_0_scripts' );

/**
 * Enqueue Customizer live preview script
 * Ensures postMessage updates are instantly reflected in the preview window
 */
function abundant_thought_2025_v5_0_customize_preview_js() {
    wp_enqueue_script(
        'abundant-thought-2025-v5-0-customizer',
        get_template_directory_uri() . '/assets/js/customizer.js',
        array( 'customize-preview', 'jquery' ),
        '5.0',
        true
    );
}
add_action( 'customize_preview_init', 'abundant_thought_2025_v5_0_customize_preview_js' );

/**
 * Widget area registration
 */
function abundant_thought_2025_v5_0_widgets_init() {
    register_sidebar( array(
        'name'          => __( 'Primary Sidebar', 'abundant-thought-2025-v5-0' ),
        'id'            => 'sidebar-1',
        'description'   => __( 'Main sidebar appearing on right side.', 'abundant-thought-2025-v5-0' ),
        'before_widget' => '<section id="%1$s" class="widget %2$s">',
        'after_widget'  => '</section>',
        'before_title'  => '<h3 class="widget-title">',
        'after_title'   => '</h3>',
    ) );
}
add_action( 'widgets_init', 'abundant_thought_2025_v5_0_widgets_init' );

/**
 * Include modular theme components
 */
foreach (
    array(
        'block-styles.php',
        'block-patterns.php',
        'widgets.php',
        'theme-seo.php',
        'template-tags.php',
        'customizer.php',
    ) as $inc_file
) {
    $inc_path = get_template_directory() . '/inc/' . $inc_file;
    if ( file_exists( $inc_path ) ) {
        require_once $inc_path;
    }
}

/**
 * Generate inline CSS variables for header layout styles (Used by header.php)
 */
if ( ! function_exists( 'abundantthought_header_style' ) ) {
    function abundantthought_header_style() {
        $vars = [];

        // Menu + Regular Spacing Variables
        $pairs = array(
            '--menu-margin'           => get_theme_mod( 'menu_margin', '0' ),
            '--menu-padding'          => get_theme_mod( 'menu_padding', '0' ),
            '--logo-margin'           => get_theme_mod( 'logo_margin', '0' ),
            '--logo-padding'          => get_theme_mod( 'logo_padding', '0' ),
            '--site_title-margin'     => get_theme_mod( 'site_title_margin', '0' ),
            '--site_title-padding'    => get_theme_mod( 'site_title_padding', '0' ),
            '--tagline-margin'        => get_theme_mod( 'tagline_margin', '0' ),
            '--tagline-padding'       => get_theme_mod( 'tagline_padding', '0' ),
        );

        // Border Top/Bottom
        foreach ( array( 'top', 'bottom' ) as $tb ) {
            $enabled = get_theme_mod( "menu_border_{$tb}_enabled", false );
            $pairs[ "--menu-border-{$tb}-width" ]  = $enabled ? get_theme_mod( "menu_border_{$tb}_width", 0 ) . 'px' : '0';
            $pairs[ "--menu-border-{$tb}-style" ]  = $enabled ? get_theme_mod( "menu_border_{$tb}_style", 'none' ) : 'none';
            $pairs[ "--menu-border-{$tb}-color" ]  = $enabled ? get_theme_mod( "menu_border_{$tb}_color", 'transparent' ) : 'transparent';
            $pairs[ "--menu-border-{$tb}-length" ] = get_theme_mod( "menu_border_{$tb}_length", 100 ) . '%';
        }

        foreach ( $pairs as $key => $val ) {
            $vars[] = $key . ':' . esc_attr( $val );
        }

        return implode( ';', $vars );
    }
}
