## **Immediate Fix:**

Replace your entire `customizer.js` with this **fixed version** that uses the proper WordPress customizer binding:

```javascript
(function($){
    'use strict';

    console.log('=== Abundant Thought Customizer Loaded ===');

    /* ============================================================
       PROPER WORDPRESS CUSTOMIZER BINDING
    ============================================================ */

    // Function to update border properties
    function updateBorder(edge, property, value) {
        const cssProperty = `--menu-border-${edge}-${property}`;
        const cssValue = property === 'width' ? value + 'px' : value;

        console.log(`Setting ${cssProperty} to ${cssValue}`);

        // Apply to both document root AND nav container for maximum compatibility
        document.documentElement.style.setProperty(cssProperty, cssValue);

        const nav = document.querySelector('.nav-container, #site-navigation');
        if (nav) {
            nav.style.setProperty(cssProperty, cssValue);
        }
    }

    // Function to handle border enable/disable
    function handleBorderEnable(edge, isEnabled) {
        console.log(`Border ${edge} enabled:`, isEnabled);

        if (isEnabled) {
            // Get current values and apply them
            const width = wp.customize.value('menu_border_' + edge + '_width')();
            const style = wp.customize.value('menu_border_' + edge + '_style')();
            const color = wp.customize.value('menu_border_' + edge + '_color')();

            updateBorder(edge, 'width', width);
            updateBorder(edge, 'style', style);
            updateBorder(edge, 'color', color);
        } else {
            // Disable border
            updateBorder(edge, 'width', '0');
            updateBorder(edge, 'style', 'none');
            updateBorder(edge, 'color', 'transparent');
        }
    }

    /* ============================================================
       BORDER CONTROLS - PROPER BINDING
    ============================================================ */

    ['top', 'bottom'].forEach(function(edge) {

        // Border Enable/Disable - Use proper WordPress binding
        wp.customize('menu_border_' + edge + '_enabled', function(setting) {
            // Initial load
            handleBorderEnable(edge, setting.get());

            // Live updates
            setting.bind(function(newValue) {
                handleBorderEnable(edge, newValue);
            });
        });

        // Individual border properties
        ['width', 'style', 'color'].forEach(function(property) {
            wp.customize('menu_border_' + edge + '_' + property, function(setting) {
                // Live updates
                setting.bind(function(newValue) {
                    console.log(`Border ${edge} ${property} changed to:`, newValue);

                    // Only update if border is enabled
                    if (wp.customize('menu_border_' + edge + '_enabled').get()) {
                        updateBorder(edge, property, newValue);
                    }
                });
            });
        });

        // Border Length
        wp.customize('menu_border_' + edge + '_length', function(setting) {
            setting.bind(function(newValue) {
                updateBorder(edge, 'length', newValue + '%');
            });
        });
    });

    /* ============================================================
       MARGIN & PADDING CONTROLS
    ============================================================ */

    ['menu', 'logo', 'site_title', 'tagline'].forEach(function(element) {
        ['margin', 'padding'].forEach(function(property) {
            wp.customize(element + '_' + property, function(setting) {
                setting.bind(function(newValue) {
                    const cssProperty = '--' + element.replace('_', '-') + '-' + property;
                    console.log(`Setting ${cssProperty} to ${newValue}`);

                    document.documentElement.style.setProperty(cssProperty, newValue);

                    const header = document.querySelector('.site-header');
                    if (header) {
                        header.style.setProperty(cssProperty, newValue);
                    }
                });
            });
        });
    });

    console.log('=== All customizer controls registered ===');

})(jQuery);
```

## **Key Changes Made:**

1. **Proper WordPress binding** using `setting.bind()` instead of `value.bind()`
2. **Initial load handling** - applies settings when customizer first opens
3. **Dual application** - applies CSS variables to both document root AND specific elements
4. **Proper value access** using `wp.customize.value()()`

