```php
<?php
/**
 * Abundant Thought v6 - Core Functions
 */

if (!defined('ABSPATH')) {
    exit; // Exit if accessed directly
}

// Theme setup
function abundantthought_v6_setup() {
    // Make theme available for translation
    load_theme_textdomain('abundant-thought-v6', get_template_directory() . '/languages');

    // Add default posts and comments RSS feed links to head
    add_theme_support('automatic-feed-links');

    // Let WordPress manage the document title
    add_theme_support('title-tag');

    // Enable support for Post Thumbnails
    add_theme_support('post-thumbnails');

    // Register navigation menus
    register_nav_menus(array(
        'primary' => __('Primary Menu', 'abundant-thought-v6'),
        'footer' => __('Footer Menu', 'abundant-thought-v6'),
        'mobile' => __('Mobile Menu', 'abundant-thought-v6'),
    ));

    // Switch default core markup for search form, comment form, and comments to output valid HTML5
    add_theme_support('html5', array(
        'search-form',
        'comment-form',
        'comment-list',
        'gallery',
        'caption',
        'style',
        'script',
    ));

    // Add theme support for selective refresh for widgets
    add_theme_support('customize-selective-refresh-widgets');

    // Add support for core custom logo
    add_theme_support('custom-logo', array(
        'height'      => 100,
        'width'       => 400,
        'flex-width'  => true,
        'flex-height' => true,
    ));

    // Add support for custom background
    add_theme_support('custom-background', array(
        'default-color' => 'ffffff',
        'default-image' => '',
    ));

    // Add support for WooCommerce
    add_theme_support('woocommerce');
    add_theme_support('wc-product-gallery-zoom');
    add_theme_support('wc-product-gallery-lightbox');
    add_theme_support('wc-product-gallery-slider');
}
add_action('after_setup_theme', 'abundantthought_v6_setup');

// Enqueue scripts and styles
function abundantthought_v6_scripts() {
    // Main stylesheet
    wp_enqueue_style('abundantthought-v6-style', get_template_directory_uri() . '/assets/css/main.css', array(), '6.0.0');

    // Responsive styles
    wp_enqueue_style('abundantthought-v6-responsive', get_template_directory_uri() . '/assets/css/responsive.css', array('abundantthought-v6-style'), '6.0.0');

    // Main JavaScript
    wp_enqueue_script('abundantthought-v6-main', get_template_directory_uri() . '/assets/js/main.js', array('jquery'), '6.0.0', true);

    // Navigation JavaScript
    wp_enqueue_script('abundantthought-v6-navigation', get_template_directory_uri() . '/assets/js/navigation.js', array('abundantthought-v6-main'), '6.0.0', true);

    // Comments reply script
    if (is_singular() && comments_open() && get_option('thread_comments')) {
        wp_enqueue_script('comment-reply');
    }
}
add_action('wp_enqueue_scripts', 'abundantthought_v6_scripts');

// Include customizer settings
require get_template_directory() . '/inc/customizer.php';

// Include template tags
require get_template_directory() . '/inc/template-tags.php';

// Include hooks
require get_template_directory() . '/inc/hooks.php';

// Include widgets
require get_template_directory() . '/inc/widgets.php';
