<?php
/**
 * Theme hooks and filters
 */

// Add custom body classes
function abundantthought_v6_body_classes($classes) {
    // Adds a class of hfeed to non-singular pages.
    if (!is_singular()) {
        $classes[] = 'hfeed';
    }

    // Adds a class of no-sidebar when there is no sidebar present.
    if (!is_active_sidebar('sidebar-1')) {
        $classes[] = 'no-sidebar';
    }

    // Add layout class
    $layout = get_theme_mod('layout_type', 'wide');
    $classes[] = 'layout-' . sanitize_html_class($layout);

    // Add header style class
    $header_style = get_theme_mod('header_style', 'style1');
    $classes[] = 'header-' . sanitize_html_class($header_style);

    return $classes;
}
add_filter('body_class', 'abundantthought_v6_body_classes');

