// Sanitization functions
function abundantthought_v6_sanitize_layout($input) {
    $valid = array('wide', 'boxed', 'fullwidth');
    return in_array($input, $valid) ? $input : 'wide';
}

function abundantthought_v6_sanitize_header_layout($input) {
    $valid = array(
        'logo-left-menu-right',
        'logo-center-menu-below', 
        'logo-left-menu-center',
        'logo-center-menu-center',
        'stacked'
    );
    return in_array($input, $valid) ? $input : 'logo-left-menu-right';
}

function abundantthought_v6_sanitize_menu_position($input) {
    $valid = array('above-header', 'in-header', 'below-header');
    return in_array($input, $valid) ? $input : 'in-header';
}

function abundantthought_v6_sanitize_menu_alignment($input) {
    $valid = array('left', 'center', 'right');
    return in_array($input, $valid) ? $input : 'right';
}

function abundantthought_v6_sanitize_font_weight($input) {
    $valid = array('300', '400', '500', '600', '700');
    return in_array($input, $valid) ? $input : '500';
}
