/**
 * Abundant Thought v6 - Customizer Live Preview
 */

(function($) {
    'use strict';

    // Live preview for customizer
    wp.customize.bind('preview-ready', function() {

        // Layout Type
        wp.customize('layout_type', function(value) {
            value.bind(function(to) {
                $('body').removeClass('layout-wide layout-boxed layout-fullwidth').addClass('layout-' + to);
            });
        });

        // Container Width
        wp.customize('container_width', function(value) {
            value.bind(function(to) {
                const styleId = 'abundantthought-container-width';
                let $style = $('#' + styleId);

                if (!$style.length) {
                    $style = $('<style id="' + styleId + '"></style>').appendTo('head');
                }

                $style.text(`
                    .layout-wide .container,
                    .layout-wide .header-container,
                    .layout-wide .footer-container {
                        max-width: ${to}px;
                    }
                `);
            });
        });

        // Header Layout Style
        wp.customize('header_layout_style', function(value) {
            value.bind(function(to) {
                $('body').removeClass(
                    'header-logo-left-menu-right header-logo-center-menu-below header-logo-left-menu-center header-logo-center-menu-center header-stacked'
                ).addClass('header-' + to);
            });
        });

        // Menu Position
        wp.customize('menu_position', function(value) {
            value.bind(function(to) {
                $('body').removeClass('menu-above-header menu-in-header menu-below-header').addClass('menu-' + to);
            });
        });

        // Menu Alignment
        wp.customize('menu_alignment', function(value) {
            value.bind(function(to) {
                $('.main-navigation').removeClass('menu-align-left menu-align-center menu-align-right').addClass('menu-align-' + to);
            });
        });

        // Sticky Header
        wp.customize('sticky_header', function(value) {
            value.bind(function(to) {
                $('body').toggleClass('sticky-header', to);
            });
        });

        // Display Site Title
        wp.customize('display_site_title', function(value) {
            value.bind(function(to) {
                $('.site-title-wrap .site-title').toggle(to);
            });
        });

        // Display Site Tagline
