// Body classes for layout
function abundantthought_v6_body_classes($classes) {
    // Layout classes
    $layout = abundantthought_v6_get_theme_mod('layout_type', 'wide');
    $classes[] = 'layout-' . sanitize_html_class($layout);

    // Header layout class
    $header_layout = abundantthought_v6_get_theme_mod('header_layout_style', 'logo-left-menu-right');
    $classes[] = 'header-' . sanitize_html_class($header_layout);

    // Menu position class
    $menu_position = abundantthought_v6_get_theme_mod('menu_position', 'in-header');
    $classes[] = 'menu-' . sanitize_html_class($menu_position);

    // Menu alignment class
    $menu_alignment = abundantthought_v6_get_theme_mod('menu_alignment', 'right');
    $classes[] = 'menu-align-' . sanitize_html_class($menu_alignment);

    // Sticky header class
    if (abundantthought_v6_get_theme_mod('sticky_header', true)) {
        $classes[] = 'sticky-header';
    }

    // No sidebar class
    if (!is_active_sidebar('sidebar-1')) {
        $classes[] = 'no-sidebar';
    }

    // Hfeed for non-singular pages
    if (!is_singular()) {
        $classes[] = 'hfeed';
    }

    return $classes;
}
