    $classes[] = 'header-' . sanitize_html_class($header_layout);

    // Menu position class
    $menu_position = get_theme_mod('menu_position', 'in-header');
    $classes[] = 'menu-' . sanitize_html_class($menu_position);

    // Menu alignment class
    $menu_alignment = get_theme_mod('menu_alignment', 'right');
    $classes[] = 'menu-align-' . sanitize_html_class($menu_alignment);

    // Sticky header class
    if (get_theme_mod('sticky_header', true)) {
        $classes[] = 'sticky-header';
    }

    // No sidebar class
    if (!is_active_sidebar('sidebar-1')) {
        $classes[] = 'no-sidebar';
    }

    // Hfeed for non-singular pages
    if (!is_singular()) {
        $classes[] = 'hfeed';
    }

    return $classes;
}
