    background: #f8f9fa;
    color: #555;
    margin-top: 60px;
}

.footer-widgets {
    display: grid;
    grid-template-columns: repeat(var(--footer-columns, 4), 1fr);
    gap: 40px;
    padding: 60px 0 40px;
}

.footer-column .widget {
    margin-bottom: 30px;
}

.widget-title {
    font-size: 1.125rem;
    margin-bottom: 20px;
    color: #333;
}

.site-info {
    border-top: 1px solid #ddd;
    padding: 30px 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 20px;
}

.footer-copyright {
    font-size: 0.9rem;
}

.footer-navigation ul {
    display: flex;
    list-style: none;
    gap: 20px;
    margin: 0;
    padding: 0;
}

.footer-navigation a {
    color: inherit;
    text-decoration: none;
    font-size: 0.9rem;
}

.footer-navigation a:hover {
    color: var(--primary-color, #2563eb);
}

/* ===== PAGINATION ===== */
.pagination {
    display: flex;
    justify-content: center;
    gap: 10px;
    margin-top: 40px;
}

.pagination .page-numbers {
    padding: 8px 16px;
    border: 1px solid #ddd;
    text-decoration: none;
    color: #333;
    border-radius: 4px;
    transition: all 0.3s ease;
}

.pagination .page-numbers.current {
    background: var(--primary-color, #2563eb);
    color: #fff;
    border-color: var(--primary-color, #2563eb);
}

.pagination .page-numbers:hover {
    background: #f8f9fa;
    border-color: #999;
}

/* ===== UTILITY CLASSES ===== */
.no-content {
    text-align: center;
    padding: 60px 20px;
}

.no-content h2 {
    margin-bottom: 20px;
    color: #666;
}

/* ===== RESPONSIVE DESIGN ===== */
@media (max-width: 1024px) {
    .footer-widgets {
        grid-template-columns: repeat(2, 1fr);
        gap: 30px;
    }

    .posts-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 20px;
    }

    .header-logo-left-menu-center .header-container {
        gap: 20px;
    }
}

@media (max-width: 768px) {
    .container,
    .header-container,
    .footer-container {
        padding: 0 15px;
    }

    .site-content {
        padding: 30px 0;
    }

    .header-container {
        min-height: 70px;
        gap: 20px;
    }

    .menu-toggle {
        display: flex;
    }

    #primary-menu {
        display: none;
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background: #fff;
        flex-direction: column;
        box-shadow: 0 5px 20px rgba(0,0,0,0.1);
        padding: 20px;
        gap: 0;
    }

    #primary-menu.active {
        display: flex;
    }

    #primary-menu li {
        border-bottom: 1px solid #eee;
    }

    #primary-menu li:last-child {
        border-bottom: none;
    }

    #primary-menu a {
        padding: 15px 0;
    }

    .site-branding {
        flex: 1;
    }

    .header-logo-center-menu-below .header-container,
    .header-logo-center-menu-center .header-container,
    .header-stacked .header-container {
        grid-template-columns: 1fr;
        text-align: left;
    }

    .header-logo-center-menu-below .site-branding,
    .header-logo-center-menu-center .site-branding,
    .header-stacked .site-branding {
        margin-bottom: 0;
    }

    .posts-grid {
        grid-template-columns: 1fr;
        gap: 20px;
    }

    .site-info {
        flex-direction: column;
        text-align: center;
        gap: 15px;
    }

    .footer-navigation ul {
        justify-content: center;
    }

    /* Mobile menu positioning */
    .menu-above-header .above-header-menu,
    .menu-below-header .below-header-menu {
        flex-direction: column;
        gap: 0;
    }

    .menu-above-header .above-header-menu li,
    .menu-below-header .below-header-menu li {
        border-bottom: 1px solid #e9ecef;
    }

    .menu-above-header .above-header-menu a,
    .menu-below-header .below-header-menu a {
        padding: 12px 0;
        display: block;
    }
}

@media (max-width: 480px) {
    .footer-widgets {
        grid-template-columns: 1fr;
        gap: 30px;
    }

    .site-logo img {
        max-height: 50px;
    }

    .site-title {
        font-size: 1.25rem;
    }

    .post-content {
        padding: 20px;
    }

    .post-meta {
        flex-direction: column;
        gap: 5px;
    }

    .pagination {
        flex-wrap: wrap;
    }

    .footer-navigation ul {
        flex-direction: column;
        gap: 10px;
        text-align: center;
    }

    .header-container {
        flex-wrap: wrap;
    }
}

/* Large desktops */
@media (min-width: 1440px) {
    .layout-wide .container,
    .layout-wide .header-container,
    .layout-wide .footer-container {
        max-width: 1400px;
    }
}

/* High DPI displays */
@media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 192dpi) {
    .site-logo img {
        image-rendering: -webkit-optimize-contrast;
        image-rendering: crisp-edges;
    }
}

/* Print styles */
@media print {
    .site-header,
    .site-footer,
    .menu-toggle {
        display: none !important;
    }

    .site-content {
        padding: 0;
        margin: 0;
    }

    .container {
        max-width: none;
        padding: 0;
    }

    a {
        text-decoration: underline !important;
        color: #000 !important;
    }

    .post-card {
        box-shadow: none !important;
        border: 1px solid #000 !important;
        break-inside: avoid;
    }
}
