    function toggleBodyClass(className, add) {
        if (add) {
            $('body').addClass(className);
        } else {
            $('body').removeClass(className);
        }
    }

    /**
     * Update multiple classes on body
     */
    function updateBodyClassGroup(prefix, newValue, validClasses) {
        // Remove all classes with this prefix
        var bodyClasses = $('body').attr('class').split(/\s+/);
        $.each(bodyClasses, function(index, className) {
            if (className.indexOf(prefix) === 0) {
                $('body').removeClass(className);
            }
        });

        // Add new class
        if (validClasses.indexOf(newValue) !== -1) {
            $('body').addClass(prefix + newValue);
        }
