    function loadGoogleFont(fontFamily) {
        if (!fontFamily || fontFamily === 'inherit' || fontFamily === 'default') {
            return;
        }

        // Check if font is already loaded
        var linkId = 'google-font-' + fontFamily.replace(/\s+/g, '-').toLowerCase();
        if ($('#' + linkId).length) {
            return;
        }

        // Create font URL
        var fontUrl = 'https://fonts.googleapis.com/css2?family=' + 
                     fontFamily.replace(/\s+/g, '+') + 
                     ':wght@300;400;500;600;700&display=swap';

        // Add font link to head
        $('head').append(
            '<link id="' + linkId + '" rel="stylesheet" href="' + fontUrl + '">'
        );
    }

