/**
 * Sanitize select choices
 */
function abundantthought_v6_sanitize_select($input, $setting) {
    $input = sanitize_key($input);
    $choices = $setting->manager->get_control($setting->id)->choices;
    return (array_key_exists($input, $choices) ? $input : $setting->default);
}

/**
 * Sanitize numbers with decimals
 */
function abundantthought_v6_sanitize_number($input) {
    return is_numeric($input) ? floatval($input) : 0;
}

/**
 * Sanitize checkbox
 */
function abundantthought_v6_sanitize_checkbox($checked) {
    return ((isset($checked) && true == $checked) ? true : false);
}

/**
 * Render callback for site title
 */
function abundantthought_v6_customize_partial_blogname() {
    bloginfo('name');
}

/**
 * Render callback for site tagline
 */
function abundantthought_v6_customize_partial_blogdescription() {
    bloginfo('description');
}

