```javascript
(function($) {
    'use strict';

    $(document).ready(function() {
        var $grid = $('#portfolio-grid');
        var $filterButtons = $('.filter-btn');

        // Initialize Isotope
        if ($grid.length && $.fn.isotope) {
            $grid.isotope({
                itemSelector: '.portfolio-item',
                layoutMode: 'fitRows'
            });

            // Filter items on button click
            $filterButtons.on('click', function() {
                var filterValue = $(this).attr('data-filter');
                $grid.isotope({ filter: filterValue });
                $filterButtons.removeClass('active');
                $(this).addClass('active');
            });
        } else {
            // Fallback without Isotope: hide all then show selected
            $filterButtons.on('click', function() {
                var filterValue = $(this).attr('data-filter');
                $filterButtons.removeClass('active');
                $(this).addClass('active');

                if (filterValue === '*') {
                    $grid.find('.portfolio-item').show();
                } else {
                    $grid.find('.portfolio-item').hide();
                    $grid.find('.portfolio-item' + filterValue).show();
                }
            });
        }
    });

})(jQuery);
```

