```javascript
/**
 * Abundant Thought v6 - Portfolio Filtering
 * Handles portfolio category filtering with smooth animations
 */

(function($) {
    'use strict';

    // Document ready
    $(document).ready(function() {
        initPortfolioFiltering();
        initPortfolioLightbox();
    });

    /**
     * Portfolio filtering functionality
     */
    function initPortfolioFiltering() {
        const $filterButtons = $('.filter-btn');
        const $portfolioItems = $('.portfolio-item');
        const $portfolioGrid = $('#portfolio-grid');

        // Check if we're on a portfolio page
        if (!$filterButtons.length || !$portfolioItems.length) {
            return;
        }

        // Filter button click handler
        $filterButtons.on('click', function(e) {
            e.preventDefault();

            const $this = $(this);
            const filterValue = $this.data('filter');

            // Update active state
            $filterButtons.removeClass('active');
            $this.addClass('active');

            // Show loading state
            $portfolioGrid.addClass('filtering');

            // Filter items
            if (filterValue === '*') {
                // Show all items
                $portfolioItems.each(function(index) {
                    const $item = $(this);
                    setTimeout(function() {
                        $item.show().addClass('animate-in');
                    }, index * 100);
                });
            } else {
                // Filter by category
                $portfolioItems.hide().removeClass('animate-in');
                $(filterValue).each(function(index) {
                    const $item = $(this);
                    setTimeout(function() {
                        $item.show().addClass('animate-in');
                    }, index * 100);
                });
            }

            // Remove loading state
            setTimeout(function() {
                $portfolioGrid.removeClass('filtering');
            }, $portfolioItems.length * 100 + 200);

            // Update URL for sharing (without page reload)
            updateFilterURL(filterValue);

            // Trigger custom event for other scripts
            $(document).trigger('portfolioFiltered', [filterValue]);
        });

        // Handle browser back/forward buttons
        $(window).on('popstate', function() {
            const urlParams = new URLSearchParams(window.location.search);
            const filter = urlParams.get('filter') || '*';
            applyFilter(filter);
        });

        // Check for filter in URL on page load
        const urlParams = new URLSearchParams(window.location.search);
        const initialFilter = urlParams.get('filter');
        if (initialFilter) {
            const $matchingButton = $('.filter-btn[data-filter=".' + initialFilter + '"]');
            if ($matchingButton.length) {
                $matchingButton.click();
            }
        }
    }

    /**
     * Apply filter programmatically
     */
    function applyFilter(filterValue) {
        const $matchingButton = $('.filter-btn[data-filter="' + filterValue + '"]');
        if ($matchingButton.length) {
            $matchingButton.click();
        }
    }

    /**
     * Update URL with filter parameter
     */
    function updateFilterURL(filterValue) {
        const baseUrl = window.location.origin + window.location.pathname;
        let newUrl = baseUrl;

        if (filterValue && filterValue !== '*') {
            // Remove the dot from class selector
            const category = filterValue.replace('.', '');
            newUrl += '?filter=' + encodeURIComponent(category);
        }

        // Update URL without reloading page
        if (window.history && window.history.pushState) {
            window.history.pushState({ filter: filterValue }, '', newUrl);
        }
    }

    /**
     * Portfolio lightbox functionality
     */
    function initPortfolioLightbox() {
        const $lightboxLinks = $('.portfolio-lightbox');

        if (!$lightboxLinks.length) {
            return;
        }

        $lightboxLinks.on('click', function(e) {
            e.preventDefault();

            const $this = $(this);
            const imageUrl = $this.attr('href');
            const imageTitle = $this.attr('title') || $this.closest('.portfolio-item').find('.portfolio-title').text();

            // Create lightbox overlay
            const $lightbox = $(
                '<div class="portfolio-lightbox-overlay">' +
                    '<div class="lightbox-content">' +
                        '<button class="lightbox-close" aria-label="Close lightbox">&times;</button>' +
                        '<div class="lightbox-image-container">' +
                            '<img src="' + imageUrl + '" alt="' + imageTitle + '">' +
                        '</div>' +
                        '<div class="lightbox-caption">' +
                            '<h3>' + imageTitle + '</h3>' +
                        '</div>' +
                    '</div>' +
                '</div>'
            );

            // Add to page
            $('body').append($lightbox);

            // Show lightbox with animation
            setTimeout(function() {
                $lightbox.addClass('active');
            }, 50);

            // Close lightbox handlers
            function closeLightbox() {
                $lightbox.removeClass('active');
                setTimeout(function() {
                    $lightbox.remove();
                }, 300);
            }

            $lightbox.find('.lightbox-close').on('click', closeLightbox);
            $lightbox.on('click', function(e) {
                if (e.target === this) {
                    closeLightbox();
                }
            });

            // Close on escape key
            $(document).on('keyup.portfolioLightbox', function(e) {
                if (e.key === 'Escape') {
                    closeLightbox();
                    $(document).off('keyup.portfolioLightbox');
                }
            });

            // Prevent body scroll
            $('body').addClass('lightbox-open');

            // Remove body scroll lock when lightbox closes
            $lightbox.on('transitionend', function() {
                if (!$lightbox.hasClass('active')) {
                    $('body').removeClass('lightbox-open');
                }
            });
        });
    }

    /**
     * Utility function to check if element is in viewport
     */
    function isElementInViewport(el) {
        const rect = el.getBoundingClientRect();
        return (
            rect.top >= 0 &&
            rect.left >= 0 &&
            rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) &&
            rect.right <= (window.innerWidth || document.documentElement.clientWidth)
        );
    }

    /**
     * Animate portfolio items on scroll
     */
    function initPortfolioAnimations() {
        const $portfolioItems = $('.portfolio-item');

        if (!$portfolioItems.length) {
            return;
        }

        function checkAnimation() {
            $portfolioItems.each(function() {
                const $item = $(this);
                if (isElementInViewport(this) && !$item.hasClass('animate-in')) {
                    $item.addClass('animate-in');
                }
            });
        }

        // Check on load and scroll
        checkAnimation();
        $(window).on('scroll', window.abundantthoughtDebounce(checkAnimation, 100));
    }

    // Initialize animations when DOM is ready
    $(document).ready(function() {
        initPortfolioAnimations();
    });

})(jQuery);
