/* ===== PORTFOLIO LIGHTBOX ===== */
.portfolio-lightbox-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.9);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 9999;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
}

.portfolio-lightbox-overlay.active {
    opacity: 1;
    visibility: visible;
}

.lightbox-content {
    position: relative;
    max-width: 90%;
    max-height: 90%;
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    transform: scale(0.8);
    transition: transform 0.3s ease;
}

.portfolio-lightbox-overlay.active .lightbox-content {
    transform: scale(1);
}

.lightbox-close {
    position: absolute;
    top: 15px;
    right: 15px;
    background: var(--primary-color, #e67e22);
    color: #fff;
    border: none;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    font-size: 1.5rem;
    cursor: pointer;
    z-index: 10;
    transition: all 0.3s ease;
}

.lightbox-close:hover {
    background: var(--primary-color-dark, #d35400);
    transform: rotate(90deg);
}

.lightbox-image-container {
    max-height: 70vh;
    overflow: hidden;
}

.lightbox-image-container img {
    width: 100%;
    height: auto;
    display: block;
}

.lightbox-caption {
    padding: 20px;
    background: #fff;
}

.lightbox-caption h3 {
    margin: 0;
    color: #333;
    font-size: 1.25rem;
}

/* Body scroll lock when lightbox is open */
body.lightbox-open {
    overflow: hidden;
}

/* Portfolio filtering animation */
#portfolio-grid.filtering {
    opacity: 0.7;
    pointer-events: none;
}

.portfolio-item {
    transition: all 0.3s ease;
}

.portfolio-item.animate-in {
    animation: fadeInUp 0.6s ease-out;
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
