    clear: both;
}

/* Smooth scrolling for all internal links */
html {
    scroll-padding-top: 100px; /* Accounts for sticky header */
}

/* Better focus indicators for keyboard navigation */
:focus-visible {
    outline: 2px dashed var(--primary-color, #2563eb);
