}

/* Tablets */
@media (max-width: 768px) {
    .container,
    .header-container,
    .footer-container {
        padding: 0 15px;
    }

    .site-content {
        padding: 30px 0;
    }

    .header-container {
        min-height: 70px;
        gap: 20px;
    }

