    }
}

/* High DPI displays */
@media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 192dpi) {
    .site-logo img {
        image-rendering: -webkit-optimize-contrast;
        image-rendering: crisp-edges;
    }
}

/* Print styles */
@media print {
    .site-header,
    .site-footer,
    .menu-toggle {
        display: none !important;
    }

    .site-content {
        padding: 0;
        margin: 0;
    }

    .container {
        max-width: none;
        padding: 0;
    }

