function abundantthought_v6_footer_copyright() {
    $custom_copyright = get_theme_mod('footer_copyright', '');
    if (!empty($custom_copyright)) {
        return wp_kses_post($custom_copyright);
    }

    return sprintf(
        '&copy; %s %s. %s',
        date('Y'),
        get_bloginfo('name'),
        __('All rights reserved.', 'abundant-thought-v6')
    );
