    // Header image height
    wp.customize('at_header_image_height', function(value) {
        value.bind(function(to) {
            updateCSSVariable('header-image-height', to + 'px');
        });
    });

    // Header image opacity
    wp.customize('at_header_image_opacity', function(value) {
        value.bind(function(to) {
            updateCSSVariable('header-image-opacity', to);
        });
    });

    // Other settings can be added here similarly

})(jQuery);

