function abundantthought_v6_cpt_templates($template) {
    // Single post templates
    if (is_singular('ebook') && file_exists(get_template_directory() . '/single-ebook.php')) {
        return get_template_directory() . '/single-ebook.php';
    }
    if (is_singular('portfolio') && file_exists(get_template_directory() . '/single-portfolio.php')) {
        return get_template_directory() . '/single-portfolio.php';
    }
    if (is_singular('testimonial') && file_exists(get_template_directory() . '/single-testimonial.php')) {
        return get_template_directory() . '/single-testimonial.php';
    }

    // Archive templates
    if (is_post_type_archive('ebook') && file_exists(get_template_directory() . '/archive-ebook.php')) {
        return get_template_directory() . '/archive-ebook.php';
    }
    if (is_post_type_archive('portfolio') && file_exists(get_template_directory() . '/archive-portfolio.php')) {
        return get_template_directory() . '/archive-portfolio.php';
    }
    if (is_post_type_archive('testimonial') && file_exists(get_template_directory() . '/archive-testimonial.php')) {
        return get_template_directory() . '/archive-testimonial.php';
    }

    // Taxonomy archives
    if (is_tax('ebook_category') && file_exists(get_template_directory() . '/taxonomy-ebook-category.php')) {
        return get_template_directory() . '/taxonomy-ebook-category.php';
    }
    if (is_tax('portfolio_category') && file_exists(get_template_directory() . '/taxonomy-portfolio-category.php')) {
        return get_template_directory() . '/taxonomy-portfolio-category.php';
    }

    return $template;
}
