(function($) {
    'use strict';

    // Function to update CSS variable
    function updateCSSVariable(variableName, value) {
        $('head').append('<style> :root { --' + variableName + ': ' + value + '; } </style>');
    }

    // Header image height
    wp.customize('at_header_image_height', function(value) {
        value.bind(function(to) {
            updateCSSVariable('header-image-height', to + 'px');
        });
    });

    // Header image opacity
    wp.customize('at_header_image_opacity', function(value) {
        value.bind(function(to) {
            updateCSSVariable('header-image-opacity', to);
        });
    });

    // Header image position
    wp.customize('at_header_image_position', function(value) {
        value.bind(function(to) {
            $('.site-header').removeClass('header-image-background header-image-above').addClass('header-image-' + to);
        });
    });

    // Blog name
    wp.customize('blogname', function(value) {
        value.bind(function(to) {
            $('.site-title a').text(to);
        });
    });

    // Blog description
    wp.customize('blogdescription', function(value) {
        value.bind(function(to) {
            $('.site-description').text(to);
        });
