function abundantthought_v6_google_fonts_url() {
    $body_font = get_theme_mod('body_font_family', 'Inter');
    $heading_font = get_theme_mod('heading_font_family', 'Inter');

    $font_families = array();
    if ('Inter' === $body_font || 'Inter' === $heading_font) $font_families[] = 'Inter:300,400,500,600,700';
    if ('Roboto' === $body_font || 'Roboto' === $heading_font) $font_families[] = 'Roboto:300,400,500,700';
    if ('Open Sans' === $body_font || 'Open Sans' === $heading_font) $font_families[] = 'Open+Sans:300,400,500,600,700';
    if ('Lato' === $body_font || 'Lato' === $heading_font) $font_families[] = 'Lato:300,400,700';
    if ('Montserrat' === $body_font || 'Montserrat' === $heading_font) $font_families[] = 'Montserrat:300,400,500,600,700';
    if ('Poppins' === $body_font || 'Poppins' === $heading_font) $font_families[] = 'Poppins:300,400,500,600,700';

    if (empty($font_families)) return '';

    $query_args = array('family' => implode('|', $font_families), 'display' => 'swap');
    return add_query_arg($query_args, 'https://fonts.googleapis.com/css');
}

