// ===== FONT FAMILY HELPER =====
function abundantthought_v6_get_font_family_css($setting, $default) {
    $font = get_theme_mod($setting, $default);
    $system_fonts = array('Arial', 'Helvetica', 'Georgia', 'Times New Roman', 'Trebuchet MS');

    if ('inherit' === $font) return 'inherit';
    if (in_array($font, $system_fonts)) return $font . ', sans-serif';

    $google_fonts = array('Inter', 'Roboto', 'Open Sans', 'Lato', 'Montserrat', 'Poppins');
    if (in_array($font, $google_fonts)) return "'" . $font . "', sans-serif";

    return $default . ', sans-serif';
}

