```javascript
/**
 * Abundant Thought v7 - Navigation Functionality
 * Handles mobile menu, dropdowns, and mega menus
 */

(function($) {
    'use strict';

    class ATNavigation {
        constructor() {
            this.init();
        }

        init() {
            this.mobileMenu();
            this.dropdownMenus();
            this.megaMenus();
            this.searchToggle();
            this.stickyHeader();
        }

        // Mobile Menu Toggle
        mobileMenu() {
            const $menuToggle = $('.at-menu-toggle');
            const $menuContainer = $('.at-primary-nav-container');

            $menuToggle.on('click', function(e) {
                e.preventDefault();
                const $this = $(this);
                const expanded = $this.attr('aria-expanded') === 'true';

                $this.attr('aria-expanded', !expanded);
                $menuContainer.toggleClass('active');
                $('body').toggleClass('at-menu-open');
            });

            // Close menu when clicking outside
            $(document).on('click', function(e) {
                if (!$(e.target).closest('.at-main-navigation').length) {
                    $menuToggle.attr('aria-expanded', 'false');
                    $menuContainer.removeClass('active');
                    $('body').removeClass('at-menu-open');
                }
            });

            // Close menu on escape key
            $(document).on('keyup', function(e) {
                if (e.keyCode === 27) {
                    $menuToggle.attr('aria-expanded', 'false');
                    $menuContainer.removeClass('active');
                    $('body').removeClass('at-menu-open');
                }
            });
        }

        // Dropdown Menu Enhancement
        dropdownMenus() {
            const $menuItems = $('.at-primary-nav .menu-item-has-children > a');

            // Add toggle buttons for mobile
            $menuItems.after('<button class="at-dropdown-toggle" aria-expanded="false"><span class="screen-reader-text">Toggle submenu</span></button>');

            const $dropdownToggles = $('.at-dropdown-toggle');

            // Toggle dropdowns on button click
            $dropdownToggles.on('click', function(e) {
                e.preventDefault();
                e.stopPropagation();

                const $this = $(this);
                const $parent = $this.parent();
                const expanded = $this.attr('aria-expanded') === 'true';

                $this.attr('aria-expanded', !expanded);
                $parent.toggleClass('at-dropdown-open');
            });

            // Close dropdowns when clicking outside
            $(document).on('click', function() {
                $dropdownToggles.attr('aria-expanded', 'false');
                $('.menu-item-has-children').removeClass('at-dropdown-open');
            });

            // Keyboard navigation
            $('.at-primary-nav').on('keydown', 'a', function(e) {
                const $this = $(this);
                const $parent = $this.parent();
                const $submenu = $parent.find('.sub-menu');

                if (e.keyCode === 13 && $submenu.length) {
                    e.preventDefault();
                    $parent.find('.at-dropdown-toggle').trigger('click');
                }
            });
        }

        // Mega Menu Functionality
        megaMenus() {
            const $megaMenus = $('.at-mega-menu');

            $megaMenus.each(function() {
                const $megaMenu = $(this);
                const $submenu = $megaMenu.find('.sub-menu');

                // Add mega menu class for styling
                $submenu.addClass('at-mega-content');

                // Handle hover intent for better UX
                let hoverTimer;
                $megaMenu.hover(
                    function() {
                        clearTimeout(hoverTimer);
                        $megaMenu.addClass('at-mega-open');
                    },
                    function() {
                        hoverTimer = setTimeout(function() {
                            $megaMenu.removeClass('at-mega-open');
                        }, 300);
                    }
                );

                // Touch device support
                if ('ontouchstart' in window) {
                    $megaMenu.on('touchstart', function(e) {
                        if (!$megaMenu.hasClass('at-mega-open')) {
                            e.preventDefault();
                            $('.at-mega-menu').removeClass('at-mega-open');
                            $megaMenu.addClass('at-mega-open');
                        }
                    });
                }
            });

            // Close mega menus on escape
            $(document).on('keyup', function(e) {
                if (e.keyCode === 27) {
                    $('.at-mega-menu').removeClass('at-mega-open');
                }
            });
        }

        // Search Toggle
        searchToggle() {
            const $searchToggle = $('.at-search-toggle');
            const $searchForm = $('.at-search-form');

            $searchToggle.on('click', function(e) {
                e.preventDefault();
                e.stopPropagation();

                const $this = $(this);
                const isActive = $searchForm.hasClass('active');

                // Close all other search forms
                $('.at-search-form').removeClass('active');

                if (!isActive) {
                    $searchForm.addClass('active');
                    $searchForm.find('.search-field').focus();
                }
            });

            // Close search when clicking outside
            $(document).on('click', function(e) {
                if (!$(e.target).closest('.at-header-search').length) {
                    $searchForm.removeClass('active');
                }
            });

            // Close on escape key
            $(document).on('keyup', function(e) {
                if (e.keyCode === 27) {
                    $searchForm.removeClass('active');
                }
            });
        }

        // Sticky Header
        stickyHeader() {
            const $header = $('.at-sticky-header');
            if (!$header.length) return;

            let lastScrollTop = 0;
            const headerHeight = $header.outerHeight();

            $(window).on('scroll', function() {
                const scrollTop = $(this).scrollTop();

                if (scrollTop > headerHeight) {
                    $header.addClass('scrolled');

                    // Hide/show on scroll direction
                    if (scrollTop > lastScrollTop && scrollTop > headerHeight) {
                        $header.addClass('at-header-hidden');
                    } else {
                        $header.removeClass('at-header-hidden');
                    }
                } else {
                    $header.removeClass('scrolled at-header-hidden');
                }

                lastScrollTop = scrollTop;
            });
        }
    }

    // Initialize when document is ready
    $(document).ready(function() {
        new ATNavigation();
    });

})(jQuery);
