/**
 * Abundant Thought v7 - Main JavaScript
 * General theme functionality and enhancements
 */

(function($) {
    'use strict';

    class ATMain {
        constructor() {
            this.init();
        }

        init() {
            this.smoothScroll();
            this.parallaxEffects();
            this.lazyLoading();
            this.contactForm();
            this.animations();
            this.accessibility();
        }

        // Smooth scrolling for anchor links
        smoothScroll() {
            $('a[href*="#"]:not([href="#"])').on('click', function(e) {
                if (location.pathname.replace(/^\//, '') === this.pathname.replace(/^\//, '') && location.hostname === this.hostname) {
                    let target = $(this.hash);
                    target = target.length ? target : $('[name=' + this.hash.slice(1) + ']');

                    if (target.length) {
                        e.preventDefault();
                        $('html, body').animate({
                            scrollTop: target.offset().top - 100
                        }, 1000, 'swing');
                    }
                }
            });
        }

        // Simple parallax effect for background images
        parallaxEffects() {
            const $parallaxElements = $('.at-parallax');

            if ($parallaxElements.length && !this.isMobile()) {
                $(window).on('scroll', function() {
                    const scrolled = $(window).scrollTop();

                    $parallaxElements.each(function() {
                        const $element = $(this);
                        const speed = $element.data('parallax-speed') || 0.5;
                        const yPos = -(scrolled * speed);
                        $element.css('transform', `translateY(${yPos}px)`);
                    });
                });
            }
        }

        // Lazy loading for images
        lazyLoading() {
            if ('IntersectionObserver' in window) {
                const lazyImageObserver = new IntersectionObserver(function(entries) {
                    entries.forEach(function(entry) {
                        if (entry.isIntersecting) {
                            const lazyImage = entry.target;
                            lazyImage.src = lazyImage.dataset.src;
                            if (lazyImage.dataset.srcset) {
                                lazyImage.srcset = lazyImage.dataset.srcset;
                            }
                            lazyImage.classList.remove('lazy');
                            lazyImageObserver.unobserve(lazyImage);
                        }
                    });
                });

                $('img.lazy').each(function() {
                    lazyImageObserver.observe(this);
                });
            }
        }

        // Contact form enhancements
        contactForm() {
            $('.wpcf7-form, .at-contact-form').on('submit', function() {
                const $form = $(this);
                $form.addClass('at-form-submitting');

                // Remove submitting class when form is done
                setTimeout(function() {
                    $form.removeClass('at-form-submitting');
                }, 3000);
            });
        }

        // Scroll animations
        animations() {
            if ('IntersectionObserver' in window) {
                const animationObserver = new IntersectionObserver(function(entries) {
                    entries.forEach(function(entry) {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('at-animate-in');
                            animationObserver.unobserve(entry.target);
                        }
                    });
                }, {
                    threshold: 0.1,
                    rootMargin: '0px 0px -50px 0px'
                });

                $('.at-animate').each(function() {
                    animationObserver.observe(this);
                });
            }
        }

        // Accessibility enhancements
        accessibility() {
            // Add focus states for keyboard navigation
            $('a, button, input, textarea, select').on('focus', function() {
                $(this).addClass('at-focus-visible');
            }).on('blur', function() {
                $(this).removeClass('at-focus-visible');
            });

            // Remove focus styles for mouse users
            let usingMouse = false;
            $('body').on('mousedown', function() {
                usingMouse = true;
            }).on('keydown', function() {
                usingMouse = false;
            });

            $('a, button').on('focus', function() {
                if (usingMouse) {
                    $(this).addClass('at-mouse-focus');
                }
            }).on('blur', function() {
                $(this).removeClass('at-mouse-focus');
            });
        }

        // Mobile detection
        isMobile() {
            return window.matchMedia('(max-width: 767px)').matches;
        }
    }

    // Initialize when document is ready
    $(document).ready(function() {
        new ATMain();
    });

    // Window load events
    $(window).on('load', function() {
        $('body').addClass('at-loaded');
    });

})(jQuery);
