class AT_Recent_Posts_Widget extends WP_Widget {
    public function __construct() {
        parent::__construct(
            'at_recent_posts',
            __('AT Recent Posts', 'abundant-thought-v7'),
            array('description' => __('Recent posts with thumbnails', 'abundant-thought-v7'))
        );
    }

    public function widget($args, $instance) {
        $title = !empty($instance['title']) ? $instance['title'] : __('Recent Posts', 'abundant-thought-v7');
        $number = !empty($instance['number']) ? absint($instance['number']) : 5;
        $show_thumbnail = !empty($instance['show_thumbnail']);
        $show_date = !empty($instance['show_date']);

        echo $args['before_widget'];
        echo $args['before_title'] . apply_filters('widget_title', $title) . $args['after_title'];

        $recent_posts = wp_get_recent_posts(array(
            'numberposts' => $number,
            'post_status' => 'publish',
        ));

        if ($recent_posts) {
            echo '<ul class="at-recent-posts-widget">';
            foreach ($recent_posts as $post) {
                echo '<li class="at-recent-post">';

                if ($show_thumbnail && has_post_thumbnail($post['ID'])) {
                    echo '<div class="at-recent-post-thumbnail">';
                    echo get_the_post_thumbnail($post['ID'], 'thumbnail');
                    echo '</div>';
                }

                echo '<div class="at-recent-post-content">';
                echo '<a href="' . get_permalink($post['ID']) . '">' . get_the_title($post['ID']) . '</a>';

                if ($show_date) {
                    echo '<span class="at-recent-post-date">' . get_the_date('', $post['ID']) . '</span>';
                }

                echo '</div>';
                echo '</li>';
            }
            echo '</ul>';
        }

        echo $args['after_widget'];
    }

    public function form($instance) {
        $title = !empty($instance['title']) ? $instance['title'] : '';
        $number = !empty($instance['number']) ? $instance['number'] : 5;
        $show_thumbnail = !empty($instance['show_thumbnail']);
        $show_date = !empty($instance['show_date']);
        ?>
        <p>
            <label for="<?php echo $this->get_field_id('title'); ?>"><?php _e('Title:', 'abundant-thought-v7'); ?></label>
            <input class="widefat" id="<?php echo $this->get_field_id('title'); ?>" name="<?php echo $this->get_field_name('title'); ?>" type="text" value="<?php echo esc_attr($title); ?>">
        </p>
        <p>
            <label for="<?php echo $this->get_field_id('number'); ?>"><?php _e('Number of posts:', 'abundant-thought-v7'); ?></label>
            <input class="tiny-text" id="<?php echo $this->get_field_id('number'); ?>" name="<?php echo $this->get_field_name('number'); ?>" type="number" value="<?php echo esc_attr($number); ?>" size="3" min="1" max="10">
        </p>
        <p>
            <input class="checkbox" type="checkbox" <?php checked($show_thumbnail); ?> id="<?php echo $this->get_field_id('show_thumbnail'); ?>" name="<?php echo $this->get_field_name('show_thumbnail'); ?>" />
            <label for="<?php echo $this->get_field_id('show_thumbnail'); ?>"><?php _e('Show thumbnails?', 'abundant-thought-v7'); ?></label>
        </p>
        <p>
            <input class="checkbox" type="checkbox" <?php checked($show_date); ?> id="<?php echo $this->get_field_id('show_date'); ?>" name="<?php echo $this->get_field_name('show_date'); ?>" />
            <label for="<?php echo $this->get_field_id('show_date'); ?>"><?php _e('Show dates?', 'abundant-thought-v7'); ?></label>
        </p>
        <?php
    }

    public function update($new_instance, $old_instance) {
        $instance = array();
        $instance['title'] = !empty($new_instance['title']) ? sanitize_text_field($new_instance['title']) : '';
        $instance['number'] = !empty($new_instance['number']) ? absint($new_instance['number']) : 5;
        $instance['show_thumbnail'] = !empty($new_instance['show_thumbnail']);
        $instance['show_date'] = !empty($new_instance['show_date']);
        return $instance;
    }
}

/**
 * Register custom widgets
 */
function abundant_thought_v7_register_widgets() {
    register_widget('AT_Recent_Posts_Widget');
