/**
 * Save meta box content
 */
function abundant_thought_v7_save_page_layout_meta($post_id) {
    // Check nonce
    if (!isset($_POST['at_page_layout_nonce']) || !wp_verify_nonce($_POST['at_page_layout_nonce'], 'at_page_layout_nonce')) {
        return;
    }

    // Check if autosave
    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
        return;
    }

    // Check user permissions
    if (!current_user_can('edit_post', $post_id)) {
        return;
    }

    // Save layout
    if (isset($_POST['at_page_layout'])) {
        update_post_meta($post_id, '_at_page_layout', sanitize_text_field($_POST['at_page_layout']));
    }
}
add_action('save_post', 'abundant_thought_v7_save_page_layout_meta');

/**
 * Apply page layout to body class
 */
function abundant_thought_v7_page_layout_body_class($classes) {
    if (is_singular()) {
        $layout = get_post_meta(get_the_ID(), '_at_page_layout', true);
        if ($layout) {
            $classes[] = 'at-page-layout-' . $layout;
        }
    }
    return $classes;
}
add_filter('body_class', 'abundant_thought_v7_page_layout_body_class');
