#### 3. JavaScript: Progressive Enhancement for Mega Menu
Use simple, robust JavaScript for menu interactions. This example uses a hover-based mega menu.

**File: `/assets/js/navigation.js`**
```javascript
(function($) {
    'use strict';

    // Initialize on document ready
    $(document).ready(function() {
        const $menuItems = $('.at-primary-nav .menu-item-has-children');

        // Desktop: Hover intent for mega menus
        $menuItems.hover(
            function() {
                // Mouse in
                if (!isMobile()) {
                    $(this).addClass('at-menu-item-open');
                    $(this).children('.at-mega-menu').stop(true, true).fadeIn(200);
                }
            },
            function() {
                // Mouse out
                if (!isMobile()) {
                    $(this).removeClass('at-menu-item-open');
                    $(this).children('.at-mega-menu').stop(true, true).fadeOut(100);
                }
            }
        );

        // Mobile: Click toggle for dropdowns
        if (typeof isMobile === 'function' && isMobile()) {
            $menuItems.children('a').on('click', function(e) {
                e.preventDefault();
                const $parent = $(this).parent();
                $parent.toggleClass('at-menu-item-open').siblings().removeClass('at-menu-item-open');
                $parent.children('.at-mega-menu').stop(true, true).slideToggle(200);
            });
        }
    });

    // Simple mobile detection
    function isMobile() {
        return window.innerWidth < 768;
    }

})(jQuery);
```

