/**
 * Sanitize font size values
 */
function abundant_thought_v8_sanitize_font_size( $value ) {
	if ( preg_match( '/^\d+(px|em|rem)$/', $value ) ) {
		return $value;
	}
	return '16px';
}

/**
 * Sanitize float values
 */
function abundant_thought_v8_sanitize_float( $value ) {
	return floatval( $value );
}
