(function($) {
	'use strict';

	// Range Control Value Display
	wp.customize.controlConstructor['abundant-thought-range'] = wp.customize.Control.extend({
		ready: function() {
			var control = this;
			var rangeInput = control.container.find('input[type="range"]');
			var valueDisplay = control.container.find('.abundant-thought-range-value');

			// Update value display on input
			rangeInput.on('input', function() {
				valueDisplay.text($(this).val());
			});

			// Update value display on control load
			valueDisplay.text(rangeInput.val());
		}
	});

	// Toggle Switch Control
	wp.customize.controlConstructor['abundant-thought-toggle'] = wp.customize.Control.extend({
		ready: function() {
			var control = this;
			var toggle = control.container.find('.abundant-thought-toggle__switch');
			var checkbox = control.container.find('input[type="checkbox"]');

			toggle.on('click', function() {
				checkbox.prop('checked', !checkbox.prop('checked')).trigger('change');
			});

			checkbox.on('change', function() {
				var value = $(this).is(':checked') ? true : false;
				control.setting.set(value);
			});
		}
	});

	// Expand/Collapse Advanced Sections
	$(document).ready(function() {
		// Add expand/collapse functionality to sections with advanced controls
