	// Add header layout class for v8
	$header_layout = get_theme_mod( 'at_header_layout', 'minimal' );
	$classes[] = 'at-header-' . sanitize_html_class( $header_layout );

	// Add body class for custom background color
	$background_color = get_theme_mod( 'at_background_color', '#ffffff' );
	if ( $background_color !== '#ffffff' ) {
		$classes[] = 'at-custom-background';
