/**
 * Sanitize header layout selection
 */
function abundant_thought_v8_sanitize_header_layout( $input ) {
	$valid = array( 'minimal', 'centered', 'split', 'stacked' );
	return in_array( $input, $valid ) ? $input : 'minimal';
}

/**
 * Sanitize multiple checkboxes
 */
function abundant_thought_v8_sanitize_multiple_checkboxes( $values ) {
	$multi_values = ! is_array( $values ) ? explode( ',', $values ) : $values;

	if ( ! empty( $multi_values ) ) {
		$valid_values = array( 'search', 'social', 'cta', 'cart' );
		foreach ( $multi_values as $key => $value ) {
			if ( ! in_array( $value, $valid_values ) ) {
				unset( $multi_values[ $key ] );
			}
		}
		return $multi_values;
	}

	return array();
}

/**
 * Sanitize CSS unit values
 */
function abundant_thought_v8_sanitize_css_unit( $value ) {
	if ( preg_match( '/^\d+(\.\d+)?(px|em|rem|%|vh|vw)$/', $value ) ) {
		return $value;
	}
	return '1rem';
}

/**
 * Check if CTA is enabled
 */
function abundant_thought_v8_is_cta_enabled() {
	$elements = get_theme_mod( 'at_header_elements', array( 'search' ) );
	return in_array( 'cta', (array) $elements );
}

/**
 * Check if header border is enabled
 */
function abundant_thought_v8_is_header_border_enabled() {
	return get_theme_mod( 'at_header_border', false );
}

// Register the header settings
add_action( 'customize_register', 'abundant_thought_v8_header_settings' );
