function abundant_thought_v8_display_header_cart() {
	if ( ! class_exists( 'WooCommerce' ) ) {
		return;
	}
	?>
	<div class="at-header-cart">
		<a href="<?php echo esc_url( wc_get_cart_url() ); ?>" class="at-cart-link">
			<span class="at-cart-icon">
				<svg width="20" height="20" viewBox="0 0 20 20" fill="currentColor">
					<path d="M5 4h13l-1.6 7.4a2 2 0 0 1-2 1.6H8.6a2 2 0 0 1-2-1.6L5 4zm0 0l-1-2M7 18a1 1 0 1 0 0-2 1 1 0 0 0 0 2zm9 0a1 1 0 1 0 0-2 1 1 0 0 0 0 2z"/>
				</svg>
			</span>
			<span class="at-cart-count">
				<?php echo WC()->cart->get_cart_contents_count(); ?>
			</span>
		</a>
	</div>
	<?php
}

/**
 * Fallback function for primary menu
 */
function abundant_thought_v8_primary_menu_fallback() {
	?>
	<ul id="primary-menu" class="menu">
		<li class="menu-item">
			<a href="<?php echo esc_url( admin_url( 'nav-menus.php' ) ); ?>">
				<?php esc_html_e( 'Add a menu', 'abundant-thought-v8' ); ?>
			</a>
		</li>
	</ul>
	<?php
}

/**
 * Get social links array
 */
function abundant_thought_v8_get_social_links() {
	return get_theme_mod( 'at_social_links', array() );
}

/**
 * Check if social links are available
 */
function abundant_thought_v8_has_social_links() {
	$social_links = abundant_thought_v8_get_social_links();
	return ! empty( $social_links );
}
