 */
function abundant_thought_v8_sanitize_social_links( $input ) {
	if ( ! is_array( $input ) ) {
		return array();
	}

	$valid_platforms = array(
		'facebook', 'twitter', 'instagram', 'linkedin', 'youtube',
		'pinterest', 'github', 'dribbble', 'behance', 'tiktok',
		'snapchat', 'whatsapp', 'telegram', 'vimeo', 'spotify'
	);

	$sanitized = array();

	foreach ( $input as $link ) {
		if ( ! is_array( $link ) ) {
			continue;
		}

		$platform = sanitize_text_field( $link['platform'] ?? '' );
		$url = esc_url_raw( $link['url'] ?? '' );

		if ( ! empty( $platform ) && ! empty( $url ) && in_array( $platform, $valid_platforms ) ) {
			$sanitized[] = array(
				'platform' => $platform,
				'url'      => $url,
			);
		}
	}

	return $sanitized;
}

