(function() {
	'use strict';

	/**
	 * Mobile Navigation
	 */
	class MobileNavigation {
		constructor() {
			this.menuToggle = document.querySelector('.menu-toggle');
			this.menu = document.querySelector('#primary-menu');
			this.header = document.querySelector('.site-header');

			if (!this.menuToggle || !this.menu) return;

			this.init();
		}

		init() {
			// Toggle menu on button click
			this.menuToggle.addEventListener('click', (e) => {
				e.preventDefault();
				this.toggleMenu();
			});

			// Close menu when clicking outside
			document.addEventListener('click', (e) => {
				if (!this.menu.contains(e.target) && !this.menuToggle.contains(e.target)) {
					this.closeMenu();
				}
			});

			// Close menu on escape key
			document.addEventListener('keydown', (e) => {
				if (e.key === 'Escape') {
					this.closeMenu();
				}
			});

			// Handle window resize
			window.addEventListener('resize', () => {
				this.handleResize();
			});

			// Initialize menu state
			this.handleResize();
		}

		toggleMenu() {
			const isExpanded = this.menuToggle.getAttribute('aria-expanded') === 'true';

			if (isExpanded) {
				this.closeMenu();
			} else {
				this.openMenu();
			}
		}

		openMenu() {
			this.menuToggle.setAttribute('aria-expanded', 'true');
			this.menu.classList.add('toggled-on');
			this.menu.style.display = 'flex';

			// Add body class to prevent scrolling
			document.body.classList.add('menu-open');

			// Focus first menu item for accessibility
			const firstMenuItem = this.menu.querySelector('a');
			if (firstMenuItem) {
				firstMenuItem.focus();
			}
		}

		closeMenu() {
			this.menuToggle.setAttribute('aria-expanded', 'false');
			this.menu.classList.remove('toggled-on');

			// Use setTimeout to allow CSS transition
			setTimeout(() => {
				if (!this.menu.classList.contains('toggled-on')) {
					this.menu.style.display = 'none';
				}
			}, 300);

			// Remove body class
			document.body.classList.remove('menu-open');
		}

		handleResize() {
			const isMobile = window.innerWidth <= 768; // Match CSS breakpoint

			if (isMobile) {
				// Ensure menu is hidden on mobile if not toggled
				if (!this.menu.classList.contains('toggled-on')) {
					this.menu.style.display = 'none';
				}
				this.menuToggle.style.display = 'block';
			} else {
				// Reset menu for desktop
				this.menu.style.display = 'flex';
				this.menu.classList.remove('toggled-on');
				this.menuToggle.setAttribute('aria-expanded', 'false');
				this.menuToggle.style.display = 'none';
				document.body.classList.remove('menu-open');
			}
		}
	}

	/**
	 * Sticky Header
	 */
	class StickyHeader {
		constructor() {
			this.header = document.querySelector('.site-header');
			if (!this.header) return;

			this.init();
		}

		init() {
			// Only initialize if sticky header is enabled
			if (!document.body.classList.contains('at-sticky-header')) return;

			let lastScrollY = window.scrollY;
			const headerHeight = this.header.offsetHeight;

			// Set initial header height CSS variable
			document.documentElement.style.setProperty('--at-header-height', headerHeight + 'px');

			window.addEventListener('scroll', () => {
				const currentScrollY = window.scrollY;

				if (currentScrollY > lastScrollY && currentScrollY > headerHeight) {
					// Scrolling down
					this.header.classList.add('header-hidden');
				} else {
					// Scrolling up
					this.header.classList.remove('header-hidden');
				}

				// Add/remove scrolled class for background
				if (currentScrollY > 50) {
					this.header.classList.add('header-scrolled');
				} else {
					this.header.classList.remove('header-scrolled');
				}

				lastScrollY = currentScrollY;
			});

			// Update header height on resize
			window.addEventListener('resize', () => {
				const newHeight = this.header.offsetHeight;
				document.documentElement.style.setProperty('--at-header-height', newHeight + 'px');
			});
		}
	}

	/**
	 * Smooth Scroll for Anchor Links
	 */
	class SmoothScroll {
		constructor() {
			this.init();
		}

		init() {
			document.addEventListener('click', (e) => {
				const link = e.target.closest('a[href^="#"]');
				if (!link) return;

				const href = link.getAttribute('href');
				if (href === '#') return;

				const target = document.querySelector(href);
				if (!target) return;

				e.preventDefault();
				this.scrollToTarget(target);
			});
		}

		scrollToTarget(target) {
			const headerHeight = document.querySelector('.site-header')?.offsetHeight || 0;
			const targetPosition = target.getBoundingClientRect().top + window.pageYOffset - headerHeight;

			window.scrollTo({
				top: targetPosition,
				behavior: 'smooth'
			});
		}
	}

