				</svg>
			`;

			const searchForm = this.searchContainer.querySelector('.search-form');
			searchForm.style.display = 'none';

			toggle.addEventListener('click', () => {
				const isVisible = searchForm.style.display !== 'none';
				searchForm.style.display = isVisible ? 'none' : 'flex';
				if (!isVisible) {
					searchForm.querySelector('.search-field')?.focus();
				}
			});

			this.searchContainer.prepend(toggle);
		}

		removeMobileToggle() {
			const toggle = this.searchContainer.querySelector('.search-toggle');
			const searchForm = this.searchContainer.querySelector('.search-form');

			if (toggle) {
				toggle.remove();
			}
			if (searchForm) {
				searchForm.style.display = 'flex';
			}
		}
	}

	// Initialize when DOM is loaded
	document.addEventListener('DOMContentLoaded', function() {
		new MobileNavigation();
		new StickyHeader();
		new SmoothScroll();
		new HeaderSearch();
	});

})();
