/**
 * Display related posts
 */
function abundant_thought_v8_display_related_posts() {
	if ( ! get_theme_mod( 'at_show_related_posts', true ) || ! is_single() ) {
		return;
	}

	$current_post_id = get_the_ID();
	$categories = wp_get_post_categories( $current_post_id );

	if ( empty( $categories ) ) {
		return;
	}

	$related_args = array(
		'category__in'   => $categories,
		'post__not_in'   => array( $current_post_id ),
		'posts_per_page' => 3,
		'orderby'        => 'rand',
	);

	$related_posts = new WP_Query( $related_args );

	if ( $related_posts->have_posts() ) {
		echo '<div class="at-related-posts">';
		echo '<h3 class="at-related-posts-title">' . __( 'Related Posts', 'abundant-thought-v8' ) . '</h3>';
		echo '<div class="at-related-posts-grid">';

		while ( $related_posts->have_posts() ) {
			$related_posts->the_post();
			?>
			<article class="at-related-post">
				<?php if ( has_post_thumbnail() && get_theme_mod( 'at_show_featured_images', true ) ) : ?>
					<div class="at-related-post-thumbnail">
						<a href="<?php the_permalink(); ?>">
							<?php the_post_thumbnail( 'medium' ); ?>
						</a>
					</div>
				<?php endif; ?>
				<div class="at-related-post-content">
					<h4 class="at-related-post-title">
						<a href="<?php the_permalink(); ?>"><?php the_title(); ?></a>
					</h4>
					<div class="at-related-post-excerpt">
						<?php the_excerpt(); ?>
					</div>
				</div>
			</article>
			<?php
		}

		echo '</div>';
		echo '</div>';
		wp_reset_postdata();
	}
}
