		$modules = array(
			'global-settings',
			'header-settings', 
			'social-settings',
			'body-settings',
			'sidebar-settings',
			'footer-settings'
		);

		foreach ( $modules as $module ) {
			$file_path = get_template_directory() . '/inc/customizer/' . $module . '.php';
			if ( file_exists( $file_path ) ) {
				require_once $file_path;
			}
		}

		// Initialize modules
		if ( function_exists( 'abundant_thought_v8_global_settings' ) ) {
			abundant_thought_v8_global_settings( $wp_customize );
		}

		// Initialize header settings module
		if ( function_exists( 'abundant_thought_v8_header_settings' ) ) {
			abundant_thought_v8_header_settings( $wp_customize );
		}

		// Initialize social settings module
		if ( function_exists( 'abundant_thought_v8_social_settings' ) ) {
			abundant_thought_v8_social_settings( $wp_customize );
		}

		// Initialize body settings module
		if ( function_exists( 'abundant_thought_v8_body_settings' ) ) {
			abundant_thought_v8_body_settings( $wp_customize );
		}

		// Initialize sidebar settings module
		if ( function_exists( 'abundant_thought_v8_sidebar_settings' ) ) {
			abundant_thought_v8_sidebar_settings( $wp_customize );
		}
	}

	/**
	 * Output dynamic CSS based on customizer settings
	 */
	public function output_dynamic_css() {
		$css = ':root {' . "\n";

		// Global Colors
		$css .= $this->generate_css_variable( '--at-primary-color', get_theme_mod( 'at_primary_color', '#2c5aa0' ) );
		$css .= $this->generate_css_variable( '--at-secondary-color', get_theme_mod( 'at_secondary_color', '#1a365f' ) );
		$css .= $this->generate_css_variable( '--at-accent-color', get_theme_mod( 'at_accent_color', '#d63638' ) );
		$css .= $this->generate_css_variable( '--at-text-color', get_theme_mod( 'at_text_color', '#333333' ) );
		$css .= $this->generate_css_variable( '--at-background-color', get_theme_mod( 'at_background_color', '#ffffff' ) );
		$css .= $this->generate_css_variable( '--at-header-bg-color', get_theme_mod( 'at_header_bg_color', '#ffffff' ) );

		// Typography
		$css .= $this->generate_css_variable( '--at-body-font-size', get_theme_mod( 'at_body_font_size', '16px' ) );
		$css .= $this->generate_css_variable( '--at-body-line-height', get_theme_mod( 'at_body_line_height', '1.6' ) );
		$css .= $this->generate_css_variable( '--at-header-padding-y', get_theme_mod( 'at_header_padding_y', '1rem' ) );

		// Header specific CSS variables
		$css .= $this->generate_css_variable( '--at-header-text-color', get_theme_mod( 'at_header_text_color', '' ) );
		$css .= $this->generate_css_variable( '--at-mobile-breakpoint', get_theme_mod( 'at_mobile_breakpoint', '768' ) . 'px' );

		// Header border
		if ( get_theme_mod( 'at_header_border', false ) ) {
			$border_color = get_theme_mod( 'at_header_border_color', '#e5e5e5' );
			$css .= "  --at-header-border-color: {$border_color};\n";
		}

		// Body & Content CSS Variables
		$css .= $this->generate_css_variable( '--at-container-width', get_theme_mod( 'at_container_width', '1200px' ) );
		$css .= $this->generate_css_variable( '--at-container-padding', get_theme_mod( 'at_container_padding', '1rem' ) );
		$css .= $this->generate_css_variable( '--at-content-bg-color', get_theme_mod( 'at_content_bg_color', '#ffffff' ) );
		$css .= $this->generate_css_variable( '--at-content-text-color', get_theme_mod( 'at_content_text_color', '' ) );
		$css .= $this->generate_css_variable( '--at-content-link-color', get_theme_mod( 'at_content_link_color', '' ) );
		$css .= $this->generate_css_variable( '--at-content-border-radius', get_theme_mod( 'at_content_border_radius', '0' ) );

		// Sidebar CSS Variables
		$css .= $this->generate_css_variable( '--at-sidebar-width', get_theme_mod( 'at_sidebar_width', '30%' ) );
		$css .= $this->generate_css_variable( '--at-sidebar-bg-color', get_theme_mod( 'at_sidebar_bg_color', '#f8f9fa' ) );
		$css .= $this->generate_css_variable( '--at-sidebar-padding', get_theme_mod( 'at_sidebar_padding', '2rem' ) );
		$css .= $this->generate_css_variable( '--at-sidebar-border-radius', get_theme_mod( 'at_sidebar_border_radius', '8px' ) );
		$css .= $this->generate_css_variable( '--at-widget-bg-color', get_theme_mod( 'at_widget_bg_color', '#ffffff' ) );
		$css .= $this->generate_css_variable( '--at-widget-padding', get_theme_mod( 'at_widget_padding', '1.5rem' ) );
		$css .= $this->generate_css_variable( '--at-widget-border-radius', get_theme_mod( 'at_widget_border_radius', '6px' ) );

		$css .= '}' . "\n";

		// Output the CSS
		if ( ! empty( $css ) ) {
			echo '<style type="text/css" id="abundant-thought-v8-dynamic-css">' . $css . '</style>';
		}
	}

	/**
	 * Generate CSS variable string
	 */
	private function generate_css_variable( $variable, $value, $default = '' ) {
		if ( ! empty( $value ) || ! empty( $default ) ) {
			$final_value = ! empty( $value ) ? $value : $default;
			return "  {$variable}: {$final_value};\n";
		}
		return '';
	}

	/**
	 * Enqueue customizer live preview JS
	 */
	public function customizer_live_preview() {
		wp_enqueue_script( 
			'abundant-thought-v8-customizer-preview',
			get_template_directory_uri() . '/assets/js/customizer-preview.js',
			array( 'jquery', 'customize-preview' ),
			'1.0.0',
			true
		);
	}

	/**
	 * Enqueue customizer control scripts
