function abundant_thought_v8_get_footer_layout_class() {
	$layout = get_theme_mod( 'at_footer_layout', 'columns' );
	return 'at-footer-' . sanitize_html_class( $layout );
}

/**
 * Get number of footer columns
 */
function abundant_thought_v8_get_footer_columns() {
	return get_theme_mod( 'at_footer_columns', 3 );
}

/**
 * Check if footer bottom bar should be displayed
 */
function abundant_thought_v8_should_display_footer_bottom() {
	return get_theme_mod( 'at_show_footer_bottom', true );
}

/**
 * Check if footer social links should be displayed
 */
function abundant_thought_v8_should_display_footer_social() {
	return get_theme_mod( 'at_show_footer_social', true ) && abundant_thought_v8_has_social_links();
}

/**
 * Display footer social links
 */
function abundant_thought_v8_display_footer_social_links() {
	if ( ! abundant_thought_v8_should_display_footer_social() ) {
		return;
	}

	$social_links = abundant_thought_v8_get_social_links();
	if ( empty( $social_links ) ) {
		return;
	}

	$new_tab = get_theme_mod( 'at_social_links_new_tab', true );
	$target = $new_tab ? ' target="_blank" rel="noopener noreferrer"' : '';

	echo '<div class="at-footer-social-links">';
	foreach ( $social_links as $social ) {
		if ( ! empty( $social['url'] ) && ! empty( $social['platform'] ) ) {
			$icon = abundant_thought_v8_get_social_icon( $social['platform'] );
			echo '<a href="' . esc_url( $social['url'] ) . '" class="footer-social-link footer-social-' . esc_attr( $social['platform'] ) . '"' . $target . '>';
			echo $icon;
			echo '<span class="screen-reader-text">' . esc_html( $social['platform'] ) . '</span>';
			echo '</a>';
		}
	}
	echo '</div>';
}

/**
 * Get copyright text
 */
function abundant_thought_v8_get_copyright_text() {
	$default = sprintf(
		/* translators: 1: Current year, 2: Site name */
		__( '© %1$s %2$s. All rights reserved.', 'abundant-thought-v8' ),
		date( 'Y' ),
		get_bloginfo( 'name' )
	);

	return get_theme_mod( 'at_copyright_text', $default );
}
