	$container_width = get_theme_mod( 'at_container_width', '1200px' );
	$classes[] = 'at-container-' . sanitize_html_class( str_replace( 'px', '', $container_width ) );

	// Add footer layout class
	$footer_layout = get_theme_mod( 'at_footer_layout', 'columns' );
