<?php
/**
 * Sanitization functions for Abundant Thought v8
 * 
 * @package Abundant_Thought_v8
 */

// Exit if accessed directly.
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Sanitize checkbox values
 */
function abundant_thought_v8_sanitize_checkbox( $input ) {
	return ( isset( $input ) && true == $input ) ? true : false;
}

/**
 * Sanitize select choices
 */
function abundant_thought_v8_sanitize_select( $input, $setting ) {
	$input = sanitize_key( $input );
	$choices = $setting->manager->get_control( $setting->id )->choices;
	return ( array_key_exists( $input, $choices ) ? $input : $setting->default );
}

/**
 * Sanitize RGB color values
 */
function abundant_thought_v8_sanitize_rgb_color( $color ) {
	if ( empty( $color ) || is_array( $color ) ) {
		return 'rgb(255, 255, 255)';
	}

	if ( false === strpos( $color, 'rgb' ) ) {
		return abundant_thought_v8_sanitize_hex_color( $color );
	}

	$color = str_replace( array( ' ', 'rgb(', 'rgba(', ')' ), '', $color );
	$color = explode( ',', $color );

	// RGB should have exactly 3 values
	if ( 3 !== count( $color ) ) {
		return 'rgb(255, 255, 255)';
	}

	$red   = abundant_thought_v8_sanitize_color_component( $color[0] );
	$green = abundant_thought_v8_sanitize_color_component( $color[1] );
	$blue  = abundant_thought_v8_sanitize_color_component( $color[2] );

	return "rgb({$red}, {$green}, {$blue})";
}

/**
 * Sanitize individual color component
 */
function abundant_thought_v8_sanitize_color_component( $component ) {
	$component = intval( $component );
	$component = max( 0, $component );
	$component = min( 255, $component );
	return $component;
}

/**
 * Sanitize hex color
 */
function abundant_thought_v8_sanitize_hex_color( $color ) {
	if ( '' === $color ) {
		return '';
	}

	// 3 or 6 hex digits, or the empty string.
	if ( preg_match( '|^#([A-Fa-f0-9]{3}){1,2}$|', $color ) ) {
		return $color;
	}

	return '';
}

/**
 * Sanitize font size values
 */
function abundant_thought_v8_sanitize_font_size( $value ) {
	if ( preg_match( '/^\d+(px|em|rem)$/', $value ) ) {
		return $value;
	}
	return '16px';
}

/**
 * Sanitize float values
 */
function abundant_thought_v8_sanitize_float( $value ) {
	return floatval( $value );
}

/**
 * Sanitize integer values
 */
function abundant_thought_v8_sanitize_int( $value ) {
	return intval( $value );
}

/**
 * Sanitize textarea
 */
function abundant_thought_v8_sanitize_textarea( $input ) {
	return wp_kses_post( $input );
}

/**
 * Sanitize HTML
 */
function abundant_thought_v8_sanitize_html( $input ) {
	return wp_kses_post( $input );
}

/**
 * Sanitize CSS unit values
 */
function abundant_thought_v8_sanitize_css_unit( $value ) {
	if ( preg_match( '/^\d+(\.\d+)?(px|em|rem|%|vh|vw)$/', $value ) ) {
		return $value;
	}
	return '1rem';
}

/**
 * Sanitize header layout selection
 */
function abundant_thought_v8_sanitize_header_layout( $input ) {
	$valid = array( 'minimal', 'centered', 'split', 'stacked' );
	return in_array( $input, $valid ) ? $input : 'minimal';
}

/**
 * Sanitize multiple checkboxes
 */
function abundant_thought_v8_sanitize_multiple_checkboxes( $values ) {
	$multi_values = ! is_array( $values ) ? explode( ',', $values ) : $values;

	if ( ! empty( $multi_values ) ) {
		$valid_values = array( 'search', 'social', 'cta', 'cart' );
		foreach ( $multi_values as $key => $value ) {
			if ( ! in_array( $value, $valid_values ) ) {
				unset( $multi_values[ $key ] );
			}
		}
		return $multi_values;
	}

	return array();
}

/**
 * Sanitize blog layout selection
 */
function abundant_thought_v8_sanitize_blog_layout( $input ) {
	$valid = array( 'list', 'grid', 'masonry' );
	return in_array( $input, $valid ) ? $input : 'list';
}

/**
 * Sanitize sidebar layout selection
 */
function abundant_thought_v8_sanitize_sidebar_layout( $input ) {
	$valid = array( 'right', 'left', 'none' );
	return in_array( $input, $valid ) ? $input : 'right';
}

/**
 * Sanitize footer layout selection
 */
function abundant_thought_v8_sanitize_footer_layout( $input ) {
	$valid = array( 'columns', 'simple', 'minimal' );
	return in_array( $input, $valid ) ? $input : 'columns';
}

/**
 * Sanitize social links array
 */
function abundant_thought_v8_sanitize_social_links( $input ) {
	if ( ! is_array( $input ) ) {
		return array();
	}

	$valid_platforms = array(
		'facebook', 'twitter', 'instagram', 'linkedin', 'youtube',
		'pinterest', 'github', 'dribbble', 'behance', 'tiktok',
		'snapchat', 'whatsapp', 'telegram', 'vimeo', 'spotify'
	);

	$sanitized = array();

	foreach ( $input as $link ) {
		if ( ! is_array( $link ) ) {
			continue;
		}

		$platform = sanitize_text_field( $link['platform'] ?? '' );
		$url = esc_url_raw( $link['url'] ?? '' );

		if ( ! empty( $platform ) && ! empty( $url ) && in_array( $platform, $valid_platforms ) ) {
			$sanitized[] = array(
				'platform' => $platform,
				'url'      => $url,
			);
		}
	}

	return $sanitized;
}
