(function($) {
    "use strict";

    // Toggle Control Handler
    wp.customize.bind('ready', function() {
        // Toggle controls visibility based on dependencies
        function abundant_thought_v8_handle_toggles() {
            $('.customize-control-toggle').each(function() {
                var $toggle = $(this);
                var $checkbox = $toggle.find('input[type="checkbox"]');
                var $slider = $toggle.find('.toggle-slider');

                // Initialize state
                if ($checkbox.is(':checked')) {
                    $toggle.addClass('active');
                    $slider.addClass('active');
                }

                // Toggle on click
                $toggle.on('click', function(e) {
                    e.preventDefault();
                    var isChecked = $checkbox.is(':checked');

                    $checkbox.prop('checked', !isChecked).trigger('change');
                    $toggle.toggleClass('active', !isChecked);
                    $slider.toggleClass('active', !isChecked);

                    // Trigger customizer change
                    wp.customize($checkbox.attr('data-customize-setting-link')).set(!isChecked);
                });
            });
        }

        // Range Slider Handler
        function abundant_thought_v8_handle_sliders() {
            $('.customize-control-range .slider').each(function() {
                var $slider = $(this);
                var $input = $slider.siblings('input');
                var $value = $slider.siblings('.slider-value');

                $slider.slider({
                    range: 'min',
                    value: $input.val(),
                    min: parseInt($slider.data('min')),
                    max: parseInt($slider.data('max')),
                    step: parseInt($slider.data('step')),
                    slide: function(event, ui) {
                        $input.val(ui.value).trigger('change');
                        $value.text(ui.value);
                        wp.customize($input.attr('data-customize-setting-link')).set(ui.value);
                    }
                });
            });
        }

        // Initialize controls
        abundant_thought_v8_handle_toggles();
        abundant_thought_v8_handle_sliders();

