/**
 * Check if sidebar should be displayed
 */
function abundant_thought_v8_display_sidebar() {
    $sidebar_layout = get_theme_mod('abundant_thought_v8_sidebar_layout', 'right-sidebar');
    $display_sidebar = true;

    // Hide sidebar on full-width pages
    if (is_page() && $sidebar_layout === 'no-sidebar') {
        $display_sidebar = false;
    }

    // Hide sidebar if no widgets active
    if (!is_active_sidebar('sidebar-1')) {
        $display_sidebar = false;
    }

    return apply_filters('abundant_thought_v8_display_sidebar', $display_sidebar);
}

/**
 * Get content class based on sidebar layout
 */
function abundant_thought_v8_content_class() {
    $sidebar_layout = get_theme_mod('abundant_thought_v8_sidebar_layout', 'right-sidebar');
    $classes = array('site-main');

    if (abundant_thought_v8_display_sidebar()) {
        $classes[] = 'has-sidebar';
        $classes[] = $sidebar_layout;
    } else {
        $classes[] = 'no-sidebar';
        $classes[] = 'full-width';
    }

    return implode(' ', $classes);
}

/**
 * Display post meta information
 */
function abundant_thought_v8_post_meta() {
    echo '<div class="entry-meta">';

    // Author
    echo '<span class="byline">';
    echo '<span class="author vcard">';
    printf(
        __('By %s', 'abundant-thought-v8'),
        '<a class="url fn n" href="' . esc_url(get_author_posts_url(get_the_author_meta('ID'))) . '">' . esc_html(get_the_author()) . '</a>'
    );
    echo '</span>';
    echo '</span>';

    // Date
    echo '<span class="posted-on">';
    echo '<time class="entry-date published" datetime="' . esc_attr(get_the_date('c')) . '">';
    echo esc_html(get_the_date());
    echo '</time>';
    echo '</span>';

    // Categories
    if ('post' === get_post_type()) {
        $categories_list = get_the_category_list(__(', ', 'abundant-thought-v8'));
        if ($categories_list) {
            echo '<span class="cat-links">' . $categories_list . '</span>';
        }
    }

    // Comments
    if (!post_password_required() && (comments_open() || get_comments_number())) {
        echo '<span class="comments-link">';
        comments_popup_link(
            __('Leave a comment', 'abundant-thought-v8'),
            __('1 Comment', 'abundant-thought-v8'),
            __('% Comments', 'abundant-thought-v8')
        );
        echo '</span>';
    }

    echo '</div>';
}

/**
 * Display post thumbnail with fallback
 */
function abundant_thought_v8_post_thumbnail($size = 'post-thumbnail') {
    if (post_password_required() || is_attachment() || !has_post_thumbnail()) {
        return;
    }

    if (is_singular()) {
        echo '<div class="post-thumbnail">';
        the_post_thumbnail($size);
        echo '</div>';
    } else {
        echo '<div class="post-thumbnail">';
        echo '<a href="' . esc_url(get_permalink()) . '" aria-hidden="true" tabindex="-1">';
        the_post_thumbnail($size, array(
            'alt' => the_title_attribute(array('echo' => false)),
        ));
        echo '</a>';
        echo '</div>';
    }
}
