```javascript
/**
 * Abundant Thought v8 - Customizer Controls JavaScript
 * Debugged and optimized toggle/slider functionality
 */

(function($) {
    "use strict";

    // Wait for customizer to be ready
    wp.customize.bind('ready', function() {

        /**
         * Toggle Switch Control Handler
         */
        function abundantThoughtHandleToggles() {
            $('.toggle-switch-control').each(function() {
                var $control = $(this);
                var $checkbox = $control.find('.toggle-checkbox');
                var $toggleLabel = $control.find('.toggle-label');
                var setting = $checkbox.data('customize-setting-link');

                if (!setting) return;

                // Initialize toggle state
                var currentValue = wp.customize(setting).get();
                $checkbox.prop('checked', currentValue);
                updateToggleState($checkbox, currentValue);

                // Toggle on click
                $toggleLabel.on('click', function(e) {
                    e.preventDefault();
                    var newValue = !$checkbox.prop('checked');

                    $checkbox.prop('checked', newValue).trigger('change');
                    updateToggleState($checkbox, newValue);

                    // Update customizer setting
                    wp.customize(setting).set(newValue);
                });

                // Handle checkbox change
                $checkbox.on('change', function() {
                    updateToggleState($(this), $(this).prop('checked'));
                });

                // Listen for customizer changes
                wp.customize(setting, function(value) {
                    value.bind(function(newVal) {
                        $checkbox.prop('checked', newVal);
                        updateToggleState($checkbox, newVal);
                    });
                });
            });
        }

        /**
         * Update toggle visual state
         */
        function updateToggleState($checkbox, isChecked) {
            var $toggleLabel = $checkbox.siblings('.toggle-label');
            if (isChecked) {
                $toggleLabel.addClass('active');
            } else {
                $toggleLabel.removeClass('active');
            }
        }

        /**
         * Range Slider Control Handler
         */
        function abundantThoughtHandleSliders() {
            $('.range-slider-control').each(function() {
                var $control = $(this);
                var $slider = $control.find('.slider');
                var $valueDisplay = $control.find('.slider-value');
                var $suffix = $control.find('.slider-suffix');
                var setting = $slider.data('customize-setting-link');

                if (!setting) return;

                // Get slider attributes
                var min = parseInt($slider.attr('min')) || 0;
                var max = parseInt($slider.attr('max')) || 100;
                var step = parseInt($slider.attr('step')) || 1;
                var suffix = $suffix.text() || '';

                // Initialize slider value
                var currentValue = wp.customize(setting).get();
                $slider.val(currentValue);
                $valueDisplay.text(currentValue);

                // Update on slider input
                $slider.on('input change', function() {
                    var newValue = $(this).val();
                    $valueDisplay.text(newValue);

                    // Update customizer setting
                    wp.customize(setting).set(newValue);
                });

                // Listen for customizer changes
                wp.customize(setting, function(value) {
                    value.bind(function(newVal) {
                        $slider.val(newVal);
                        $valueDisplay.text(newVal);
                    });
                });

                // Add keyboard support
                $slider.on('keydown', function(e) {
                    var currentVal = parseInt($(this).val());

                    switch(e.which) {
                        case 38: // Up arrow
                        case 39: // Right arrow
                            e.preventDefault();
                            var newVal = Math.min(currentVal + step, max);
                            $(this).val(newVal).trigger('change');
                            break;

                        case 37: // Left arrow
                        case 40: // Down arrow
                            e.preventDefault();
                            var newVal = Math.max(currentVal - step, min);
                            $(this).val(newVal).trigger('change');
                            break;
                    }
                });
            });
        }

        /**
         * Initialize all controls
         */
        function initializeControls() {
            abundantThoughtHandleToggles();
            abundantThoughtHandleSliders();
        }

        // Initialize controls when ready
        initializeControls();

        // Re-initialize when section expands (for dynamically loaded controls)
        wp.customize.section.each(function(section) {
            section.expanded.bind(function(isExpanded) {
                if (isExpanded) {
                    setTimeout(initializeControls, 100);
                }
            });
        });

        // Handle preview ready state
        wp.customize.previewer.bind('ready', function() {
            initializeControls();
        });

    });

    /**
     * Conditional Control Dependencies
     */
    wp.customize.bind('ready', function() {

        // Show/Hide controls based on dependencies
        function handleControlDependencies() {
            // Example: Show header height only if sticky header is enabled
            wp.customize('abundant_thought_v8_sticky_header', function(value) {
                value.bind(function(newVal) {
                    var $headerHeightControl = $('#customize-control-abundant_thought_v8_header_height');
                    if (newVal) {
                        $headerHeightControl.show();
                    } else {
                        $headerHeightControl.hide();
                    }
                });
            });

            // Show grid columns only if grid layout is selected
            wp.customize('abundant_thought_v8_blog_layout', function(value) {
                value.bind(function(newVal) {
                    var $gridColumnsControl = $('#customize-control-abundant_thought_v8_grid_columns');
                    if (newVal === 'grid') {
                        $gridColumnsControl.show();
                    } else {
                        $gridColumnsControl.hide();
                    }
                });
            });

            // Show footer widget columns only if footer widgets are enabled
            wp.customize('abundant_thought_v8_footer_widgets', function(value) {
                value.bind(function(newVal) {
                    var $footerColumnsControl = $('#customize-control-abundant_thought_v8_footer_widgets_columns');
                    if (newVal) {
                        $footerColumnsControl.show();
                    } else {
                        $footerColumnsControl.hide();
                    }
                });
            });
        }

        // Initialize dependencies
        handleControlDependencies();

    });

})(jQuery);
