    function abundantThoughtMobileMenu() {
        var $mobileToggle = $('.mobile-menu-toggle');
        var $mainNavigation = $('.main-navigation');
        var $primaryMenu = $('#primary-menu');

        if (!$mobileToggle.length || !$mainNavigation.length) return;

        // Toggle mobile menu
        $mobileToggle.on('click', function(e) {
            e.preventDefault();
            e.stopPropagation();

            var $this = $(this);
            var isExpanded = $this.attr('aria-expanded') === 'true';

            // Toggle states
            $this.toggleClass('active');
            $mainNavigation.toggleClass('active');
            $('body').toggleClass('mobile-menu-open');

            // Update accessibility attributes
            $this.attr('aria-expanded', !isExpanded);
            $mainNavigation.attr('aria-hidden', isExpanded);

            // Focus management
            if (!isExpanded) {
                setTimeout(function() {
                    $primaryMenu.find('a').first().focus();
                }, 300);
            }
        });

        // Close mobile menu when clicking outside
        $(document).on('click', function(e) {
            if (!$(e.target).closest('.main-navigation, .mobile-menu-toggle').length) {
                closeMobileMenu();
            }
        });

        // Close mobile menu on escape key
        $(document).on('keyup', function(e) {
            if (e.keyCode === 27) { // Escape key
                closeMobileMenu();
            }
        });

        // Close mobile menu when clicking on a link (for single page sites)
        $mainNavigation.find('a').on('click', function() {
            if ($(window).width() < 769) { // Mobile breakpoint
                closeMobileMenu();
            }
        });

        // Helper function to close mobile menu
        function closeMobileMenu() {
            $mobileToggle.removeClass('active').attr('aria-expanded', 'false');
            $mainNavigation.removeClass('active').attr('aria-hidden', 'true');
            $('body').removeClass('mobile-menu-open');
            $mobileToggle.focus();
        }

        // Handle window resize
        let resizeTimer;
