    /**
     * Smooth Scrolling for Anchor Links
     */
    function abundantThoughtSmoothScroll() {
        $('a[href*="#"]')
            .not('[href="#"]')
            .not('[href="#0"]')
            .not('[href*="modal"]')
            .not('[href*="tab"]')
            .click(function(event) {
                if (
                    location.pathname.replace(/^\//, '') === this.pathname.replace(/^\//, '') 
                    && 
                    location.hostname === this.hostname
                ) {
                    var target = $(this.hash);
                    target = target.length ? target : $('[name=' + this.hash.slice(1) + ']');

                    if (target.length) {
                        event.preventDefault();
                        $('html, body').animate({
                            scrollTop: target.offset().top - 100
                        }, 800, function() {
                            var $target = $(target);
                            $target.focus();
                            if ($target.is(":focus")) {
                                return false;
                            } else {
                                $target.attr('tabindex','-1');
                                $target.focus();
                            }
                        });
                    }
                }
            });
    }

    /**
     * Sticky Header Behavior
     */
    function abundantThoughtStickyHeader() {
        var $header = $('#masthead');
        var $body = $('body');

        if (!$header.length || !$body.hasClass('sticky-header')) return;

        var headerHeight = $header.outerHeight();
        var lastScrollTop = 0;
        var delta = 5;
        var didScroll = false;

        // Add padding to body to account for sticky header
        $('body').css('padding-top', headerHeight);

        // Scroll event handler
        $(window).on('scroll', function() {
            didScroll = true;
        });

        // Check scroll position periodically
        setInterval(function() {
            if (didScroll) {
                hasScrolled();
                didScroll = false;
            }
        }, 250);

        function hasScrolled() {
            var st = $(this).scrollTop();

            // Make sure they scroll more than delta
            if (Math.abs(lastScrollTop - st) <= delta) return;

            // If they scrolled down and are past the header, add class
            if (st > lastScrollTop && st > headerHeight) {
                // Scroll Down
                $header.removeClass('header-visible').addClass('header-hidden');
            } else {
                // Scroll Up
                if (st + $(window).height() < $(document).height()) {
                    $header.removeClass('header-hidden').addClass('header-visible');
                }
            }

            lastScrollTop = st;
        }
    }

    /**
     * Skip Link Focus Fix
     */
    function abundantThoughtSkipLinkFocus() {
        var isIe = /(trident|msie)/i.test(navigator.userAgent);

        if (isIe && document.getElementById && window.addEventListener) {
            window.addEventListener('hashchange', function() {
                var id = location.hash.substring(1),
                    element;

                if (!(/^[A-z0-9_-]+$/.test(id))) {
                    return;
                }

                element = document.getElementById(id);

                if (element) {
                    if (!(/^(?:a|select|input|button|textarea)$/i.test(element.tagName))) {
                        element.tabIndex = -1;
                    }

                    element.focus();
                }
            }, false);
        }
    }

    /**
     * Initialize all functionality when document is ready
     */
    $(document).ready(function() {
        abundantThoughtMobileMenu();
        abundantThoughtSmoothScroll();
        abundantThoughtStickyHeader();
        abundantThoughtSkipLinkFocus();

        // Add loaded class to body for CSS transitions
        setTimeout(function() {
            $('body').addClass('loaded');
        }, 100);
    });

    /**
     * Handle custom events from customizer
     */
    $(document).on('headerLayoutChanged', function(event, layout) {
        // Re-initialize mobile menu if header layout changes
        setTimeout(abundantThoughtMobileMenu, 100);
    });

})(jQuery);
