```javascript
/**
 * Abundant Thought v8 - Customizer Controls JavaScript
 * FIXED: Proper initialization timing and event handling
 */

(function($) {
    "use strict";

    // Initialize when both DOM and Customizer are ready
    function abundantThoughtInitControls() {
        console.log('Abundant Thought: Initializing customizer controls...');

        initToggleSwitches();
        initRangeSliders();
        initControlDependencies();
    }

    /**
     * Toggle Switch Controls
     */
    function initToggleSwitches() {
        $('.toggle-switch-control').each(function() {
            var $control = $(this);
            var $checkbox = $control.find('.toggle-checkbox');
            var $toggleLabel = $control.find('.toggle-label');
            var settingId = $checkbox.attr('id');

            if (!settingId) return;

            // Get the setting name from data attribute or ID
            var settingName = $checkbox.data('customize-setting-link') || settingId;

            // Initialize current state
            var currentValue = wp.customize(settingName).get();
            $checkbox.prop('checked', currentValue);
            updateToggleState($toggleLabel, currentValue);

            // Handle toggle click
            $toggleLabel.off('click').on('click', function(e) {
                e.preventDefault();
                e.stopPropagation();

                var newValue = !$checkbox.prop('checked');
                $checkbox.prop('checked', newValue);
                updateToggleState($toggleLabel, newValue);

                // Update customizer setting
                wp.customize(settingName).set(newValue);
            });

            // Listen for external changes
            wp.customize(settingName, function(value) {
                value.bind(function(newVal) {
                    $checkbox.prop('checked', newVal);
                    updateToggleState($toggleLabel, newVal);
                });
            });
        });
    }

    function updateToggleState($toggleLabel, isActive) {
        if (isActive) {
            $toggleLabel.addClass('active');
        } else {
            $toggleLabel.removeClass('active');
        }
    }

    /**
     * Range Slider Controls
     */
    function initRangeSliders() {
        $('.range-slider-control').each(function() {
            var $control = $(this);
            var $slider = $control.find('.slider');
            var $valueDisplay = $control.find('.slider-value');
            var settingId = $slider.attr('name');

            if (!settingId) return;

            var settingName = $slider.data('customize-setting-link') || settingId;
            var min = parseInt($slider.attr('min')) || 0;
            var max = parseInt($slider.attr('max')) || 100;
            var step = parseInt($slider.attr('step')) || 1;

            // Initialize current value
            var currentValue = wp.customize(settingName).get();
            $slider.val(currentValue);
            $valueDisplay.text(currentValue);

            // Handle slider input
            $slider.off('input change').on('input change', function() {
                var newValue = $(this).val();
                $valueDisplay.text(newValue);
                wp.customize(settingName).set(newValue);
            });

            // Listen for external changes
            wp.customize(settingName, function(value) {
                value.bind(function(newVal) {
                    $slider.val(newVal);
                    $valueDisplay.text(newVal);
                });
            });

            // Keyboard support
            $slider.off('keydown').on('keydown', function(e) {
                var currentVal = parseInt($(this).val());
                var newVal = currentVal;

                switch(e.which) {
                    case 38: // Up arrow
                    case 39: // Right arrow
                        e.preventDefault();
                        newVal = Math.min(currentVal + step, max);
                        break;
                    case 37: // Left arrow
                    case 40: // Down arrow
                        e.preventDefault();
                        newVal = Math.max(currentVal - step, min);
                        break;
                }

                if (newVal !== currentVal) {
                    $(this).val(newVal).trigger('change');
                }
            });
        });
    }

    /**
     * Control Dependencies
     */
    function initControlDependencies() {
        // Show/Hide header height when sticky header is enabled
        wp.customize('abundant_thought_v8_sticky_header', function(value) {
