    // Global navigation state
    var navigation = {
        isMobileMenuOpen: false,
        $mobileToggle: null,
        $mainNavigation: null,
        $primaryMenu: null
    };

    /**
     * Initialize mobile menu functionality
     */
    function initMobileMenu() {
        navigation.$mobileToggle = $('.mobile-menu-toggle');
        navigation.$mainNavigation = $('.main-navigation');
        navigation.$primaryMenu = $('#primary-menu');

        // Ensure mobile toggle is visible on mobile
        updateMobileToggleVisibility();

        // Initialize mobile menu toggle
        navigation.$mobileToggle.off('click').on('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            toggleMobileMenu();
        });

        // Close mobile menu when clicking outside
        $(document).off('click').on('click', function(e) {
            if (navigation.isMobileMenuOpen && !$(e.target).closest('.main-navigation, .mobile-menu-toggle').length) {
                closeMobileMenu();
            }
        });

        // Close mobile menu on escape key
        $(document).off('keyup').on('keyup', function(e) {
            if (e.key === 'Escape' && navigation.isMobileMenuOpen) {
                closeMobileMenu();
            }
        });

        // Close mobile menu when clicking on a link (for single page navigation)
        navigation.$mainNavigation.find('a').off('click').on('click', function() {
            if (window.innerWidth <= 768) {
                closeMobileMenu();
            }
        });

        // Handle window resize
        var resizeTimer;
        $(window).off('resize').on('resize', function() {
            clearTimeout(resizeTimer);
            resizeTimer = setTimeout(function() {
                updateMobileToggleVisibility();
                if (window.innerWidth > 768 && navigation.isMobileMenuOpen) {
                    closeMobileMenu();
                }
            }, 250);
        });
    }

    /**
     * Toggle mobile menu open/close
     */
    function toggleMobileMenu() {
        if (navigation.isMobileMenuOpen) {
            closeMobileMenu();
        } else {
            openMobileMenu();
        }
    }

    /**
     * Open mobile menu
     */
    function openMobileMenu() {
        navigation.isMobileMenuOpen = true;
        navigation.$mobileToggle.addClass('active').attr('aria-expanded', 'true');
        navigation.$mainNavigation.addClass('active').attr('aria-hidden', 'false');
        $('body').addClass('mobile-menu-open');

        // Focus management
        setTimeout(function() {
            navigation.$primaryMenu.find('a').first().focus();
        }, 300);
    }

    /**
     * Close mobile menu
     */
    function closeMobileMenu() {
        navigation.isMobileMenuOpen = false;
        navigation.$mobileToggle.removeClass('active').attr('aria-expanded', 'false');
        navigation.$mainNavigation.removeClass('active').attr('aria-hidden', 'true');
        $('body').removeClass('mobile-menu-open');

        // Return focus to toggle button
        navigation.$mobileToggle.focus();
    }

    /**
