    /**
     * Smooth scrolling for anchor links
     */
    function initSmoothScroll() {
        $('a[href*="#"]:not([href="#"]):not([href="#0"]):not([href*="modal"]):not([href*="tab"])').off('click').on('click', function(event) {
            if (location.pathname.replace(/^\//, '') === this.pathname.replace(/^\//, '') && location.hostname === this.hostname) {
                var target = $(this.hash);
                target = target.length ? target : $('[name=' + this.hash.slice(1) + ']');

                if (target.length) {
                    event.preventDefault();
                    $('html, body').animate({
                        scrollTop: target.offset().top - 100
                    }, 800, function() {
                        var $target = $(target);
                        $target.focus();
                        if (!$target.is(':focus')) {
                            $target.attr('tabindex', '-1');
                            $target.focus();
                        }
                    });
                }
            }
        });
    }

    /**
     * Sticky header behavior
     */
    function initStickyHeader() {
        var $header = $('#masthead');
        var $body = $('body');

        if (!$header.length || !$body.hasClass('sticky-header')) return;

        var headerHeight = $header.outerHeight();
        var lastScrollTop = 0;
        var scrollDelta = 5;

        // Add padding to body to account for sticky header
        $('html').css('padding-top', headerHeight);

        $(window).off('scroll').on('scroll', function() {
            var st = $(this).scrollTop();

            // Only trigger if scrolled more than delta
            if (Math.abs(lastScrollTop - st) <= scrollDelta) return;

            if (st > lastScrollTop && st > headerHeight) {
                // Scrolling down
                $header.removeClass('header-visible').addClass('header-hidden');
            } else {
                // Scrolling up
                if (st + $(window).height() < $(document).height()) {
                    $header.removeClass('header-hidden').addClass('header-visible');
                }
            }

            lastScrollTop = st;
        });
    }

    /**
     * Skip link focus fix
     */
    function initSkipLinkFocus() {
        var isIe = /(trident|msie)/i.test(navigator.userAgent);

        if (isIe && document.getElementById && window.addEventListener) {
            window.addEventListener('hashchange', function() {
                var id = location.hash.substring(1),
                    element;

                if (!(/^[A-z0-9_-]+$/.test(id))) {
                    return;
                }

                element = document.getElementById(id);

                if (element) {
                    if (!(/^(?:a|select|input|button|textarea)$/i.test(element.tagName))) {
                        element.tabIndex = -1;
                    }

                    element.focus();
                }
            }, false);
        }
    }

    /**
     * Initialize all navigation functionality
     */
    function initNavigation() {
        initMobileMenu();
        initSmoothScroll();
        initStickyHeader();
        initSkipLinkFocus();

        // Add loaded class for CSS transitions
        setTimeout(function() {
            $('body').addClass('loaded');
        }, 100);
    }

    // Initialize when document is ready
    $(document).ready(function() {
        initNavigation();
    });

    // Re-initialize when header layout changes
    $(document).off('headerLayoutChanged').on('headerLayoutChanged', function(event, layout) {
        setTimeout(initNavigation, 500);
    });

})(jQuery);
