            if ($body_text !== '#333333') {
                $css .= "body { color: {$body_text}; }";
            }

            if ($link_color !== '#3498db') {
                $css .= "a { color: {$link_color}; }";
                $css .= "a:hover { color: {$link_color}; opacity: 0.8; }";
            }

            // Typography
            $heading_font = get_theme_mod('abundant_thought_v8_heading_font', 'inherit');
