```php
<?php
/**
 * Abundant Thought v8 - CSS Generator
 * Enhanced with !important to override WordPress core styles
 */

if (!class_exists('Abundant_Thought_CSS_Generator')) {
    class Abundant_Thought_CSS_Generator {

        private $css_output = '';

        public function __construct() {
            add_action('wp_head', array($this, 'output_dynamic_css'), 10);
            add_action('customize_preview_init', array($this, 'customizer_live_preview'));
        }

        /**
         * Generate dynamic CSS based on theme mods
         */
        public function generate_dynamic_css() {
            $css = '';

            // Header Styles
            $header_bg = get_theme_mod('abundant_thought_v8_header_bg_color', '#ffffff');
            $header_text = get_theme_mod('abundant_thought_v8_header_text_color', '#333333');
            $header_height = get_theme_mod('abundant_thought_v8_header_height', 80);

            if ($header_bg !== '#ffffff') {
                $css .= ".site-header { background-color: {$header_bg} !important; }";
            }

            if ($header_text !== '#333333') {
                $css .= ".site-header { color: {$header_text} !important; }";
                $css .= ".site-title, .site-title a { color: {$header_text} !important; }";
                $css .= ".site-description { color: {$header_text} !important; }";
                $css .= ".main-navigation a { color: {$header_text} !important; }";
            }

            if ($header_height !== 80) {
                $css .= ".site-header { min-height: {$header_height}px !important; }";
            }

            // Container Width
            $container_width = get_theme_mod('abundant_thought_v8_container_width', 1200);
            if ($container_width !== 1200) {
                $css .= ".container, .site-content, .header-container, .footer-container { max-width: {$container_width}px !important; }";
            }

            // Body Styles
            $body_bg = get_theme_mod('abundant_thought_v8_body_bg_color', '#ffffff');
            $body_text = get_theme_mod('abundant_thought_v8_body_text_color', '#333333');
            $link_color = get_theme_mod('abundant_thought_v8_link_color', '#3498db');

            if ($body_bg !== '#ffffff') {
                $css .= "body { background-color: {$body_bg} !important; }";
            }

            if ($body_text !== '#333333') {
                $css .= "body { color: {$body_text} !important; }";
            }

            if ($link_color !== '#3498db') {
                $css .= "a { color: {$link_color} !important; }";
                $css .= "a:hover { color: {$link_color} !important; opacity: 0.8 !important; }";
            }

            // Typography
            $heading_font = get_theme_mod('abundant_thought_v8_heading_font', 'inherit');
            $body_font = get_theme_mod('abundant_thought_v8_body_font', 'inherit');

            if ($heading_font !== 'inherit') {
                $css .= "h1, h2, h3, h4, h5, h6 { font-family: {$heading_font}, sans-serif !important; }";
            }

            if ($body_font !== 'inherit') {
                $css .= "body { font-family: {$body_font}, sans-serif !important; }";
            }

            return $css;
        }

        /**
         * Output CSS in head
         */
        public function output_dynamic_css() {
            $dynamic_css = $this->generate_dynamic_css();
            if (!empty($dynamic_css)) {
                echo '<style id="abundant-thought-dynamic-css">' . $dynamic_css . '</style>';
            }
        }

        /**
         * Live preview handler for customizer
         */
        public function customizer_live_preview() {
            wp_enqueue_script('abundant-thought-customizer-preview');
        }
    }

    new Abundant_Thought_CSS_Generator();
}
