function abundant_thought_display_sidebar() {
	$sidebar_layout = get_theme_mod( 'sidebar_layout', 'right-sidebar' );
	$display_sidebar = true;

	// Hide sidebar on full-width pages
	if ( is_page() && $sidebar_layout === 'no-sidebar' ) {
		$display_sidebar = false;
	}

	// Hide sidebar if no widgets active
	if ( ! is_active_sidebar( 'sidebar-1' ) ) {
		$display_sidebar = false;
	}

	return apply_filters( 'abundant_thought_display_sidebar', $display_sidebar );
}

/**
 * Get content class based on sidebar layout
 */
function abundant_thought_content_class() {
	$sidebar_layout = get_theme_mod( 'sidebar_layout', 'right-sidebar' );
	$classes = array( 'site-main' );

	if ( abundant_thought_display_sidebar() ) {
		$classes[] = 'has-sidebar';
		$classes[] = $sidebar_layout;
	} else {
