<?php
/**
 * Abundant Thought v8 - Sanitization Functions
 * Sanitization callback functions for customizer settings
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit; // Exit if accessed directly.
}

/**
 * Sanitize select/radio choices
 */
function abundant_thought_sanitize_select( $input, $setting ) {
	$input = sanitize_key( $input );
	$choices = $setting->manager->get_control( $setting->id )->choices;
	return ( array_key_exists( $input, $choices ) ? $input : $setting->default );
}

/**
 * Sanitize checkbox
 */
function abundant_thought_sanitize_checkbox( $checked ) {
	return ( ( isset( $checked ) && true == $checked ) ? true : false );
}

/**
 * Sanitize number range
 */
function abundant_thought_sanitize_number_range( $number, $setting ) {
	$number = absint( $number );
	$atts = $setting->manager->get_control( $setting->id )->input_attrs;
	$min = ( isset( $atts['min'] ) ? $atts['min'] : $number );
	$max = ( isset( $atts['max'] ) ? $atts['max'] : $number );
	$step = ( isset( $atts['step'] ) ? $atts['step'] : 1 );
	return ( $min <= $number && $number <= $max && is_int( $number / $step ) ? $number : $setting->default );
}

/**
 * Sanitize hex color
 */
function abundant_thought_sanitize_hex_color( $color ) {
	if ( '' === $color ) {
		return '';
	}

	// 3 or 6 hex digits, or the empty string.
	if ( preg_match( '|^#([A-Fa-f0-9]{3}){1,2}$|', $color ) ) {
		return $color;
	}

	return null;
}

/**
 * Sanitize alpha color (hex or rgba)
 */
function abundant_thought_sanitize_alpha_color( $color ) {
	if ( '' === $color ) {
		return '';
	}

	// Hex color
	if ( preg_match( '|^#([A-Fa-f0-9]{3}){1,2}$|', $color ) || $color === 'transparent' ) {
		return $color;
	}

	// RGB or RGBA color
	if ( preg_match( '/^rgba?\((\d{1,3}),\s*(\d{1,3}),\s*(\d{1,3})(?:,\s*(\d*(?:\.\d+)?))?\)$/', $color, $matches ) ) {
		// Validate RGB values
		$red = intval( $matches[1] );
		$green = intval( $matches[2] );
		$blue = intval( $matches[3] );

		if ( $red >= 0 && $red <= 255 && $green >= 0 && $green <= 255 && $blue >= 0 && $blue <= 255 ) {
			return $color;
		}
	}

	return null;
}

/**
 * Sanitize textarea with limited HTML
 */
function abundant_thought_sanitize_textarea( $input ) {
	return wp_kses_post( force_balance_tags( $input ) );
}

/**
 * Sanitize URL
 */
function abundant_thought_sanitize_url( $url ) {
	return esc_url_raw( $url );
}

/**
 * Sanitize HTML content
 */
function abundant_thought_sanitize_html( $input ) {
	return wp_kses_post( $input );
}

/**
 * Sanitize CSS content
 */
function abundant_thought_sanitize_css( $css ) {
	return wp_strip_all_tags( $css );
}

/**
 * Sanitize email address
 */
function abundant_thought_sanitize_email( $email ) {
	return sanitize_email( $email );
}

/**
 * Sanitize text field
 */
function abundant_thought_sanitize_text( $input ) {
	return sanitize_text_field( $input );
}

/**
 * Sanitize multiple select
 */
function abundant_thought_sanitize_multiple_select( $input, $setting ) {
	$choices = $setting->manager->get_control( $setting->id )->choices;
	$input = (array) $input;
	$output = array();

	foreach ( $input as $value ) {
		if ( array_key_exists( $value, $choices ) ) {
			$output[] = sanitize_key( $value );
		}
	}

	return $output;
}

/**
 * Sanitize font family
 */
function abundant_thought_sanitize_font_family( $input ) {
	$valid_fonts = array(
		'system-ui', '-apple-system', 'BlinkMacSystemFont', 'Segoe UI', 'Roboto', 
		'Oxygen', 'Ubuntu', 'Cantarell', 'Open Sans', 'Helvetica Neue', 'sans-serif',
		'Arial', 'Helvetica', 'Georgia', 'Times New Roman', 'Courier New', 'monospace'
	);

	if ( in_array( $input, $valid_fonts ) ) {
		return $input;
	}

	return 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif';
}

/**
 * Sanitize font weight
 */
function abundant_thought_sanitize_font_weight( $input ) {
	$valid_weights = array( '100', '200', '300', '400', '500', '600', '700', '800', '900' );
	return in_array( $input, $valid_weights ) ? $input : '400';
}

/**
 * Sanitize header layout
 */
function abundant_thought_sanitize_header_layout( $input ) {
	$valid_layouts = array( 'default', 'centered', 'minimal', 'split', 'stacked' );
	return in_array( $input, $valid_layouts ) ? $input : 'default';
}

/**
 * Sanitize sidebar layout
 */
function abundant_thought_sanitize_sidebar_layout( $input ) {
	$valid_layouts = array( 'right-sidebar', 'left-sidebar', 'no-sidebar' );
	return in_array( $input, $valid_layouts ) ? $input : 'right-sidebar';
}
