		$css .= '.site-header { background-color: ' . esc_attr( $header_bg_color ) . '; }';
	}

	// Header Text Color
	$header_text_color = get_theme_mod( 'header_text_color', '#333333' );
	if ( $header_text_color ) {
		$css .= '.site-header, .site-header a, .site-title, .site-title a { color: ' . esc_attr( $header_text_color ) . '; }';
		$css .= '.main-navigation a { color: ' . esc_attr( $header_text_color ) . '; }';
	}

	// Link Colors
	$link_color = get_theme_mod( 'link_color', '#0073aa' );
	if ( $link_color ) {
		$css .= 'a { color: ' . esc_attr( $link_color ) . '; }';
	}

	$link_hover_color = get_theme_mod( 'link_hover_color', '#005a87' );
	if ( $link_hover_color ) {
		$css .= 'a:hover, a:focus { color: ' . esc_attr( $link_hover_color ) . '; }';
	}

	// Header Padding
