function abundant_thought_v8_generate_custom_css() {
    $css = '';

    // Container Width
    $container_width = get_theme_mod( 'container_width', 1200 );
    if ( $container_width ) {
        $css .= '.container, .header-container, .footer-container { max-width: ' . absint( $container_width ) . 'px; }';
    }

    // Content Width  
    $content_width = get_theme_mod( 'content_width', 70 );
    if ( $content_width ) {
        $css .= '.site-main { width: ' . absint( $content_width ) . '%; }';
        $sidebar_width = 100 - absint( $content_width );
        $css .= '.widget-area { width: ' . $sidebar_width . '%; }';
    }

    // Sidebar Width (alternative calculation)
    $sidebar_width_setting = get_theme_mod( 'sidebar_width', 25 );
    if ( $sidebar_width_setting && ! $content_width ) {
        $css .= '.widget-area { width: ' . absint( $sidebar_width_setting ) . '%; }';
        $content_width_calc = 100 - absint( $sidebar_width_setting );
        $css .= '.site-main { width: ' . $content_width_calc . '%; }';
    }

    // Gutter Size
    $gutter_size = get_theme_mod( 'gutter_size', 30 );
    if ( $gutter_size ) {
        $half_gutter = absint( $gutter_size ) / 2;
        $css .= '.container, .header-container { padding-left: ' . $half_gutter . 'px; padding-right: ' . $half_gutter . 'px; }';
    }

    // Base Font Size
    $base_font_size = get_theme_mod( 'base_font_size', 16 );
    if ( $base_font_size ) {
        $css .= 'html { font-size: ' . absint( $base_font_size ) . 'px; }';
    }

    // Base Line Height
    $base_line_height = get_theme_mod( 'base_line_height', 1.6 );
    if ( $base_line_height ) {
        $css .= 'body { line-height: ' . floatval( $base_line_height ) . '; }';
    }

    // Header Background Color
    $header_bg_color = get_theme_mod( 'header_background_color', '#ffffff' );
    if ( $header_bg_color ) {
        $css .= '.site-header { background-color: ' . esc_attr( $header_bg_color ) . '; }';
    }

    // Header Text Color
    $header_text_color = get_theme_mod( 'header_text_color', '#333333' );
    if ( $header_text_color ) {
        $css .= '.site-header, .site-header a, .site-title, .site-title a, .main-navigation a { color: ' . esc_attr( $header_text_color ) . '; }';
    }

    // Link Colors
    $link_color = get_theme_mod( 'link_color', '#0073aa' );
    if ( $link_color ) {
        $css .= 'a:not(.site-header a):not(.main-navigation a) { color: ' . esc_attr( $link_color ) . '; }';
    }

    $link_hover_color = get_theme_mod( 'link_hover_color', '#005a87' );
    if ( $link_hover_color ) {
        $css .= 'a:hover, a:focus { color: ' . esc_attr( $link_hover_color ) . '; }';
    }

    // Header Padding
    $header_padding = get_theme_mod( 'header_padding', 20 );
    if ( $header_padding ) {
        $css .= '.site-header { padding-top: ' . absint( $header_padding ) . 'px; padding-bottom: ' . absint( $header_padding ) . 'px; }';
    }

    // Sticky Header
    if ( get_theme_mod( 'sticky_header', false ) ) {
        $css .= '.site-header { position: sticky; top: 0; z-index: 1000; }';
        $css .= 'body.admin-bar .site-header { top: 32px; }';
    }

    // Hide search if disabled
    if ( ! get_theme_mod( 'show_search', true ) ) {
        $css .= '.header-search { display: none !important; }';
    }

    // Hide site title if disabled
    if ( ! get_theme_mod( 'show_site_title', true ) ) {
        $css .= '.site-title { display: none !important; }';
    }

    // Hide tagline if disabled
    if ( ! get_theme_mod( 'show_tagline', true ) ) {
        $css .= '.site-description { display: none !important; }';
    }

    return $css;
}

