### 📦 The Missing Piece: A Customizer Controls Script

Your theme is missing the JavaScript that brings the interactive controls (like range sliders and toggle switches) to life in the customizer panel itself. This file should be enqueued only in the customizer controls panel, not the front-end preview.

Create a new file: `/assets/js/customizer-controls.js`

```javascript
(function($) {
	'use strict';

	// Range Slider Control Live Update
	wp.customize.control.each(function(control) {
		if (control.params.type === 'range-slider') {
			// Update the live value display when the slider is moved
			control.container.find('input[type=range]').on('input', function() {
				$(this).closest('.range-slider-control').find('.range-value').text(this.value);
			});
		}
	});

	// Toggle Switch Enhancements
	wp.customize.control.each(function(control) {
		if (control.params.type === 'toggle-switch') {
			// Add a class to the container when the toggle is checked
			var updateToggleState = function() {
				var checkbox = control.container.find('.toggle-switch-checkbox');
				var container = control.container.closest('.toggle-switch-control');
				if (checkbox.is(':checked')) {
					container.addClass('is-checked');
				} else {
					container.removeClass('is-checked');
				}
			};

			// Update on initial load
			updateToggleState();

			// Update when the value changes
			control.setting.bind(function(newval) {
				updateToggleState();
			});
		}
	});

	// Initialize all controls on load
	$(document).ready(function() {
		// Initialize range slider displays
		$('.range-slider-control input[type=range]').each(function() {
			$(this).closest('.range-slider-control').find('.range-value').text(this.value);
		});
	});

})(jQuery);
```

