<?php
/**
 * Abundant Thought Dynamic CSS
 *
 * @package Abundant_Thought
 */

// Exit if accessed directly.
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Abundant Thought CSS class
 */
class Abundant_Thought_CSS {

	/**
	 * Constructor
	 */
	public function __construct() {
		add_action( 'wp_enqueue_scripts', array( $this, 'frontend_css' ), 100 );
		add_action( 'enqueue_block_editor_assets', array( $this, 'block_editor_css' ), 100 );
	}

	/**
	 * Generate frontend CSS
	 */
	public function frontend_css() {
		wp_add_inline_style( 'abundant-thought-style', $this->generate_css() );
	}

	/**
	 * Generate block editor CSS
	 */
	public function block_editor_css() {
		wp_add_inline_style( 'abundant-thought-block-editor', $this->generate_editor_css() );
	}

	/**
	 * Generate dynamic CSS
	 */
	private function generate_css() {
		$css = '';

		// CSS Variables
		$css .= $this->generate_css_variables();

		// Global Styles
		$css .= $this->generate_global_css();

		// Header Styles
		$css .= $this->generate_header_css();

		// Typography Styles
		$css .= $this->generate_typography_css();

		// Color Styles
		$css .= $this->generate_color_css();

		return $this->minify_css( $css );
	}

	/**
	 * Generate editor CSS
	 */
	private function generate_editor_css() {
		$css = '';

		// CSS Variables for editor
		$css .= $this->generate_css_variables();

		// Editor-specific styles
		$css .= $this->generate_editor_global_css();

		return $this->minify_css( $css );
	}

	/**
	 * Generate CSS variables
	 */
	private function generate_css_variables() {
		$css = ':root {';

		// Colors
		$css .= $this->get_color_variables();

		// Typography
		$css .= $this->get_typography_variables();

		// Layout
		$css .= $this->get_layout_variables();

		// Header
		$css .= $this->get_header_variables();

		$css .= '}';

		return $css;
	}

	/**
	 * Get color variables
	 */
	private function get_color_variables() {
		$colors = array(
			'--abundant-thought-palette-primary'   => get_theme_mod( 'abundant_thought_palette_primary', '#2271b1' ),
			'--abundant-thought-palette-secondary' => get_theme_mod( 'abundant_thought_palette_secondary', '#f67326' ),
			'--abundant-thought-palette-background' => get_theme_mod( 'abundant_thought_palette_background', '#ffffff' ),
			'--abundant-thought-palette-text'      => get_theme_mod( 'abundant_thought_palette_text', '#333333' ),
			'--abundant-thought-palette-heading'   => get_theme_mod( 'abundant_thought_palette_heading', '#111111' ),
		);

		$css = '';
		foreach ( $colors as $var => $value ) {
			if ( $value ) {
				$css .= $var . ':' . $value . ';';
			}
		}

		return $css;
	}

	/**
	 * Get typography variables
	 */
	private function get_typography_variables() {
		$typography = array(
			'--abundant-thought-font-family-base'    => $this->get_font_family( get_theme_mod( 'abundant_thought_base_font' ) ),
			'--abundant-thought-font-family-heading' => $this->get_font_family( get_theme_mod( 'abundant_thought_heading_font' ) ),
			'--abundant-thought-font-size-base'      => $this->get_font_size( get_theme_mod( 'abundant_thought_base_font_size' ) ),
		);

		$css = '';
		foreach ( $typography as $var => $value ) {
			if ( $value ) {
				$css .= $var . ':' . $value . ';';
			}
		}

		return $css;
	}

	/**
	 * Get layout variables
	 */
	private function get_layout_variables() {
		$layout = array(
			'--abundant-thought-container-width' => get_theme_mod( 'abundant_thought_container_width', '1200px' ),
			'--abundant-thought-container-padding' => get_theme_mod( 'abundant_thought_container_padding', '20px' ),
		);

		$css = '';
		foreach ( $layout as $var => $value ) {
			if ( $value ) {
				$css .= $var . ':' . $value . ';';
			}
		}

		return $css;
	}

	/**
	 * Get header variables
	 */
	private function get_header_variables() {
		$header = array(
			'--abundant-thought-header-background' => get_theme_mod( 'abundant_thought_header_background', '#ffffff' ),
			'--abundant-thought-header-text-color' => get_theme_mod( 'abundant_thought_header_text_color', '#333333' ),
			'--abundant-thought-header-height'     => get_theme_mod( 'abundant_thought_header_height', '80px' ),
		);

		$css = '';
		foreach ( $header as $var => $value ) {
			if ( $value ) {
				$css .= $var . ':' . $value . ';';
			}
		}

		return $css;
	}

	/**
	 * Generate global CSS
	 */
	private function generate_global_css() {
		return '
			.container {
				max-width: var(--abundant-thought-container-width);
				padding-left: var(--abundant-thought-container-padding);
				padding-right: var(--abundant-thought-container-padding);
				margin: 0 auto;
			}

			body {
				font-family: var(--abundant-thought-font-family-base);
				font-size: var(--abundant-thought-font-size-base);
				color: var(--abundant-thought-palette-text);
				background-color: var(--abundant-thought-palette-background);
			}

			h1, h2, h3, h4, h5, h6 {
				font-family: var(--abundant-thought-font-family-heading);
				color: var(--abundant-thought-palette-heading);
			}

			a {
				color: var(--abundant-thought-palette-primary);
			}

			.button, .wp-block-button__link {
				background-color: var(--abundant-thought-palette-primary);
				color: white;
			}
		';
	}

	/**
	 * Generate header CSS
	 */
	private function generate_header_css() {
		return '
			.site-header {
				background-color: var(--abundant-thought-header-background);
				color: var(--abundant-thought-header-text-color);
				min-height: var(--abundant-thought-header-height);
			}

			.main-navigation a {
				color: var(--abundant-thought-header-text-color);
			}
		';
	}

	/**
	 * Generate typography CSS
	 */
	private function generate_typography_css() {
		return '
			body {
				font-family: var(--abundant-thought-font-family-base);
				font-size: var(--abundant-thought-font-size-base);
				line-height: 1.6;
			}

			h1 { font-size: 2.5rem; }
			h2 { font-size: 2rem; }
			h3 { font-size: 1.75rem; }
			h4 { font-size: 1.5rem; }
			h5 { font-size: 1.25rem; }
			h6 { font-size: 1rem; }
		';
	}

	/**
	 * Generate color CSS
	 */
	private function generate_color_css() {
		return '
			.site-header {
				background-color: var(--abundant-thought-header-background);
			}

			.site-footer {
				background-color: var(--abundant-thought-palette-text);
				color: var(--abundant-thought-palette-background);
			}
		';
	}

	/**
	 * Generate editor global CSS
	 */
	private function generate_editor_global_css() {
		return '
			.editor-styles-wrapper {
				font-family: var(--abundant-thought-font-family-base);
				font-size: var(--abundant-thought-font-size-base);
				color: var(--abundant-thought-palette-text);
				background-color: var(--abundant-thought-palette-background);
			}

			.editor-styles-wrapper h1,
			.editor-styles-wrapper h2,
			.editor-styles-wrapper h3,
			.editor-styles-wrapper h4,
			.editor-styles-wrapper h5,
			.editor-styles-wrapper h6 {
				font-family: var(--abundant-thought-font-family-heading);
				color: var(--abundant-thought-palette-heading);
			}
		';
	}

	/**
	 * Get font family from setting
	 */
	private function get_font_family( $font_setting ) {
		if ( empty( $font_setting ) ) {
			return 'system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif';
		}

		return $font_setting;
	}

	/**
	 * Get font size from setting
	 */
	private function get_font_size( $size_setting ) {
		if ( empty( $size_setting ) ) {
			return '16px';
		}

		return is_numeric( $size_setting ) ? $size_setting . 'px' : $size_setting;
	}

	/**
	 * Minify CSS
	 */
	private function minify_css( $css ) {
		$css = preg_replace( '/\s+/', ' ', $css );
		$css = preg_replace( '/\/\*[^*]*\*+([^\/][^*]*\*+)*\//', '', $css );
		$css = str_replace( array( ' {', ': ', '; }', ' ,' ), array( '{', ':', '}', ',' ), $css );
		return trim( $css );
	}
}

new Abundant_Thought_CSS();
