class Abundant_Thought_Customizer_Global {

	/**
	 * Constructor
	 */
	public function __construct() {
		add_action( 'customize_register', array( $this, 'register_options' ), 20 );
	}

	/**
	 * Register global options
	 */
	public function register_options( $wp_customize ) {

		// Global Panel
		$wp_customize->add_panel(
			'abundant_thought_global_panel',
			array(
				'title'       => __( 'Global Settings', 'abundant-thought' ),
				'priority'    => 10,
			)
		);

		// Layout Section
		$wp_customize->add_section(
			'abundant_thought_global_layout',
			array(
				'title' => __( 'Layout', 'abundant-thought' ),
				'panel' => 'abundant_thought_global_panel',
			)
		);

		// Container Width
		$wp_customize->add_setting(
			'abundant_thought_container_width',
			array(
				'default'           => '1200px',
				'transport'         => 'postMessage',
				'sanitize_callback' => 'abundant_thought_sanitize_dimension',
			)
		);

		$wp_customize->add_control(
			new Abundant_Thought_Range_Control(
				$wp_customize,
				'abundant_thought_container_width',
