function at_enqueue_scripts() {
	// Main stylesheet
	wp_enqueue_style( 
		'abundant-thought-style', 
		get_stylesheet_uri(), 
		array(), 
		AT_THEME_VERSION 
	);

	// Custom CSS
	wp_enqueue_style( 
		'abundant-thought-custom', 
		AT_THEME_URI . '/assets/css/custom.css', 
		array( 'abundant-thought-style' ), 
		AT_THEME_VERSION 
	);

	// Block editor CSS
	wp_enqueue_style( 
		'abundant-thought-block-editor', 
		AT_THEME_URI . '/assets/css/block-editor.css', 
		array( 'abundant-thought-style' ), 
		AT_THEME_VERSION 
	);

	// Navigation JavaScript
	wp_enqueue_script( 
		'abundant-thought-navigation', 
		AT_THEME_URI . '/assets/js/navigation.js', 
		array(), 
		AT_THEME_VERSION, 
		true 
	);

	// Skip link focus fix
	wp_enqueue_script( 
		'abundant-thought-skip-link-focus-fix', 
		AT_THEME_URI . '/assets/js/skip-link-focus-fix.js', 
		array(), 
		AT_THEME_VERSION, 
		true 
	);

	// Main JavaScript
	wp_enqueue_script( 
		'abundant-thought-main', 
		AT_THEME_URI . '/assets/js/main.js', 
		array( 'jquery' ), 
		AT_THEME_VERSION, 
		true 
	);

	// Customizer JavaScript for live preview
	if ( is_customize_preview() ) {
		wp_enqueue_script( 
			'abundant-thought-customizer', 
			AT_THEME_URI . '/assets/js/customizer.js', 
			array( 'jquery', 'customize-preview' ), 
			AT_THEME_VERSION, 
			true 
		);
	}

	// Localize script for AJAX and dynamic data
	wp_localize_script( 'abundant-thought-main', 'at_ajax', array(
		'ajax_url' => admin_url( 'admin-ajax.php' ),
		'nonce'    => wp_create_nonce( 'at_nonce' ),
	) );

	// Comment reply script
	if ( is_singular() && comments_open() && get_option( 'thread_comments' ) ) {
		wp_enqueue_script( 'comment-reply' );
	}
}
