/**
 * Add preconnect for Google Fonts
 */
function at_resource_hints( $urls, $relation_type ) {
	if ( wp_style_is( 'abundant-thought-fonts', 'queue' ) && 'preconnect' === $relation_type ) {
		$urls[] = array(
			'href' => 'https://fonts.gstatic.com',
			'crossorigin',
		);
	}
	return $urls;
}
