/**
 * Sets up theme defaults and registers support for various WordPress features
 */
function at_setup_theme() {
	// Make theme available for translation
	load_theme_textdomain( 'abundant-thought', get_template_directory() . '/languages' );

	// Add default posts and comments RSS feed links to head
	add_theme_support( 'automatic-feed-links' );

	// Let WordPress manage the document title
	add_theme_support( 'title-tag' );

	// Enable support for Post Thumbnails on posts and pages
	add_theme_support( 'post-thumbnails' );

	// Register menu locations
	register_nav_menus( array(
		'primary' => __( 'Primary Menu', 'abundant-thought' ),
		'footer'  => __( 'Footer Menu', 'abundant-thought' ),
		'social'  => __( 'Social Menu', 'abundant-thought' ),
	) );

	// Switch default core markup for search form, comment form, and comments to output valid HTML5
	add_theme_support( 'html5', array(
		'search-form',
		'comment-form',
		'comment-list',
		'gallery',
		'caption',
		'style',
		'script',
	) );

	// Add theme support for selective refresh for widgets
	add_theme_support( 'customize-selective-refresh-widgets' );

	// Add support for core custom logo
	add_theme_support( 'custom-logo', array(
		'height'      => 100,
		'width'       => 300,
		'flex-width'  => true,
		'flex-height' => true,
	) );

	// Add support for Block Styles
	add_theme_support( 'wp-block-styles' );

	// Add support for full and wide align images
	add_theme_support( 'align-wide' );

	// Add support for editor styles
	add_theme_support( 'editor-styles' );

	// Enqueue editor styles
	add_editor_style( array( 'assets/css/block-editor.css' ) );

	// Add support for responsive embedded content
	add_theme_support( 'responsive-embeds' );

