<?php
/**
 * Custom template tags for this theme
 *
 * @package Abundant_Thought
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Prints HTML with meta information for the current post-date/time
 */
function at_posted_on() {
	$time_string = '<time class="entry-date published updated" datetime="%1$s">%2$s</time>';
	if ( get_the_time( 'U' ) !== get_the_modified_time( 'U' ) ) {
		$time_string = '<time class="entry-date published" datetime="%1$s">%2$s</time><time class="updated" datetime="%3$s">%4$s</time>';
	}

	$time_string = sprintf(
		$time_string,
		esc_attr( get_the_date( DATE_W3C ) ),
		esc_html( get_the_date() ),
		esc_attr( get_the_modified_date( DATE_W3C ) ),
		esc_html( get_the_modified_date() )
	);

	$posted_on = sprintf(
		/* translators: %s: post date */
		esc_html_x( 'Posted on %s', 'post date', 'abundant-thought' ),
		'<a href="' . esc_url( get_permalink() ) . '" rel="bookmark">' . $time_string . '</a>'
	);

	echo '<span class="posted-on">' . $posted_on . '</span>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
}

/**
 * Prints HTML with meta information for the current author
 */
function at_posted_by() {
	$byline = sprintf(
		/* translators: %s: post author */
		esc_html_x( 'by %s', 'post author', 'abundant-thought' ),
		'<span class="author vcard"><a class="url fn n" href="' . esc_url( get_author_posts_url( get_the_author_meta( 'ID' ) ) ) . '">' . esc_html( get_the_author() ) . '</a></span>'
	);

	echo '<span class="byline"> ' . $byline . '</span>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
}

/**
 * Prints HTML with meta information for the categories, tags and comments
 */
function at_entry_footer() {
	// Hide category and tag text for pages
	if ( 'post' === get_post_type() ) {
		/* translators: used between list items, there is a space after the comma */
		$categories_list = get_the_category_list( esc_html__( ', ', 'abundant-thought' ) );
		if ( $categories_list ) {
			/* translators: 1: list of categories */
			printf( '<span class="cat-links">' . esc_html__( 'Posted in %1$s', 'abundant-thought' ) . '</span>', $categories_list ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
		}

		/* translators: used between list items, there is a space after the comma */
		$tags_list = get_the_tag_list( '', esc_html_x( ', ', 'list item separator', 'abundant-thought' ) );
		if ( $tags_list ) {
			/* translators: 1: list of tags */
			printf( '<span class="tags-links">' . esc_html__( 'Tagged %1$s', 'abundant-thought' ) . '</span>', $tags_list ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
		}
	}

	if ( ! is_single() && ! post_password_required() && ( comments_open() || get_comments_number() ) ) {
		echo '<span class="comments-link">';
		comments_popup_link(
			sprintf(
				wp_kses(
					/* translators: %s: post title */
					__( 'Leave a Comment<span class="screen-reader-text"> on %s</span>', 'abundant-thought' ),
					array(
						'span' => array(
							'class' => array(),
						),
					)
				),
				wp_kses_post( get_the_title() )
			)
		);
		echo '</span>';
	}

	edit_post_link(
		sprintf(
			wp_kses(
				/* translators: %s: Name of current post. Only visible to screen readers */
				__( 'Edit <span class="screen-reader-text">%s</span>', 'abundant-thought' ),
				array(
					'span' => array(
						'class' => array(),
					),
				)
			),
			wp_kses_post( get_the_title() )
		),
		'<span class="edit-link">',
		'</span>'
	);
}

/**
 * Displays an optional post thumbnail
 */
function at_post_thumbnail() {
	if ( post_password_required() || is_attachment() || ! has_post_thumbnail() ) {
		return;
	}

	if ( is_singular() ) :
		?>
		<div class="post-thumbnail">
			<?php the_post_thumbnail( 'large', array( 'alt' => the_title_attribute( array( 'echo' => false ) ) ) ); ?>
		</div>
		<?php
	else :
		?>
		<a class="post-thumbnail" href="<?php the_permalink(); ?>" aria-hidden="true" tabindex="-1">
			<?php
			the_post_thumbnail(
				'at-blog-thumbnail',
				array(
					'alt' => the_title_attribute(
						array(
							'echo' => false,
						)
					),
				)
			);
			?>
		</a>
		<?php
	endif;
}

/**
 * Prints HTML with the site logo
 */
function at_site_logo() {
	if ( has_custom_logo() ) {
		the_custom_logo();
	} else {
		$site_title = get_bloginfo( 'name' );
		?>
		<a href="<?php echo esc_url( home_url( '/' ) ); ?>" class="custom-logo-link" rel="home">
			<span class="site-title"><?php echo esc_html( $site_title ); ?></span>
		</a>
		<?php
	}
}

/**
 * Get the site title with proper markup
 */
function at_get_site_title() {
	$site_title = get_bloginfo( 'name' );
	$show_title = get_theme_mod( 'site_title_show', true );

	if ( ! $show_title ) {
		return '';
	}

	$font_family = get_theme_mod( 'site_title_font_family', 'inherit' );
	$font_size   = get_theme_mod( 'site_title_font_size', '2rem' );
	$font_weight = get_theme_mod( 'site_title_font_weight', '700' );
	$color       = get_theme_mod( 'site_title_color', '#222222' );
	$letter_spacing = get_theme_mod( 'site_title_letter_spacing', '0' );

	$styles = array();
	if ( 'inherit' !== $font_family ) {
		$styles[] = 'font-family: ' . esc_attr( $font_family );
	}
	if ( '2rem' !== $font_size ) {
		$styles[] = 'font-size: ' . esc_attr( $font_size );
	}
	if ( '700' !== $font_weight ) {
		$styles[] = 'font-weight: ' . esc_attr( $font_weight );
	}
	if ( '#222222' !== $color ) {
		$styles[] = 'color: ' . esc_attr( $color );
	}
	if ( '0' !== $letter_spacing ) {
		$styles[] = 'letter-spacing: ' . esc_attr( $letter_spacing ) . 'em';
	}

	$style_attr = ! empty( $styles ) ? ' style="' . implode( '; ', $styles ) . '"' : '';

	return '<h1 class="site-title"' . $style_attr . '><a href="' . esc_url( home_url( '/' ) ) . '" rel="home">' . esc_html( $site_title ) . '</a></h1>';
}

/**
 * Get the site tagline with proper markup
 */
function at_get_site_tagline() {
	$tagline = get_bloginfo( 'description' );
	$show_tagline = get_theme_mod( 'site_tagline_show', true );

	if ( ! $show_tagline || empty( $tagline ) ) {
		return '';
	}

	$font_family = get_theme_mod( 'site_tagline_font_family', 'inherit' );
	$font_size   = get_theme_mod( 'site_tagline_font_size', '1rem' );
	$color       = get_theme_mod( 'site_tagline_color', '#666666' );

	$styles = array();
	if ( 'inherit' !== $font_family ) {
		$styles[] = 'font-family: ' . esc_attr( $font_family );
	}
	if ( '1rem' !== $font_size ) {
		$styles[] = 'font-size: ' . esc_attr( $font_size );
	}
	if ( '#666666' !== $color ) {
		$styles[] = 'color: ' . esc_attr( $color );
	}

	$style_attr = ! empty( $styles ) ? ' style="' . implode( '; ', $styles ) . '"' : '';

	return '<p class="site-description"' . $style_attr . '>' . esc_html( $tagline ) . '</p>';
}
