 */
function at_body_classes( $classes ) {
	// Adds a class of hfeed to non-singular pages
	if ( ! is_singular() ) {
		$classes[] = 'hfeed';
	}

	// Adds a class of no-sidebar when there is no sidebar present
	if ( ! is_active_sidebar( 'sidebar-1' ) ) {
		$classes[] = 'no-sidebar';
	}

	// Add class for sticky header
	if ( get_theme_mod( 'header_sticky', false ) ) {
		$classes[] = 'has-sticky-header';
	}

	// Add class for header layout
	$header_layout = get_theme_mod( 'header_layout', 'full-width' );
	$classes[] = 'header-layout-' . sanitize_html_class( $header_layout );

	// Add class for menu position
	$menu_position = get_theme_mod( 'menu_position', 'in-header' );
	$classes[] = 'menu-position-' . sanitize_html_class( $menu_position );

	return $classes;
}
