/**
 * Add async/defer attributes to enqueued scripts
 */
function at_script_loader_tag( $tag, $handle, $src ) {
	// Defer main navigation script
	if ( 'abundant-thought-navigation' === $handle ) {
		return str_replace( '<script', '<script defer', $tag );
	}

	// Async for customizer controls
	if ( 'abundant-thought-customizer-controls' === $handle ) {
		return str_replace( '<script', '<script async', $tag );
