		'instagram' => __( 'Instagram', 'abundant-thought' ),
		'youtube'   => __( 'YouTube', 'abundant-thought' ),
		'twitter'   => __( 'Twitter', 'abundant-thought' ),
	);

	foreach ( $platforms as $platform => $label ) {
