 */
function at_display_social_icons() {
	$social_links = at_get_social_links();
	$icon_color = get_theme_mod( 'social_icon_color', '#333333' );
	$alignment = get_theme_mod( 'social_alignment', 'left' );

	if ( empty( $social_links ) ) {
		return;
	}

	$style = $icon_color !== '#333333' ? ' style="color: ' . esc_attr( $icon_color ) . '"' : '';

	echo '<div class="social-icons social-alignment-' . esc_attr( $alignment ) . '">';
	echo '<ul>';

	foreach ( $social_links as $platform => $data ) {
		echo '<li>';
		echo '<a href="' . esc_url( $data['url'] ) . '" target="_blank" rel="noopener noreferrer"' . $style . '>';
		echo '<span class="screen-reader-text">' . esc_html( $data['label'] ) . '</span>';
		echo '<span class="icon-' . esc_attr( $platform ) . '"></span>';
		echo '</a>';
		echo '</li>';
	}

	echo '</ul>';
	echo '</div>';
}

/**
 * Get header CTA button HTML
 */
function at_get_header_cta() {
	$enable_cta = get_theme_mod( 'header_cta_enable', false );
	$cta_text = get_theme_mod( 'header_cta_text', __( 'Get Started', 'abundant-thought' ) );
	$cta_url = get_theme_mod( 'header_cta_url', '#' );
	$bg_color = get_theme_mod( 'header_cta_bg_color', '#FF6B35' );
	$text_color = get_theme_mod( 'header_cta_text_color', '#FFFFFF' );

	if ( ! $enable_cta || empty( $cta_text ) ) {
		return '';
	}

	$styles = array();
	if ( '#FF6B35' !== $bg_color ) {
		$styles[] = 'background-color: ' . esc_attr( $bg_color );
	}
	if ( '#FFFFFF' !== $text_color ) {
		$styles[] = 'color: ' . esc_attr( $text_color );
	}

	$style_attr = ! empty( $styles ) ? ' style="' . implode( '; ', $styles ) . '"' : '';

	return '<a href="' . esc_url( $cta_url ) . '" class="header-cta-button"' . $style_attr . '>' . esc_html( $cta_text ) . '</a>';
}

/**
 * Get search form HTML
 */
function at_get_search_form() {
	$enable_search = get_theme_mod( 'header_search_enable', true );
	$placeholder = get_theme_mod( 'header_search_placeholder', __( 'Search...', 'abundant-thought' ) );
	$position = get_theme_mod( 'header_search_position', 'right' );

	if ( ! $enable_search ) {
		return '';
	}

	$form = '<div class="header-search search-position-' . esc_attr( $position ) . '">';
	$form .= '<form role="search" method="get" action="' . esc_url( home_url( '/' ) ) . '">';
	$form .= '<label for="header-search-input">';
	$form .= '<span class="screen-reader-text">' . esc_html__( 'Search for:', 'abundant-thought' ) . '</span>';
	$form .= '<input type="search" id="header-search-input" class="search-field" placeholder="' . esc_attr( $placeholder ) . '" value="' . get_search_query() . '" name="s" />';
	$form .= '</label>';
	$form .= '<button type="submit" class="search-submit">';
	$form .= '<span class="screen-reader-text">' . esc_html__( 'Search', 'abundant-thought' ) . '</span>';
	$form .= '</button>';
	$form .= '</form>';
	$form .= '</div>';

	return $form;
}
