<?php
/**
 * Custom navigation walker for mega menu support
 *
 * @package Abundant_Thought
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Custom walker class for mega menu support
 */
class AT_Mega_Menu_Walker extends Walker_Nav_Menu {

	/**
	 * Starts the list before the elements are added.
	 */
	public function start_l( &$output, $depth = 0, $args = null ) {
		if ( isset( $args->item_spacing ) && 'discard' === $args->item_spacing ) {
			$t = '';
			$n = '';
		} else {
			$t = "\t";
			$n = "\n";
		}
		$indent = str_repeat( $t, $depth );

		// Add classes for mega menu
		$classes = array();
		if ( $depth === 0 ) {
			$classes[] = 'menu-depth-0';
		} elseif ( $depth === 1 ) {
			$classes[] = 'menu-depth-1';
		}

		$class_names = implode( ' ', $classes );
		$class_names = $class_names ? ' class="' . esc_attr( $class_names ) . '"' : '';

		$output .= "{$n}{$indent}<ul{$class_names}>{$n}";
	}

	/**
	 * Starts the element output.
	 */
	public function start_el( &$output, $item, $depth = 0, $args = null, $id = 0 ) {
		if ( isset( $args->item_spacing ) && 'discard' === $args->item_spacing ) {
			$t = '';
			$n = '';
		} else {
			$t = "\t";
			$n = "\n";
		}
		$indent = ( $depth ) ? str_repeat( $t, $depth ) : '';

		$classes = empty( $item->classes ) ? array() : (array) $item->classes;
		$classes[] = 'menu-item-' . $item->ID;

		// Add mega menu classes
		if ( in_array( 'mega-parent', $classes, true ) && $depth === 0 ) {
			$classes[] = 'menu-item-has-megamenu';
		}

		if ( in_array( 'mega-column', $classes, true ) && $depth === 1 ) {
			$classes[] = 'megamenu-column';
		}

