/**
 * File: navigation.js
 * Handles mobile navigation toggle and accessibility
 */

(function() {
    'use strict';

    /**
     * Mobile navigation functionality
     */
    class MobileNavigation {
        constructor() {
            this.menuToggle = document.querySelector('.menu-toggle');
            this.primaryMenu = document.querySelector('#primary-menu');
            this.menuItems = document.querySelectorAll('#primary-menu .menu-item-has-children > a');

            this.init();
        }

        init() {
            if (this.menuToggle) {
                this.menuToggle.addEventListener('click', () => this.toggleMenu());
            }

            if (this.menuItems.length > 0) {
                this.menuItems.forEach(item => {
                    item.addEventListener('click', (e) => this.handleMenuItemClick(e));
                });
            }

            // Close menu when clicking outside
            document.addEventListener('click', (e) => this.handleDocumentClick(e));

            // Handle escape key
            document.addEventListener('keydown', (e) => this.handleKeydown(e));
        }

        toggleMenu() {
            const isExpanded = this.menuToggle.getAttribute('aria-expanded') === 'true';

            this.menuToggle.setAttribute('aria-expanded', !isExpanded);
            this.primaryMenu.classList.toggle('active');

            // Toggle hamburger animation
            this.menuToggle.classList.toggle('is-active');

            // Prevent body scroll when menu is open
            document.body.classList.toggle('menu-open', !isExpanded);
        }

        handleMenuItemClick(e) {
            const menuItem = e.currentTarget.parentElement;
            const submenu = menuItem.querySelector('ul');

            if (window.innerWidth <= 768 && submenu) {
                e.preventDefault();
                menuItem.classList.toggle('active');

                // Close other open submenus
                const otherMenuItems = Array.from(this.menuItems).map(item => item.parentElement);
                otherMenuItems.forEach(item => {
                    if (item !== menuItem && item.classList.contains('active')) {
                        item.classList.remove('active');
                    }
                });
            }
        }

        handleDocumentClick(e) {
            if (!this.primaryMenu.contains(e.target) && !this.menuToggle.contains(e.target)) {
                this.closeMenu();
            }
        }

        handleKeydown(e) {
            if (e.key === 'Escape') {
                this.closeMenu();
            }

            // Trap focus within mobile menu when open
            if (e.key === 'Tab' && this.primaryMenu.classList.contains('active')) {
                this.trapFocus(e);
            }
        }

        closeMenu() {
            this.menuToggle.setAttribute('aria-expanded', 'false');
            this.primaryMenu.classList.remove('active');
            this.menuToggle.classList.remove('is-active');
            document.body.classList.remove('menu-open');

            // Close all submenus
            document.querySelectorAll('.menu-item.active').forEach(item => {
                item.classList.remove('active');
            });
        }

        trapFocus(e) {
            const focusableElements = this.primaryMenu.querySelectorAll(
                'a[href], button, textarea, input, select, [tabindex]:not([tabindex="-1"])'
            );
            const firstElement = focusableElements[0];
            const lastElement = focusableElements[focusableElements.length - 1];

            if (e.shiftKey) {
                if (document.activeElement === firstElement) {
                    e.preventDefault();
                    lastElement.focus();
                }
            } else {
                if (document.activeElement === lastElement) {
                    e.preventDefault();
                    firstElement.focus();
                }
            }
        }
    }

    /**
     * Mega menu functionality
     */
    class MegaMenu {
        constructor() {
            this.megaMenuItems = document.querySelectorAll('.menu-item-has-megamenu');
            this.init();
        }

        init() {
            if (this.megaMenuItems.length > 0) {
                this.megaMenuItems.forEach(item => {
                    item.addEventListener('mouseenter', () => this.openMegaMenu(item));
                    item.addEventListener('mouseleave', () => this.closeMegaMenu(item));
                    item.addEventListener('focusin', () => this.openMegaMenu(item));
                    item.addEventListener('focusout', (e) => this.handleMegaMenuFocusOut(e, item));
                });
            }
        }

        openMegaMenu(menuItem) {
            if (window.innerWidth > 768) {
                const megaMenu = menuItem.querySelector('ul');
                if (megaMenu) {
                    megaMenu.style.display = 'flex';
                    menuItem.classList.add('mega-open');
                }
            }
        }

        closeMegaMenu(menuItem) {
            if (window.innerWidth > 768) {
                const megaMenu = menuItem.querySelector('ul');
                if (megaMenu) {
                    megaMenu.style.display = 'none';
                    menuItem.classList.remove('mega-open');
                }
            }
        }

        handleMegaMenuFocusOut(e, menuItem) {
            if (window.innerWidth > 768) {
                setTimeout(() => {
                    if (!menuItem.contains(document.activeElement)) {
                        this.closeMegaMenu(menuItem);
                    }
                }, 100);
            }
        }
    }

    /**
     * Smooth scrolling for anchor links
     */
    class SmoothScroll {
        constructor() {
            this.init();
        }

        init() {
            document.addEventListener('click', (e) => {
                const link = e.target.closest('a[href^="#"]');
                if (link && this.isSamePageAnchor(link)) {
                    e.preventDefault();
                    this.scrollToTarget(link.getAttribute('href'));
                }
            });
        }

        isSamePageAnchor(link) {
            return link.hash && link.pathname === window.location.pathname;
        }

        scrollToTarget(targetId) {
            const target = document.querySelector(targetId);
            if (target) {
                const headerHeight = document.querySelector('.site-header')?.offsetHeight || 0;
                const targetPosition = target.offsetTop - headerHeight - 20;

                window.scrollTo({
                    top: targetPosition,
                    behavior: 'smooth'
                });

                // Update URL without jumping
                history.pushState(null, null, targetId);

                // Focus the target for accessibility
                target.setAttribute('tabindex', '-1');
                target.focus();
            }
        }
    }

    /**
     * Sticky header functionality
     */
    class StickyHeader {
        constructor() {
            this.header = document.querySelector('.site-header');
            this.lastScrollY = window.scrollY;
            this.scrollDirection = 'down';

            if (this.header && this.header.classList.contains('has-sticky-header')) {
                this.init();
            }
        }

        init() {
            window.addEventListener('scroll', () => this.handleScroll());
            this.updateHeaderState();
        }

        handleScroll() {
            const currentScrollY = window.scrollY;

            // Determine scroll direction
            this.scrollDirection = currentScrollY > this.lastScrollY ? 'down' : 'up';
            this.lastScrollY = currentScrollY;

            this.updateHeaderState();
        }

        updateHeaderState() {
            const scrollY = window.scrollY;

            if (scrollY > 100) {
                this.header.classList.add('sticky-active');

                if (this.scrollDirection === 'down') {
                    this.header.classList.add('sticky-hidden');
                } else {
                    this.header.classList.remove('sticky-hidden');
                }
            } else {
                this.header.classList.remove('sticky-active', 'sticky-hidden');
            }
        }
    }

    /**
     * Initialize all navigation functionality when DOM is loaded
     */
    document.addEventListener('DOMContentLoaded', function() {
        new MobileNavigation();
        new MegaMenu();
        new SmoothScroll();
        new StickyHeader();
    });

})();
