<?php
/**
 * Customizer sanitization functions
 *
 * @package Abundant_Thought
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Sanitize checkbox
 */
function at_sanitize_checkbox( $input ) {
	return ( isset( $input ) && true == $input ) ? true : false;
}

/**
 * Sanitize select
 */
function at_sanitize_select( $input, $setting ) {
	$input = sanitize_key( $input );
	$choices = $setting->manager->get_control( $setting->id )->choices;
	return ( array_key_exists( $input, $choices ) ? $input : $setting->default );
}

/**
 * Sanitize font family
 */
function at_sanitize_font_family( $input ) {
	$choices = at_get_font_family_choices();
	return ( array_key_exists( $input, $choices ) ? $input : 'inherit' );
}

/**
 * Sanitize font size
 */
function at_sanitize_font_size( $input ) {
	$choices = at_get_font_size_choices();
	return ( array_key_exists( $input, $choices ) ? $input : '1rem' );
}

/**
 * Sanitize font weight
 */
function at_sanitize_font_weight( $input ) {
	$choices = at_get_font_weight_choices();
	return ( array_key_exists( $input, $choices ) ? $input : '400' );
}

/**
 * Sanitize letter spacing
 */
function at_sanitize_letter_spacing( $input ) {
	$input = floatval( $input );
	return ( $input >= -0.1 && $input <= 0.5 ) ? $input : 0;
}

/**
 * Sanitize logo alignment
 */
function at_sanitize_logo_alignment( $input ) {
	$valid = array( 'left', 'center', 'right' );
	return ( in_array( $input, $valid ) ) ? $input : 'left';
}

/**
 * Sanitize header layout
 */
function at_sanitize_header_layout( $input ) {
	$valid = array( 'full-width', 'boxed', 'centered' );
	return ( in_array( $input, $valid ) ) ? $input : 'full-width';
}

/**
 * Sanitize search position
 */
function at_sanitize_search_position( $input ) {
	$valid = array( 'left', 'center', 'right' );
	return ( in_array( $input, $valid ) ) ? $input : 'right';
}

/**
 * Sanitize social alignment
 */
function at_sanitize_social_alignment( $input ) {
	$valid = array( 'left', 'center', 'right' );
	return ( in_array( $input, $valid ) ) ? $input : 'left';
}

/**
 * Sanitize menu position
 */
function at_sanitize_menu_position( $input ) {
	$valid = array( 'in-header', 'above-header', 'below-header' );
	return ( in_array( $input, $valid ) ) ? $input : 'in-header';
}

/**
 * Sanitize menu alignment
 */
function at_sanitize_menu_alignment( $input ) {
	$valid = array( 'left', 'center', 'right' );
	return ( in_array( $input, $valid ) ) ? $input : 'left';
}

/**
 * Sanitize dropdown animation
 */
function at_sanitize_dropdown_animation( $input ) {
	$valid = array( 'fade', 'slide', 'none' );
	return ( in_array( $input, $valid ) ) ? $input : 'fade';
}

/**
 * Sanitize number range
 */
function at_sanitize_number_range( $input, $setting ) {
	$input = absint( $input );
	$atts = $setting->manager->get_control( $setting->id )->input_attrs;

	$min = ( isset( $atts['min'] ) ? $atts['min'] : $input );
	$max = ( isset( $atts['max'] ) ? $atts['max'] : $input );
	$step = ( isset( $atts['step'] ) ? $atts['step'] : 1 );

	return ( $input >= $min && $input <= $max && is_int( $input / $step ) ? $input : $setting->default );
}

/**
 * Sanitize HTML
 */
function at_sanitize_html( $input ) {
	return wp_kses_post( $input );
}

/**
 * Sanitize URL
 */
function at_sanitize_url( $input ) {
	return esc_url_raw( $input );
}

/**
 * Sanitize textarea
 */
function at_sanitize_textarea( $input ) {
	return sanitize_textarea_field( $input );
}

/**
 * Sanitize color with fallback
 */
function at_sanitize_color( $input ) {
	if ( empty( $input ) ) {
		return '';
	}

	if ( false === strpos( $input, 'rgba' ) ) {
		return sanitize_hex_color( $input );
	}

	// Sanitize rgba color
	$input = str_replace( ' ', '', $input );
	sscanf( $input, 'rgba(%d,%d,%d,%f)', $red, $green, $blue, $alpha );
	return 'rgba(' . $red . ',' . $green . ',' . $blue . ',' . $alpha . ')';
}
