    font-size: 1.25rem;
    margin-bottom: 30px;
    opacity: 0.9;
    line-height: 1.6;
}

.hero-buttons {
    display: flex;
    gap: 15px;
    justify-content: center;
    flex-wrap: wrap;
}

/* Hero Button Styles */
.hero-buttons .button {
    display: inline-block;
    padding: 15px 35px;
    border-radius: 4px;
    text-decoration: none;
    font-weight: 600;
    transition: all 0.3s ease;
    border: 2px solid transparent;
    font-size: 1.1rem;
}

.hero-buttons .button-primary {
    background: #FFFFFF;
    color: var(--at-primary-color);
}

.hero-buttons .button-primary:hover {
    background: transparent;
    color: #FFFFFF;
    border-color: #FFFFFF;
    transform: translateY(-2px);
}

.hero-buttons .button-secondary {
    background: transparent;
    color: #FFFFFF;
    border-color: #FFFFFF;
}

.hero-buttons .button-secondary:hover {
    background: #FFFFFF;
    color: var(--at-primary-color);
    transform: translateY(-2px);
}

@media (max-width: 768px) {
    .front-page-hero {
        padding: 60px 0;
    }

    .hero-title {
        font-size: 2rem;
    }

    .hero-description {
        font-size: 1rem;
    }

    .hero-buttons {
        flex-direction: column;
        align-items: center;
    }

    .hero-buttons .button {
        width: 200px;
        text-align: center;
    }
}
