// 2. HEADER LAYOUT HELPER FUNCTIONS
function abundant_thought_get_header_layout() {
    $layout = array();

    $elements = array('logo', 'site_title', 'menu', 'search', 'cta', 'social');

    foreach ($elements as $element) {
        $layout[$element] = array(
            'position' => get_theme_mod("header_{$element}_position", 'left'),
            'visible' => true
        );
    }

    // Override visibility based on settings
    $layout['site_title']['visible'] = get_theme_mod('header_show_site_title', true);
    $layout['search']['visible'] = get_theme_mod('header_show_search', true);
    $layout['cta']['visible'] = get_theme_mod('header_show_cta', false);
    $layout['social']['visible'] = get_theme_mod('header_show_social', false);

    $layout['menu_vertical'] = get_theme_mod('header_menu_vertical', 'in-header');

    return $layout;
}

// 3. DYNAMIC CSS CLASSES
function abundant_thought_header_classes() {
    $layout = abundant_thought_get_header_layout();
    $classes = array();

    // Add position classes for each element
    foreach ($layout as $element => $settings) {
        if ($element !== 'menu_vertical' && $settings['visible']) {
            $classes[] = "header-{$element}-{$settings['position']}";
        }
    }

    // Add menu vertical position class
    $classes[] = "menu-{$layout['menu_vertical']}";

    // Add visibility classes
    if (!$layout['site_title']['visible']) $classes[] = 'no-site-title';
    if (!$layout['search']['visible']) $classes[] = 'no-search';
    if (!$layout['cta']['visible']) $classes[] = 'no-cta';
    if (!$layout['social']['visible']) $classes[] = 'no-social';

    return implode(' ', $classes);
}
