        function initSmoothScroll() {
            $('a[href*="#"]:not([href="#"])').on('click', function(e) {
                if (location.pathname.replace(/^\//, '') === this.pathname.replace(/^\//, '') && 
                    location.hostname === this.hostname) {

                    const target = $(this.hash);
                    if (target.length) {
                        e.preventDefault();
                        $('html, body').animate({
