                    searchField.focus();
                }
            });

            // Expand search on focus (mobile)
            searchField.on('focus', function() {
                if (window.innerWidth <= 768) {
                    $(this).parent().addClass('expanded');
                }
            });

            searchField.on('blur', function() {
