/**
 * Sanitization Functions
 */
function abundant_thought_sanitize_header_preset($input) {
    $valid = array('default', 'centered', 'split', 'stacked');
    return in_array($input, $valid) ? $input : 'default';
}

function abundant_thought_sanitize_horizontal_position($input) {
    $valid = array('left', 'center', 'right');
    return in_array($input, $valid) ? $input : 'left';
}

function abundant_thought_sanitize_vertical_placement($input) {
    $valid = array('above', 'inline', 'below');
    return in_array($input, $valid) ? $input : 'inline';
}

function abundant_thought_sanitize_element_display($input) {
    $valid = array('none', 'left', 'right');
    return in_array($input, $valid) ? $input : 'none';
}

/**
 * Header Layout Utility Functions
 */

/**
 * Get header layout configuration
 */
function abundant_thought_get_header_layout() {
    return array(
        'preset'        => get_theme_mod('abundant_thought_header_layout_preset', 'default'),
        'logo_position' => get_theme_mod('abundant_thought_logo_position', 'left'),
        'menu_position' => get_theme_mod('abundant_thought_menu_position', 'right'),
        'menu_vertical' => get_theme_mod('abundant_thought_menu_vertical_placement', 'inline'),
        'search'        => get_theme_mod('abundant_thought_search_display', 'right'),
        'cta'           => get_theme_mod('abundant_thought_cta_display', 'right'),
        'cta_text'      => get_theme_mod('abundant_thought_cta_text', __('Get Started', 'abundant-thought')),
        'cta_url'       => get_theme_mod('abundant_thought_cta_url', home_url('/contact')),
        'social'        => get_theme_mod('abundant_thought_social_display', 'none'),
    );
}

/**
 * Generate CSS Grid classes for header layout
 */
function abundant_thought_header_classes() {
    $layout = abundant_thought_get_header_layout();
    $classes = array('site-header', 'header-grid');

    // Preset class
    $classes[] = 'header-preset-' . $layout['preset'];

    // Logo position
    $classes[] = 'logo-' . $layout['logo_position'];

    // Menu position
    $classes[] = 'menu-' . $layout['menu_position'];

    // Menu vertical placement
    $classes[] = 'menu-vertical-' . $layout['menu_vertical'];

    // Element visibility
    if ($layout['search'] !== 'none') {
        $classes[] = 'has-search';
        $classes[] = 'search-' . $layout['search'];
    }

    if ($layout['cta'] !== 'none') {
        $classes[] = 'has-cta';
        $classes[] = 'cta-' . $layout['cta'];
    }

    if ($layout['social'] !== 'none') {
        $classes[] = 'has-social';
        $classes[] = 'social-' . $layout['social'];
    }

    return implode(' ', $classes);
}

/**
 * Check if header element should be displayed
 */
function abundant_thought_should_display_element($element_type) {
    $layout = abundant_thought_get_header_layout();
    return isset($layout[$element_type]) && $layout[$element_type] !== 'none';
}

/**
 * Get social media links (placeholder - to be configured)
 */
function abundant_thought_get_social_links() {
    return array(
        'facebook'  => get_theme_mod('social_facebook', ''),
        'twitter'   => get_theme_mod('social_twitter', ''),
        'instagram' => get_theme_mod('social_instagram', ''),
        'linkedin'  => get_theme_mod('social_linkedin', ''),
        'youtube'   => get_theme_mod('social_youtube', ''),
    );
}
