## **Required JavaScript Files**

Create `/assets/js/theme.js`:
```javascript
/**
 * Abundant Thought Theme JavaScript
 * Mobile menu and interactive elements
 */

document.addEventListener('DOMContentLoaded', function() {

    // Mobile Menu Toggle
    const menuToggle = document.querySelector('.menu-toggle');
    const mobileMenuPanel = document.querySelector('.mobile-menu-panel');

    if (menuToggle && mobileMenuPanel) {
        menuToggle.addEventListener('click', function() {
            const isExpanded = this.getAttribute('aria-expanded') === 'true';
            this.setAttribute('aria-expanded', !isExpanded);
            mobileMenuPanel.classList.toggle('active', !isExpanded);
        });
    }

    // Search Toggle
    const searchToggle = document.querySelector('.search-toggle');
    const searchContainer = document.querySelector('.search-form-container');

    if (searchToggle && searchContainer) {
        searchToggle.addEventListener('click', function() {
            const isExpanded = this.getAttribute('aria-expanded') === 'true';
            this.setAttribute('aria-expanded', !isExpanded);
            this.parentElement.classList.toggle('active', !isExpanded);
        });

        // Close search when clicking outside
        document.addEventListener('click', function(event) {
            if (!event.target.closest('.header-search')) {
                searchToggle.setAttribute('aria-expanded', 'false');
                searchToggle.parentElement.classList.remove('active');
            }
        });
    }

    // Close mobile menu when clicking on a link
    const mobileMenuLinks = document.querySelectorAll('.mobile-navigation a');
    mobileMenuLinks.forEach(link => {
        link.addEventListener('click', function() {
            if (menuToggle && mobileMenuPanel) {
                menuToggle.setAttribute('aria-expanded', 'false');
                mobileMenuPanel.classList.remove('active');
            }
        });
    });

    // Keyboard navigation improvements
    document.addEventListener('keydown', function(event) {
        // Escape key closes menus
        if (event.key === 'Escape') {
            if (menuToggle && mobileMenuPanel && mobileMenuPanel.classList.contains('active')) {
                menuToggle.setAttribute('aria-expanded', 'false');
                mobileMenuPanel.classList.remove('active');
                menuToggle.focus();
            }

            if (searchToggle && searchContainer && searchContainer.parentElement.classList.contains('active')) {
                searchToggle.setAttribute('aria-expanded', 'false');
                searchContainer.parentElement.classList.remove('active');
                searchToggle.focus();
            }
        }
    });
});
