    function updateHeaderClasses() {
        var preset = wp.customize('abundant_thought_header_layout_preset').get();
        var $body = $('body');

        // Remove all header-related classes
        $body.removeClass(function(index, className) {
            return (className.match(/(^|\s)(header-preset-|logo-|menu-|has-|search-|cta-|social-)\S+/g) || []).join(' ');
        });

        // Add preset class
        $body.addClass('header-preset-' + preset);

        // For custom preset, use individual settings
        if (preset === 'custom') {
            var logoPos = wp.customize('abundant_thought_logo_position').get();
            var menuPos = wp.customize('abundant_thought_menu_position').get();
            var menuVert = wp.customize('abundant_thought_menu_vertical_placement').get();

            $body.addClass('logo-' + logoPos);
            $body.addClass('menu-' + menuPos);
            $body.addClass('menu-vertical-' + menuVert);
        } else {
            // For presets, use preset-specific classes
            switch(preset) {
                case 'default':
                case 'split':
                    $body.addClass('logo-left menu-right menu-vertical-inline');
                    break;
                case 'centered':
                    $body.addClass('logo-center menu-center menu-vertical-inline');
                    break;
                case 'stacked':
                    $body.addClass('logo-center menu-center menu-vertical-below');
                    break;
            }
