// src/services/audioService.ts - REWRITTEN VERSION
import { Soundscape } from '../types';

type AudioPriority = 'PRACTICE' | 'VOICE' | 'AMBIENCE' | 'UI';
type AudioSource = 'DEFAULT' | 'USER_UPLOAD' | 'ADMIN_UPLOAD';

interface AudioTrack {
  url: string;
  category: string;
  source: AudioSource;
  priority: AudioPriority;
  id: string;
}

class AudioManager {
  private static instance: AudioManager;
  private audioContext: AudioContext | null = null;
  private tracks: Map<string, HTMLAudioElement> = new Map();
  private currentPriority: AudioPriority | null = null;
  private currentTrackId: string | null = null;

  // Default tracks
  private defaultAmbience: AudioTrack = {
    id: 'default-ambience',
    url: './assets/audio/ambient-default.mp3',
    category: 'AMBIENCE',
    source: 'DEFAULT',
    priority: 'AMBIENCE'
  };

  private buttonClickSound: AudioTrack = {
    id: 'button-click',
    url: './assets/audio/button-click.mp3',
    category: 'UI',
    source: 'DEFAULT',
    priority: 'UI'
  };

  private isInitialized = false;
  private isMuted = false;
  private masterVolume = 0.5;
  private backgroundVolume = 0.3;
  private practiceVolume = 0.5;

  static getInstance(): AudioManager {
    if (!AudioManager.instance) {
      AudioManager.instance = new AudioManager();
    }
    return AudioManager.instance;
  }

  async initialize(): Promise<void> {
    if (this.isInitialized) return;

    try {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      this.isInitialized = true;

      // Preload default sounds
      await this.preloadSound(this.defaultAmbience);
      await this.preloadSound(this.buttonClickSound);
    } catch (error) {
      console.warn('AudioContext not supported, falling back to HTML5 Audio');
    }
  }

  private async preloadSound(track: AudioTrack): Promise<void> {
    return new Promise((resolve) => {
      const audio = new Audio();
      audio.src = track.url;
      audio.preload = 'auto';
      audio.load();

      audio.addEventListener('canplaythrough', () => {
        this.tracks.set(track.id, audio);
        resolve();
      }, { once: true });

      audio.addEventListener('error', () => {
        console.warn(`Failed to load sound: ${track.url}`);
        resolve();
      }, { once: true });
    });
  }

  // START BACKGROUND AMBIENCE
  async startBackgroundAmbience(customTrack?: Soundscape | string): Promise<void> {
    // Stop any current background
    this.stopByPriority('AMBIENCE');

    let track: AudioTrack;

    if (customTrack) {
      const url = typeof customTrack === 'string' ? customTrack : customTrack.url;
      if (!url) {
        track = this.defaultAmbience;
      } else {
        track = {
          id: `custom-ambience-${Date.now()}`,
          url: this.resolveUrl(url),
          category: 'AMBIENCE',
          source: 'USER_UPLOAD',
          priority: 'AMBIENCE'
        };
      }
    } else {
      track = this.defaultAmbience;
    }

    await this.playTrack(track, { loop: true, volume: this.backgroundVolume });
    this.currentPriority = 'AMBIENCE';
    this.currentTrackId = track.id;
  }

  // START PRACTICE AUDIO (I AM / I LOVE / MEDITATION)
  async startPracticeAudio(
    soundscape: Soundscape, 
    practiceType: string,
    resumeBackground: boolean = true
  ): Promise<void> {
    // Store current background for later resumption
    const currentBackground = this.currentTrackId;

    // Stop current audio
    this.stopAll();

    const track: AudioTrack = {
      id: `practice-${practiceType}-${soundscape.id}`,
      url: this.resolveUrl(soundscape.url || ''),
      category: practiceType,
      source: soundscape.url?.includes('user_') ? 'USER_UPLOAD' : 'ADMIN_UPLOAD',
      priority: 'PRACTICE'
    };

    await this.playTrack(track, { 
      loop: true, 
      volume: this.practiceVolume,
      onEnd: resumeBackground ? () => {
        if (currentBackground) {
          const bgAudio = this.tracks.get(currentBackground);
          if (bgAudio) {
            bgAudio.play().catch(() => {});
            this.currentPriority = 'AMBIENCE';
            this.currentTrackId = currentBackground;
          }
        }
      } : undefined
    });

    this.currentPriority = 'PRACTICE';
    this.currentTrackId = track.id;
  }

  // PLAY VOICE (Welcome message, etc.)
  async playVoice(url: string): Promise<void> {
    this.stopByPriority('VOICE');

    const track: AudioTrack = {
      id: `voice-${Date.now()}`,
      url: this.resolveUrl(url),
      category: 'VOICE',
      source: 'DEFAULT',
      priority: 'VOICE'
    };

    await this.playTrack(track, { 
      loop: false, 
      volume: 0.8,
      onEnd: () => {
        // Resume background after voice ends
        if (this.currentTrackId !== track.id) {
          const bgAudio = this.tracks.get(this.currentTrackId || '');
          if (bgAudio && bgAudio.paused) {
            bgAudio.play().catch(() => {});
          }
        }
      }
    });

    this.currentPriority = 'VOICE';
    this.currentTrackId = track.id;
  }

  // PLAY UI SOUNDS (buttons, etc.)
  playUiSound(type: 'click' | 'confirm' | 'back' = 'click'): void {
    if (this.isMuted) return;

    const sound = this.buttonClickSound;
    const audio = new Audio(sound.url);
    audio.volume = 0.3;
    audio.play().catch(() => {});
  }

  // UTILITY METHODS
  private async playTrack(
    track: AudioTrack, 
    options: { loop: boolean; volume: number; onEnd?: () => void }
  ): Promise<void> {
    let audio = this.tracks.get(track.id);

    if (!audio) {
      audio = new Audio(track.url);
      this.tracks.set(track.id, audio);
    }

    audio.loop = options.loop;
    audio.volume = this.isMuted ? 0 : options.volume;

    if (options.onEnd) {
      audio.onended = options.onEnd;
    }

    try {
      await audio.play();
    } catch (error) {
      console.warn('Audio play failed:', error);
    }
  }

  private stopByPriority(priority: AudioPriority): void {
    for (const [id, audio] of this.tracks.entries()) {
      if (audio && !audio.paused) {
        audio.pause();
        audio.currentTime = 0;
      }
    }
  }

  stopAll(): void {
    this.stopByPriority('AMBIENCE');
    this.stopByPriority('PRACTICE');
    this.stopByPriority('VOICE');
    this.currentPriority = null;
    this.currentTrackId = null;
  }

  setMuted(muted: boolean): void {
    this.isMuted = muted;
    for (const audio of this.tracks.values()) {
      if (audio) {
        audio.volume = muted ? 0 : this.masterVolume;
      }
    }
  }

  setVolume(volume: number): void {
    this.masterVolume = Math.max(0, Math.min(1, volume));
    if (!this.isMuted) {
      for (const audio of this.tracks.values()) {
        if (audio && !audio.paused) {
          audio.volume = this.masterVolume;
        }
      }
    }
  }

  private resolveUrl(url: string): string {
    // Handle different URL formats
    if (!url) return '';

    if (url.startsWith('http://') || url.startsWith('https://') || url.startsWith('/')) {
      return url;
    }

    if (url.startsWith('user_') || url.startsWith('admin_')) {
      // This should point to your PHP endpoint that serves uploaded files
      return `/abundance-alchemy/api/get-audio.php?file=${encodeURIComponent(url)}`;
    }

    // Local asset
    return `./assets/audio/${url}`;
  }
}

export const audioManager = AudioManager.getInstance();

// Legacy API for compatibility
export const startAmbience = (soundscape?: Soundscape | string) => {
  audioManager.startBackgroundAmbience(soundscape);
};

export const stopAmbience = () => {
  audioManager.stopAll();
};

export const previewSoundscape = (soundscape: Soundscape) => {
  const tempAudio = new Audio(audioManager['resolveUrl'](soundscape.url || ''));
  tempAudio.volume = 0.5;
  tempAudio.play().catch(() => {});
  setTimeout(() => tempAudio.pause(), 5000);
};

export const playCompletionSound = () => {
  audioManager.playUiSound('confirm');
};
