    });

    this.currentPriority = 'AMBIENCE';
    this.currentTrackId = track.id;
    this.backgroundQueue = null;
  }

  // 2. PRACTICE AUDIO (I AM / I LOVE / MEDITATION)
  async startPracticeAudio(
    soundscape: Soundscape, 
    practiceType: string
  ): Promise<void> {
    // Stop current audio
    this.stopAll();

    const track: AudioTrack = {
      id: `practice-${practiceType}-${soundscape.id}`,
      url: soundscape.url || '',
      category: practiceType,
      source: this.getSourceFromUrl(soundscape.url || ''),
      priority: 'PRACTICE',
      label: soundscape.label
    };

    await this.playTrack(track, { 
      loop: true, 
      volume: this.practiceVolume
    });

    this.currentPriority = 'PRACTICE';
    this.currentTrackId = track.id;
  }

  // 3. STOP PRACTICE & RESUME BACKGROUND
  async stopPracticeAndResumeBackground(): Promise<void> {
    if (this.currentPriority !== 'PRACTICE') return;

    this.stopByPriority('PRACTICE');
    this.currentPriority = null;
    this.currentTrackId = null;

    // Resume queued background or default
    if (this.backgroundQueue) {
      await this.startBackgroundAmbience(this.backgroundQueue);
    } else {
      await this.startBackgroundAmbience();
    }
  }

  // 4. VOICE MESSAGES
  async playVoice(url: string, pauseBackground: boolean = true): Promise<void> {
    if (pauseBackground && this.currentPriority === 'AMBIENCE') {
      const currentAudio = this.tracks.get(this.currentTrackId || '');
      if (currentAudio) {
        currentAudio.pause();
      }
    }

    const track: AudioTrack = {
      id: `voice-${Date.now()}`,
      url,
      category: 'VOICE',
      source: 'SYSTEM',
      priority: 'VOICE'
    };

    const audio = new Audio(this.resolveUrl(url));
    audio.volume = this.masterVolume;

    audio.onended = () => {
      // Resume background if it was paused
      if (pauseBackground && this.currentPriority === 'AMBIENCE') {
        const bgAudio = this.tracks.get(this.currentTrackId || '');
        if (bgAudio) {
          bgAudio.play().catch(() => {});
        }
      }
    };

    try {
      await audio.play();
    } catch (error) {
      console.warn('Voice playback failed:', error);
    }
  }

  // 5. UI SOUNDS
  playUiSound(type: 'click' | 'confirm' | 'back' = 'click'): void {
    if (this.isMuted) return;

    const sound = this.uiSounds[type];
    const audio = new Audio(this.resolveUrl(sound.url));
    audio.volume = sound.volume * this.masterVolume;
    audio.play().catch(() => {});
  }

  // 6. PREVIEW SOUNDSCAPE
  previewSoundscape(soundscape: Soundscape): void {
    const url = this.resolveUrl(soundscape.url || '');
    const previewAudio = new Audio(url);
    previewAudio.volume = 0.5;
    previewAudio.play().catch(() => {});

    // Auto-stop after 3 seconds
    setTimeout(() => {
      if (!previewAudio.paused) {
        previewAudio.pause();
      }
    }, 3000);
  }

  // 7. CONTROLS
  stopAll(): void {
    this.tracks.forEach(audio => {
      if (audio && !audio.paused) {
        audio.pause();
        audio.currentTime = 0;
      }
    });
    this.currentPriority = null;
    this.currentTrackId = null;
  }

  setMuted(muted: boolean): void {
    this.isMuted = muted;
    this.tracks.forEach(audio => {
      if (audio) {
        audio.volume = muted ? 0 : this.masterVolume;
      }
    });
  }

  setVolume(volume: number): void {
    this.masterVolume = Math.max(0, Math.min(1, volume));
    if (!this.isMuted) {
      this.tracks.forEach(audio => {
        if (audio && !audio.paused) {
          audio.volume = this.masterVolume;
        }
      });
    }
  }

  // UTILITIES
  private async playTrack(
    track: AudioTrack, 
    options: { loop: boolean; volume: number }
  ): Promise<void> {
    let audio = this.tracks.get(track.id);

    if (!audio) {
      audio = new Audio(this.resolveUrl(track.url));
      this.tracks.set(track.id, audio);
    }

    audio.loop = options.loop;
    audio.volume = this.isMuted ? 0 : options.volume;

    try {
      await audio.play();
    } catch (error) {
      console.warn(`Failed to play track ${track.label || track.id}:`, error);
    }
  }

  private stopByPriority(priority: AudioPriority): void {
    for (const [id, audio] of this.tracks.entries()) {
      if (audio && !audio.paused && this.currentPriority === priority) {
        audio.pause();
        audio.currentTime = 0;
      }
    }
  }

  private resolveUrl(url: string): string {
    if (!url) return '';

    // Already absolute URL
    if (url.startsWith('http://') || url.startsWith('https://') || url.startsWith('/')) {
      return url;
    }

    // User/admin uploaded file
    if (url.includes('user_') || url.includes('admin_')) {
      return `/abundance-alchemy/api/get-audio.php?file=${encodeURIComponent(url)}`;
    }

    // Local asset - ensure correct path
    if (url.startsWith('assets/')) {
      return `./${url}`;
    }

    // Default to audio directory
    return `./assets/audio/${url}`;
  }

  private getSourceFromUrl(url: string): AudioSource {
    if (url.includes('user_')) return 'USER_UPLOAD';
    if (url.includes('admin_')) return 'ADMIN_UPLOAD';
    if (url.startsWith('./assets/')) return 'SYSTEM';
    return 'DEFAULT';
  }

  // GETTERS
  getCurrentPriority(): AudioPriority | null {
    return this.currentPriority;
  }

  isPlaying(): boolean {
    return this.currentPriority !== null;
  }

  getVolume(): number {
    return this.masterVolume;
  }

  isAudioMuted(): boolean {
    return this.isMuted;
  }
}

// Singleton instance
export const audioManager = AudioManager.getInstance();

// Legacy API for compatibility with existing code
export const startAmbience = (soundscape?: Soundscape | string) => {
  audioManager.startBackgroundAmbience(soundscape);
};

export const stopAmbience = () => {
  audioManager.stopAll();
};

export const previewSoundscape = (soundscape: Soundscape) => {
  audioManager.previewSoundscape(soundscape);
};

export const playCompletionSound = () => {
  audioManager.playUiSound('confirm');
};

export const playBell = () => {
  audioManager.playUiSound('confirm');
};

export const getAmbienceAudio = (): HTMLAudioElement | null => {
  // Return the current audio element if exists
  const tracks = (audioManager as any).tracks;
  for (const audio of tracks.values()) {
    if (audio && !audio.paused) {
      return audio;
    }
  }
  return null;
};

export const isPracticeActive = (): boolean => {
  return audioManager.getCurrentPriority() === 'PRACTICE';
};

export const setAudioSettings = (effectsOn: boolean, musicOn: boolean) => {
  audioManager.setMuted(!musicOn);
  // Note: Button sounds are handled separately
};

export const updateVolume = (percent: number) => {
  audioManager.setVolume(percent / 100);
};
