// src/services/audioService.ts
import { Soundscape } from '../types';

type AudioPriority = 'PRACTICE' | 'VOICE' | 'AMBIENCE' | 'UI';
type AudioSource = 'DEFAULT' | 'USER_UPLOAD' | 'ADMIN_UPLOAD' | 'SYSTEM';

interface AudioTrack {
  url: string;
  category: string;
  source: AudioSource;
  priority: AudioPriority;
  id: string;
  label?: string;
}

class AudioManager {
  private static instance: AudioManager;
  private tracks: Map<string, HTMLAudioElement> = new Map();
  private currentPriority: AudioPriority | null = null;
  private currentTrackId: string | null = null;
  private pendingBackgroundResume: boolean = false;

  // Default tracks
  private defaultAmbience: AudioTrack = {
    id: 'default-ambience',
    url: './assets/audio/ambient/calm.mp3',
    category: 'AMBIENCE',
    source: 'DEFAULT',
    priority: 'AMBIENCE',
    label: 'Default Ambience'
  };

  private uiSounds = {
    click: { url: './assets/audio/ui/click.mp3', volume: 0.3 },
    confirm: { url: './assets/audio/ui/confirm.mp3', volume: 0.4 },
    back: { url: './assets/audio/ui/back.mp3', volume: 0.3 }
  };

  private isMuted = false;
  private masterVolume = 0.5;
  private backgroundVolume = 0.3;
  private practiceVolume = 0.5;
  private uiVolume = 0.3;

  // Queue for background music to resume
  private backgroundQueue: AudioTrack | null = null;

  static getInstance(): AudioManager {
    if (!AudioManager.instance) {
      AudioManager.instance = new AudioManager();
    }
    return AudioManager.instance;
  }

  // INITIALIZATION
  async initialize(): Promise<void> {
    // Preload default sounds
    await this.preloadTrack(this.defaultAmbience);
    console.log('AudioManager initialized');
  }

  private async preloadTrack(track: AudioTrack): Promise<void> {
    return new Promise((resolve) => {
      const audio = new Audio();
      audio.src = this.resolveUrl(track.url);
      audio.preload = 'auto';
      audio.load();

      audio.addEventListener('canplaythrough', () => {
        this.tracks.set(track.id, audio);
        resolve();
      }, { once: true });

      audio.addEventListener('error', () => {
        console.warn(`Failed to load sound: ${track.url}`);
        resolve();
      }, { once: true });
    });
  }

  // PUBLIC API

  // 1. BACKGROUND AMBIENCE
  async startBackgroundAmbience(customTrack?: Soundscape | string): Promise<void> {
    // If practice is active, queue the background to resume later
    if (this.currentPriority === 'PRACTICE') {
      if (customTrack) {
        const url = typeof customTrack === 'string' ? customTrack : customTrack.url;
        this.backgroundQueue = {
          id: `queued-${Date.now()}`,
          url: url || this.defaultAmbience.url,
          category: 'AMBIENCE',
          source: 'SYSTEM',
          priority: 'AMBIENCE',
          label: typeof customTrack === 'object' ? customTrack.label : 'Custom'
        };
      } else {
        this.backgroundQueue = this.defaultAmbience;
      }
      return;
    }

    // Stop any current background
    this.stopByPriority('AMBIENCE');

    let track: AudioTrack;

    if (customTrack) {
      const url = typeof customTrack === 'string' ? customTrack : customTrack.url;
      if (!url) {
        track = this.defaultAmbience;
      } else {
        track = {
          id: `ambience-${Date.now()}`,
          url,
          category: 'AMBIENCE',
          source: this.getSourceFromUrl(url),
          priority: 'AMBIENCE',
          label: typeof customTrack === 'object' ? customTrack.label : 'Custom'
        };
      }
    } else {
      track = this.defaultAmbience;
    }

    await this.playTrack(track, { 
      loop: true, 
      volume: this.backgroundVolume 
    });

    this.currentPriority = 'AMBIENCE';
    this.currentTrackId = track.id;
    this.backgroundQueue = null;
  }

  // 2. PRACTICE AUDIO (I AM / I LOVE / MEDITATION)
  async startPracticeAudio(
    soundscape: Soundscape, 
    practiceType: string
  ): Promise<void> {
    // Stop current audio
    this.stopAll();

    const track: AudioTrack = {
      id: `practice-${practiceType}-${soundscape.id}`,
      url: soundscape.url || '',
      category: practiceType,
      source: this.getSourceFromUrl(soundscape.url || ''),
      priority: 'PRACTICE',
      label: soundscape.label
    };

    await this.playTrack(track, { 
      loop: true, 
      volume: this.practiceVolume
    });

    this.currentPriority = 'PRACTICE';
    this.currentTrackId = track.id;
  }

  // 3. STOP PRACTICE & RESUME BACKGROUND
  async stopPracticeAndResumeBackground(): Promise<void> {
    if (this.currentPriority !== 'PRACTICE') return;

    this.stopByPriority('PRACTICE');
    this.currentPriority = null;
    this.currentTrackId = null;

    // Resume queued background or default
    if (this.backgroundQueue) {
      await this.startBackgroundAmbience(this.backgroundQueue);
    } else {
      await this.startBackgroundAmbience();
    }
  }

  // 4. VOICE MESSAGES
  async playVoice(url: string, pauseBackground: boolean = true): Promise<void> {
    if (pauseBackground && this.currentPriority === 'AMBIENCE') {
      const currentAudio = this.tracks.get(this.currentTrackId || '');
      if (currentAudio) {
        currentAudio.pause();
      }
    }

    const track: AudioTrack = {
      id: `voice-${Date.now()}`,
      url,
      category: 'VOICE',
      source: 'SYSTEM',
      priority: 'VOICE'
    };

    const audio = new Audio(this.resolveUrl(url));
    audio.volume = this.masterVolume;

    audio.onended = () => {
      // Resume background if it was paused
      if (pauseBackground && this.currentPriority === 'AMBIENCE') {
        const bgAudio = this.tracks.get(this.currentTrackId || '');
        if (bgAudio) {
          bgAudio.play().catch(() => {});
        }
      }
    };

    try {
      await audio.play();
    } catch (error) {
      console.warn('Voice playback failed:', error);
    }
  }

  // 5. UI SOUNDS
  playUiSound(type: 'click' | 'confirm' | 'back' = 'click'): void {
    if (this.isMuted) return;

    const sound = this.uiSounds[type];
    const audio = new Audio(this.resolveUrl(sound.url));
    audio.volume = sound.volume * this.masterVolume;
    audio.play().catch(() => {});
  }

  // 6. PREVIEW SOUNDSCAPE
  previewSoundscape(soundscape: Soundscape): void {
    const url = this.resolveUrl(soundscape.url || '');
    const previewAudio = new Audio(url);
    previewAudio.volume = 0.5;
    previewAudio.play().catch(() => {});

    // Auto-stop after 3 seconds
    setTimeout(() => {
      if (!previewAudio.paused) {
        previewAudio.pause();
      }
    }, 3000);
  }

  // 7. CONTROLS
  stopAll(): void {
    this.tracks.forEach(audio => {
      if (audio && !audio.paused) {
        audio.pause();
        audio.currentTime = 0;
      }
    });
    this.currentPriority = null;
    this.currentTrackId = null;
  }

  setMuted(muted: boolean): void {
    this.isMuted = muted;
    this.tracks.forEach(audio => {
      if (audio) {
        audio.volume = muted ? 0 : this.masterVolume;
      }
    });
  }

  setVolume(volume: number): void {
    this.masterVolume = Math.max(0, Math.min(1, volume));
    if (!this.isMuted) {
      this.tracks.forEach(audio => {
        if (audio && !audio.paused) {
          audio.volume = this.masterVolume;
        }
      });
    }
  }

  // UTILITIES
  private async playTrack(
    track: AudioTrack, 
    options: { loop: boolean; volume: number }
  ): Promise<void> {
    let audio = this.tracks.get(track.id);

    if (!audio) {
      audio = new Audio(this.resolveUrl(track.url));
      this.tracks.set(track.id, audio);
    }

    audio.loop = options.loop;
    audio.volume = this.isMuted ? 0 : options.volume;

    try {
      await audio.play();
    } catch (error) {
      console.warn(`Failed to play track ${track.label || track.id}:`, error);
    }
  }

  private stopByPriority(priority: AudioPriority): void {
    for (const [id, audio] of this.tracks.entries()) {
      if (audio && !audio.paused && this.currentPriority === priority) {
        audio.pause();
        audio.currentTime = 0;
      }
    }
  }

  private resolveUrl(url: string): string {
    if (!url) return '';

    // Already absolute URL
    if (url.startsWith('http://') || url.startsWith('https://') || url.startsWith('/')) {
      return url;
    }

    // User/admin uploaded file
    if (url.includes('user_') || url.includes('admin_')) {
      return `/abundance-alchemy/api/get-audio.php?file=${encodeURIComponent(url)}`;
    }

    // Local asset - ensure correct path
    if (url.startsWith('assets/')) {
      return `./${url}`;
    }

    // Default to audio directory
    return `./assets/audio/${url}`;
  }

  private getSourceFromUrl(url: string): AudioSource {
    if (url.includes('user_')) return 'USER_UPLOAD';
    if (url.includes('admin_')) return 'ADMIN_UPLOAD';
    if (url.startsWith('./assets/')) return 'SYSTEM';
    return 'DEFAULT';
  }

  // GETTERS
  getCurrentPriority(): AudioPriority | null {
    return this.currentPriority;
  }

  isPlaying(): boolean {
    return this.currentPriority !== null;
  }

  getVolume(): number {
    return this.masterVolume;
  }

  isAudioMuted(): boolean {
    return this.isMuted;
  }
}

