// src/services/buttonSoundService.ts
import { audioManager } from './audioService';

export type ButtonSoundType = 'click' | 'confirm' | 'back';

class ButtonSoundService {
  private static instance: ButtonSoundService;
  private enabled = true;
  private sounds: Record<ButtonSoundType, string> = {
    click: './assets/audio/ui/click.mp3',
    confirm: './assets/audio/ui/confirm.mp3',
    back: './assets/audio/ui/back.mp3'
  };

  static getInstance(): ButtonSoundService {
    if (!ButtonSoundService.instance) {
      ButtonSoundService.instance = new ButtonSoundService();
    }
    return ButtonSoundService.instance;
  }

  setEnabled(enabled: boolean): void {
    this.enabled = enabled;
  }

  play(type: ButtonSoundType = 'click'): void {
    if (!this.enabled) return;

    // Use audio manager if available, otherwise fallback
    if (audioManager) {
      audioManager.playUiSound(type);
    } else {
      const audio = new Audio(this.sounds[type]);
      audio.volume = 0.3;
      audio.play().catch(() => {});
    }
  }
}

export const buttonSoundService = ButtonSoundService.getInstance();

// React hook for button sounds
export const useButtonSound = () => {
  const playClick = () => buttonSoundService.play('click');
  const playConfirm = () => buttonSoundService.play('confirm');
  const playBack = () => buttonSoundService.play('back');

  return { playClick, playConfirm, playBack, setEnabled: buttonSoundService.setEnabled };
};

// Higher-order component for automatic button sounds
export const withButtonSound = (WrappedComponent: React.ComponentType<any>) => {
  return (props: any) => {
    const handleClick = (e: React.MouseEvent) => {
      buttonSoundService.play('click');
      if (props.onClick) props.onClick(e);
    };

    return <WrappedComponent {...props} onClick={handleClick} />;
  };
};
