    // Set initial audio settings
    buttonSoundService.setEnabled(settings.soundEffectsOn);
    setAudioSettings(settings.soundEffectsOn, settings.musicOn);
    updateVolume(settings.ambienceVolume);

    // Load soundscapes
    apiService.getSoundscapes().then((list) => {
      const normalized = (Array.isArray(list) ? list : []).map(normalizeSoundscape);
      setSoundscapes(normalized);
    });

    return () => {
      // Cleanup on unmount
      audioManager.stopAll();
    };
  }, []);

  // ---------- SETTINGS SYNC ----------
  useEffect(() => {
    localStorage.setItem('abundance_settings', JSON.stringify(settings));

    // Update audio settings when settings change
    buttonSoundService.setEnabled(settings.soundEffectsOn);
    setAudioSettings(settings.soundEffectsOn, settings.musicOn);
    updateVolume(settings.ambienceVolume);

    // Start/stop background based on music setting
    if (settings.musicOn && hasUserInteracted) {
      const activeSoundscape = soundscapes.find(s => s.id === settings.soundscapeId) || soundscapes[0];
      if (activeSoundscape && mode !== AppMode.PRACTICE && !isSplashWelcome) {
