import React, { useState } from 'react';
import { UserAccount } from '../types';
import { Lock, Mail, User, ArrowLeft, Eye, EyeOff, CheckCircle, KeyRound } from 'lucide-react';
import { AlchemistAvatar } from './AlchemistAvatar';
import { apiService } from '../services/apiService';
import { buttonSoundService } from '../services/buttonSoundService';

interface AuthProps {
  onRegister: (account: UserAccount) => void;
  onLogin: (account: UserAccount) => void;
  onBack?: () => void;
  theme: 'light' | 'dark';
}

export const Auth: React.FC<AuthProps> = ({ onRegister, onLogin, onBack, theme }) => {
  const [mode, setMode] = useState<'login' | 'register'>('register');
  const [showForgot, setShowForgot] = useState(false);

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [resetSent, setResetSent] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    buttonSoundService.play('click');
    setError('');

    const trimmedEmail = email.trim().toLowerCase();
    const trimmedName = name.trim();
    const trimmedPassword = password.trim();

    // Forgot Password Flow
    if (showForgot) {
      if (!trimmedEmail) {
        setError('Please enter your email address.');
        return;
      }
      setLoading(true);
      const sent = await apiService.requestPasswordReset(trimmedEmail);
      setLoading(false);

      if (sent) {
        setResetSent(true);
        setTimeout(() => {
          setShowForgot(false);
          setResetSent(false);
          setMode('login');
          setError('');
        }, 2000);
      } else {
        setError('Could not send reset link. Please try again.');
      }
      return;
    }

    // Normal Login/Register Flow
    if (!trimmedEmail || !trimmedPassword) {
      setError('Please fill in all fields');
      return;
    }

    if (mode === 'register' && !trimmedName) {
      setError('Please enter your name');
      return;
    }

    setLoading(true);

    try {
      if (mode === 'register') {
        const response = await apiService.register(trimmedName, trimmedEmail, trimmedPassword);

        if (response && response.message) {
          const msg = response.message.toLowerCase();
          if (msg.includes('exists') || msg.includes('registered') || msg.includes('duplicate')) {
            setMode('login');
            setPassword('');
            setError('Account exists. Please enter your password to sign in.');
            setLoading(false);
            return;
          }
          if (!response.id) {
            throw new Error(response.message);
          }
        }

        if (!response || !response.id) {
          throw new Error('Registration failed. Server did not respond with success.');
        }

        setSuccess(true);
        setTimeout(() => {
          const newAccount: UserAccount = {
            name: trimmedName,
            email: trimmedEmail,
            passwordHash: ''
          };
          onRegister(newAccount);
        }, 1500);
      } else {
        const response = await apiService.login(trimmedEmail, trimmedPassword);

        if (response && response.message && !response.id && !response.email) {
          throw new Error(response.message);
        }

        if (!response || (!response.id && !response.email)) {
          console.error('Login Response Invalid:', response);
          throw new Error(`Login failed. Server returned: ${JSON.stringify(response || 'null')}`);
        }

        setSuccess(true);
        setTimeout(() => {
          onLogin(response as UserAccount);
        }, 1500);
      }
    } catch (err: any) {
      console.error('Auth error:', err);
      setError(err.message || (mode === 'register' ? 'Registration failed.' : 'Login failed.'));
      setLoading(false);
    }
  };

  const textColor = 'text-slate-100';
  const subTextColor = 'text-slate-400';
  const inputBg = 'bg-slate-900/50 border-slate-700';
  const cardBg = 'bg-slate-900/80 border-slate-700';

  if (success) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-8 space-y-6 animate-in fade-in zoom-in">
        <div className="w-24 h-24 rounded-full bg-green-500/20 flex items-center justify-center border border-green-500/50 shadow-[0_0_30px_rgba(34,197,94,0.3)]">
          <CheckCircle size={48} className="text-green-500" />
        </div>
        <div className="text-center space-y-2">
          <h1 className="text-2xl font-bold font-serif text-white">Success!</h1>
          <p className="text-slate-300">{mode === 'register' ? 'Account created successfully' : 'Welcome back'}</p>
        </div>
      </div>
    );
  }

  if (resetSent) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-8 space-y-6 animate-in fade-in zoom-in">
        <div className="w-24 h-24 rounded-full bg-amber-500/20 flex items-center justify-center border border-amber-500/50 shadow-[0_0_30px_rgba(251,191,36,0.3)]">
          <Mail size={48} className="text-amber-500" />
        </div>
        <div className="text-center space-y-2">
          <h1 className="text-2xl font-bold font-serif text-white">Check Your Email</h1>
          <p className="text-slate-300">
            We've sent a password reset link to <br /> <span className="text-amber-400 font-bold">{email}</span>
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className={`h-full flex flex-col items-center justify-center p-8 space-y-6 max-w-md mx-auto relative ${textColor}`}>
      {onBack && !showForgot && (
        <button
          onClick={() => {
            buttonSoundService.play('back');
            onBack();
          }}
          type="button"
          className={`absolute top-4 left-4 flex items-center space-x-2 text-xs ${subTextColor} hover:text-amber-400 transition-colors`}
        >
          <ArrowLeft size={16} />
          <span>Back</span>
        </button>
      )}

      {showForgot && (
        <button
          onClick={() => {
            buttonSoundService.play('back');
            setShowForgot(false);
            setError('');
          }}
          type="button"
          className={`absolute top-4 left-4 flex items-center space-x-2 text-xs ${subTextColor} hover:text-amber-400 transition-colors`}
        >
          <ArrowLeft size={16} />
          <span>Back to Login</span>
        </button>
      )}

      <div className="relative">
        <img
          src="/logo.png"
          alt="Abundant Thought"
          className="h-16 object-contain mx-auto drop-shadow-[0_0_20px_rgba(251,191,36,0.3)]"
          onError={(e) => {
            e.currentTarget.style.display = 'none';
          }}
        />
      </div>

      <AlchemistAvatar size="md" mood="calm" speaking={false} />

      <div className="text-center space-y-2">
        <h1 className="text-2xl font-bold font-serif text-white">
          {showForgot ? 'Reset Password' : mode === 'login' ? 'Welcome Back' : 'Begin Your Journey'}
        </h1>
        <p className={`text-sm ${subTextColor}`}>
          {showForgot
            ? 'Enter your email to receive a reset link'
            : mode === 'login'
            ? 'Continue your transformation'
            : 'Create your account to start'}
        </p>
      </div>

      <form onSubmit={handleSubmit} className={`w-full space-y-4 rounded-2xl p-6 border shadow-xl ${cardBg}`} autoComplete="off">
        {mode === 'register' && !showForgot && (
          <div className="space-y-2">
            <label className={`text-xs font-bold ${subTextColor}`}>Name</label>
            <div className="relative">
              <User size={18} className={`absolute left-3 top-1/2 -translate-y-1/2 ${subTextColor}`} />
              <input
                type="text"
                name="name"
                autoComplete="name"
                inputMode="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Your name"
                className={`w-full pl-10 pr-4 py-3 rounded-xl border focus:ring-2 focus:ring-amber-500 outline-none transition-all ${inputBg} ${textColor} placeholder-slate-500`}
