```typescript
// audioService.ts
export interface Soundscape {
  id: string;
  label: string;
  url: string;  // Made required to match implementation
  category?: string;
}

export interface AudioSettings {
  soundEffects: boolean;
  music: boolean;
  ambienceVolume: number;
}

type AudioPriority = 'VOICE' | 'AMBIENCE' | 'EFFECT' | 'PRACTICE';

class AudioManager {
  private audioContext: AudioContext | null = null;
  private currentAudio: {
    [key in AudioPriority]?: {
      source: AudioBufferSourceNode | HTMLAudioElement;
      gainNode: GainNode;
      playing: boolean;
    }
  } = {};
  private currentVolume: number = 0.5;
  private currentSettings: AudioSettings = {
    soundEffects: true,
    music: true,
    ambienceVolume: 50
  };
  private ambienceTrackId: string | null = null;

  constructor() {
    // Initialize audio context on user interaction
    if (typeof window !== 'undefined') {
      document.addEventListener('click', () => {
        if (!this.audioContext) {
          this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        }
      }, { once: true });
    }
  }

  // Initialize method required by App.tsx
  initialize(): void {
    if (!this.audioContext) {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
  }

  // Stop all audio method required by App.tsx
  stopAll(): void {
    Object.keys(this.currentAudio).forEach(priority => {
      const audio = this.currentAudio[priority as AudioPriority];
      if (audio && audio.playing) {
        if (audio.source instanceof AudioBufferSourceNode) {
          audio.source.stop();
        } else if (audio.source instanceof HTMLAudioElement) {
          audio.source.pause();
        }
      }
    });
    this.currentAudio = {};
  }

  // Check if any audio is playing
  isPlaying(): boolean {
    return Object.values(this.currentAudio).some(audio => audio?.playing);
  }

  // Get current priority
  getCurrentPriority(): AudioPriority | null {
    const priorities: AudioPriority[] = ['VOICE', 'PRACTICE', 'AMBIENCE', 'EFFECT'];
    for (const priority of priorities) {
      if (this.currentAudio[priority]?.playing) {
        return priority;
      }
    }
    return null;
  }

  // Method required by PracticeSession flow
  stopPracticeAndResumeBackground(): void {
    // Stop practice audio
    const practiceAudio = this.currentAudio['PRACTICE'];
    if (practiceAudio?.playing) {
      if (practiceAudio.source instanceof AudioBufferSourceNode) {
        practiceAudio.source.stop();
      } else if (practiceAudio.source instanceof HTMLAudioElement) {
        practiceAudio.source.pause();
      }
      delete this.currentAudio['PRACTICE'];
    }

    // Resume background if we have a track ID
    if (this.ambienceTrackId && this.currentSettings.music) {
      this.playAmbience(this.ambienceTrackId);
    }
  }

  // Voice playback method required by SplashScreen
  playVoice(text: string, voiceId: string = 'Fenrir'): void {
    console.log(`Playing voice: ${text} with voice ${voiceId}`);
    // Implementation would call TTS service
    // For now, just log and stop any background audio
    this.stopPriority('AMBIENCE');
  }

  // Stop audio by priority
  private stopPriority(priority: AudioPriority): void {
    const audio = this.currentAudio[priority];
    if (audio && audio.playing) {
      if (audio.source instanceof AudioBufferSourceNode) {
        audio.source.stop();
      } else if (audio.source instanceof HTMLAudioElement) {
        audio.source.pause();
      }
      delete this.currentAudio[priority];
    }
  }

  // Play ambience track
  playAmbience(trackId: string, loop: boolean = true): void {
    this.ambienceTrackId = trackId;

    if (!this.currentSettings.music) return;

    this.stopPriority('AMBIENCE');

    // Create audio element for simple playback
    const audio = new Audio(trackId);
    audio.loop = loop;
    audio.volume = this.currentVolume * (this.currentSettings.ambienceVolume / 100);

    audio.play().catch(e => console.warn('Ambience playback failed:', e));

    this.currentAudio['AMBIENCE'] = {
      source: audio,
      gainNode: null as any, // Not used for HTMLAudioElement
      playing: true
    };
  }

  // Play sound effect
  playSoundEffect(url: string): void {
    if (!this.currentSettings.soundEffects) return;

    const audio = new Audio(url);
    audio.volume = this.currentVolume;

    audio.play().catch(e => console.warn('Sound effect playback failed:', e));

    this.currentAudio['EFFECT'] = {
      source: audio,
      gainNode: null as any,
      playing: true
    };

    // Auto-cleanup after playback
    audio.onended = () => {
      delete this.currentAudio['EFFECT'];
    };
  }

  // Update settings
  updateSettings(settings: Partial<AudioSettings>): void {
    this.currentSettings = { ...this.currentSettings, ...settings };

    // Update ambience volume if playing
    const ambience = this.currentAudio['AMBIENCE'];
    if (ambience?.source instanceof HTMLAudioElement) {
      ambience.source.volume = this.currentVolume * (this.currentSettings.ambienceVolume / 100);
    }
  }

  // Set master volume
  setVolume(volume: number): void {
    this.currentVolume = Math.max(0, Math.min(1, volume));

    // Update all audio elements
    Object.values(this.currentAudio).forEach(audio => {
      if (audio?.source instanceof HTMLAudioElement) {
        const isAmbience = audio === this.currentAudio['AMBIENCE'];
        audio.source.volume = isAmbience 
          ? this.currentVolume * (this.currentSettings.ambienceVolume / 100)
          : this.currentVolume;
      }
    });
  }
}

// Create singleton instance
export const audioManager = new AudioManager();

// Export functions that match App.tsx expectations
export const setAudioSettings = (soundEffectsOn: boolean, musicOn: boolean): void => {
  audioManager.updateSettings({ soundEffects: soundEffectsOn, music: musicOn });
};

export const updateVolume = (volume: number): void => {
  audioManager.setVolume(volume / 100); // Convert 0-100 to 0-1
};

export const startAmbience = (soundscape: { id: string; url: string } | string): void => {
  const trackId = typeof soundscape === 'string' ? soundscape : soundscape.url;
  audioManager.playAmbience(trackId);
};

export const stopAmbience = (): void => {
  const ambience = (audioManager as any).currentAudio?.['AMBIENCE'];
  if (ambience?.playing) {
    if (ambience.source instanceof HTMLAudioElement) {
      ambience.source.pause();
    }
    delete (audioManager as any).currentAudio['AMBIENCE'];
  }
};

export const previewSoundscape = (soundscape: { id: string; url: string }): void => {
  audioManager.playAmbience(soundscape.url, false);
};
