import { Dashboard } from './components/Dashboard';
import { PracticeSession } from './components/PracticeSession';
import { Settings } from './components/Settings';
import { Library } from './components/Library';
import { MeditationSetup } from './components/MeditationSetup';
import { Layout } from './components/Layout';
import { Stats } from './components/Stats';

import {
  audioManager,
  setAudioSettings,
  updateVolume,
  startAmbience,
  stopAmbience,
  previewSoundscape,
} from './services/audioService';
import { buttonSoundService } from './services/buttonSoundService';

import { apiService } from './services/apiService';

const DEFAULT_SETTINGS: AppSettings = {
  theme: 'dark',
  soundEffectsOn: true,
  musicOn: true,
  soundscapeId: '',
  iAmSoundscapeId: '',
  iLoveSoundscapeId: '',
  meditationSoundscapeId: '',
  ambienceVolume: 50,
  reminders: { enabled: false, mode: 'INTERVAL', intervalMinutes: 60, specificTimes: [] },
  voiceId: 'Fenrir',
};

function safeParse<T>(raw: string | null): T | null {
  if (!raw) return null;
  try {
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

function hydrateSettings(raw: any): AppSettings {
  const merged: AppSettings = {
    ...DEFAULT_SETTINGS,
    ...(raw || {}),
    reminders: {
      ...DEFAULT_SETTINGS.reminders,
      ...(raw?.reminders || {}),
      specificTimes: Array.isArray(raw?.reminders?.specificTimes)
        ? raw.reminders.specificTimes
        : DEFAULT_SETTINGS.reminders.specificTimes,
    },
  };
  if (typeof merged.ambienceVolume !== 'number') merged.ambienceVolume = DEFAULT_SETTINGS.ambienceVolume;
  if (!merged.voiceId) merged.voiceId = DEFAULT_SETTINGS.voiceId;
  return merged;
}

function normalizeUserProfile(u: any): UserProfile {
  if (!u || typeof u !== 'object') return u as UserProfile;

  const out: any = { ...u };

  const raw = Array.isArray(out.focusAreas) ? out.focusAreas : [];
  out.focusAreas = raw
    .filter((x: any) => x !== undefined)
    .map((p: any) => {
      if (!p) return { label: 'Focus', value: 'focus' };
      if (typeof p === 'string') return { label: p, value: p };
      if (typeof p === 'object') {
        const label = p.label ?? p.name ?? p.title ?? p.value ?? 'Focus';
        const value = p.value ?? p.id ?? label;
        return { ...p, label, value };
      }
      return { label: String(p), value: String(p) };
    })
    .filter((p: any) => p && typeof p.label === 'string' && p.label.length > 0);

  if (!Array.isArray(out.customAffirmations)) out.customAffirmations = [];

  return out as UserProfile;
}

function normalizeSoundscape(s: any): Soundscape {
  if (!s || typeof s !== 'object') {
    // Return a minimal valid Soundscape if input is invalid
    return {
      id: String(Math.random()),
      label: 'Soundscape',
      url: '',
      category: 'GENERAL' as SoundscapeCategory
    };
  }

  const label = (s.label ?? s.name ?? s.title ?? s.id ?? 'Soundscape') as string;

  // Ensure url is always present - use audio_url as fallback
  const url = s.url || s.audio_url || '';

  // Get category, defaulting to a valid category
  const category = (s.category || 'GENERAL') as SoundscapeCategory;

  return { 
    ...s, 
    id: s.id || String(Math.random()),
    label, 
    url,  // This is now required
    category 
  } as Soundscape;
}

const App: React.FC = () => {
  const hasPreSplash = (AppMode as any).PRE_SPLASH !== undefined;

  const initialSettings = useMemo(() => {
    const raw = safeParse<any>(localStorage.getItem('abundance_settings'));
    return hydrateSettings(raw);
  }, []);

  const initialUser = useMemo(() => {
    const raw = safeParse<any>(localStorage.getItem('abundance_user'));
    return raw ? normalizeUserProfile(raw) : null;
  }, []);

  const initialEntered = useMemo(() => {
    try {
      return sessionStorage.getItem('aa_entered') === '1';
    } catch {
      return false;
    }
  }, []);

  const [mode, setMode] = useState<AppMode>(
    hasPreSplash && !initialEntered ? ((AppMode as any).PRE_SPLASH as AppMode) : AppMode.SPLASH
  );
  const [user, setUser] = useState<UserProfile | null>(initialUser);
  const [settings, setSettings] = useState<AppSettings>(initialSettings);
  const [soundscapes, setSoundscapes] = useState<Soundscape[]>([]);
  const [sessionConfig, setSessionConfig] = useState<PracticeSessionConfig | null>(null);
  const [userAudioFile, setUserAudioFile] = useState<File | null>(null);

  const [hasUserInteracted, setHasUserInteracted] = useState<boolean>(initialEntered);
  const [isSplashWelcome, setIsSplashWelcome] = useState(false);

  // ---------- INITIALIZE AUDIO ----------
  useEffect(() => {
    // Initialize audio manager
    audioManager.initialize();

    // Set initial audio settings
    buttonSoundService.setEnabled(settings.soundEffectsOn);
    setAudioSettings(settings.soundEffectsOn, settings.musicOn);
    updateVolume(settings.ambienceVolume);

    // Load soundscapes
    apiService.getSoundscapes().then((list) => {
      const normalized = (Array.isArray(list) ? list : []).map(normalizeSoundscape);
      setSoundscapes(normalized);
    });

    return () => {
      // Cleanup on unmount
      audioManager.stopAll();
    };
  }, []);

  // ---------- SETTINGS SYNC ----------
  useEffect(() => {
    localStorage.setItem('abundance_settings', JSON.stringify(settings));

    // Update audio settings when settings change
    buttonSoundService.setEnabled(settings.soundEffectsOn);
    setAudioSettings(settings.soundEffectsOn, settings.musicOn);
    updateVolume(settings.ambienceVolume);

    // Start/stop background based on music setting
    if (settings.musicOn && hasUserInteracted) {
      const activeSoundscape = soundscapes.find(s => s.id === settings.soundscapeId) || soundscapes[0];
      if (activeSoundscape && mode !== AppMode.PRACTICE && !isSplashWelcome) {
        startAmbience(activeSoundscape);
      }
    } else {
      stopAmbience();
    }
  }, [settings, hasUserInteracted, soundscapes, mode, isSplashWelcome]);

  useEffect(() => {
    if (user) localStorage.setItem('abundance_user', JSON.stringify(user));
  }, [user]);

  // Always pass a sanitized user downward
  const safeUser = useMemo(() => (user ? normalizeUserProfile(user) : null), [user]);

  // Choose a default ambience if none selected yet
  const activeSoundscape =
    soundscapes.find((s) => s.id === settings.soundscapeId) ||
    soundscapes[0] ||
    undefined;

  // ---------- AUDIO STATE MANAGEMENT ----------
  useEffect(() => {
    // Handle audio based on current mode
    if (!hasUserInteracted || !settings.musicOn) return;

    switch (mode) {
      case AppMode.SPLASH:
        if (isSplashWelcome) {
          // Voice is playing, pause background
          stopAmbience();
        } else {
          // Play background ambience
          if (activeSoundscape) {
            startAmbience(activeSoundscape);
          }
        }
        break;

      case AppMode.PRACTICE:
        // Practice audio is handled by PracticeSession component
        break;

      case AppMode.AUTH:
      case AppMode.ONBOARDING:
      case AppMode.TUTORIAL:
      case AppMode.DASHBOARD:
      case AppMode.SETTINGS:
      case AppMode.LIBRARY:
      case AppMode.PROFILE:
      case AppMode.MEDITATION_SETUP:
        // Resume background if not already playing
        if (activeSoundscape && (!audioManager.isPlaying() || audioManager.getCurrentPriority() === 'AMBIENCE')) {
          startAmbience(activeSoundscape);
        }
        break;
    }
  }, [mode, isSplashWelcome, hasUserInteracted, settings.musicOn, activeSoundscape]);

  // ---------- PRACTICE FLOW ----------
  const startPractice = (type: PracticeType, duration: number) => {
    buttonSoundService.play('confirm');

    setSessionConfig({
      type,
      duration,
      soundscape: activeSoundscape,
      focusAreas: safeUser?.focusAreas || [],
    });
    setMode(AppMode.PRACTICE);
  };

  const endPractice = (log?: GratitudeLog) => {
    // Stop practice audio and resume background
    audioManager.stopPracticeAndResumeBackground();
    setMode(AppMode.DASHBOARD);

    // Update user stats if log exists
    if (log && safeUser) {
      const updatedUser = {
        ...safeUser,
        gratitudeLogs: [...(safeUser.gratitudeLogs || []), log],
        affirmationsCompleted: (safeUser.affirmationsCompleted || 0) + 1,
        lastPracticeDate: new Date().toISOString(),
      };
      setUser(updatedUser);
    }
  };

  const handleSignOut = () => {
    buttonSoundService.play('back');

    localStorage.clear();
    try {
      sessionStorage.removeItem('aa_entered');
    } catch {}

    audioManager.stopAll();
    buttonSoundService.setEnabled(false);

    setUser(null);
    setSessionConfig(null);
    setIsSplashWelcome(false);
    setHasUserInteracted(false);
    setMode(hasPreSplash ? ((AppMode as any).PRE_SPLASH as AppMode) : AppMode.AUTH);
  };

  // ---------- HANDLE AUDIO UPLOAD ----------
  const handleAudioUpload = async (file: File, category: string) => {
    if (!safeUser?.email) {
      console.error('No user email for audio upload');
      return;
    }

    try {
      const result = await apiService.uploadUserAudio(file, category, safeUser.email);

      if (result.success) {
        // Refresh soundscapes to include the new upload
        const updatedSoundscapes = await apiService.getSoundscapes(safeUser.email);
        const normalized = (Array.isArray(updatedSoundscapes) ? updatedSoundscapes : []).map(normalizeSoundscape);
        setSoundscapes(normalized);

        // Play success sound
        buttonSoundService.play('confirm');

        // Update user audio file state if needed
        if (category === 'CUSTOM') {
          setUserAudioFile(file);
        }
      } else {
        buttonSoundService.play('back');
        console.error('Audio upload failed');
      }
    } catch (error) {
      console.error('Audio upload error:', error);
      buttonSoundService.play('back');
    }
  };

  // ---------- RENDER ----------
  const renderContent = () => {
    switch (mode) {
      case (AppMode as any).PRE_SPLASH:
        return (
          <PreSplash
            onStartIntro={() => {
              setHasUserInteracted(true);
              try {
                sessionStorage.setItem('aa_entered', '1');
              } catch {}
              // Initialize audio when user first interacts
              if (settings.musicOn && activeSoundscape) {
                startAmbience(activeSoundscape);
              }
            }}
            onContinue={() => setMode(AppMode.SPLASH)}
          />
        );

      case AppMode.SPLASH:
        return (
          <SplashScreen
            onStartWelcome={() => setIsSplashWelcome(true)}
            onComplete={() => {
              setIsSplashWelcome(false);

              // If user is missing for any reason, recover from storage
              const recovered = safeUser || 
                (safeParse<any>(localStorage.getItem('abundance_user')) ? 
                  normalizeUserProfile(safeParse<any>(localStorage.getItem('abundance_user'))) : null);

              if (recovered && !safeUser) setUser(recovered);

              setMode(recovered ? AppMode.DASHBOARD : AppMode.AUTH);
            }}
          />
        );

      case AppMode.AUTH:
        return (
          <Auth
            theme={settings.theme}
            onLogin={() => {
              buttonSoundService.play('confirm');
              const raw = safeParse<any>(localStorage.getItem('abundance_user'));
              const recovered = raw ? normalizeUserProfile(raw) : null;
              if (recovered) setUser(recovered);
              setMode(recovered ? AppMode.DASHBOARD : AppMode.AUTH);
            }}
            onRegister={() => {
              buttonSoundService.play('confirm');
              setMode(AppMode.ONBOARDING);
            }}
            onBack={() => {
              buttonSoundService.play('back');
              setMode(hasPreSplash ? ((AppMode as any).PRE_SPLASH as AppMode) : AppMode.SPLASH);
            }}
          />
        );

      case AppMode.ONBOARDING:
        return (
          <Onboarding
            onComplete={(u) => {
              buttonSoundService.play('confirm');
              const nu = normalizeUserProfile(u);
              setUser(nu);
              localStorage.setItem('abundance_user', JSON.stringify(nu));
              setMode(AppMode.TUTORIAL);
            }}
          />
        );

      case AppMode.TUTORIAL:
        return (
          <TutorialOverlay
            theme={settings.theme}
            onComplete={() => {
              buttonSoundService.play('confirm');
              const recovered = safeUser || 
                (safeParse<any>(localStorage.getItem('abundance_user')) ? 
                  normalizeUserProfile(safeParse<any>(localStorage.getItem('abundance_user'))) : null);

              if (recovered && !safeUser) setUser(recovered);
              setMode(recovered ? AppMode.DASHBOARD : AppMode.AUTH);
            }}
            onChangeFocus={() => {}}
          />
        );

      case AppMode.DASHBOARD:
        return safeUser ? (
          <Dashboard
            user={safeUser}
            theme={settings.theme}
            activeSoundscape={activeSoundscape}
            onStartPractice={startPractice}
            onOpenMeditation={() => {
              buttonSoundService.play('click');
              setMode(AppMode.MEDITATION_SETUP);
            }}
            onOpenSettings={() => {
              buttonSoundService.play('click');
              setMode(AppMode.SETTINGS);
            }}
            onSignOut={handleSignOut}
          />
        ) : null;

      case AppMode.MEDITATION_SETUP:
        return (
          <MeditationSetup
            theme={settings.theme}
            availableSoundscapes={soundscapes}
            onBack={() => {
              buttonSoundService.play('back');
              setMode(AppMode.DASHBOARD);
            }}
            onBegin={(cfg) => {
              buttonSoundService.play('confirm');
              setSessionConfig(cfg);
              setMode(AppMode.PRACTICE);
            }}
          />
        );

      case AppMode.PRACTICE:
        return sessionConfig && safeUser ? (
          <PracticeSession
            config={sessionConfig}
            theme={settings.theme}
            soundscape={sessionConfig.soundscape}
            customAffirmations={safeUser.customAffirmations}
            userAudioFile={userAudioFile}
            onComplete={endPractice}
            onExit={() => {
              buttonSoundService.play('back');
              endPractice();
            }}
          />
        ) : null;

      case AppMode.SETTINGS:
        return (
          <Settings
            settings={settings}
            theme={settings.theme}
            availableSoundscapes={soundscapes}
            userAudioFile={userAudioFile}
            onChangeSettings={(newSettings) => {
              buttonSoundService.play('click');
              setSettings(newSettings);
            }}
            onChangeFocus={() => {
              buttonSoundService.play('click');
              // Handle focus change
            }}
            onReplayTutorial={() => {
              buttonSoundService.play('click');
              setMode(AppMode.TUTORIAL);
            }}
            onBack={() => {
              buttonSoundService.play('back');
              setMode(AppMode.DASHBOARD);
            }}
            onAudioUpload={handleAudioUpload}
            onSignOut={handleSignOut}
          />
        );

      case AppMode.LIBRARY:
        return safeUser ? (
          <Library
            theme={settings.theme}
            soundscapes={soundscapes}
            activeSoundscapeId={settings.soundscapeId}
            onSetActiveSoundscape={(id) => {
              buttonSoundService.play('confirm');
              setSettings((prev) => ({ ...prev, soundscapeId: id }));
              setMode(AppMode.DASHBOARD);
            }}
          />
        ) : null;

      case AppMode.PROFILE:
        return safeUser ? <Stats user={safeUser} /> : null;

      default:
        return null;
    }
  };

  return (
    <Layout 
      mode={mode} 
      practiceType={sessionConfig?.type} 
      theme={settings.theme}
      volume={settings.ambienceVolume}
      musicOn={settings.musicOn}
      onUpdateVolume={(vol) => {
        setSettings(prev => ({ ...prev, ambienceVolume: vol }));
        updateVolume(vol);
      }}
      onToggleMusic={() => {
        setSettings(prev => ({ ...prev, musicOn: !prev.musicOn }));
      }}
      isWelcomePhase={isSplashWelcome}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;
