The issue is likely in the **Dashboard component** trying to render `focusAreas` objects directly. We need to fix the `normalizeUserProfile` function to ensure `focusAreas` are properly formatted:

```typescript
// In App.tsx, update the normalizeUserProfile function:

function normalizeUserProfile(u: any): UserProfile {
  if (!u || typeof u !== 'object') {
    return {
      name: 'User',
      email: '',
      focusAreas: [],  // Ensure this is an EMPTY array, not null/undefined
      cyclePreference: CycleType.DAILY,
      streak: 0,
      lastPracticeDate: null,
      affirmationsCompleted: 0,
      level: 1,
      customAffirmations: [],
      gratitudeLogs: []
    } as UserProfile;
  }

  const out: any = { ...u };

  // Ensure all required fields exist with defaults
  out.name = out.name || 'User';
  out.email = out.email || '';
  out.cyclePreference = out.cyclePreference || CycleType.DAILY;
  out.streak = typeof out.streak === 'number' ? out.streak : 0;
  out.affirmationsCompleted = typeof out.affirmationsCompleted === 'number' ? out.affirmationsCompleted : 0;
  out.level = typeof out.level === 'number' ? out.level : 1;
  out.lastPracticeDate = out.lastPracticeDate || null;

  // CRITICAL FIX: Ensure focusAreas is ALWAYS an array of PROPER objects
  const raw = Array.isArray(out.focusAreas) ? out.focusAreas : [];
  out.focusAreas = raw
    .filter((x: any) => x !== undefined && x !== null)
    .map((p: any) => {
      // If it's already a proper object with label/value
      if (p && typeof p === 'object' && p.label && p.value) {
        return { label: String(p.label), value: String(p.value) };
      }
      // If it's an object but missing label/value
      if (p && typeof p === 'object') {
        const label = p.label || p.name || p.title || p.value || 'Focus';
        const value = p.value || p.id || label;
        return { label: String(label), value: String(value) };
      }
      // If it's a string
      if (typeof p === 'string') {
        return { label: p, value: p.toLowerCase().replace(/\s+/g, '-') };
      }
      // Default fallback
      return { label: 'Focus', value: 'focus' };
    })
    .filter((p: any) => p && typeof p.label === 'string' && p.label.length > 0);

  // Ensure arrays exist and are properly typed
  if (!Array.isArray(out.customAffirmations)) out.customAffirmations = [];
  if (!Array.isArray(out.gratitudeLogs)) out.gratitudeLogs = [];

  // Add missing required fields with defaults
  if (!out.cyclePreference) out.cyclePreference = CycleType.DAILY;
  if (!out.lastPracticeDate) out.lastPracticeDate = null;

  return out as UserProfile;
}
