  const trimmed = url.trim();
  if (!trimmed) return;
  if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) return trimmed;
  if (trimmed.startsWith('/')) return trimmed;
  const base = (import.meta as any).env?.BASE_URL || '/';
  return `${base}${trimmed.replace(/^\/+/, '')}`;
}

