export const useBackgrounds = () => {
  const [backgrounds, setBackgrounds] = useState<Record<string, any>>({});

  useEffect(() => {
    // Load backgrounds from API
    apiService.getBackgrounds()
      .then(data => {
        setBackgrounds(data);
      })
      .catch(() => {
        // Fallback to empty
        setBackgrounds({});
      });
  }, []);

  return { backgrounds };
};
