// services/audioManager.ts
import { Soundscape } from '../types';
import { 
  startAmbience, 
  stopAmbience, 
  startSessionAudio, 
  stopSessionAudio,
  playBell,
  playButtonTap,
  playCompletionSound,
  playConfirm
} from './audioService';

// Audio preview system
let previewAudio: HTMLAudioElement | null = null;

export const audioManager = {
  // Ambient control
  startAmbience(soundscapeId: string, volume: number = 50) {
    stopAmbience();
    return startAmbience(soundscapeId, volume);
  },

  stopAmbience() {
    stopAmbience();
  },

  // Session audio control
  startSessionAudio(url: string, volume: number = 50) {
    stopAmbience();
    return startSessionAudio(url, volume);
  },

  stopSessionAudio() {
    stopSessionAudio();
  },

  // Preview a soundscape (for selection)
  previewSoundscape(soundscape: Soundscape, volume: number = 30) {
    // Stop any existing preview
    if (previewAudio) {
      previewAudio.pause();
      previewAudio.currentTime = 0;
      previewAudio = null;
    }

    if (!soundscape?.url) return;

    try {
      const audio = new Audio(soundscape.url);
      previewAudio = audio;

      audio.volume = Math.min(volume, 100) / 100;
      audio.loop = false;

      // Auto-stop after 10 seconds
      const stopTimeout = setTimeout(() => {
        if (previewAudio === audio) {
          audio.pause();
          audio.currentTime = 0;
          previewAudio = null;
        }
      }, 10000);

      audio.addEventListener('ended', () => {
        clearTimeout(stopTimeout);
        if (previewAudio === audio) {
          previewAudio = null;
