// services/audioService.ts
// Audio service for the Abundance Alchemy app
import { asset } from './base';

export type AudioSource = {
  id: string;
  url: string;
  volume?: number;
  loop?: boolean;
};

export class AudioService {
  private audioCache: Map<string, HTMLAudioElement> = new Map();
  private playingSounds: Set<HTMLAudioElement> = new Set();

  preload(sources: AudioSource[]): void {
    sources.forEach(source => {
      if (!this.audioCache.has(source.id)) {
        const audio = new Audio(asset(source.url));
        audio.preload = 'auto';
        audio.volume = source.volume || 1.0;
        audio.loop = source.loop || false;
        this.audioCache.set(source.id, audio);
      }
    });
  }

  play(id: string, options?: { volume?: number; onEnded?: () => void }): Promise<void> {
    const audio = this.audioCache.get(id);
    if (!audio) {
      console.warn(`Audio ${id} not found in cache`);
      return Promise.resolve();
    }

    const audioClone = audio.cloneNode() as HTMLAudioElement;
    if (options?.volume !== undefined) {
      audioClone.volume = options.volume;
    }

    if (options?.onEnded) {
      audioClone.addEventListener('ended', options.onEnded, { once: true });
    }

    this.playingSounds.add(audioClone);
    audioClone.addEventListener('ended', () => {
      this.playingSounds.delete(audioClone);
    }, { once: true });

    return audioClone.play().catch(err => {
      console.warn(`Audio playback failed for ${id}:`, err);
      this.playingSounds.delete(audioClone);
    });
  }

  stopAll(): void {
    this.playingSounds.forEach(audio => {
      audio.pause();
      audio.currentTime = 0;
    });
    this.playingSounds.clear();
  }

  setGlobalVolume(volume: number): void {
    this.audioCache.forEach(audio => {
      audio.volume = volume;
    });
    this.playingSounds.forEach(audio => {
      audio.volume = volume;
    });
  }
}

export const audioService = new AudioService();
```

