    }

    if (previewAudio) {
      previewAudio.pause();
      previewAudio.currentTime = 0;
      previewAudio.removeAttribute('src');
      previewAudio.load();
      previewAudio = null;
    }
  },

  playSoundEffect: (soundUrl: string) => {
    const audio = new Audio(soundUrl);
    audio.volume = 0.5;
    audio.play().catch(() => {});
    return audio;
  },

  // Session audio control
  startSessionAudio: (url: string, volume: number = 50) => {
    stopAmbience();
    return startSessionAudio(url, volume);
  },

  stopSessionAudio: () => {
    stopSessionAudio();
  },

  // Sound effects (for convenience)
  playButtonTap,
  playCompletionSound,
  playConfirm,

  // Status check
  isPreviewPlaying: () => {
    return !!(previewAudio && !previewAudio.paused);
  },

  updateSettings: (settings: { soundEffects?: boolean; musicOn?: boolean }) => {
    console.log('Audio settings updated:', settings);
    // Note: You might want to import setAudioSettings from audioService
  }
};
