// src/components/PracticeSession.tsx - UPDATED VERSION
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  PracticeSessionConfig, 
  PracticeType, 
  Affirmation, 
  Soundscape,
  GratitudeLog 
} from '../types';
import { 
  playCompletionSound, 
  updateVolume, 
  stopAmbience, 
  startAmbienceWithSoundscape,
  startSessionAudio,
  stopSessionAudio
} from '../services/audioService';
import { buttonSoundService } from '../services/buttonSoundService';
import { 
  Play, 
  Pause, 
  SkipForward, 
  Volume2, 
  VolumeX, 
  CheckCircle, 
  XCircle,
  Heart,
  Sparkles,
  Moon,
  Sun
} from 'lucide-react';

interface PracticeSessionProps {
  config: PracticeSessionConfig;
  customAffirmations: Affirmation[];
  onComplete: (log?: GratitudeLog) => void;
  onExit: () => void;
  userAudioFile?: File;
  theme: 'light' | 'dark';
  soundscape: Soundscape;
}

type SessionPhase = 'preparation' | 'practice' | 'completion';

export const PracticeSession: React.FC<PracticeSessionProps> = ({
  config,
  customAffirmations,
  onComplete,
  onExit,
  userAudioFile,
  theme,
  soundscape
}) => {
  const [currentTime, setCurrentTime] = useState(0); // in seconds
  const [isPaused, setIsPaused] = useState(false);
  const [phase, setPhase] = useState<SessionPhase>('preparation');
  const [currentAffirmationIndex, setCurrentAffirmationIndex] = useState(0);
  const [showGratitudeInput, setShowGratitudeInput] = useState(false);
  const [gratitudeText, setGratitudeText] = useState('');
  const [volume, setVolume] = useState(50);
  const [isMuted, setIsMuted] = useState(false);

  const timerRef = useRef<NodeJS.Timeout | null>(null);
  const totalTime = config.duration * 60; // convert minutes to seconds
  const progress = totalTime > 0 ? (currentTime / totalTime) * 100 : 0;

  // Filter affirmations by practice type
  const relevantAffirmations = customAffirmations.filter(
    (aff) => aff.type === config.type
  );

  const currentAffirmation = relevantAffirmations[currentAffirmationIndex] || {
    text: config.type === PracticeType.MORNING_IAM 
      ? 'I AM abundant, worthy, and whole.'
      : config.type === PracticeType.EVENING_ILOVE
      ? 'I LOVE myself exactly as I am.'
      : 'I breathe in peace, I breathe out tension.',
    category: 'Default'
  };

  // Timer control
  const startTimer = useCallback(() => {
    if (timerRef.current) clearInterval(timerRef.current);

    timerRef.current = setInterval(() => {
      setCurrentTime(prev => {
        if (prev >= totalTime) {
          if (timerRef.current) clearInterval(timerRef.current);
          handleSessionComplete();
          return totalTime;
        }
        return prev + 1;
      });
    }, 1000);
  }, [totalTime]);

  const pauseTimer = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  // Phase transitions
  useEffect(() => {
    if (currentTime >= totalTime * 0.9) { // Last 10% of session
      setPhase('completion');
    } else if (currentTime >= 30) { // After 30 seconds of preparation
      setPhase('practice');
    }
  }, [currentTime, totalTime]);

  // Audio management
  useEffect(() => {
    // Stop ambient music when session starts
    stopAmbience();

    // Start session audio if soundscape is provided
    if (soundscape?.url) {
      startSessionAudio(soundscape.url, volume);
    } else if (typeof config.soundscape === 'string' && config.soundscape) {
      startSessionAudio(config.soundscape, volume);
    }

    // Start timer
    startTimer();

    return () => {
      pauseTimer();
      stopSessionAudio();
    };
  }, []);

  // Update volume when changed
  useEffect(() => {
    updateVolume(isMuted ? 0 : volume);
  }, [volume, isMuted]);

  // Affirmation rotation
  useEffect(() => {
    if (phase === 'practice' && relevantAffirmations.length > 1) {
      const interval = setInterval(() => {
        setCurrentAffirmationIndex(prev => 
          (prev + 1) % relevantAffirmations.length
        );
      }, 30000); // Change affirmation every 30 seconds

      return () => clearInterval(interval);
    }
  }, [phase, relevantAffirmations.length]);

  const handlePlayPause = () => {
    buttonSoundService.play('click');
    if (isPaused) {
      setIsPaused(false);
      startTimer();
    } else {
      setIsPaused(true);
      pauseTimer();
    }
  };

  const handleSkipForward = () => {
    buttonSoundService.play('click');
    setCurrentTime(prev => Math.min(prev + 30, totalTime));
  };

  const handleVolumeChange = (newVolume: number) => {
    setVolume(newVolume);
  };

  const handleMuteToggle = () => {
    buttonSoundService.play('click');
    setIsMuted(!isMuted);
  };

  const handleSessionComplete = () => {
    pauseTimer();
    playCompletionSound();

    if (config.type === PracticeType.EVENING_ILOVE) {
      setShowGratitudeInput(true);
    } else {
      onComplete();
    }
  };

  const handleGratitudeSubmit = () => {
    if (gratitudeText.trim()) {
      const gratitudeLog: GratitudeLog = {
        id: Date.now().toString(),
        date: new Date().toISOString(),
        text: gratitudeText,
        focusArea: config.focusAreas?.[0]?.toString() || 'General',
        sessionType: config.type
      };
      onComplete(gratitudeLog);
    } else {
      onComplete();
    }
  };

  const handleExit = () => {
    buttonSoundService.play('click');
    pauseTimer();
    onExit();
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getSessionTitle = () => {
    switch (config.type) {
      case PracticeType.MORNING_IAM:
        return 'Morning I AM Practice';
      case PracticeType.EVENING_ILOVE:
        return 'Evening I LOVE Practice';
      case PracticeType.GRATITUDE:
        return 'Gratitude Practice';
      case PracticeType.MEDITATION:
        return 'Sacred Meditation';
      default:
        return 'Practice Session';
    }
  };

  const getSessionIcon = () => {
    switch (config.type) {
      case PracticeType.MORNING_IAM:
        return <Sun className="w-6 h-6 text-amber-500" />;
      case PracticeType.EVENING_ILOVE:
        return <Moon className="w-6 h-6 text-indigo-500" />;
      case PracticeType.MEDITATION:
        return <Sparkles className="w-6 h-6 text-purple-500" />;
      default:
        return <Heart className="w-6 h-6 text-rose-500" />;
    }
  };

  if (showGratitudeInput) {
    return (
      <div className={`min-h-screen p-6 flex flex-col ${
        theme === 'dark' ? 'bg-slate-950 text-slate-100' : 'bg-amber-50 text-slate-800'
      }`}>
        <div className="flex-1 flex flex-col items-center justify-center">
          <div className="max-w-md w-full space-y-6">
            <div className="text-center">
              <CheckCircle className="w-16 h-16 text-emerald-500 mx-auto mb-4" />
              <h2 className="text-2xl font-bold mb-2">Practice Complete!</h2>
              <p className="text-slate-400">Take a moment to reflect on your gratitude</p>
            </div>

            <div className="space-y-4">
              <label className="block text-sm font-medium">
                What are you grateful for today?
              </label>
              <textarea
                value={gratitudeText}
                onChange={(e) => setGratitudeText(e.target.value)}
                placeholder="I am grateful for..."
                className="w-full h-32 p-4 rounded-2xl border resize-none focus:ring-2 focus:ring-amber-500 outline-none bg-slate-900/50 border-slate-700 text-slate-100"
                autoFocus
              />
            </div>

            <div className="flex space-x-3">
              <button
                onClick={() => {
                  buttonSoundService.play('click');
                  onComplete();
                }}
                className="flex-1 py-3 rounded-xl border border-slate-700 hover:bg-slate-800 transition-colors"
              >
                Skip
              </button>
              <button
                onClick={() => {
                  buttonSoundService.play('confirm');
                  handleGratitudeSubmit();
                }}
                className="flex-1 py-3 rounded-xl bg-gradient-to-r from-emerald-500 to-cyan-500 text-white font-medium hover:opacity-90 transition-opacity"
              >
                Save & Complete
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen p-6 flex flex-col ${
      theme === 'dark' ? 'bg-slate-950 text-slate-100' : 'bg-amber-50 text-slate-800'
    }`}>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center space-x-3">
          {getSessionIcon()}
          <div>
            <h1 className="text-lg font-bold">{getSessionTitle()}</h1>
            <p className="text-sm text-slate-400">
              {formatTime(currentTime)} / {formatTime(totalTime)}
            </p>
          </div>
        </div>

        <button
          onClick={handleExit}
          className="p-2 rounded-full hover:bg-slate-800/50 transition-colors"
        >
          <XCircle className="w-5 h-5" />
        </button>
      </div>

      {/* Progress */}
      <div className="mb-8">
        <div className="h-2 rounded-full bg-slate-800 overflow-hidden">
          <div 
            className="h-full bg-gradient-to-r from-amber-500 via-orange-500 to-red-500 transition-all duration-300"
            style={{ width: `${progress}%` }}
          />
        </div>
        <div className="flex justify-between text-xs text-slate-400 mt-2">
          <span>Start</span>
          <span>{Math.round(progress)}%</span>
