// services/audioInitializer.ts
import { audioManager } from './audioManager';
import { attachGlobalClickSound } from './globalClickSound';

let audioInitialized = false;

export function initializeAudio() {
  if (audioInitialized) return;

  // Unlock audio context on first user interaction
  const unlockAudio = () => {
    // Try to play a silent audio to unlock Web Audio API
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();

    // Create a silent buffer and play it
    const buffer = audioContext.createBuffer(1, 1, 22050);
    const source = audioContext.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContext.destination);
    source.start(0);

    // Resume if suspended
    if (audioContext.state === 'suspended') {
      audioContext.resume();
    }

    // Close after unlocking
    setTimeout(() => {
      audioContext.close();
    }, 100);

    console.log('Audio context unlocked');
  };

  // Attach to multiple user interactions
  const events = ['click', 'touchstart', 'keydown', 'mousedown'];
  const unlockOnce = () => {
    unlockAudio();
    events.forEach(e => document.removeEventListener(e, unlockOnce));
  };

  events.forEach(e => document.addEventListener(e, unlockOnce, { once: true }));

  // Attach global click sounds
  attachGlobalClickSound();

  audioInitialized = true;
  console.log('Audio system initialized');
}
```

