// services/buttonTone.ts
// Generated button tone (no audio files). Fixed sound/volume; always the same.
// Why: WebAudio tone is reliable across deploys and ignores missing asset issues.

type Ctx = AudioContext | (Window & typeof globalThis)["webkitAudioContext"];
const AC: typeof AudioContext =
  (window as any).AudioContext || (window as any).webkitAudioContext;

let ctx: AudioContext | null = null;
function ensureCtx(): AudioContext {
  if (!ctx) ctx = new AC();
  return ctx;
}

/** Call once on a real user gesture to satisfy autoplay policies. */
export async function unlockButtonTone(): Promise<void> {
  const c = ensureCtx();
  if (c.state === "suspended") await c.resume();
  // tiny silent tick primes iOS
  const b = c.createBuffer(1, 1, 22050);
  const s = c.createBufferSource();
  s.buffer = b; s.connect(c.destination); s.start(0);
}

/** Play the immutable button tone. Always the same envelope/frequency/volume. */
export async function playButtonTone(): Promise<void> {
  const c = ensureCtx();
  if (c.state === "suspended") await c.resume();

  // Params chosen to feel “crisp” without being harsh.
  const now = c.currentTime;
  const dur = 0.12;                // total length
  const fStart = 920;              // Hz
  const fEnd = 760;                // Hz (tiny downward glide)
  const gainMax = 0.12;            // global loudness cap
  const attack = 0.004;            // fast attack
  const decay = dur - attack;      // short decay

  const osc = c.createOscillator();
  const gain = c.createGain();

  // Gentle “ping”: triangle with a hint of noise via slight detune.
  osc.type = "triangle";
  osc.frequency.setValueAtTime(fStart, now);
  osc.frequency.linearRampToValueAtTime(fEnd, now + dur);

  // Envelope (clicky but not clipping)
  gain.gain.setValueAtTime(0, now);
  gain.gain.linearRampToValueAtTime(gainMax, now + attack);
  gain.gain.exponentialRampToValueAtTime(0.0005, now + attack + decay);

  osc.connect(gain);
  gain.connect(c.destination);

  osc.start(now);
  osc.stop(now + dur + 0.01);
  osc.onended = () => {
    try { osc.disconnect(); gain.disconnect(); } catch {}
  };
}

/** Immutable façade for the original "can't change" behavior. */
export const buttonToneService = Object.freeze({
  unlock: unlockButtonTone,
  play: () => { void playButtonTone(); },
});
```

