// services/buttonTone.ts - WITH FM SYNTHESIS TONE
let audioCtx: AudioContext | null = null;

function getAudioContext(): AudioContext {
  if (!audioCtx) {
    audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
  }
  return audioCtx;
}

/** Call once on a real user gesture to satisfy autoplay policies. */
export async function unlockButtonTone(): Promise<void> {
  const ctx = getAudioContext();
  if (ctx.state === "suspended") await ctx.resume();
  // tiny silent tick primes iOS
  const b = ctx.createBuffer(1, 1, 22050);
  const s = ctx.createBufferSource();
  s.buffer = b; s.connect(ctx.destination); s.start(0);
}

/**
 * Creates a unique oscillating synthetic tone using FM synthesis.
 * This provides a mystical "vibrating thump" feel rather than a flat click.
 */
export async function playButtonTone(): Promise<void> {
  try {
    const ctx = getAudioContext();
    if (ctx.state === "suspended") await ctx.resume();

    const carrier = ctx.createOscillator();
    const modulator = ctx.createOscillator();
    const modGain = ctx.createGain();
    const mainGain = ctx.createGain();

    // CARRIER: The main frequency of the tone
    carrier.type = 'sine';
    const baseFreq = 140;
    carrier.frequency.setValueAtTime(baseFreq, ctx.currentTime);
    // Dynamic pitch drop for that "thump" impact
    carrier.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.25);

    // MODULATOR: Creates the "oscillation" (vibration) quality
    modulator.type = 'triangle';
    modulator.frequency.setValueAtTime(45, ctx.currentTime); // 45Hz vibration
    modGain.gain.setValueAtTime(80, ctx.currentTime); // Depth of oscillation

    // Connect FM chain: Modulator -> ModGain -> Carrier Frequency
    modulator.connect(modGain);
    modGain.connect(carrier.frequency);

    // ENVELOPE: Smooth attack and exponential decay
    const volume = 0.7; // Adjust volume level (0.0 to 1.0)
    mainGain.gain.setValueAtTime(0, ctx.currentTime);
    mainGain.gain.linearRampToValueAtTime(0.4 * volume, ctx.currentTime + 0.02);
    mainGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);

    carrier.connect(mainGain);
    mainGain.connect(ctx.destination);

    modulator.start();
    carrier.start();

    // Stop oscillators after the envelope has fully decayed
    modulator.stop(ctx.currentTime + 0.35);
    carrier.stop(ctx.currentTime + 0.35);

    // Cleanup
    setTimeout(() => {
      try {
        carrier.disconnect();
        modulator.disconnect();
        modGain.disconnect();
        mainGain.disconnect();
      } catch (e) {
        // Ignore cleanup errors
      }
    }, 400);

  } catch (e) {
    console.warn("Button tone failed:", e);
  }
}

