/**
 * Creates the original mystical "oscillating thump" using FM synthesis.
 */
export function playClick() {
  if (!effectsEnabled) return;

  try {
    if (!audioCtx) {
      audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }

    if (audioCtx.state === 'suspended') {
      audioCtx.resume();
    }

    const carrier = audioCtx.createOscillator();
    const modulator = audioCtx.createOscillator();
    const modGain = audioCtx.createGain();
    const mainGain = audioCtx.createGain();

    const now = audioCtx.currentTime;

    // CARRIER: The primary "hum" frequency
    carrier.type = 'sine';
    const baseFreq = 160; 
    carrier.frequency.setValueAtTime(baseFreq, now);
    carrier.frequency.exponentialRampToValueAtTime(50, now + 0.2);

    // MODULATOR: Creates the internal "vibration"
    modulator.type = 'sine';
    modulator.frequency.setValueAtTime(42, now); 

    modGain.gain.setValueAtTime(120, now); 
    modGain.gain.exponentialRampToValueAtTime(10, now + 0.25);

    // FM Connection
    modulator.connect(modGain);
    modGain.connect(carrier.frequency);

    // ENVELOPE
    mainGain.gain.setValueAtTime(0, now);
    mainGain.gain.linearRampToValueAtTime(0.5 * volume, now + 0.015);
    mainGain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);

    carrier.connect(mainGain);
    mainGain.connect(audioCtx.destination);

    modulator.start(now);
    carrier.start(now);

    modulator.stop(now + 0.35);
    carrier.stop(now + 0.35);

    setTimeout(() => {
        carrier.disconnect();
        modulator.disconnect();
        modGain.disconnect();
        mainGain.disconnect();
    }, 400);

  } catch (e) {
    console.warn("Web Audio API blocked or unavailable", e);
  }
