// services/globalClickSound.ts - CORRECTED VERSION
import { buttonSoundService } from './buttonSoundService';

// Guard so we only attach listeners once (even with HMR/dev reloads)
declare global {
  interface Window {
    __AA_GLOBAL_CLICK_SOUND_ATTACHED__?: boolean;
  }
}

function isInteractiveEl(el: Element | null): el is Element {
  if (!el) return false;

  // Any of these should produce the universal button tone
  return Boolean(
    el.closest(
      'button, a, [role="button"], [data-sound="click"], [data-sound="confirm"], [data-sound="back"]'
    )
  );
}

function shouldSkip(el: Element): boolean {
  const target = el.closest(
    'button, a, [role="button"], [data-sound="click"], [data-sound="confirm"], [data-sound="back"]'
  );

  if (!target) return true;

  // Manual opt-out per element
  if ((target as HTMLElement).dataset?.noSound === 'true') return true;

  // Skip disabled buttons
  if (target instanceof HTMLButtonElement && target.disabled) return true;

  // Skip text inputs/textarea interactions (in case a wrapper has role button)
  const tag = (el as HTMLElement).tagName?.toLowerCase();
  if (tag === 'input' || tag === 'textarea' || tag === 'select') return true;

  return false;
}

function getVariant(el: Element): 'click' | 'confirm' | 'back' {
  const target = el.closest('[data-sound]') as HTMLElement | null;
  const v = (target?.dataset?.sound || '').toLowerCase();
  if (v === 'confirm') return 'confirm';
  if (v === 'back') return 'back';
  return 'click';
}

export function attachGlobalClickSound() {
  if (window.__AA_GLOBAL_CLICK_SOUND_ATTACHED__) return;
  window.__AA_GLOBAL_CLICK_SOUND_ATTACHED__ = true;

  // Use pointerdown in capture phase:
  // - registers as a user gesture (good for iOS/web audio)
  // - fires before onClick handlers / route changes
  document.addEventListener(
    'pointerdown',
    (ev) => {
      const el = ev.target as Element | null;
      if (!isInteractiveEl(el)) return;

      const target = el.closest(
        'button, a, [role="button"], [data-sound], [data-no-sound]'
      ) as Element | null;

      if (!target) return;
      if (shouldSkip(el)) return;

      // If any element sets data-sound="confirm|back|click" we honor it; else click.
      const variant = getVariant(target);
      buttonSoundService.play(variant);
    },
    true
  );
}

// Auto-attach on import
attachGlobalClickSound();
