## Step 2: Create the Sound Generator Function
Here's the complete `playBell()` function using these JSON parameters:

```typescript
export function playBell() {
  if (!_sfxEnabled) return;

  try {
    const ctx = getCtx();
    if (ctx.state === 'suspended') ctx.resume();
    const t = ctx.currentTime;

    // JSON parameters
    const params = {
      wave_type: 2,           // 0=square, 1=sawtooth, 2=sine, 3=noise
      p_base_freq: 0.17,      // Base frequency (0-1 scale)
      p_env_attack: 0.305,    // Attack time in seconds
      p_env_decay: 0.725,     // Decay time in seconds
      p_env_sustain: 0.445,   // Sustain level (0-1)
      sound_vol: 0.25,        // Max volume (0-1)
      p_vib_strength: 0.045,  // Vibrato strength
      p_vib_speed: 0,         // Vibrato speed
      p_duty: 0,              // Square wave duty cycle
      p_lpf_freq: 1,          // Low-pass filter frequency (0-1)
      p_lpf_resonance: 0      // Filter resonance
    };

    // Convert base frequency to Hz (sfxr uses 0-1 where 1=~2000Hz)
    const baseFreqHz = 60 + Math.pow(params.p_base_freq, 2) * 10000;
    const frequency = Math.min(baseFreqHz, 10000);

    // Create oscillator with square wave
    const osc = ctx.createOscillator();
    osc.type = 'square';

    // Apply vibrato if present
    if (params.p_vib_strength > 0 && params.p_vib_speed > 0) {
      const vib = ctx.createOscillator();
      vib.type = 'sine';
      vib.frequency.value = params.p_vib_speed * 10;

      const vibGain = ctx.createGain();
      vibGain.gain.value = params.p_vib_strength * frequency * 0.5;

      vib.connect(vibGain);
      vibGain.connect(osc.frequency);
      vib.start(t);
      vib.stop(t + params.p_env_attack + params.p_env_decay);
    }

    osc.frequency.setValueAtTime(frequency, t);

    // Create volume envelope
    const gain = ctx.createGain();

    // Attack phase: 0 → max volume
    gain.gain.setValueAtTime(0.00001, t);
    gain.gain.linearRampToValueAtTime(params.sound_vol, t + params.p_env_attack);

    // Decay phase: max volume → sustain level
    const decayEnd = t + params.p_env_attack + params.p_env_decay;
    gain.gain.linearRampToValueAtTime(
      params.sound_vol * params.p_env_sustain, 
      decayEnd
    );

    // Release: sustain → 0 (quick release)
    gain.gain.exponentialRampToValueAtTime(0.00001, decayEnd + 0.1);

    // Apply low-pass filter if needed
    if (params.p_lpf_freq < 1) {
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = params.p_lpf_freq * 22050;
      filter.Q.value = params.p_lpf_resonance * 10;

      osc.connect(filter);
      filter.connect(gain);
    } else {
      osc.connect(gain);
    }

    gain.connect(ctx.destination);

    // Start/stop timing
    osc.start(t);
    osc.stop(decayEnd + 0.2);

  } catch (e) {
    console.warn('Bell sound failed:', e);
  }
}
