// ---------- Button Tone (low Om, quick end before next screen) ----------

export function playClick(variant: 'normal' | 'hover' | 'click' = 'normal') {
  if (!_sfxEnabled) return;

  try {
    if (!audioCtx) {
      audioCtx = new (window.AudioContext ||
        (window as any).webkitAudioContext)();
    }

    if (audioCtx.state === 'suspended') {
      audioCtx.resume();
    }

    const ctx = audioCtx;
    const now = ctx.currentTime;

    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.type = 'sine';

    // Low-first motion for Om feel
    oscillator.frequency.setValueAtTime(72, now);               // very low start
    oscillator.frequency.linearRampToValueAtTime(76, now + 0.14); // small bloom
    oscillator.frequency.linearRampToValueAtTime(73, now + 0.35); // settle back lower

    // Global soft level
    const baseMaxGain = 0.026 * volume;
    let maxGain = baseMaxGain;
    let attack = 0.03;
    let sustainTime = 0.4;
    let totalDuration = 0.7;

    if (variant === 'click') {
      // End comfortably before the next screen completes transition
      maxGain = baseMaxGain * 0.95;
      attack = 0.03;
      sustainTime = 0.35;
      totalDuration = 0.65; // ~650ms, tightly contained
    } else if (variant === 'normal') {
      maxGain = baseMaxGain * 1.1;
      sustainTime = 0.6;
      totalDuration = 1.0;
    } else {
      // hover: very subtle and short
      maxGain = baseMaxGain * 0.5;
      sustainTime = 0.3;
      totalDuration = 0.6;
    }

    const attackEnd = now + attack;
    const sustainEnd = now + attack + sustainTime;
    const releaseEnd = now + totalDuration;

    // Smooth fade out; no "carried" high end
    gainNode.gain.setValueAtTime(0.00003, now);
    gainNode.gain.exponentialRampToValueAtTime(maxGain, attackEnd);
    gainNode.gain.setValueAtTime(maxGain, sustainEnd);
    gainNode.gain.exponentialRampToValueAtTime(0.00003, releaseEnd);

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    oscillator.start(now);
    oscillator.stop(releaseEnd);

    const safetyMs = (totalDuration + 0.2) * 1000;
    setTimeout(() => {
      try {
        oscillator.disconnect();
        gainNode.disconnect();
      } catch {
        // ignore
      }
    }, safetyMs);
  } catch (e) {
    console.warn('Button tone failed:', e);
  }
}

