    // Attack phase: 0.305s to 25% volume
    gain.gain.setValueAtTime(0.00001, t);
    gain.gain.linearRampToValueAtTime(0.25, t + 0.305);

    // Decay phase: 0.725s to 44.5% of 25% (≈11%)
    const decayEnd = t + 0.305 + 0.725;
    gain.gain.linearRampToValueAtTime(0.25 * 0.445, decayEnd);

    // Quick release
    gain.gain.exponentialRampToValueAtTime(0.00001, decayEnd + 0.1);

    // Connect and play
    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start(t);
    osc.stop(decayEnd + 0.2);

