    osc.frequency.exponentialRampToValueAtTime(1046.5, now + 0.55);

    const maxGain = 0.16 * volume;
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(maxGain, now + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.6);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start(now);
    osc.stop(now + 0.65);

    setTimeout(() => {
      try {
        osc.disconnect();
        gain.disconnect();
      } catch {
        // ignore
      }
    }, 800);
  } catch (e) {
    // swallow
  }
}

// ---------- EXACT BELL SOUND (from your parameters) ----------
// Square wave, 110.3Hz, 0.2109s attack, 0.4490s sustain, 1.192s decay

export function playBell() {
  if (!_sfxEnabled) return;

  try {
    const ctx = getCtx();
    if (ctx.state === 'suspended') ctx.resume();
    const t = ctx.currentTime;

    // Create oscillator with your exact parameters
    const osc = ctx.createOscillator();

    // Square wave with 50% duty cycle
    osc.type = 'square';

    // Start frequency: 110.3Hz
    osc.frequency.setValueAtTime(110.3, t);

    // Slide: -0.005090 8va/sec (octaves per second)
    const totalDuration = 0.2109 + 0.4490 + 1.192;
    const endFrequency = 110.3 * Math.pow(2, -0.00509 * totalDuration);
    osc.frequency.linearRampToValueAtTime(endFrequency, t + totalDuration);

    // Create gain node for volume envelope
    const gain = ctx.createGain();

    // Attack phase: 0.2109s to full volume
    gain.gain.setValueAtTime(0.00001, t);
    gain.gain.linearRampToValueAtTime(0.25, t + 0.2109); // Using 25% volume

    // Sustain phase: 0.4490s at full volume
    const sustainEnd = t + 0.2109 + 0.4490;
    gain.gain.setValueAtTime(0.25, sustainEnd);

    // Decay phase: 1.192s to silence
    const decayEnd = sustainEnd + 1.192;
    gain.gain.exponentialRampToValueAtTime(0.00001, decayEnd);

    // Apply Low-Pass Filter: 2928Hz cutoff, 49.29% resonance
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 2928;
    filter.Q.value = 10; // Adjusted Q value for resonance

    // Filter sweep
    filter.frequency.exponentialRampToValueAtTime(
      2928 * 0.7, // Slight downward sweep
      decayEnd
    );

    // Connect: osc → filter → gain → destination
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(ctx.destination);

    // Start/stop timing
    osc.start(t);
    osc.stop(decayEnd + 0.1);

  } catch (e) {
    console.warn('Bell sound failed:', e);
  }
}

// ---------- Additional Exports ----------

export function stopAll() {
  stopAmbience();
  stopSessionAudio(false);
}

export function setAmbienceVolume(vol: number) {
  if (ambienceAudio) {
    ambienceAudio.volume = vol / 100;
  }
}

export function isAmbiencePlaying(): boolean {
  return !!(
    ambienceAudio && !ambienceAudio.paused && !ambienceAudio.muted
  );
}

export async function unlockAudio(): Promise<void> {
  if (!audioCtx) {
    audioCtx = new (window.AudioContext ||
      (window as any).webkitAudioContext)();
  }

  if (audioCtx.state === 'suspended') await audioCtx.resume();

  const b = audioCtx.createBuffer(1, 1, 22050);
  const s = audioCtx.createBufferSource();
  s.buffer = b;
  s.connect(audioCtx.destination);
  s.start(0);
}
