```jsx
import React, { useState, useRef, useEffect } from 'react';
import './BreathingOrb.css';

const BreathingOrb = ({ audioContext, isAudioPlaying }) => {
  const [isActive, setIsActive] = useState(false);
  const [breathPhase, setBreathPhase] = useState(0);
  const [audioData, setAudioData] = useState(new Array(64).fill(0));
  const animationRef = useRef(null);
  const analyserRef = useRef(null);
  const dataArrayRef = useRef(new Uint8Array(64));
  const orbRef = useRef(null);

  // Breathing animation
  useEffect(() => {
    let startTime = null;
    let phase = 0;

    const animateBreathing = (timestamp) => {
      if (!startTime) startTime = timestamp;
      const elapsed = timestamp - startTime;

      // 5-second breathing cycle (inhale 2.5s, exhale 2.5s)
      const cycleTime = 5000;
      const progress = (elapsed % cycleTime) / cycleTime;

      // Smooth sinusoidal breathing pattern
      const breath = Math.sin(progress * Math.PI * 2) * 0.5 + 0.5;

      // Adjust breathing with audio if playing
      let audioModifier = 1;
      if (isAudioPlaying && audioData.length > 0) {
        const avgAudio = audioData.reduce((a, b) => a + b) / audioData.length;
        audioModifier = 1 + (avgAudio / 255) * 0.3;
      }

      setBreathPhase(breath * audioModifier);

      // Pulsing glow based on audio
      if (orbRef.current) {
        const baseGlow = 15 + breath * 10;
        const audioGlow = isAudioPlaying ? 
          (audioData[0] / 255) * 25 : 0;

        orbRef.current.style.setProperty('--pulse-glow', `${baseGlow + audioGlow}px`);
        orbRef.current.style.setProperty('--spark-intensity', `${audioGlow / 10}`);
      }

      animationRef.current = requestAnimationFrame(animateBreathing);
    };

    animationRef.current = requestAnimationFrame(animateBreathing);
    return () => cancelAnimationFrame(animationRef.current);
  }, [isAudioPlaying, audioData]);

  // Audio analysis setup
  useEffect(() => {
    if (audioContext && isAudioPlaying) {
      const analyser = audioContext.createAnalyser();
      analyser.fftSize = 128;
      analyserRef.current = analyser;

      const bufferLength = analyser.frequencyBinCount;
      dataArrayRef.current = new Uint8Array(bufferLength);

      const updateAudioData = () => {
        if (analyserRef.current && isAudioPlaying) {
          analyserRef.current.getByteFrequencyData(dataArrayRef.current);
          setAudioData(Array.from(dataArrayRef.current));
        }
        if (isAudioPlaying) {
          requestAnimationFrame(updateAudioData);
        }
      };

      updateAudioData();
    }
  }, [audioContext, isAudioPlaying]);

  const handleClick = () => {
    setIsActive(!isActive);
    // Add click effect
    if (orbRef.current) {
      orbRef.current.classList.add('orb-clicked');
      setTimeout(() => {
        orbRef.current.classList.remove('orb-clicked');
      }, 300);
    }
  };

  return (
    <div className="orb-container">
      <div 
        ref={orbRef}
        className={`breathing-orb ${isActive ? 'active' : ''} ${isAudioPlaying ? 'audio-responsive' : ''}`}
        onClick={handleClick}
        style={{
          '--breath-phase': breathPhase,
          '--audio-data': audioData.slice(0, 8).join(',')
        }}
      >
        {/* Core Orb */}
        <div className="orb-core">
          <div className="orb-inner-glow" />
        </div>

        {/* Fire Ring */}
        <div className="fire-ring">
          <div className="fire-layer fire-orange" />
          <div className="fire-layer fire-gold" />
          <div className="fire-layer fire-blue" />
          <div className="fire-layer fire-white" />
        </div>

        {/* Subtle Sparks */}
        <div className="sparks-container">
          {[...Array(12)].map((_, i) => (
            <div 
              key={i} 
              className="spark" 
              style={{
                '--spark-index': i,
                '--spark-delay': `${i * 0.3}s`
              }}
            />
          ))}
        </div>

        {/* Audio-responsive particles */}
        {isAudioPlaying && (
          <div className="audio-particles">
            {audioData.slice(0, 16).map((value, i) => (
              <div 
                key={i}
                className="audio-particle"
                style={{
                  '--particle-index': i,
                  '--particle-energy': value / 255
                }}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default BreathingOrb;
```

