```tsx
import React, { useState, useRef, useEffect, FC } from 'react';
import './BreathingOrb.css';
import { OrbProps, OrbState } from '../types/orb';

const BreathingOrb: FC<OrbProps> = ({ 
  audioContext, 
  isAudioPlaying, 
  size = 175,
  breathingSpeed = 5000 
}) => {
  const [state, setState] = useState<OrbState>({
    isActive: false,
    breathPhase: 0,
    audioData: new Array(64).fill(0),
    audioIntensity: 0
  });

  const animationRef = useRef<number | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const dataArrayRef = useRef<Uint8Array | null>(null);
  const orbRef = useRef<HTMLDivElement>(null);
  const audioSourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  // Breathing animation
  useEffect(() => {
    let startTime: number | null = null;

    const animateBreathing = (timestamp: number) => {
      if (!startTime) startTime = timestamp;
      const elapsed = timestamp - startTime;

      const progress = (elapsed % breathingSpeed) / breathingSpeed;
      const breath = Math.sin(progress * Math.PI * 2) * 0.5 + 0.5;

      // Audio modulation
      let audioModifier = 1;
      if (isAudioPlaying && state.audioData.length > 0) {
        const avgAudio = state.audioData.reduce((a, b) => a + b) / state.audioData.length;
        audioModifier = 1 + (avgAudio / 255) * 0.3;

        setState(prev => ({
          ...prev,
          audioIntensity: avgAudio / 255
        }));
      }

      const currentBreathPhase = breath * audioModifier;
      setState(prev => ({ ...prev, breathPhase: currentBreathPhase }));

      // Update CSS variables
      if (orbRef.current) {
        const baseGlow = 15 + breath * 10;
        const audioGlow = isAudioPlaying ? state.audioIntensity * 25 : 0;

        orbRef.current.style.setProperty('--breath-phase', currentBreathPhase.toString());
        orbRef.current.style.setProperty('--pulse-glow', `${baseGlow + audioGlow}px`);
        orbRef.current.style.setProperty('--spark-intensity', `${state.audioIntensity}`);
        orbRef.current.style.setProperty('--orb-size', `${size}px`);
      }

      animationRef.current = requestAnimationFrame(animateBreathing);
    };

    animationRef.current = requestAnimationFrame(animateBreathing);

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [isAudioPlaying, state.audioData, state.audioIntensity, breathingSpeed, size]);

  // Audio analysis setup
  useEffect(() => {
    const setupAudioAnalysis = async () => {
      if (audioContext && isAudioPlaying) {
        try {
          const analyser = audioContext.createAnalyser();
          analyser.fftSize = 128;
          analyserRef.current = analyser;

          const bufferLength = analyser.frequencyBinCount;
          dataArrayRef.current = new Uint8Array(bufferLength);

          // Connect to audio element
          const audioElement = document.getElementById('welcome-audio') as HTMLAudioElement;
          if (audioElement && !audioSourceRef.current) {
            audioSourceRef.current = audioContext.createMediaElementSource(audioElement);
            audioSourceRef.current.connect(analyser);
            analyser.connect(audioContext.destination);
          }

          const updateAudioData = () => {
            if (analyserRef.current && dataArrayRef.current && isAudioPlaying) {
              analyserRef.current.getByteFrequencyData(dataArrayRef.current);
              setState(prev => ({
                ...prev,
                audioData: Array.from(dataArrayRef.current!)
              }));
            }
            if (isAudioPlaying) {
              requestAnimationFrame(updateAudioData);
            }
          };

          updateAudioData();
        } catch (error) {
          console.error('Audio analysis setup failed:', error);
        }
      }
    };

    setupAudioAnalysis();

    return () => {
      if (audioSourceRef.current) {
        audioSourceRef.current.disconnect();
        audioSourceRef.current = null;
      }
    };
  }, [audioContext, isAudioPlaying]);

  const handleClick = () => {
    setState(prev => ({ ...prev, isActive: !prev.isActive }));

    if (orbRef.current) {
      orbRef.current.classList.add('orb-clicked');
      setTimeout(() => {
        orbRef.current?.classList.remove('orb-clicked');
      }, 300);
    }
  };

  const handleHover = (isHovering: boolean) => {
    if (orbRef.current) {
      if (isHovering) {
        orbRef.current.style.setProperty('--hover-intensity', '1');
      } else {
        orbRef.current.style.setProperty('--hover-intensity', '0');
      }
    }
  };

  return (
    <div className="orb-container">
      <div 
        ref={orbRef}
        className={`breathing-orb ${state.isActive ? 'active' : ''} ${isAudioPlaying ? 'audio-responsive' : ''}`}
        onClick={handleClick}
        onMouseEnter={() => handleHover(true)}
        onMouseLeave={() => handleHover(false)}
        style={{
          '--orb-size': `${size}px`,
          '--breath-phase': state.breathPhase,
          '--audio-intensity': state.audioIntensity,
          '--breathing-speed': `${breathingSpeed}ms`
        } as React.CSSProperties}
      >
        {/* Core Orb */}
        <div className="orb-core">
          <div className="orb-inner-glow" />
          <div className="orb-depth" />
        </div>

        {/* Fire Ring Layers */}
        <div className="fire-ring">
          <div className="fire-layer fire-orange" />
          <div className="fire-layer fire-gold" />
          <div className="fire-layer fire-blue" />
          <div className="fire-layer fire-white" />
        </div>

        {/* Subtle Sparks */}
        <div className="sparks-container">
          {Array.from({ length: 12 }).map((_, i) => (
            <div 
              key={i}
              className="spark"
              data-spark-index={i}
              style={{
                '--spark-index': i,
                '--spark-delay': `${i * 0.2}s`
              } as React.CSSProperties}
            />
          ))}
        </div>

        {/* Audio-responsive particles */}
        {isAudioPlaying && (
          <div className="audio-particles">
            {state.audioData.slice(0, 16).map((value, i) => (
              <div 
                key={i}
                className="audio-particle"
                style={{
                  '--particle-index': i,
                  '--particle-energy': value / 255
