```tsx
import React, { useState, useRef, useEffect } from 'react';
import BreathingOrb from './components/BreathingOrb';
import './App.css';

function App() {
  const [isAudioPlaying, setIsAudioPlaying] = useState<boolean>(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioElementRef = useRef<HTMLAudioElement>(null);

  const initializeAudioContext = () => {
    if (!audioContextRef.current) {
      try {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      } catch (error) {
        console.error('AudioContext not supported:', error);
      }
    }
  };

  const handleAudioPlay = () => {
    initializeAudioContext();
    setIsAudioPlaying(true);
  };

  const handleAudioPause = () => {
    setIsAudioPlaying(false);
  };

  // Resume AudioContext on user interaction (browser policy)
  useEffect(() => {
    const handleUserInteraction = () => {
      if (audioContextRef.current && audioContextRef.current.state === 'suspended') {
        audioContextRef.current.resume();
      }
    };

    window.addEventListener('click', handleUserInteraction);
    window.addEventListener('touchstart', handleUserInteraction);

    return () => {
      window.removeEventListener('click', handleUserInteraction);
      window.removeEventListener('touchstart', handleUserInteraction);
    };
  }, []);

  return (
    <div className="app">
      {/* Header with Breathing Orb */}
      <header className="app-header">
        <div className="orb-wrapper">
          <BreathingOrb 
            audioContext={audioContextRef.current}
            isAudioPlaying={isAudioPlaying}
            size={175}
            breathingSpeed={5000}
          />
        </div>
        <h1 className="app-title">Abundance Alchemy</h1>
      </header>

      {/* Audio Element */}
      <audio
        ref={audioElementRef}
        id="welcome-audio"
        src="/audio/welcome.mp3"
        onPlay={handleAudioPlay}
        onPause={handleAudioPause}
        onEnded={handleAudioPause}
        preload="metadata"
      />

      {/* Audio Controls (Optional) */}
      <div className="audio-controls">
        <button 
          onClick={() => audioElementRef.current?.play()}
          disabled={isAudioPlaying}
        >
          Play Welcome Audio
        </button>
        <button 
          onClick={() => audioElementRef.current?.pause()}
          disabled={!isAudioPlaying}
        >
          Pause Audio
        </button>
      </div>

      {/* Rest of your app content */}
      <main className="app-content">
        {/* Your existing components */}
      </main>
    </div>
  );
}

export default App;
```

