// services/useWelcomeAudio.ts
import { useState, useEffect, useRef } from 'react';

export const useWelcomeAudio = () => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [intensity, setIntensity] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);

  useEffect(() => {
    // Find welcome audio element
    const audioElement = document.getElementById('welcome-audio') as HTMLAudioElement;
    if (audioElement) {
      audioRef.current = audioElement;

      // Setup audio analysis if AudioContext is supported
      if (window.AudioContext) {
        const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        const analyser = audioContext.createAnalyser();
        analyser.fftSize = 64;

        const source = audioContext.createMediaElementSource(audioElement);
        source.connect(analyser);
        analyser.connect(audioContext.destination);
        analyserRef.current = analyser;

        const dataArray = new Uint8Array(analyser.frequencyBinCount);

        const updateIntensity = () => {
          if (analyserRef.current && isPlaying) {
            analyserRef.current.getByteFrequencyData(dataArray);
            const avg = dataArray.reduce((a, b) => a + b) / dataArray.length;
            setIntensity(avg / 255);
          }
          if (isPlaying) {
            requestAnimationFrame(updateIntensity);
          }
        };

        audioElement.onplay = () => {
          setIsPlaying(true);
          updateIntensity();
        };

        audioElement.onpause = () => {
          setIsPlaying(false);
          setIntensity(0);
        };

        audioElement.onended = () => {
          setIsPlaying(false);
          setIntensity(0);
        };
      }
    }

    return () => {
      // Cleanup
      setIsPlaying(false);
      setIntensity(0);
    };
  }, []);

  return { isPlaying, intensity };
};
```

