## 🔧 **STEP 2: UPDATE USEWELCOMEAUDIO.TSX TO PROVIDE INTENSITY**

```typescript
// services/useWelcomeAudio.ts - UPDATED VERSION
import { useState, useEffect, useRef, useCallback } from "react";
import { stopAmbience, startAmbience, unlockAudio } from "./audioService";
import { href } from "./base";

export function useWelcomeAudio(onComplete?: () => void) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [intensity, setIntensity] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const animationRef = useRef<number | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  // Analyze audio for visual feedback
  const analyzeAudio = useCallback(() => {
    if (!analyserRef.current || !isPlaying) {
      setIntensity(0);
      return;
    }

    const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
    analyserRef.current.getByteFrequencyData(dataArray);

    // Calculate average intensity (0-1)
    const avg = dataArray.reduce((a, b) => a + b, 0) / dataArray.length;
    const normalizedIntensity = avg / 255;

    setIntensity(normalizedIntensity);

    if (isPlaying) {
      animationRef.current = requestAnimationFrame(analyzeAudio);
    }
  }, [isPlaying]);

  // Initialize and play welcome audio
  useEffect(() => {
    let isMounted = true;

    const initAudio = async () => {
      try {
        unlockAudio();
        stopAmbience();

        // Create audio element
        const src = href("assets/audio/voices/welcome.mp3");
        const audio = new Audio(src);
        audioRef.current = audio;

        // Setup audio analysis if supported
        if (window.AudioContext || (window as any).webkitAudioContext) {
          try {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            audioContextRef.current = new AudioContextClass();

            if (audioContextRef.current.state === 'suspended') {
              await audioContextRef.current.resume();
            }

            const analyser = audioContextRef.current.createAnalyser();
            analyser.fftSize = 128;
            analyserRef.current = analyser;

            const source = audioContextRef.current.createMediaElementSource(audio);
            source.connect(analyser);
            analyser.connect(audioContextRef.current.destination);
          } catch (audioContextError) {
            console.warn('AudioContext not fully supported:', audioContextError);
          }
        }

        // Event listeners
        const handlePlay = () => {
          if (isMounted) setIsPlaying(true);
          if (analyserRef.current) {
            animationRef.current = requestAnimationFrame(analyzeAudio);
          }
        };

        const handlePause = () => {
          if (isMounted) setIsPlaying(false);
          setIntensity(0);
        };

        const handleEnded = () => {
          if (isMounted) setIsPlaying(false);
          setIntensity(0);
          if (onComplete) {
            setTimeout(onComplete, 500);
          }
        };

        audio.addEventListener('play', handlePlay);
        audio.addEventListener('pause', handlePause);
        audio.addEventListener('ended', handleEnded);

        // Auto-play with user interaction fallback
        const playPromise = audio.play();
        if (playPromise !== undefined) {
          playPromise.catch((error) => {
            console.log('Auto-play prevented, waiting for user interaction:', error);
          });
        }

        // Cleanup function
        return () => {
          audio.removeEventListener('play', handlePlay);
          audio.removeEventListener('pause', handlePause);
          audio.removeEventListener('ended', handleEnded);
          audio.pause();
          audioRef.current = null;

          if (animationRef.current) {
            cancelAnimationFrame(animationRef.current);
          }

          if (audioContextRef.current) {
            audioContextRef.current.close();
            audioContextRef.current = null;
          }

          startAmbience("OM", 50);
        };
      } catch (error) {
        console.error('Error initializing welcome audio:', error);
        if (isMounted) setIsPlaying(false);
        startAmbience("OM", 50);
      }
    };

    initAudio();

    return () => {
      isMounted = false;
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [onComplete, analyzeAudio]);

  return { isPlaying, intensity };
}
