### 3. **Fixed useWelcomeAudio.ts - MAKE AUDIO PLAY**:
```typescript
// services/useWelcomeAudio.ts - FIXED VERSION
import { useState, useEffect, useRef, useCallback } from "react";
import { stopAmbience, startAmbience, unlockAudio } from "./audioService";
import { href } from "./base";

export function useWelcomeAudio(onComplete?: () => void) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [intensity, setIntensity] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const animationRef = useRef<number | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  const analyzeAudio = useCallback(() => {
    if (!analyserRef.current || !isPlaying) {
      setIntensity(0);
      return;
    }

    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    analyserRef.current.getByteFrequencyData(dataArray);

    // Calculate average intensity (0-1)
    let sum = 0;
    for (let i = 0; i < bufferLength; i++) {
      sum += dataArray[i];
    }
    const avg = sum / bufferLength;
    const normalizedIntensity = Math.min(avg / 255, 1);

    setIntensity(normalizedIntensity);

    if (isPlaying) {
      animationRef.current = requestAnimationFrame(analyzeAudio);
    }
  }, [isPlaying]);

  // FIXED: Audio playback with proper initialization
  useEffect(() => {
    let isMounted = true;

    const initAndPlayAudio = async () => {
      try {
        // Stop any existing ambience
        stopAmbience();

        // Create audio element
        const audioSrc = href("assets/audio/voices/welcome.mp3");
        const audio = new Audio(audioSrc);
        audioRef.current = audio;

        // Preload audio
        audio.preload = "auto";

        // Setup audio context for analysis
        if (window.AudioContext || (window as any).webkitAudioContext) {
          try {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            const audioContext = new AudioContextClass();

            // Resume audio context (required by browser policy)
            if (audioContext.state === 'suspended') {
              await audioContext.resume();
            }

            const analyser = audioContext.createAnalyser();
            analyser.fftSize = 256;
            analyser.smoothingTimeConstant = 0.8;
            analyserRef.current = analyser;

            const source = audioContext.createMediaElementSource(audio);
            source.connect(analyser);
            analyser.connect(audioContext.destination);

            audioContextRef.current = audioContext;
          } catch (audioCtxError) {
            console.warn('Audio analysis not available:', audioCtxError);
          }
        }

        // Event handlers
        const handlePlay = () => {
          if (isMounted) {
            setIsPlaying(true);
            if (analyserRef.current) {
              animationRef.current = requestAnimationFrame(analyzeAudio);
            }
          }
        };

        const handlePause = () => {
          if (isMounted) {
            setIsPlaying(false);
            if (animationRef.current) {
              cancelAnimationFrame(animationRef.current);
            }
          }
        };

        const handleEnded = () => {
          if (isMounted) {
            setIsPlaying(false);
            setIntensity(0);
            if (animationRef.current) {
              cancelAnimationFrame(animationRef.current);
            }
            if (onComplete) {
              setTimeout(() => onComplete(), 800);
            }
            // Restore ambience
            startAmbience("OM", 50);
          }
        };

        const handleError = (e: any) => {
          console.error('Audio error:', e);
          if (isMounted) {
            setIsPlaying(false);
            // Fallback to ambience
            startAmbience("OM", 50);
          }
        };

        // Add event listeners
        audio.addEventListener('play', handlePlay);
        audio.addEventListener('pause', handlePause);
        audio.addEventListener('ended', handleEnded);
        audio.addEventListener('error', handleError);

        // FIXED: Auto-play with user interaction handled by parent component
        // The audio will play when the WelcomeScreen triggers it

        // Return cleanup
        return () => {
          audio.removeEventListener('play', handlePlay);
          audio.removeEventListener('pause', handlePause);
          audio.removeEventListener('ended', handleEnded);
          audio.removeEventListener('error', handleError);

          audio.pause();
          audio.currentTime = 0;

          if (animationRef.current) {
            cancelAnimationFrame(animationRef.current);
          }

          if (audioContextRef.current) {
            audioContextRef.current.close().catch(console.warn);
          }

          // Don't start ambience here - let parent component handle it
        };

      } catch (error) {
        console.error('Error setting up welcome audio:', error);
        if (isMounted) {
          setIsPlaying(false);
        }
      }
    };

    initAndPlayAudio();

    return () => {
      isMounted = false;
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [onComplete, analyzeAudio]);

  // Function to manually trigger audio play
  const playAudio = useCallback(() => {
    if (audioRef.current) {
      unlockAudio(); // Ensure audio is unlocked
      audioRef.current.play().catch((error) => {
        console.log('Manual play prevented:', error);
      });
    }
  }, []);

  return { isPlaying, intensity, playAudio };
}
