          console.warn('Audio analysis not available:', audioCtxError);
        }
      }
    };

    // Add event listeners
    audio.addEventListener('play', onPlay);
    audio.addEventListener('pause', onPause);
    audio.addEventListener('ended', onEnded);
    audio.addEventListener('error', onError);

    // Initialize and setup
    setupAudioAnalysis();

    // Sacred breath before audio (half second pause)
    startTimeout = window.setTimeout(() => {
      if (cancelled) return;

      audio.play().catch((error) => {
        console.log('Auto-play prevented:', error);
        // If auto-play fails, still proceed after pause
        setTimeout(() => {
          if (!cancelled && !finishedRef.current) {
            completeOnce();
          }
        }, 3000); // Give user 3 seconds to interact
      });
    }, PRE_AUDIO_PAUSE_MS);

    return () => {
      cancelled = true;
      if (startTimeout) clearTimeout(startTimeout);
      if (endTimeout) clearTimeout(endTimeout);
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }

      try {
        audio.pause();
        audio.currentTime = 0;
      } catch {
        // ignore
      }

      audio.removeEventListener('play', onPlay);
      audio.removeEventListener('pause', onPause);
      audio.removeEventListener('ended', onEnded);
      audio.removeEventListener('error', onError);

      audioRef.current = null;
      setIsSpeaking(false);
      setAudioIntensity(0);
    };
  }, [nextMode, onComplete]);

  const handleSkip = () => {
    // Stop audio immediately to prevent overlap
    try {
      audioRef.current?.pause();
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    } catch {
      // ignore
    }
    onComplete(nextMode);
  };

  return (
    <div className="relative min-h-screen bg-slate-950 text-slate-100">
      {/* Background image */}
      <div
        className="absolute inset-0 bg-cover bg-center"
        style={{
