// services/audioService.ts - UPDATED VERSION
import { href } from './base';

// Default ambient music URL
const DEFAULT_AMBIENCE_URL = href('assets/audio/ambient/default.mp3');

// Soundscape URL mapping
const SOUNDSCAPE_URLS: Record<string, string> = {
  OM: DEFAULT_AMBIENCE_URL,
  RAIN: href('assets/audio/ambient/rain.mp3'),
  FOREST: href('assets/audio/ambient/forest.mp3'),
  CELESTIAL: href('assets/audio/ambient/celestial.mp3'),
  // Add other soundscapes as needed
};

const getSoundscapeUrl = (soundscapeId: string): string => {
  return SOUNDSCAPE_URLS[soundscapeId] || DEFAULT_AMBIENCE_URL;
};

let ambienceAudio: HTMLAudioElement | null = null;
let sessionAudio: HTMLAudioElement | null = null;
let soundEffectsEnabled = true;
let musicEnabled = true;

export const setAudioSettings = (effects: boolean, music: boolean) => {
  soundEffectsEnabled = effects;
  musicEnabled = music;

  // Update existing audio elements
  if (ambienceAudio) {
    ambienceAudio.muted = !musicEnabled;
  }
  if (sessionAudio) {
    sessionAudio.muted = !musicEnabled;
  }
};

export const startAmbience = (soundscapeId: string = 'OM', volume: number = 50) => {
  // Stop existing ambience first
  stopAmbience();

  if (!musicEnabled) return;

  const url = getSoundscapeUrl(soundscapeId);
  const audio = new Audio(url);
  ambienceAudio = audio;

  // Set audio properties
  audio.volume = Math.min(volume, 100) / 100;
  audio.loop = true;
  audio.muted = !musicEnabled;
  audio.preload = 'auto';

  // Play with fallback
  const playPromise = audio.play();
  if (playPromise !== undefined) {
    playPromise.catch(error => {
      console.log('Ambience auto-play prevented:', error);
      // Don't throw - this is expected on some browsers
    });
  }

  return audio;
};

export const stopAmbience = () => {
  if (ambienceAudio) {
    ambienceAudio.pause();
    ambienceAudio.currentTime = 0;
    ambienceAudio = null;
  }
};

export const startSessionAudio = (url: string, volume: number = 50) => {
  // Stop ambience during session
  stopAmbience();

  if (!musicEnabled) return;

  const audio = new Audio(url);
  sessionAudio = audio;

  audio.volume = Math.min(volume, 100) / 100;
  audio.muted = !musicEnabled;

  const playPromise = audio.play();
  if (playPromise !== undefined) {
    playPromise.catch(error => {
      console.log('Session audio auto-play prevented:', error);
    });
  }

  return audio;
};

export const stopSessionAudio = () => {
  if (sessionAudio) {
    sessionAudio.pause();
    sessionAudio.currentTime = 0;
    sessionAudio = null;
  }
};

export const unlockAudio = () => {
  // Create and play a silent audio buffer to unlock audio context
  // This helps with browser autoplay policies
  const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
  const buffer = audioContext.createBuffer(1, 1, 22050);
  const source = audioContext.createBufferSource();
  source.buffer = buffer;
  source.connect(audioContext.destination);
  source.start();

  // Resume audio context if suspended
  if (audioContext.state === 'suspended') {
    audioContext.resume();
  }

  // Close after unlocking
  setTimeout(() => {
    audioContext.close();
  }, 100);
};

// Helper to check if audio is playing
export const isAmbiencePlaying = (): boolean => {
  return !!(ambienceAudio && !ambienceAudio.paused && !ambienceAudio.muted);
};

// Helper to change ambience volume in real-time
export const setAmbienceVolume = (volume: number) => {
  if (ambienceAudio) {
    ambienceAudio.volume = Math.min(volume, 100) / 100;
  }
};
