    stopAmbience();

    const audio = new Audio(WELCOME_URL);
    audioRef.current = audio;

    let cancelled = false;
    let startTimeout: number | undefined;
    let endTimeout: number | undefined;
    let rafId = 0;

    const completeOnce = () => {
      if (cancelled || finishedRef.current) return;
      finishedRef.current = true;

      // ✅ CRITICAL: Restart background music after welcome audio completes
      // Use setTimeout to ensure audio context is ready
      setTimeout(() => {
        startAmbience('OM', 50);
