      }

      rafId = window.requestAnimationFrame(update);
    };

    const onPlay = () => {
      setIsSpeaking(true);
      setAudioInitialized(true);
    };

    const onPause = () => setIsSpeaking(false);

    const onEnded = () => {
      setIsSpeaking(false);
      setProgress(100);
      completeOnce();
    };

    const onError = (e: any) => {
      console.error('Welcome audio error:', e);
      setIsSpeaking(false);
      // If audio fails, still restart ambience and proceed
      setTimeout(() => {
        startAmbience('OM', 50);
        onComplete(nextMode);
      }, 1000);
    };

    audio.addEventListener('play', onPlay);
    audio.addEventListener('pause', onPause);
    audio.addEventListener('ended', onEnded);
    audio.addEventListener('error', onError);

    // Sacred breath before audio
    startTimeout = window.setTimeout(() => {
      if (cancelled) return;

      audio
        .play()
        .then(() => {
          // Start progress only after playback actually begins
          rafId = window.requestAnimationFrame(update);
        })
