export const playButtonTap = () => playSoundEffect(BUTTON_TAP_URL, 0.4);
export const playCompletionSound = () => playSoundEffect(COMPLETION_SOUND_URL, 0.8);
export const playConfirm = () => playSoundEffect(CONFIRM_SOUND_URL, 0.6);

// Volume Controls - MISSING EXPORTS
export const updateVolume = (volume: number) => {
  if (ambienceAudio) {
    ambienceAudio.volume = Math.min(volume, 100) / 100 * masterVolume;
  }
};

export const setMasterVolume = (volume: number) => {
  masterVolume = Math.max(0, Math.min(1, volume));

  // Update all audio elements
  if (ambienceAudio) {
    ambienceAudio.volume = (ambienceAudio.volume / (masterVolume || 1)) * masterVolume;
  }
  if (sessionAudio) {
    sessionAudio.volume = (sessionAudio.volume / (masterVolume || 1)) * masterVolume;
  }
};

export const stopAll = () => {
  stopAmbience();
  stopSessionAudio();

  // Stop all sound effects
  Object.values(soundCache).forEach(audio => {
    audio.pause();
    audio.currentTime = 0;
  });
};

// Helper functions
