// components/WelcomeScreen.tsx - SIMPLE WORKING VERSION
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AppMode, UserProfile } from '../types';
import { SacredButton } from './ui/SacredButton';
import { href } from '../services/base';
import { stopAmbience, startAmbience } from '../services/audioService';
import { buttonSoundService } from '../services/buttonSoundService';

interface WelcomeScreenProps {
  user: UserProfile | null;
  onComplete: (nextMode: AppMode) => void;
}

const WELCOME_URL = href('assets/audio/voices/welcome.mp3');

export const WelcomeScreen: React.FC<WelcomeScreenProps> = ({ user, onComplete }) => {
  const [progress, setProgress] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const nextMode = useMemo(() => (user ? AppMode.DASHBOARD : AppMode.AUTH), [user]);

  useEffect(() => {
    // ✅ STOP background music when welcome screen loads
    stopAmbience();

    const audio = new Audio(WELCOME_URL);
    audioRef.current = audio;

    const handlePlay = () => setIsPlaying(true);
    const handlePause = () => setIsPlaying(false);
    const handleEnded = () => {
      setIsPlaying(false);
      setProgress(100);
      // ✅ RESTART background music after welcome audio
      setTimeout(() => {
        startAmbience('OM', 50);
        onComplete(nextMode);
      }, 700);
    };

    const handleTimeUpdate = () => {
      if (audio.duration) {
        setProgress((audio.currentTime / audio.duration) * 100);
      }
    };

    audio.addEventListener('play', handlePlay);
    audio.addEventListener('pause', handlePause);
    audio.addEventListener('ended', handleEnded);
    audio.addEventListener('timeupdate', handleTimeUpdate);

    // Auto-play after short delay
    const timer = setTimeout(() => {
      audio.play().catch(() => {
        // Auto-play blocked, show play button
        console.log('Auto-play blocked');
      });
    }, 500);

    return () => {
      clearTimeout(timer);
      audio.pause();
      audio.removeEventListener('play', handlePlay);
      audio.removeEventListener('pause', handlePause);
      audio.removeEventListener('ended', handleEnded);
      audio.removeEventListener('timeupdate', handleTimeUpdate);
    };
  }, [nextMode, onComplete]);

  const handleSkip = () => {
    buttonSoundService.play('click'); // ✅ Button sound
    if (audioRef.current) {
      audioRef.current.pause();
    }
    // ✅ RESTART background music when skipping
    startAmbience('OM', 50);
    onComplete(nextMode);
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gradient-to-b from-slate-950 to-black text-slate-100 p-6">
      {/* Simple Orb */}
      <div className="mb-8">
        <div className={`w-40 h-40 rounded-full border-4 ${
          isPlaying ? 'border-amber-500/50 animate-pulse' : 'border-slate-700'
        } flex items-center justify-center`}>
          <div className="text-4xl">
            {isPlaying ? '🌀' : '✨'}
          </div>
        </div>
      </div>

      {/* Title */}
      <h1 className="text-2xl font-light tracking-widest mb-4 text-center">
        Sacred Invocation
      </h1>

      {/* Message */}
      <div className="max-w-sm text-center mb-6 text-slate-300 space-y-2">
        <p>We honor your presence in this sacred space.</p>
        <p>Take a deep breath and allow this invocation to prepare your spirit.</p>
      </div>

      {/* Progress */}
      <div className="w-64 mb-6">
        <div className="w-full h-1 bg-slate-800 rounded-full overflow-hidden">
          <div 
            className="h-full bg-gradient-to-r from-amber-400 to-orange-400 transition-all duration-150"
            style={{ width: `${progress}%` }}
          />
        </div>
        <div className="text-xs text-slate-400 mt-2 text-center">
          {isPlaying ? 'Playing...' : 'Ready'}
        </div>
      </div>

      {/* Skip Button */}
      <div className="mt-4">
        <SacredButton
          onClick={handleSkip}
          variant="primary"
