// components/ui/SacredButton.tsx
interface SacredButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
}

const SacredButton: React.FC<SacredButtonProps> = ({ 
  variant = 'primary', 
  size = 'md', 
  children, 
  onClick,
  ...props 
}) => {
  const handleClick = (e: React.MouseEvent) => {
    buttonSoundService.play('click'); // Universal sound
    onClick?.(e);
  };

  return (
    <button
      className={`sacred-button sacred-button-${variant} sacred-button-${size}`}
      onClick={handleClick}
      {...props}
    >
      {children}
    </button>
  );
};
```
