// components/providers/SacredBackground.tsx
import React from 'react';
import { backgrounds } from '../../design/tokens';

interface SacredBackgroundProps {
  children: React.ReactNode;
  theme?: 'dark' | 'light';
  backgroundImage?: string; // Optional custom image
}

export const SacredBackground: React.FC<SacredBackgroundProps> = ({
  children,
  theme = 'dark',
  backgroundImage = '/backgrounds/sacred-bg.jpg' // Default image
}) => {
  const bgConfig = backgrounds.sacred;

  return (
    <div className={theme === 'dark' ? bgConfig.container : bgConfig.light.container}>
      {/* Background Image Layer */}
      <div className={theme === 'dark' ? bgConfig.imageWrapper : bgConfig.light.imageWrapper}>
        <img 
          src={backgroundImage} 
          alt="" 
          className={bgConfig.image}
          onError={(e) => {
            // Fallback if image doesn't exist
            e.currentTarget.style.display = 'none';
          }}
        />
      </div>

      {/* Gradient Overlay */}
      <div className={theme === 'dark' ? bgConfig.overlay : bgConfig.light.overlay} />

      {/* Content */}
      <div className="relative z-10">
        {children}
      </div>
    </div>
  );
};

// Optional HOC version for wrapping components
export const withSacredBackground = <P extends object>(
  WrappedComponent: React.ComponentType<P>,
  options?: { theme?: 'dark' | 'light' }
) => {
  return (props: P) => (
    <SacredBackground theme={options?.theme}>
      <WrappedComponent {...props} />
    </SacredBackground>
  );
};
