import React, { useMemo } from 'react';
import { AppMode, PracticeType, ThemeMode } from '../types';
import { useBackgrounds } from '../services/useBackgrounds';
import { useWelcomeAudio } from '../services/useWelcomeAudio';
import BreathingOrb from './BreathingOrb';
import { buttonSoundService } from '../services/buttonSoundService';
import type { BackgroundSlot } from '../services/apiService';
import { SacredBackground } from './providers/SacredBackground'; // IMPORT FROM PROVIDERS

interface LayoutProps {
  mode: AppMode;
  practiceType?: PracticeType;
  theme: ThemeMode;
  children: React.ReactNode;
}

function normalizeImageUrl(url: string): string | undefined {
  const trimmed = url.trim();
  if (!trimmed) return;
  if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) return trimmed;
  if (trimmed.startsWith('/')) return trimmed;
  const base = (import.meta as any).env?.BASE_URL || '/';
  return `${base}${trimmed.replace(/^\/+/, '')}`;
}

export const Layout: React.FC<LayoutProps> = ({ mode, practiceType, theme, children }) => {
  const { backgrounds } = useBackgrounds();
  const { isPlaying: isWelcomeAudioPlaying, intensity: audioIntensity } = useWelcomeAudio();

  const isBottomNavMode = [
    AppMode.DASHBOARD,
    AppMode.LIBRARY,
    AppMode.PROFILE,
    AppMode.STATS,
    AppMode.SETTINGS
  ].includes(mode);

  const shouldShowOrb = ![
    AppMode.SPLASH,
    AppMode.PRACTICE,
    AppMode.MEDITATION_SETUP,
    AppMode.AUTH
  ].includes(mode);

  const shouldEnableOverlay = ![
    AppMode.PRACTICE,
    AppMode.MEDITATION_SETUP
  ].includes(mode);

  const orbSize = (() => {
    switch (mode) {
      case AppMode.DASHBOARD: return 140;
      case AppMode.WELCOME: return 120;
      default: return 110;
    }
  })();

  const slot: BackgroundSlot | null = useMemo(() => {
    switch (mode) {
      case AppMode.SPLASH: return 'SPLASH';
      case AppMode.AUTH: return 'AUTH';
      case AppMode.WELCOME: return 'WELCOME';
      case AppMode.PERSONAL_GREETING: return 'WELCOME';
      case AppMode.FOCUS_INTRODUCTION: return 'WELCOME';
      case AppMode.FOCUS_SELECTION: return 'WELCOME';
      case AppMode.FOCUS_CONFIRMATION: return 'WELCOME';
      case AppMode.TUTORIAL: return 'HOME';
      case AppMode.DASHBOARD: return 'HOME';
      case AppMode.LIBRARY: return 'HOME';
      case AppMode.SETTINGS: return 'SETTINGS';
      case AppMode.PROFILE: case AppMode.STATS: return 'PROGRESS';
      case AppMode.MEDITATION_SETUP: return 'MEDITATION_SETUP';
      case AppMode.PRACTICE: {
        if (practiceType === PracticeType.MEDITATION) return 'MEDITATION_PRACTICE';
        if (practiceType === PracticeType.MORNING_IAM) return 'IAM_PRACTICE';
        if (practiceType === PracticeType.EVENING_ILOVE) return 'ILOVE_PRACTICE';
        return 'HOME';
      }
      default: return 'HOME';
    }
  }, [mode, practiceType]);

  const bgEntry = slot ? backgrounds?.[slot] : undefined;
  const apiBackgroundImage = bgEntry?.imageUrl ? normalizeImageUrl(bgEntry.imageUrl) : null;

  const handleOrbClick = () => {
    buttonSoundService.play('click');
  };

  return (
    <SacredBackground 
      theme={theme}
      backgroundImage={apiBackgroundImage}
      enableOverlay={shouldEnableOverlay}
    >
      {/* Universal Breathing Orb */}
      {shouldShowOrb && (
        <div className="absolute top-6 left-0 right-0 z-30 flex justify-center">
          <div className="pointer-events-auto">
            <BreathingOrb 
              isAudioPlaying={isWelcomeAudioPlaying}
              audioIntensity={audioIntensity}
              size={orbSize}
              onClick={handleOrbClick}
            />
          </div>
        </div>
      )}

      {/* Content Container */}
      <div className={[
        'relative mx-auto min-h-screen w-full',
        shouldShowOrb ? 'pt-32' : 'pt-6',
        'max-w-[420px]',
        'shadow-2xl shadow-black/40',
        isBottomNavMode ? 'pb-24' : 'pb-6'
      ].join(' ')}>
        <div className="relative z-20">
          {children}
        </div>
      </div>
    </SacredBackground>
  );
};
