// components/WelcomeScreen.tsx - UPDATED WITH UNIVERSAL BACKGROUND
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AppMode, UserProfile } from '../types';
import Orb from "./Orb";
import { SacredButton } from './ui/SacredButton';
import { href } from '../services/base';
import { stopAmbience, startAmbience } from '../services/audioService';
import { buttonSoundService } from '../services/buttonSoundService';
import { SacredBackground } from './providers/SacredBackground'; // ADD THIS IMPORT

interface WelcomeScreenProps {
  user: UserProfile | null;
  onComplete: (nextMode: AppMode) => void;
}

const WELCOME_URL = href('assets/audio/voices/welcome.mp3');
const SPLASH_BG = href('assets/images/backgrounds/splash.jpg'); // KEEP FOR BACKGROUND

const PRE_AUDIO_PAUSE_MS = 500;
const POST_AUDIO_PAUSE_MS = 700;

export const WelcomeScreen: React.FC<WelcomeScreenProps> = ({ user, onComplete }) => {
  const [progress, setProgress] = useState(0);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const finishedRef = useRef(false);

  const nextMode = useMemo(() => (user ? AppMode.DASHBOARD : AppMode.AUTH), [user]);

  useEffect(() => {
    finishedRef.current = false;

    // Stop background music
    stopAmbience();

    const audio = new Audio(WELCOME_URL);
    audioRef.current = audio;

    let cancelled = false;
    let startTimeout: number | undefined;
    let endTimeout: number | undefined;
    let rafId = 0;

    const completeOnce = () => {
      if (cancelled || finishedRef.current) return;
      finishedRef.current = true;

      // Restart background music after welcome audio
      setTimeout(() => {
        startAmbience('OM', 50);
        onComplete(nextMode);
      }, POST_AUDIO_PAUSE_MS);
    };

    const scheduleAfterBreath = () => {
      if (cancelled) return;
      endTimeout = window.setTimeout(() => {
        completeOnce();
      }, POST_AUDIO_PAUSE_MS);
    };

    const update = () => {
      if (cancelled) return;

      const d = audio.duration;
      const t = audio.currentTime;

      if (Number.isFinite(d) && d > 0) {
        setProgress(Math.min(100, (t / d) * 100));
      }

      rafId = window.requestAnimationFrame(update);
    };

    const onPlay = () => setIsSpeaking(true);
    const onPause = () => setIsSpeaking(false);
    const onEnded = () => {
      setIsSpeaking(false);
      setProgress(100);
      scheduleAfterBreath();
    };

    audio.addEventListener('play', onPlay);
    audio.addEventListener('pause', onPause);
    audio.addEventListener('ended', onEnded);

    // Sacred breath before audio
    startTimeout = window.setTimeout(() => {
      if (cancelled) return;

      audio
        .play()
        .then(() => {
          rafId = window.requestAnimationFrame(update);
        })
        .catch(() => {
          setIsSpeaking(false);
        });
    }, PRE_AUDIO_PAUSE_MS);

    return () => {
      cancelled = true;
      if (startTimeout) clearTimeout(startTimeout);
      if (endTimeout) clearTimeout(endTimeout);
      if (rafId) cancelAnimationFrame(rafId);

      try {
        audio.pause();
      } catch {
        // ignore
      }

      audio.removeEventListener('play', onPlay);
      audio.removeEventListener('pause', onPause);
      audio.removeEventListener('ended', onEnded);

      audioRef.current = null;
      setIsSpeaking(false);
    };
  }, [nextMode, onComplete]);

  const handleSkip = () => {
    buttonSoundService.play('click');

    // Stop audio immediately
    try {
      audioRef.current?.pause();
    } catch {
      // ignore
    }

    // Restart background music when skipping
    startAmbience('OM', 50);
    onComplete(nextMode);
  };

  return (
    <SacredBackground 
      theme="dark" 
      backgroundImage={SPLASH_BG} // Use the splash background
      enableOverlay={true}
    >
      <div className="min-h-screen max-w-md mx-auto px-6 grid grid-rows-[minmax(18px,1fr)_minmax(120px,22vh)_auto_auto_auto_minmax(16px,1fr)]">
        <div />
        <div className="flex items-center justify-center">
          <div className="relative">
            <Orb speaking={isSpeaking} sizePx={220} showParticles />
          </div>
        </div>
        <div className="text-center">
          <h1 className="text-xl font-serif font-bold text-orange-400">Abundance Alchemy</h1>
          <div className="mt-3 text-sm text-slate-300 max-w-xs mx-auto leading-relaxed space-y-1">
            <p>We Are Honored To Welcome You.</p>
            <p>Let Us Pause A Moment.</p>
            <p>Take a breath</p>
            <p>Let go and allow yourself to be immersed in this</p>
            <p>sacred invocation.</p>
            <p>Ase.</p>
          </div>
        </div>
        <div className="space-y-3">
          <div className="text-[11px] tracking-[0.2em] uppercase text-slate-400 text-center">
            We Are Praying Now
          </div>
          <div className="w-full h-2 rounded-full bg-slate-800/80 overflow-hidden">
            <div 
              className="h-full rounded-full bg-gradient-to-r from-amber-400 via-pink-400 to-violet-400 transition-[width] duration-150 ease-out"
              style={{ width: `${progress}%` }} 
            />
          </div>
        </div>
        <div className="text-center space-y-3">
          <div className="flex justify-center">
            <SacredButton
              onClick={handleSkip}
