  const widthClasses = {
    xs: 'max-w-xs',
    sm: 'max-w-sm',  
    md: 'max-w-md',
    lg: 'max-w-lg',
    full: 'max-w-full'
  };

  return (
    // BLACK OUTER TEMPLE SPACE
    <div className={`min-h-screen w-full flex items-center justify-center ${
      isDark ? 'bg-black' : 'bg-slate-50'
    }`}>

      {/* TEMPLE CONTAINER - The Sacred Space */}
      <div className={`
        relative
        w-full
        ${widthClasses[containerWidth]}
        min-h-screen
        h-auto
        mx-auto
        overflow-hidden
        shadow-2xl shadow-black/50
        border-x border-amber-500/10
        md:my-auto
        md:min-h-[90vh]
        md:max-h-[900px]
        md:rounded-2xl
        md:border-y
      `}>

        {/* SACRED BACKGROUND IMAGE */}
        {backgroundImage && (
          <div className="absolute inset-0">
            <img 
              src={backgroundImage} 
              alt="Sacred Temple Space" 
              className="w-full h-full object-cover"
              onError={(e) => {
                e.currentTarget.style.display = 'none';
                const parent = e.currentTarget.parentElement;
                if (parent) {
                  parent.style.background = isDark 
                    ? 'linear-gradient(135deg, #0f172a 0%, #1e293b 50%, #0f172a 100%)'
                    : 'linear-gradient(135deg, #f8fafc 0%, #e2e8f0 50%, #f8fafc 100%)';
                }
              }}
            />

            {/* GRADIENT OVERLAYS - Prevents gaps */}
            <div className={`absolute inset-0 ${
              isDark 
                ? 'bg-gradient-to-b from-black/40 via-transparent to-black/40' 
                : 'bg-gradient-to-b from-white/40 via-transparent to-white/40'
            }`} />

            {/* SIDE GRADIENTS - For wide screens */}
            <div className={`absolute inset-0 ${
              isDark 
                ? 'bg-gradient-to-r from-black/30 via-transparent to-black/30'
                : 'bg-gradient-to-r from-white/30 via-transparent to-white/30'
            }`} />
          </div>
        )}

        {/* CONTENT OVERLAY (optional) */}
        {enableOverlay && (
          <div className={`absolute inset-0 ${
            isDark 
              ? 'bg-gradient-to-br from-slate-950/60 via-slate-950/40 to-slate-950/60'
              : 'bg-gradient-to-br from-slate-50/60 via-slate-50/40 to-slate-50/60'
          }`} />
        )}

        {/* TEMPLE CONTENT AREA */}
        <div className="relative z-20 min-h-screen h-full flex flex-col">
          {children}
        </div>

        {/* TEMPLE BORDER GLOW */}
        <div className="absolute inset-0 pointer-events-none border border-amber-500/5 rounded-2xl" />
      </div>
    </div>
  );
};
```

