export function startAmbience(
  urlOrSound?: string | Soundscape,
  volumePercent?: number
) {
  if (!_musicEnabled) return;

  // 🎯 FIX: Use resolver function to get correct URL
  const url = resolveSoundscapeUrl(urlOrSound);
  if (!url) {
    console.warn('startAmbience: No valid URL provided', urlOrSound);
    return;
  }

  if (ambienceAudio && currentAmbienceUrl === url && !ambienceAudio.paused) {
    return;
  }

  if (ambienceAudio && currentAmbienceUrl === url && ambienceAudio.paused) {
    ambienceAudio.play().catch(() => {});
    ambiencePausedForPractice = false;
    return;
  }

  stopAmbience();

  const currentVolume =
    volumePercent !== undefined ? volumePercent / 100 : volume;

  ambienceAudio = new Audio(url);
  ambienceAudio.loop = true;
  ambienceAudio.volume = currentVolume;
  ambienceAudio.muted = !_musicEnabled;
  currentAmbienceUrl = url;
  ambiencePausedForPractice = false;

  ambienceAudio.play().catch((error) => {
    console.warn('Ambience autoplay blocked or failed:', error);
    console.log('Attempted URL:', url);
  });
}

export function startAmbienceWithSoundscape(
  soundscape: any,
  volumePercent?: number
) {
  return startAmbience(soundscape, volumePercent);
}

export function stopAmbience() {
  if (ambienceAudio) {
    ambienceAudio.pause();
    ambienceAudio = null;
  }

  currentAmbienceUrl = null;
  ambiencePausedForPractice = false;
}

// ---------- Session Audio ----------

export function startSessionAudio(url?: string, volumePercent?: number) {
  if (!_musicEnabled || !url) return;

  stopSessionAudio();

  if (ambienceAudio && !ambienceAudio.paused) {
    ambienceAudio.pause();
    ambiencePausedForPractice = true;
  }

  practiceAudio = new Audio(url);
  practiceAudio.loop = true;
  practiceAudio.volume =
    volumePercent !== undefined ? volumePercent / 100 : volume;
  practiceAudio.muted = !_musicEnabled;

  practiceAudio
    .play()
    .catch(() => console.warn('Practice audio blocked'));

  return practiceAudio;
}

export function stopSessionAudio(resumeAmbience = true) {
  if (practiceAudio) {
    practiceAudio.pause();
    practiceAudio = null;
  }

  if (resumeAmbience && ambienceAudio && ambiencePausedForPractice && _musicEnabled) {
    ambienceAudio.play().catch(() => {});
    ambiencePausedForPractice = false;
  }
}

