        setAvailableSoundscapes([...DEFAULT_SOUNDSCAPES, ...remoteSounds]);
      })
      .catch(() => {
        console.warn('Could not load remote soundscapes');
      });
  }, []);

  // 3. Load Persisted Data
  useEffect(() => {
    const loadAppData = async () => {
      try {
        const savedUser = localStorage.getItem('abundance_user');
        const savedSettings = localStorage.getItem('abundance_settings');

        if (savedSettings) {
          const parsed = JSON.parse(savedSettings);
          setSettings((prev) => ({
            ...prev,
            ...parsed,
            reminders: { ...prev.reminders, ...(parsed.reminders || {}) }
          }));
        }

        if (savedUser) {
          const u: UserProfile = JSON.parse(savedUser);
          if (!u.gratitudeLogs) u.gratitudeLogs = [];
          if (!u.customAffirmations) u.customAffirmations = [];
          setUser(u);

          // If user already completed onboarding, go to dashboard
          if (u.focusAreas.length > 0) {
            setMode(AppMode.DASHBOARD);
            startAmbience(settings.soundscapeId, settings.ambienceVolume);
          } else if (u.name) {
            // User exists but hasn't completed focus selection
            setMode(AppMode.PERSONAL_GREETING);
          }

          if (u.email) {
            apiService.getUserAffirmations(u.email).then((affs) => {
              if (affs.length > 0) {
                setUser((prev) => (prev ? { ...prev, customAffirmations: affs } : null));
              }
            });
          }
        }
      } catch (error) {
        console.error('Error loading app data:', error);
      } finally {
        setIsLoading(false);
      }
    };

    loadAppData();
  }, []);

// 4. Unlock audio on first user interaction
useEffect(() => {
  const unlockAudioOnInteraction = () => {
    console.log('🔊 App.tsx: First interaction detected, unlocking audio...');
    unlockAudio().then(() => {
      console.log('✅ App.tsx: Audio context unlocked successfully');
    }).catch((error) => {
      console.error('❌ App.tsx: Failed to unlock audio:', error);
    });

    // Remove event listeners
    document.removeEventListener('click', unlockAudioOnInteraction);
    document.removeEventListener('touchstart', unlockAudioOnInteraction);
    document.removeEventListener('keydown', unlockAudioOnInteraction);
  };

  document.addEventListener('click', unlockAudioOnInteraction);
  document.addEventListener('touchstart', unlockAudioOnInteraction);
  document.addEventListener('keydown', unlockAudioOnInteraction);

  return () => {
    document.removeEventListener('click', unlockAudioOnInteraction);
    document.removeEventListener('touchstart', unlockAudioOnInteraction);
    document.removeEventListener('keydown', unlockAudioOnInteraction);
  };
}, []);

  // 4. PreSplash Transition Logic - FIXED: Unlock audio BEFORE SplashScreen
  const handlePreSplashContinue = () => {
