import React, { useState, useEffect, useRef } from 'react';
import { Audio } from 'expo-av';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import PreSplash from './screens/PreSplash';
import SplashScreen from './screens/SplashScreen';
import WelcomeScreen from './screens/WelcomeScreen';
import AuthScreen from './screens/AuthScreen';

const Stack = createNativeStackNavigator();

// Audio management constants
const BACKGROUND_MUSIC = require('./assets/audio/background-music.mp3');
const WELCOME_SOUND = require('./assets/audio/welcome.mp3');

export default function App() {
  const [isLoading, setIsLoading] = useState(true);
  const backgroundSoundRef = useRef<Audio.Sound | null>(null);
  const welcomeSoundRef = useRef<Audio.Sound | null>(null);
  const [isBackgroundMusicLoaded, setIsBackgroundMusicLoaded] = useState(false);
  const [isWelcomeSoundLoaded, setIsWelcomeSoundLoaded] = useState(false);

  // Load audio files on mount
  useEffect(() => {
    const loadAudio = async () => {
      try {
        // Load background music
        const { sound: bgSound } = await Audio.Sound.createAsync(
          BACKGROUND_MUSIC,
          { 
            isLooping: true,
            volume: 0.7,
            shouldPlay: false // Don't auto-play, we'll control it
          }
        );
        backgroundSoundRef.current = bgSound;
        setIsBackgroundMusicLoaded(true);

        // Load welcome sound
        const { sound: welcomeSound } = await Audio.Sound.createAsync(
          WELCOME_SOUND,
          { 
            isLooping: false,
            volume: 1.0,
            shouldPlay: false
          }
        );
        welcomeSoundRef.current = welcomeSound;
        setIsWelcomeSoundLoaded(true);

        // Set audio mode
        await Audio.setAudioModeAsync({
          allowsRecordingIOS: false,
          staysActiveInBackground: true,
          playsInSilentModeIOS: true,
          shouldDuckAndroid: true,
          playThroughEarpieceAndroid: false,
        });
      } catch (error) {
        console.error('Error loading audio:', error);
      } finally {
        setIsLoading(false);
      }
    };

    loadAudio();

    // Cleanup on unmount
    return () => {
      if (backgroundSoundRef.current) {
        backgroundSoundRef.current.unloadAsync();
      }
      if (welcomeSoundRef.current) {
        welcomeSoundRef.current.unloadAsync();
      }
    };
  }, []);

  // Audio control functions
  const startBackgroundMusic = async () => {
    if (backgroundSoundRef.current && isBackgroundMusicLoaded) {
      try {
        await backgroundSoundRef.current.playAsync();
      } catch (error) {
        console.error('Error playing background music:', error);
      }
    }
  };

  const stopBackgroundMusic = async () => {
    if (backgroundSoundRef.current) {
      try {
        await backgroundSoundRef.current.stopAsync();
        await backgroundSoundRef.current.setPositionAsync(0);
      } catch (error) {
        console.error('Error stopping background music:', error);
      }
    }
  };

  const playWelcomeSound = async () => {
    if (welcomeSoundRef.current && isWelcomeSoundLoaded) {
      try {
        // Stop background music first
        await stopBackgroundMusic();
        // Play welcome sound
        await welcomeSoundRef.current.playAsync();
      } catch (error) {
        console.error('Error playing welcome sound:', error);
      }
    }
  };

  const stopWelcomeSound = async () => {
    if (welcomeSoundRef.current) {
      try {
        await welcomeSoundRef.current.stopAsync();
      } catch (error) {
        console.error('Error stopping welcome sound:', error);
      }
    }
  };

  // Screen event handlers
  const handleSplashComplete = async () => {
    await startBackgroundMusic();
  };

  const handleWelcomeComplete = async () => {
    await stopWelcomeSound();
    await startBackgroundMusic();
  };

  if (isLoading) {
    return null; // Or a minimal loading indicator
  }

  return (
    <NavigationContainer>
      <Stack.Navigator 
        screenOptions={{ 
          headerShown: false,
          animation: 'fade'
        }}
      >
        <Stack.Screen name="PreSplash" component={PreSplash} />
        <Stack.Screen name="Splash">
          {(props) => (
            <SplashScreen 
              {...props} 
              onComplete={handleSplashComplete}
            />
          )}
        </Stack.Screen>
        <Stack.Screen name="Welcome">
          {(props) => (
            <WelcomeScreen 
              {...props}
              onPlayWelcomeSound={playWelcomeSound}
              onComplete={handleWelcomeComplete}
            />
          )}
        </Stack.Screen>
        <Stack.Screen name="Auth" component={AuthScreen} />
      </Stack.Navigator>
    </NavigationContainer>
  );
}
