// src/components/WelcomeScreen.tsx - USING EXISTING BREATHINGORB
import React, { useEffect, useState } from 'react';
import { AppMode, UserProfile } from '../types';
import { playButtonTap } from '../services/audioService';
import BreathingOrb from '../components/BreathingOrb';

interface WelcomeScreenProps {
  user: UserProfile | null;
  onComplete: (nextMode: AppMode) => void;
}

const WELCOME_URL = '/assets/audio/voices/welcome.mp3';
const WELCOME_DURATION_MS = 34000; // 34 seconds
const TRANSITION_DELAY_MS = 500;

export const WelcomeScreen: React.FC<WelcomeScreenProps> = ({ user, onComplete }) => {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const audio = new Audio(WELCOME_URL);
    let isCancelled = false;
    const nextMode = user ? AppMode.DASHBOARD : AppMode.AUTH;
    let transitionTimeout: number | undefined;

    const completeOnce = () => {
      if (isCancelled) return;
      isCancelled = true;
      onComplete(nextMode);
    };

    const scheduleTransition = () => {
      if (isCancelled) return;
      transitionTimeout = window.setTimeout(() => {
        completeOnce();
      }, TRANSITION_DELAY_MS);
    };

    const handleEnded = () => {
      scheduleTransition();
    };

    audio.addEventListener('ended', handleEnded);

    const startTimeout = window.setTimeout(() => {
      if (isCancelled) return;
      audio.play().catch(() => {});
    }, 500);

    const start = performance.now();
    const tick = (now: number) => {
      if (isCancelled) return;
      const elapsed = now - start;
      const pct = Math.min(100, (elapsed / WELCOME_DURATION_MS) * 100);
      setProgress(pct);

      if (elapsed < WELCOME_DURATION_MS) {
        requestAnimationFrame(tick);
      } else {
        scheduleTransition();
      }
    };

    const rafId = requestAnimationFrame(tick);

    return () => {
      isCancelled = true;
      if (transitionTimeout) clearTimeout(transitionTimeout);
      clearTimeout(startTimeout);
      audio.pause();
      audio.removeEventListener('ended', handleEnded);
      cancelAnimationFrame(rafId);
    };
  }, [user, onComplete]);

  const handleSkip = () => {
    playButtonTap(); // Universal button tone
    const nextMode = user ? AppMode.DASHBOARD : AppMode.AUTH;
    onComplete(nextMode);
  };

  return (
    <div className="relative min-h-screen flex items-stretch justify-center bg-slate-950 text-slate-100">
      {/* Background image */}
      <div
        className="absolute inset-0 bg-cover bg-center"
        style={{
          backgroundImage: 'url(https://abundantthought.com/abundance-alchemy/assets/images/backgrounds/splash.jpg)'
        }}
      />
      {/* Dark overlay */}
      <div className="absolute inset-0 bg-slate-950/80" />

      {/* Content Container */}
      <div className="relative z-10 flex flex-col min-h-screen max-w-md mx-auto px-6 py-10 items-center justify-center">

        {/* Card Container */}
        <div className="backdrop-blur-md rounded-2xl border p-8 w-full max-w-xs shadow-xl bg-gradient-to-b from-slate-800/80 to-slate-900/80 border-white/10">

          {/* USE EXISTING BREATHINGORB COMPONENT */}
          <BreathingOrb 
            size={100}
            breathingSpeed={4000}
          />

          {/* Title */}
          <div className="text-center space-y-2 mb-6">
            <h1 className="text-xl font-light tracking-[0.2em] text-amber-500">
              Abundance Alchemy
            </h1>
            <p className="text-sm text-slate-300">
              We Are Honored To Welcome You.
            </p>
          </div>

          {/* Progress Section */}
          <div className="space-y-3 mb-6">
