export const unlockAudio = (): Promise<void> => {
  return new Promise((resolve, reject) => {
    if (audioContextUnlocked) {
      resolve();
      return;
    }

    // Create a silent sound to unlock audio context
    const silentSound = new Howl({
      src: ['data:audio/wav;base64,UklGRigAAABXQVZFZm10IBIAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA='],
      volume: 0.001,
      onload: () => {
        silentSound.play();
        setTimeout(() => {
          silentSound.stop();
          silentSound.unload();
          audioContextUnlocked = true;
          console.log('✅ Audio context unlocked');
          resolve();
        }, 100);
      },
      onloaderror: (id, error) => {
        console.warn('⚠️ Silent sound load error (may still work):', error);
        audioContextUnlocked = true;
        resolve();
      },
    });
  });
};

