import { PreSplash } from './components/PreSplash';
import { WelcomeScreen } from './components/WelcomeScreen';
import { PersonalGreeting } from './components/PersonalGreeting';
import { FocusIntroduction } from './components/FocusIntroduction';
import { FocusConfirmation } from './components/FocusConfirmation';

// Services
import {
  setAudioSettings,
  startAmbience,
  stopAmbience,
  startSessionAudio,
  stopSessionAudio,
  unlockAudio,
} from './services/audioService';
import { apiService } from './services/apiService';
import { buttonSoundService } from './services/buttonSoundService';

// Icons
import {
  Home,
  BarChart2,
  BookOpen,
  Sparkles,
  Settings as SettingsNavIcon,
} from 'lucide-react';

const DEFAULT_SOUNDSCAPES: Soundscape[] = [
  { id: 'OM', label: 'Deep Om', category: 'OM' },
  { id: 'RAIN', label: 'Rainfall', category: 'RAIN' },
  { id: 'FOREST', label: 'Forest', category: 'FOREST' },
  { id: 'CELESTIAL', label: 'Celestial', category: 'CELESTIAL' },
];

export const App: React.FC = () => {
  // State: Interaction (Audio Gate)
  const [hasInteracted, setHasInteracted] = useState(false);

  // State: Core App
  const [mode, setMode] = useState<AppMode>(AppMode.SPLASH);
  const [user, setUser] = useState<UserProfile | null>(null);
  const [activeSession, setActiveSession] = useState<PracticeSessionConfig | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // State: Settings
  const [settings, setSettings] = useState<AppSettings>({
    theme: 'dark' as ThemeMode,
    soundEffectsOn: true,
    musicOn: true,
    soundscapeId: 'OM',
    iAmSoundscapeId: 'OM',
    iLoveSoundscapeId: 'OM',
    meditationSoundscapeId: 'OM',
    ambienceVolume: 50,
    voiceId: 'Fenrir',
    reminders: {
      enabled: false,
      mode: 'INTERVAL',
      intervalMinutes: 60,
      specificTimes: ['08:00'],
    },
  });

  const [userAudioFile, setUserAudioFile] = useState<File | null>(null);
  const [tempRegName, setTempRegName] = useState('');
  const [availableSoundscapes, setAvailableSoundscapes] =
    useState<Soundscape[]>(DEFAULT_SOUNDSCAPES);
  const [selectedFocus, setSelectedFocus] = useState<FocusChoice | null>(null);

  // ==============================================
  // Effects
  // ==============================================

  // 1. Sync Audio Settings
  useEffect(() => {
    setAudioSettings(settings.soundEffectsOn, settings.musicOn);
  }, [settings.soundEffectsOn, settings.musicOn]);

  // 2. Load Remote Soundscapes
  useEffect(() => {
    apiService
      .getSoundscapes()
      .then((remoteSounds) => {
        setAvailableSoundscapes([...DEFAULT_SOUNDSCAPES, ...remoteSounds]);
      })
      .catch(() => {
        console.warn('Could not load remote soundscapes');
      });
  }, []);

  // 3. Load Persisted Data
  useEffect(() => {
    const loadAppData = async () => {
      try {
        const savedUser = localStorage.getItem('abundance_user');
        const savedSettings = localStorage.getItem('abundance_settings');

        if (savedSettings) {
          const parsed = JSON.parse(savedSettings);
          setSettings((prev) => ({
            ...prev,
            ...parsed,
            reminders: { ...prev.reminders, ...(parsed.reminders || {}) },
          }));
        }

        if (savedUser) {
          const u: UserProfile = JSON.parse(savedUser);
          if (!u.gratitudeLogs) u.gratitudeLogs = [];
          if (!u.customAffirmations) u.customAffirmations = [];
          setUser(u);

          if (u.focusAreas && u.focusAreas.length > 0) {
            setMode(AppMode.DASHBOARD);
            startAmbience(settings.soundscapeId, settings.ambienceVolume);
          } else if (u.name) {
            setMode(AppMode.PERSONAL_GREETING);
          }

          if (u.email) {
            apiService.getUserAffirmations(u.email).then((affs) => {
              if (affs.length > 0) {
                setUser((prev) =>
                  prev ? { ...prev, customAffirmations: affs } : null
                );
              }
            });
          }
        }
      } catch (error) {
        console.error('Error loading app data:', error);
      } finally {
        setIsLoading(false);
      }
    };

    loadAppData();
  }, [settings.soundscapeId, settings.ambienceVolume]);

  // ==============================================
  // Audio Flow Handlers
  // ==============================================

  // PreSplash Transition Logic - gesture-safe ambience
  const handlePreSplashContinue = () => {
    console.log('🔊 PreSplash: Button clicked, starting ambience + unlocking audio...');

    // Start ambience immediately in the same click (gesture-tied)
    startAmbience(settings.soundscapeId, settings.ambienceVolume);

    // Unlock audio in background (does not gate ambience start)
    unlockAudio()
      .then(() => {
        console.log('✅ PreSplash: Audio context unlocked');
      })
      .catch((error) => {
        console.error('❌ PreSplash: Audio unlock failed:', error);
      });

    setHasInteracted(true);
    setMode(AppMode.SPLASH);
  };

  // ==============================================
  // Handlers: Auth
  // ==============================================

  const handleRegister = (account: UserAccount) => {
    const name = account.name || '';
    setTempRegName(name);

    const newProfile: UserProfile = {
      name,
      email: account.email,
      focusAreas: [],
      cyclePreference: CycleType.DAILY,
      streak: 0,
      lastPracticeDate: null,
      affirmationsCompleted: 0,
      level: 1,
      customAffirmations: [],
      gratitudeLogs: [],
    };

    setUser(newProfile);
    localStorage.setItem('abundance_user', JSON.stringify(newProfile));
    setMode(AppMode.PERSONAL_GREETING);
  };

  const handleLogin = (account: UserAccount) => {
    const savedUser = localStorage.getItem('abundance_user');
    if (savedUser) {
      const u: UserProfile = JSON.parse(savedUser);
      setUser(u);

      if (u.focusAreas && u.focusAreas.length > 0) {
        setMode(AppMode.DASHBOARD);
        startAmbience(settings.soundscapeId, settings.ambienceVolume);
      } else {
        setMode(AppMode.PERSONAL_GREETING);
      }
    } else {
      handleRegister(account);
    }
  };

  const handleSignOut = () => {
    localStorage.removeItem('abundance_user');
    localStorage.removeItem('abundance_auth');
    stopAmbience();
    setUser(null);
    setMode(AppMode.AUTH);
  };

  // ==============================================
  // Focus Flow Handlers
  // ==============================================

  const handlePersonalGreetingComplete = (nickname: string) => {
    if (user) {
      const updatedUser: UserProfile = {
        ...user,
        nickname: nickname || user.name,
      };
      setUser(updatedUser);
      localStorage.setItem('abundance_user', JSON.stringify(updatedUser));
    }

    setMode(AppMode.FOCUS_INTRODUCTION);
  };

  const handleFocusSelectionComplete = (focus: FocusChoice, cycleType: CycleType) => {
    setSelectedFocus(focus);
    if (user) {
      const updatedUser: UserProfile = {
        ...user,
        selectedFocus: focus,
        focusAreas: [focus.label],
        cyclePreference: cycleType,
      };

      setUser(updatedUser);
      localStorage.setItem('abundance_user', JSON.stringify(updatedUser));
    }

    setMode(AppMode.FOCUS_CONFIRMATION);
  };

  const handleFocusConfirmationComplete = () => {
    setMode(AppMode.TUTORIAL);
  };

  // ==============================================
  // Practice & Sessions
  // ==============================================

  const startPractice = (type: PracticeType, duration: number) => {
    buttonSoundService.play('confirm');
    stopAmbience();
    const config: PracticeSessionConfig = { type, duration };
    setActiveSession(config);
    setMode(AppMode.PRACTICE);
  };

  const handleMeditationBegin = (config: PracticeSessionConfig) => {
    buttonSoundService.play('confirm');
    stopAmbience();

    if (config.soundscape) {
      const url =
        typeof config.soundscape === 'string'
          ? config.soundscape
          : config.soundscape.url;
      if (url) startSessionAudio(url);
    }

    setActiveSession(config);
    setMode(AppMode.PRACTICE);
  };

  const handleSessionComplete = (newLog?: GratitudeLog) => {
    if (user) {
      const updatedUser: UserProfile = {
        ...user,
        affirmationsCompleted: user.affirmationsCompleted + 1,
        streak: user.streak + 1,
        lastPracticeDate: new Date().toISOString(),
        gratitudeLogs: newLog ? [...user.gratitudeLogs, newLog] : user.gratitudeLogs,
      };

      setUser(updatedUser);
      localStorage.setItem('abundance_user', JSON.stringify(updatedUser));
      apiService.syncProgress(updatedUser);
    }

    stopSessionAudio();
    startAmbience(settings.soundscapeId, settings.ambienceVolume);
    setMode(AppMode.DASHBOARD);
    setActiveSession(null);
  };

  const handleSessionExit = () => {
    buttonSoundService.play('click');
    stopSessionAudio();
    startAmbience(settings.soundscapeId, settings.ambienceVolume);
    setMode(AppMode.DASHBOARD);
    setActiveSession(null);
  };

  // ==============================================
  // Data
  // ==============================================

  const addAffirmation = async (text: string, type: PracticeType) => {
    if (!user) return;

    const auth = JSON.parse(localStorage.getItem('abundance_auth') || '{}');
    const email = auth.email || 'guest';
    const newId = await apiService.addUserAffirmation(email, text, type);

    if (newId) {
      const newAff: Affirmation = {
        id: newId,
        text,
        category: 'Custom',
        isFavorite: true,
        type,
        dateAdded: new Date().toISOString(),
      };

      const updatedUser: UserProfile = {
        ...user,
        customAffirmations: [...user.customAffirmations, newAff],
      };

      setUser(updatedUser);
      localStorage.setItem('abundance_user', JSON.stringify(updatedUser));
    }
  };

  const removeAffirmation = async (id: string) => {
    if (!user) return;

    const success = await apiService.removeUserAffirmation(id);
    if (success) {
      const updatedUser: UserProfile = {
        ...user,
        customAffirmations: user.customAffirmations.filter((a) => a.id !== id),
      };

      setUser(updatedUser);
      localStorage.setItem('abundance_user', JSON.stringify(updatedUser));
    }
  };

  const updateSettings = (newSettings: AppSettings) => {
    setSettings(newSettings);
    localStorage.setItem('abundance_settings', JSON.stringify(newSettings));

    if (
      newSettings.soundscapeId !== settings.soundscapeId ||
      newSettings.ambienceVolume !== settings.ambienceVolume
    ) {
      startAmbience(newSettings.soundscapeId, newSettings.ambienceVolume);
    }
  };

  const handleSettingsAudioUpload = (file: File, _category: string) => {
    setUserAudioFile(file);
  };

  const handleOnboardingComplete = (profile: UserProfile) => {
    const initialProfile: UserProfile = {
      ...profile,
      customAffirmations: [],
      gratitudeLogs: [],
      selectedFocus: selectedFocus || undefined,
    };

    setUser(initialProfile);
    localStorage.setItem('abundance_user', JSON.stringify(initialProfile));
    setMode(AppMode.TUTORIAL);
  };

  // ==============================================
  // Render
  // ==============================================

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-black text-amber-100">
        Preparing your sacred space...
      </div>
    );
  }

  if (!hasInteracted) {
    return (
      <PreSplash
        onContinue={handlePreSplashContinue}
        theme={settings.theme}
      />
    );
  }

  const currentSoundscapeObj =
    availableSoundscapes.find(
      (s) => String(s.id) === String(settings.soundscapeId)
    ) || DEFAULT_SOUNDSCAPES[0];

  const renderContent = () => {
    switch (mode) {
      case AppMode.SPLASH:
        return (
          <SplashScreen
            onComplete={() => {
              console.log('🔊 SplashScreen complete -> WelcomeScreen');
              setMode(AppMode.WELCOME);
            }}
          />
        );

      case AppMode.WELCOME:
        return (
          <WelcomeScreen
            user={user}
            onComplete={(nextMode) => {
              console.log('🔊 WelcomeScreen complete ->', nextMode, '- restarting ambience');
              // Restart ambience when leaving WelcomeScreen
              startAmbience(settings.soundscapeId, settings.ambienceVolume);
              setMode(nextMode);
            }}
          />
        );

      case AppMode.AUTH:
        return (
          <Auth
            onRegister={handleRegister}
            onLogin={handleLogin}
            theme={settings.theme}
            onAudioStart={() => {
              // Ensure audio is playing when Auth loads (safety net)
              startAmbience(settings.soundscapeId, settings.ambienceVolume);
            }}
          />
        );

      case AppMode.PERSONAL_GREETING:
        return user ? (
          <PersonalGreeting
            onComplete={handlePersonalGreetingComplete}
            theme={settings.theme}
          />
        ) : null;

      case AppMode.FOCUS_INTRODUCTION:
        return (
          <FocusIntroduction
            onComplete={() => setMode(AppMode.FOCUS_SELECTION)}
            theme={settings.theme}
          />
        );

      case AppMode.FOCUS_SELECTION:
        return (
          <FocusIntroduction
            onComplete={() => setMode(AppMode.FOCUS_SELECTION)}
            theme={settings.theme}
          />
        );

      case AppMode.FOCUS_CONFIRMATION:
        return selectedFocus ? (
          <FocusConfirmation
            selectedFocus={selectedFocus}
            onComplete={handleFocusConfirmationComplete}
            theme={settings.theme}
          />
        ) : null;

      case AppMode.TUTORIAL:
        return (
          <TutorialOverlay
            onComplete={() => setMode(AppMode.DASHBOARD)}
            onChangeFocus={() => setMode(AppMode.FOCUS_SELECTION)}
            theme={settings.theme}
          />
        );

      case AppMode.SETTINGS:
        return (
          <Settings
            settings={settings}
            onUpdateSettings={updateSettings}
            onChangeFocus={() => setMode(AppMode.FOCUS_SELECTION)}
            onBack={() => setMode(AppMode.DASHBOARD)}
            onSignOut={handleSignOut}
            onReplayTutorial={() => setMode(AppMode.TUTORIAL)}
            onAudioUpload={handleSettingsAudioUpload}
            theme={settings.theme}
            userAudioFile={userAudioFile}
            availableSoundscapes={availableSoundscapes}
          />
        );

      case AppMode.DASHBOARD:
        return user ? (
          <Dashboard
            onStartPractice={startPractice}
            onOpenLibrary={() => setMode(AppMode.LIBRARY)}
            onOpenSettings={() => setMode(AppMode.SETTINGS)}
            onSignOut={handleSignOut}
            theme={settings.theme}
            userAudioFile={userAudioFile || undefined}
            activeSoundscape={currentSoundscapeObj}
          />
        ) : null;

      case AppMode.MEDITATION_SETUP:
        return (
          <MeditationSetup
            onBack={() => setMode(AppMode.DASHBOARD)}
            onBegin={handleMeditationBegin}
            theme={settings.theme}
            availableSoundscapes={availableSoundscapes}
          />
        );

      case AppMode.PRACTICE:
        return activeSession ? (
          <PracticeSession
            config={activeSession}
            onComplete={handleSessionComplete}
            onExit={handleSessionExit}
            theme={settings.theme}
          />
        ) : null;

      case AppMode.PROFILE:
        return (
          <Stats
            onBack={() => setMode(AppMode.DASHBOARD)}
            theme={settings.theme}
          />
        );

      case AppMode.LIBRARY:
        return (
          <Library
            onBack={() => setMode(AppMode.DASHBOARD)}
            onAddAffirmation={addAffirmation}
            onRemoveAffirmation={removeAffirmation}
            theme={settings.theme}
          />
        );

      case AppMode.ONBOARDING:
        return (
          <Onboarding
            onComplete={handleOnboardingComplete}
          />
        );

      default:
        return null;
    }
  };

  const hideNav = [
    AppMode.SPLASH,
    AppMode.WELCOME,
    AppMode.AUTH,
    AppMode.PERSONAL_GREETING,
    AppMode.FOCUS_INTRODUCTION,
    AppMode.FOCUS_SELECTION,
    AppMode.FOCUS_CONFIRMATION,
    AppMode.PRACTICE,
    AppMode.TUTORIAL,
    AppMode.MEDITATION_SETUP,
    AppMode.ONBOARDING,
  ].includes(mode);

  const getNavClass = (targetMode: AppMode) => {
    const isActive = mode === targetMode;
    if (settings.theme === 'light') {
      return isActive
        ? 'text-amber-600'
        : 'text-slate-400 hover:text-slate-600';
    }
    return isActive
      ? 'text-amber-400'
      : 'text-slate-500 hover:text-slate-300';
  };

  // ==============================================
  // Return Statement
  // ==============================================

  return (
    <Layout mode={mode} theme={settings.theme}>
      {renderContent()}

      {!hideNav && (
        <nav className="fixed bottom-0 left-0 right-0 pb-4 pt-2 bg-slate-950/90 border-t border-slate-800/80 backdrop-blur-md z-40">
          <div className="max-w-md mx-auto flex items-center justify-between px-6">
            {/* Home */}
            <button
              onClick={() => {
                buttonSoundService.play('click');
                setMode(AppMode.DASHBOARD);
              }}
              className={`flex flex-col items-center space-y-1 transition-colors ${getNavClass(
                AppMode.DASHBOARD
              )}`}
            >
              <Home className="w-5 h-5" />
              <span className="text-[10px] tracking-[0.16em]">
                HOME
              </span>
            </button>

            {/* Library */}
            <button
              onClick={() => {
                buttonSoundService.play('click');
                setMode(AppMode.LIBRARY);
              }}
              className={`flex flex-col items-center space-y-1 transition-colors ${getNavClass(
                AppMode.LIBRARY
              )}`}
            >
              <BookOpen className="w-5 h-5" />
              <span className="text-[10px] tracking-[0.16em]">
                MAKTABA
              </span>
            </button>

            {/* Center Sacred Button */}
            <button
              onClick={() => {
                buttonSoundService.play('confirm');
                startPractice(PracticeType.MORNING_IAM, 1);
              }}
              className="relative -mt-8 w-16 h-16 rounded-full bg-slate-900 flex items-center justify-center text-white hover:bg-slate-800 transition-colors shadow-[0_0_25px_rgba(251,191,36,0.5)] border border-amber-400/60"
            >
              <Sparkles className="w-6 h-6 text-amber-300" />
            </button>

            {/* Journey */}
            <button
              onClick={() => {
                buttonSoundService.play('click');
                setMode(AppMode.PROFILE);
              }}
              className={`flex flex-col items-center space-y-1 transition-colors ${getNavClass(
                AppMode.PROFILE
              )}`}
            >
              <BarChart2 className="w-5 h-5" />
              <span className="text-[10px] tracking-[0.16em]">
                JOURNEY
              </span>
            </button>

            {/* Settings */}
            <button
              onClick={() => {
                buttonSoundService.play('click');
                setMode(AppMode.SETTINGS);
              }}
              className={`flex flex-col items-center space-y-1 transition-colors ${getNavClass(
                AppMode.SETTINGS
              )}`}
            >
              <SettingsNavIcon className="w-5 h-5" />
              <span className="text-[10px] tracking-[0.16em]">
                SETTINGS
              </span>
            </button>
          </div>
        </nav>
      )}
    </Layout>
  );
};
```

