```typescript
// services/buttonSoundService.ts
import { getAudioContext } from './buttonTone';

export const buttonSoundService = {
  play: (type: 'click' | 'confirm' | 'back' | 'tap' | 'enter') => {
    try {
      const audioContext = getAudioContext();
      const oscillator = audioContext.createOscillator();
      const gainNode = audioContext.createGain();

      oscillator.connect(gainNode);
      gainNode.connect(audioContext.destination);

      // Different frequencies for different button types
      switch(type) {
        case 'click':
          oscillator.frequency.value = 220.5; // A3
          break;
        case 'confirm':
          oscillator.frequency.value = 110.3; // Sacred frequency (A2)
          break;
        case 'enter':
          oscillator.frequency.value = 146.8; // D3
          break;
        default:
          oscillator.frequency.value = 165.0; // E3
      }

      oscillator.type = 'sine';

      // Envelope
      const now = audioContext.currentTime;
      gainNode.gain.setValueAtTime(0, now);
      gainNode.gain.linearRampToValueAtTime(0.2, now + 0.05);
      gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.5);

      oscillator.start();
      oscillator.stop(now + 0.5);

      console.log(`🔊 Button sound: ${type} (${oscillator.frequency.value}Hz)`);
    } catch (error) {
      console.warn('Could not play button sound:', error);
    }
  }
};
```

