// Services - FIXED
import {
  setAudioSettings,
  startAmbience,
  stopAmbience,
  startSessionAudio,
  stopSessionAudio,
  unlockAudio,
} from './services/audioService';
import { apiService } from './services/apiService';
import { buttonSoundService } from './services/buttonSoundService';

// Icons
import {
  Home,
  BarChart2,
  BookOpen,
  Sparkles,
  Settings as SettingsNavIcon,
} from 'lucide-react';

const DEFAULT_SOUNDSCAPES: Soundscape[] = [
  { id: 'OM', label: 'Deep Om', category: 'OM' },
  { id: 'RAIN', label: 'Rainfall', category: 'RAIN' },
  { id: 'FOREST', label: 'Forest', category: 'FOREST' },
  { id: 'CELESTIAL', label: 'Celestial', category: 'CELESTIAL' },
];

export const App: React.FC = () => {
  // State: Interaction (Audio Gate)
  const [hasInteracted, setHasInteracted] = useState(false);

  // State: Core App
  const [mode, setMode] = useState<AppMode>(AppMode.SPLASH);
  const [user, setUser] = useState<UserProfile | null>(null);
  const [activeSession, setActiveSession] = useState<PracticeSessionConfig | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // State: Settings
  const [settings, setSettings] = useState<AppSettings>({
    theme: 'dark' as ThemeMode,
    soundEffectsOn: true,
    musicOn: true,
    soundscapeId: 'OM',
    iAmSoundscapeId: 'OM',
    iLoveSoundscapeId: 'OM',
    meditationSoundscapeId: 'OM',
    ambienceVolume: 50,
    voiceId: 'Fenrir',
    reminders: {
      enabled: false,
      mode: 'INTERVAL',
      intervalMinutes: 60,
      specificTimes: ['08:00'],
    },
  });

  const [userAudioFile, setUserAudioFile] = useState<File | null>(null);
  const [tempRegName, setTempRegName] = useState('');
  const [availableSoundscapes, setAvailableSoundscapes] =
    useState<Soundscape[]>(DEFAULT_SOUNDSCAPES);
  const [selectedFocus, setSelectedFocus] = useState<FocusChoice | null>(null);

  // ==============================================
  // Effects
  // ==============================================

  // 1. Sync Audio Settings
  useEffect(() => {
    setAudioSettings(settings.soundEffectsOn, settings.musicOn);
  }, [settings.soundEffectsOn, settings.musicOn]);

  // 2. Load Remote Soundscapes
  useEffect(() => {
    apiService
      .getSoundscapes()
      .then((remoteSounds) => {
        setAvailableSoundscapes([...DEFAULT_SOUNDSCAPES, ...remoteSounds]);
      })
      .catch(() => {
        console.warn('Could not load remote soundscapes');
      });
  }, []);

  // 3. Load Persisted Data
  useEffect(() => {
    const loadAppData = async () => {
      try {
        const savedUser = localStorage.getItem('abundance_user');
        const savedSettings = localStorage.getItem('abundance_settings');

        if (savedSettings) {
          const parsed = JSON.parse(savedSettings);
          setSettings((prev) => ({
            ...prev,
            ...parsed,
            reminders: { ...prev.reminders, ...(parsed.reminders || {}) },
          }));
        }

        if (savedUser) {
          const u: UserProfile = JSON.parse(savedUser);
          if (!u.gratitudeLogs) u.gratitudeLogs = [];
          if (!u.customAffirmations) u.customAffirmations = [];
          setUser(u);

          if (u.focusAreas && u.focusAreas.length > 0) {
            setMode(AppMode.DASHBOARD);
            startAmbience(settings.soundscapeId, settings.ambienceVolume);
          } else if (u.name) {
            setMode(AppMode.PERSONAL_GREETING);
          }

          if (u.email) {
            apiService.getUserAffirmations(u.email).then((affs) => {
              if (affs.length > 0) {
                setUser((prev) =>
                  prev ? { ...prev, customAffirmations: affs } : null
                );
              }
            });
          }
        }
      } catch (error) {
        console.error('Error loading app data:', error);
      } finally {
        setIsLoading(false);
      }
    };

    loadAppData();
  }, [settings.soundscapeId, settings.ambienceVolume]);

  // ==============================================
  // Audio Flow Handlers - FIXED
  // ==============================================

  // PreSplash Transition Logic - gesture-safe ambience
  const handlePreSplashContinue = () => {
    console.log('🔊 PreSplash: Button clicked, starting ambience + unlocking audio...');

    // Start ambience immediately in the same click (gesture-tied)
    startAmbience(settings.soundscapeId, settings.ambienceVolume);

    // Unlock audio in background (does not gate ambience start)
    unlockAudio()
      .then(() => {
        console.log('✅ PreSplash: Audio context unlocked');
      })
      .catch((error) => {
        console.error('❌ PreSplash: Audio unlock failed:', error);
      });

    setHasInteracted(true);
    setMode(AppMode.SPLASH);
  };

  // ==============================================
  // Handlers: Auth
  // ==============================================

  const handleRegister = (account: UserAccount) => {
    const name = account.name || '';
    setTempRegName(name);

    const newProfile: UserProfile = {
      name,
      email: account.email,
      focusAreas: [],
      cyclePreference: CycleType.DAILY,
      streak: 0,
      lastPracticeDate: null,
      affirmationsCompleted: 0,
      level: 1,
      customAffirmations: [],
      gratitudeLogs: [],
    };

    setUser(newProfile);
    localStorage.setItem('abundance_user', JSON.stringify(newProfile));
    setMode(AppMode.PERSONAL_GREETING);
  };

  const handleLogin = (account: UserAccount) => {
    const savedUser = localStorage.getItem('abundance_user');
    if (savedUser) {
      const u: UserProfile = JSON.parse(savedUser);
      setUser(u);

      if (u.focusAreas && u.focusAreas.length > 0) {
        setMode(AppMode.DASHBOARD);
        startAmbience(settings.soundscapeId, settings.ambienceVolume);
      } else {
        setMode(AppMode.PERSONAL_GREETING);
      }
    } else {
      handleRegister(account);
    }
  };

  const handleSignOut = () => {
    localStorage.removeItem('abundance_user');
    localStorage.removeItem('abundance_auth');
    stopAmbience();
    setUser(null);
    setMode(AppMode.AUTH);
  };

  // ==============================================
  // Practice & Sessions - SIMPLIFIED
  // ==============================================

  const startPractice = (type: PracticeType, duration: number) => {
    buttonSoundService.play('confirm');
    stopAmbience();
    const config: PracticeSessionConfig = { type, duration };
    setActiveSession(config);
    // setMode(AppMode.PRACTICE); // Commented out for now
    setMode(AppMode.DASHBOARD); // Temporary
  };

  const updateSettings = (newSettings: AppSettings) => {
    setSettings(newSettings);
    localStorage.setItem('abundance_settings', JSON.stringify(newSettings));

    if (
      newSettings.soundscapeId !== settings.soundscapeId ||
      newSettings.ambienceVolume !== settings.ambienceVolume
    ) {
      startAmbience(newSettings.soundscapeId, newSettings.ambienceVolume);
    }
  };

  const handleSettingsAudioUpload = (file: File, _category: string) => {
    setUserAudioFile(file);
  };

  // ==============================================
  // Render
  // ==============================================

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-black text-amber-100">
        Preparing your sacred space...
      </div>
    );
  }

  if (!hasInteracted) {
    return (
      <PreSplash
        onContinue={handlePreSplashContinue}
        theme={settings.theme}
      />
    );
  }

  const currentSoundscapeObj =
    availableSoundscapes.find(
      (s) => String(s.id) === String(settings.soundscapeId)
    ) || DEFAULT_SOUNDSCAPES[0];

  const renderContent = () => {
    switch (mode) {
      case AppMode.SPLASH:
        return (
          <SplashScreen
            onComplete={() => {
              console.log('🔊 SplashScreen complete -> WelcomeScreen');
              setMode(AppMode.WELCOME);
            }}
          />
        );

      case AppMode.WELCOME:
        return (
          <WelcomeScreen
            user={user}
            onComplete={(nextMode) => {
              console.log('🔊 WelcomeScreen complete ->', nextMode, '- restarting ambience');
              // Restart ambience when leaving WelcomeScreen
              startAmbience(settings.soundscapeId, settings.ambienceVolume);
              setMode(nextMode);
            }}
          />
        );

      case AppMode.AUTH:
        return (
          <Auth
            onRegister={handleRegister}
            onLogin={handleLogin}
            theme={settings.theme}
            onAudioStart={() => {
              // Ensure audio is playing when Auth loads (safety net)
              startAmbience(settings.soundscapeId, settings.ambienceVolume);
            }}
          />
        );

      case AppMode.PERSONAL_GREETING:
        return user ? (
          <PersonalGreeting
            onComplete={(nickname) => {
              console.log('Personal greeting complete:', nickname);
              // Skip focus flow for now
              setMode(AppMode.DASHBOARD);
              startAmbience(settings.soundscapeId, settings.ambienceVolume);
            }}
