// services/audioService.ts
import { Howl } from 'howler';

const SOUND_URLS: Record<string, string> = {
  // Main background/ambience soundscapes
  OM: '/abundance-alchemy/assets/audio/default/default.mp3',
  default: '/abundance-alchemy/assets/audio/default/default.mp3',

  // Voice/UI sounds
  WELCOME: '/abundance-alchemy/assets/audio/voices/welcome.mp3',

  // Placeholder - use default until you upload specific files
  RAIN: '/abundance-alchemy/assets/audio/default/default.mp3',
  FOREST: '/abundance-alchemy/assets/audio/default/default.mp3',
  CELESTIAL: '/abundance-alchemy/assets/audio/default/default.mp3',
};

let audioContextUnlocked = false;

export const unlockAudio = (): Promise<void> => {
  return new Promise((resolve, reject) => {
    if (audioContextUnlocked) {
      resolve();
      return;
    }

    const silentSound = new Howl({
      src: ['data:audio/wav;base64,UklGRigAAABXQVZFZm10IBIAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA='],
      volume: 0.001,
      onload: () => {
        silentSound.play();
        setTimeout(() => {
          silentSound.stop();
          silentSound.unload();
          audioContextUnlocked = true;
          console.log('✅ Audio context unlocked');
          resolve();
        }, 100);
      },
      onloaderror: (id, error) => {
        console.warn('⚠️ Silent sound load error (may still work):', error);
        audioContextUnlocked = true;
        resolve();
      },
    });
  });
};

let ambienceSound: Howl | null = null;
let sessionSound: Howl | null = null;
let soundEffectsEnabled = true;
let musicEnabled = true;

export const setAudioSettings = (effects: boolean, music: boolean) => {
  soundEffectsEnabled = effects;
  musicEnabled = music;

  if (ambienceSound) {
    ambienceSound.mute(!music);
  }
  if (sessionSound) {
    sessionSound.mute(!music);
  }
};

export const startAmbience = (soundscapeId: string = 'default', volume: number = 50) => {
  if (!musicEnabled) return;

  stopAmbience();

  const soundId = soundscapeId || 'default';
  const url = SOUND_URLS[soundId] || SOUND_URLS.default;

  if (!url) {
    console.warn(`⚠️ No URL for soundscape: ${soundscapeId}`);
    return;
  }

  console.log(`🔊 Starting ambience: ${soundId} -> ${url}`);

  ambienceSound = new Howl({
    src: [url],
    loop: true,
    volume: volume / 100,
    html5: true,
    onplay: () => console.log('🎵 Ambience playing'),
    onloaderror: (id, error) => {
      console.error('❌ Ambience load error:', error, 'URL:', url);
    },
    onplayerror: (id, error) => {
      console.error('❌ Ambience play error:', error);
      unlockAudio().then(() => {
        ambienceSound?.play();
      });
    },
  });

  ambienceSound.play();
};

export const stopAmbience = () => {
  if (ambienceSound) {
    console.log('🔇 Stopping ambience');
    ambienceSound.stop();
    ambienceSound.unload();
    ambienceSound = null;
  }
};

export const startSessionAudio = (url?: string, soundscapeId?: string) => {
  if (!musicEnabled) return;

  stopSessionAudio();

  let finalUrl = url;
  if (!finalUrl && soundscapeId) {
    finalUrl = SOUND_URLS[soundscapeId];
  }

  if (!finalUrl) {
    console.warn('⚠️ No URL provided for session audio');
    return;
  }

  console.log(`🔊 Starting session audio: ${finalUrl}`);

  sessionSound = new Howl({
    src: [finalUrl],
    loop: false,
    volume: 0.8,
    html5: true,
    onend: () => {
      console.log('✅ Session audio ended');
      sessionSound = null;
    },
    onloaderror: (id, error) => {
      console.error('❌ Session audio load error:', error);
    },
  });

  sessionSound.play();
};

export const stopSessionAudio = () => {
  if (sessionSound) {
    console.log('🔇 Stopping session audio');
    sessionSound.stop();
    sessionSound.unload();
    sessionSound = null;
  }
};

export const playWelcomeAudio = () => {
  const url = SOUND_URLS.WELCOME;
  if (!url) {
    console.warn('⚠️ No welcome audio URL configured');
    return;
  }

  console.log('👋 Playing welcome audio');
  startSessionAudio(url, 'WELCOME');
};

export const isAmbiencePlaying = (): boolean => {
  return ambienceSound?.playing() || false;
};

export const isSessionAudioPlaying = (): boolean => {
  return sessionSound?.playing() || false;
};
