// components/WelcomeScreen.tsx - UPDATED FOR AUDIO INTEGRATION
import React, { useEffect, useState } from 'react';
import { AppMode, UserProfile } from '../types';
import { SacredBackground } from './SacredBackground';
import { buttonSoundService } from '../services/buttonSoundService';
import BreathingOrb from './BreathingOrb';

interface WelcomeScreenProps {
  user: UserProfile | null;
  onComplete: (nextMode: AppMode) => void;
  onPlayWelcomeSound?: () => Promise<void>; // Audio trigger from App.tsx
  theme?: 'light' | 'dark';
}

const WELCOME_DURATION_MS = 34000; // 34 seconds

export const WelcomeScreen: React.FC<WelcomeScreenProps> = ({ 
  user, 
  onComplete,
  onPlayWelcomeSound,
  theme = 'dark'
}) => {
  const [progress, setProgress] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);

  useEffect(() => {
    // Start welcome sound when component mounts
    const startWelcomeAudio = async () => {
      if (onPlayWelcomeSound && !hasStarted) {
        try {
          await onPlayWelcomeSound();
          setHasStarted(true);
          setIsPlaying(true);

          // Start progress animation
          const startTime = Date.now();
          const updateProgress = () => {
            const elapsed = Date.now() - startTime;
            const pct = Math.min(100, (elapsed / WELCOME_DURATION_MS) * 100);
            setProgress(pct);

            if (elapsed < WELCOME_DURATION_MS) {
              requestAnimationFrame(updateProgress);
            } else {
              // Audio finished naturally
              setIsPlaying(false);
              setTimeout(() => {
                const nextMode = user ? AppMode.DASHBOARD : AppMode.AUTH;
                onComplete(nextMode);
              }, 500);
            }
          };

          requestAnimationFrame(updateProgress);
        } catch (error) {
          console.error('Failed to play welcome audio:', error);
          // Fallback: proceed without audio
          setIsPlaying(false);
        }
      }
    };

    const timer = setTimeout(startWelcomeAudio, 500);
    return () => clearTimeout(timer);
  }, [onPlayWelcomeSound, hasStarted, user, onComplete]);

  const handleSkip = () => {
    buttonSoundService.play('click');

    setIsPlaying(false);
    setProgress(100);

    // Immediately navigate
    const nextMode = user ? AppMode.DASHBOARD : AppMode.AUTH;
    onComplete(nextMode);
  };

  return (
    <SacredBackground theme={theme} backgroundType="welcome">
      <div className="relative z-10 flex flex-col min-h-screen max-w-md mx-auto px-6 py-10 items-center justify-center">

        {/* Sacred Card Container */}
        <div className="backdrop-blur-xl rounded-2xl border p-8 w-full max-w-xs shadow-2xl bg-gradient-to-b from-slate-800/90 to-slate-900/90 border-amber-500/20">

          {/* Breathing Orb - Centerpiece */}
          <div className="mb-4 flex justify-center">
            <BreathingOrb 
              size={120}
              breathingSpeed={4000}
              glowIntensity={isPlaying ? "high" : "medium"}
            />
          </div>

          {/* Title Section */}
          <div className="text-center space-y-3 mb-8">
            <div className="relative">
              <div className="absolute inset-0 blur-lg opacity-30 bg-gradient-to-r from-amber-500 to-transparent rounded-full" />
              <h1 className="text-2xl font-light tracking-[0.3em] relative z-10 text-amber-400">
                ABUNDANCE ALCHEMY
              </h1>
            </div>
            <div className="h-px w-24 mx-auto bg-gradient-to-r from-transparent via-amber-500/50 to-transparent" />
            <p className="text-sm font-light text-slate-300 italic tracking-wide">
              We Are Honored To Welcome You
            </p>
          </div>

          {/* Prayer Progress Section */}
          <div className="space-y-4 mb-8">
            <div className="text-center">
              <div className="text-[12px] tracking-[0.3em] uppercase text-amber-300/80 mb-2">
                WE ARE PRAYING NOW
              </div>
              <div className="w-full h-2 rounded-full bg-slate-800 overflow-hidden shadow-inner">
                <div
                  className="h-full rounded-full bg-gradient-to-r from-amber-400 via-orange-400 to-amber-500 transition-all duration-300 ease-out shadow-[0_0_10px_rgba(251,191,36,0.3)]"
                  style={{ width: `${progress}%` }}
                />
              </div>
              <div className="flex justify-between text-[10px] text-slate-400 mt-1">
                <span>SACRED BEGINNING</span>
                <span>{Math.round(progress)}%</span>
                <span>HOLY RECEPTION</span>
              </div>
            </div>
          </div>

          {/* Guidance Text */}
          <div className="text-center mb-8">
            <div className="relative inline-block">
              <div className="absolute -inset-1 bg-gradient-to-r from-amber-500/10 to-orange-500/10 blur-sm rounded-lg" />
              <p className="text-sm text-slate-200 leading-relaxed relative z-10 px-4 py-2">
                "Take this sacred moment.{"\n"}
                Allow the prayer to envelop you.{"\n"}
                Your journey begins in holy silence."
              </p>
            </div>
          </div>

          {/* Action Button */}
          <div className="space-y-3">
            <button
              type="button"
              onClick={handleSkip}
              className="group relative w-full px-6 py-3 rounded-xl overflow-hidden transition-all duration-300 hover:scale-[1.02] active:scale-[0.98]"
            >
