const [welcomeSound, setWelcomeSound] = useState<HTMLAudioElement | null>(null);

const playWelcomeSound = async () => {
  try {
    // Stop background music first
    stopAmbience();

    // Play welcome sound
    const audio = new Audio('/abundance-alchemy/assets/audio/voices/welcome.mp3');
