          storedPwd === password;

        if (authData.email !== email) {
          setError('Email not found.');
          setLoading(false);
          return;
        }

        if (!isPasswordMatch) {
          setError('Incorrect password.');
          setLoading(false);
          return;
        }

        await apiService.login(email, password);

        setLoading(false);
        onLogin(authData);
      }
