// components/Auth.tsx - WITH UNIVERSAL FOUNDATION (RED BOX FIXED)
import React, { useState } from 'react';
import { UserAccount } from '../types';
import { Lock, Mail, User, ArrowLeft, Eye, EyeOff } from 'lucide-react';
import { AlchemistAvatar } from './AlchemistAvatar';
import { apiService } from '../services/apiService';
import { SacredBackground } from './SacredBackground';
import BreathingOrb from './BreathingOrb';

interface AuthProps {
  onRegister: (account: UserAccount) => void;
  onLogin: (account: UserAccount) => void;
  onBack?: () => void;
  theme: 'light' | 'dark';
}

// UNIVERSAL TITLE CARD CLASSES (exact match WelcomeScreen)
const titleCardClasses = "backdrop-blur-lg rounded-2xl border p-5 w-full max-w-[280px] shadow-xl bg-gradient-to-b from-slate-800/50 to-slate-900/50 border-white/10";

// UNIVERSAL CONTENT CARD CLASSES
const contentCardClasses = "backdrop-blur-lg rounded-2xl border border-amber-500/20 p-6 w-full max-w-[280px] shadow-2xl space-y-6 bg-slate-900/40";

export const Auth: React.FC<AuthProps> = ({ onRegister, onLogin, onBack, theme }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // ========== EXISTING AUTH LOGIC (UNTOUCHED) ==========
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!email || !password) {
      setError('Please fill in all fields');
      setLoading(false);
      return;
    }

    if (mode === 'register' && !name) {
      setError('Please enter your name');
      setLoading(false);
      return;
    }

    try {
      if (mode === 'register') {
        const existingAuth = localStorage.getItem('abundance_auth');
        if (existingAuth) {
          const existing = JSON.parse(existingAuth);
          if (existing.email === email) {
            setError('Email already registered locally. Please login.');
            setLoading(false);
            return;
          }
        }

        await apiService.register(name, email, password);

        const newAccount: UserAccount = {
          email,
          name,
          password: btoa(password)
        };

        localStorage.setItem('abundance_auth', JSON.stringify(newAccount));
        setLoading(false);
        onRegister(newAccount);

      } else {
        const storedAuth = localStorage.getItem('abundance_auth');

        if (!storedAuth) {
          setError('No account found on this device. Please register.');
          setLoading(false);
          return;
        }

        const authData = JSON.parse(storedAuth);

        const storedPwd = authData.password || authData.passwordHash;
        const isPasswordMatch = 
          storedPwd === btoa(password) || 
          storedPwd === password;

        if (authData.email !== email) {
          setError('Email not found.');
          setLoading(false);
          return;
        }

        if (!isPasswordMatch) {
          setError('Incorrect password.');
          setLoading(false);
          return;
        }

        await apiService.login(email, password);

        setLoading(false);
        onLogin(authData);
      }
    } catch (err: any) {
      console.error(err);
      setError('Authentication failed. Please check your connection.');
      setLoading(false);
    }
  };

  // Theme colors
  const textColor = theme === 'light' ? 'text-slate-900' : 'text-slate-100';
  const subTextColor = theme === 'light' ? 'text-slate-600' : 'text-slate-400';
  const inputBg = theme === 'light' ? 'bg-white border-slate-300' : 'bg-slate-900/50 border-slate-700';

  return (
    <SacredBackground theme={theme} backgroundType="default">
      {/* UNIVERSAL FOUNDATION: Responsive Container */}
      <div className="relative z-10 min-h-screen flex flex-col items-center justify-start md:justify-center p-4 space-y-5 overflow-y-auto">

        {/* UNIVERSAL: Breathing Orb */}
        <div className="mb-1 mt-4 md:mt-0">
          <BreathingOrb size={90} breathingSpeed={4000} />
        </div>

        {/* UNIVERSAL: Title Card */}
        <div className={titleCardClasses}>
          <h1 className="text-lg font-light tracking-[0.2em] text-amber-500 text-center">
            ABUNDANCE ALCHEMY
          </h1>
        </div>

        {/* SCREEN-SPECIFIC: Auth Content Card */}
        <div className={`${contentCardClasses} mt-5`}>

          {/* Logo (Register mode only) */}
          {mode === 'register' && (
            <div className="flex justify-center -mt-2 mb-3">
              <img 
                src="https://abundantthought.com/abundance-alchemy/logo.png" 
                alt="Abundance Alchemy" 
                className="h-12 object-contain drop-shadow-[0_0_15px_rgba(251,191,36,0.3)]"
                onError={(e) => { e.currentTarget.style.display = 'none'; }}
              />
            </div>
          )}

          {/* Alchemist Avatar */}
          <div className="flex justify-center mb-4">
            <AlchemistAvatar size="sm" mood="calm" speaking={false} />
          </div>

          {/* Screen-Specific Title */}
          <div className="text-center space-y-2">
            <h2 className={`text-lg font-bold ${textColor}`}>
              {mode === 'login' ? 'Welcome Back' : 'Namaste Initiate'}
            </h2>

            {mode === 'login' ? (
              <p className={`text-sm ${subTextColor}`}>
                Continue your transformation
              </p>
            ) : (
              <div className="space-y-1">
                <p className={`text-sm font-medium ${textColor}`}>
                  Create Your Account Now
                </p>
                <p className={`text-xs ${subTextColor}`}>
                  Your Practice Awaits
                </p>
              </div>
            )}
          </div>

          {/* Back Button */}
          {onBack && (
            <button
              onClick={onBack}
              className={`absolute top-6 left-6 flex items-center space-x-1 text-xs ${subTextColor} hover:text-amber-400 transition-colors`}
            >
              <ArrowLeft size={14} />
              <span>Back</span>
            </button>
          )}

          {/* Screen-Specific: Auth Form */}
          <form onSubmit={handleSubmit} className="space-y-4 mt-4">
            {mode === 'register' && (
              <div className="space-y-2">
                <label className={`text-xs font-bold ${subTextColor}`}>Name</label>
                <div className="relative">
                  <User size={16} className={`absolute left-3 top-1/2 -translate-y-1/2 ${subTextColor}`} />
                  <input
                    type="text"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder="Your name"
                    className={`w-full pl-9 pr-3 py-2.5 text-sm rounded-xl border focus:ring-2 focus:ring-amber-500 outline-none transition-all ${inputBg} ${textColor}`}
                  />
                </div>
              </div>
            )}

            <div className="space-y-2">
              <label className={`text-xs font-bold ${subTextColor}`}>Email</label>
              <div className="relative">
                <Mail size={16} className={`absolute left-3 top-1/2 -translate-y-1/2 ${subTextColor}`} />
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="your@email.com"
                  className={`w-full pl-9 pr-3 py-2.5 text-sm rounded-xl border focus:ring-2 focus:ring-amber-500 outline-none transition-all ${inputBg} ${textColor}`}
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className={`text-xs font-bold ${subTextColor}`}>Password</label>
              <div className="relative">
                <Lock size={16} className={`absolute left-3 top-1/2 -translate-y-1/2 ${subTextColor}`} />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••"
                  className={`w-full pl-9 pr-10 py-2.5 text-sm rounded-xl border focus:ring-2 focus:ring-amber-500 outline-none transition-all ${inputBg} ${textColor}`}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className={`absolute right-3 top-1/2 -translate-y-1/2 ${subTextColor} hover:text-amber-400`}
                >
                  {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </div>

            {/* FIXED: Error message with sacred aesthetic (no red box) */}
            {error && (
              <div className="backdrop-blur-sm rounded-xl border border-amber-500/30 p-3 text-xs text-amber-400 bg-gradient-to-r from-amber-500/5 to-orange-500/5">
                <div className="flex items-center space-x-2">
                  <div className="h-1.5 w-1.5 rounded-full bg-amber-400 animate-pulse"></div>
                  <span className="font-medium">{error}</span>
                </div>
              </div>
            )}

            {/* UNIVERSAL: Button Style */}
            <button
              type="submit"
              disabled={loading}
              className="w-full px-4 py-2.5 rounded-xl bg-gradient-to-r from-amber-500 to-orange-500 text-black font-medium text-sm tracking-wide hover:opacity-90 transition-opacity shadow-lg disabled:opacity-50 mt-2"
            >
              {loading ? 'Processing...' : mode === 'login' ? 'Sign In' : 'Create Account'}
            </button>
          </form>

          {/* Screen-Specific: Toggle Login/Register */}
          <div className={`text-center text-xs ${subTextColor} pt-3 border-t border-slate-700/30 mt-4`}>
            {mode === 'login' ? "Don't have an account? " : "Already have an account? "}
            <button
              onClick={() => {
                setMode(mode === 'login' ? 'register' : 'login');
                setError('');
                setName('');
                setEmail('');
                setPassword('');
              }}
              className="text-amber-400 hover:text-amber-300 font-bold underline ml-1"
            >
              {mode === 'login' ? 'Sign Up' : 'Sign In'}
            </button>
          </div>

        </div>

        {/* Bottom Spacing for Mobile */}
        <div className="h-8 md:h-4"></div>
