import React, { useEffect, useRef, useState } from 'react';
import { AppMode, UserProfile } from '../types';
import { SacredBackground } from './SacredBackground';
import { buttonSoundService } from '../services/buttonSoundService';
import { startAmbience } from '../services/audioService';
import BreathingOrb from './BreathingOrb';

interface WelcomeScreenProps {
  user: UserProfile | null;
  onComplete: (nextMode: AppMode) => void;
  theme?: 'light' | 'dark';
}

const WELCOME_URL = '/abundance-alchemy/assets/audio/voices/welcome.mp3';
const WELCOME_DURATION_MS = 35000;

// UNIVERSAL TITLE CARD CLASSES
const titleCardClasses = "backdrop-blur-lg rounded-2xl border p-4 md:p-5 w-full max-w-[280px] shadow-xl bg-gradient-to-b from-slate-800/50 to-slate-900/50 border-white/10";

// BODY CARD CLASSES
const bodyCardClasses = "backdrop-blur-md rounded-2xl border border-amber-500/20 p-4 md:p-5 w-full max-w-[280px] shadow-2xl space-y-3 md:space-y-4 bg-slate-900/10";

export const WelcomeScreen: React.FC<WelcomeScreenProps> = ({
  user,
  onComplete,
  theme = 'dark',
}) => {
  const [progress, setProgress] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const [isPlaying, setIsPlaying] = useState(true);

  // ========== EXISTING AUDIO LOGIC ==========
  useEffect(() => {
    const audio = new Audio(WELCOME_URL);
    audioRef.current = audio;

    const timer = setTimeout(() => {
      audio
        .play()
        .catch((err) => {
          console.log('Welcome audio play failed:', err);
          setIsPlaying(false);
        });
    }, 500);

    const start = performance.now();
    const tick = (now: number) => {
      if (!audioRef.current) return;

      const elapsed = now - start;
      const pct = Math.min(100, (elapsed / WELCOME_DURATION_MS) * 100);
      setProgress(pct);

      if (elapsed < WELCOME_DURATION_MS) {
        requestAnimationFrame(tick);
      } else {
        setTimeout(() => {
          const nextMode = user ? AppMode.DASHBOARD : AppMode.AUTH;
          onComplete(nextMode);
          startAmbience(
            '/abundance-alchemy/assets/audio/ambient/default.mp3',
            50
          );
        }, 1500); // Increased pause
      }
    };

    requestAnimationFrame(tick);

    const handleEnded = () => {
      setIsPlaying(false);
      setTimeout(() => {
        const nextMode = user ? AppMode.DASHBOARD : AppMode.AUTH;
        onComplete(nextMode);
        startAmbience(
          '/abundance-alchemy/assets/audio/ambient/default.mp3',
          50
        );
      }, 1500); // Increased pause
    };

    audio.addEventListener('ended', handleEnded);

    return () => {
      clearTimeout(timer);
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current.removeEventListener('ended', handleEnded);
      }
    };
  }, [user, onComplete]);

  const handleSkip = () => {
    console.log('Skip button clicked');
    buttonSoundService.play('click');

    if (audioRef.current && isPlaying) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
      setIsPlaying(false);
    }

    const nextMode = user ? AppMode.DASHBOARD : AppMode.AUTH;
    startAmbience('/abundance-alchemy/assets/audio/ambient/default.mp3', 50);
    onComplete(nextMode);
  };

  return (
    <SacredBackground theme={theme} backgroundType="welcome">
      {/* RESPONSIVE CONTAINER: justify-start on mobile, center on medium+ */}
      <div className="relative z-10 min-h-screen flex flex-col items-center justify-start md:justify-center p-4 space-y-3 md:space-y-6 overflow-y-auto">

        {/* Breathing Orb - 80PX SIZE (LAW OF THE LAND) */}
        <div className="mt-6 md:mt-0 mb-2 md:mb-2">
          <BreathingOrb size={80} breathingSpeed={4000} />
        </div>

        {/* Title Card - "Abundance Alchemy" (not all caps) */}
        <div className={titleCardClasses}>
          <h1 className="text-base md:text-lg font-light tracking-[0.15em] md:tracking-[0.2em] text-amber-500 text-center">
            Abundance Alchemy
          </h1>
        </div>

        {/* Body Card with responsive margin - SMALLER TEXT */}
        <div className={`${bodyCardClasses} mt-3 md:mt-8`}>
          <div className="text-center space-y-2 md:space-y-3">
            <p className="text-sm md:text-base text-slate-200 font-light">
              Let us unite hearts and minds
            </p>
            <div className="space-y-1 md:space-y-1.5 text-slate-300 text-xs md:text-sm">
              <p>Pause A Moment</p>
              <p>Breath in the Divine</p>
              <p>Let go and allow</p>
              <p>Immerse yourself in this sacred invocation.</p>
              <p className="pt-1 text-amber-500 text-xs md:text-sm">Ase.</p>
