// App.tsx - FIXED FLOW
import React, { useState, useEffect } from 'react';
import { AppMode, UserAccount } from './types';
import { SplashScreen } from './components/SplashScreen/SplashScreen';
import { PreSplash } from './components/PreSplash';
import { WelcomeScreen } from './components/WelcomeScreen';
import { SacredNamingCeremony } from './components/SacredNamingCeremony';
import { Auth } from './components/Auth';

function App() {
  const [currentMode, setCurrentMode] = useState<AppMode>(AppMode.SPLASH);
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [user, setUser] = useState<UserAccount | null>(null);
  const [sacredName, setSacredName] = useState<string>('');
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  // Check for existing user session on mount
  useEffect(() => {
    const storedAuth = localStorage.getItem('abundance_auth');
    if (storedAuth) {
      try {
        const userData = JSON.parse(storedAuth);
        setUser(userData);
      } catch (error) {
        console.error('Failed to parse stored auth:', error);
      }
    }
    setIsInitialLoad(false);
  }, []);

  const handleSplashComplete = () => {
    console.log('SplashScreen complete → going to PreSplash');
    setCurrentMode(AppMode.PRE_SPLASH);
  };

  const handlePreSplashComplete = () => {
    console.log('PreSplash complete → going to Welcome');
    setCurrentMode(AppMode.WELCOME);
  };

  const handleWelcomeComplete = (nextMode: AppMode) => {
    console.log('WelcomeScreen complete → going to:', nextMode);
    setCurrentMode(nextMode);
  };

  const handleSacredNamingComplete = (userData: { name: string }) => {
    console.log('SacredNamingCeremony complete → going to Auth');
    setSacredName(userData.name);
    setCurrentMode(AppMode.AUTH);
  };

  const handleAuthRegister = (account: UserAccount) => {
    console.log('Auth register → going to Dashboard');
    setUser(account);
    localStorage.setItem('abundance_auth', JSON.stringify(account));
    setCurrentMode(AppMode.DASHBOARD);
  };

  const handleAuthLogin = (account: UserAccount) => {
    console.log('Auth login → going to Dashboard');
    setUser(account);
    setCurrentMode(AppMode.DASHBOARD);
  };

  // Debug: Log mode changes
  useEffect(() => {
    console.log('Current mode changed to:', currentMode);
  }, [currentMode]);

  // Render current screen based on mode
  const renderScreen = () => {
    // Show loading while checking initial state
    if (isInitialLoad) {
      return (
        <div className="min-h-screen bg-gradient-to-b from-slate-950 to-black flex items-center justify-center">
          <div className="text-amber-500">Loading sacred space...</div>
        </div>
      );
    }

    switch (currentMode) {
      case AppMode.SPLASH:
        return (
          <SplashScreen
            onComplete={handleSplashComplete}
            theme={theme}
          />
        );

      case AppMode.PRE_SPLASH:
        return (
          <PreSplash
            onContinue={handlePreSplashComplete}
            theme={theme}
          />
        );

      case AppMode.WELCOME:
        return (
          <WelcomeScreen
            user={user}
            onComplete={handleWelcomeComplete}
            theme={theme}
          />
        );

      case AppMode.NAMING_CEREMONY:
        return (
          <SacredNamingCeremony
            onComplete={handleSacredNamingComplete}
            theme={theme}
          />
        );

      case AppMode.AUTH:
        return (
          <Auth
            onRegister={handleAuthRegister}
            onLogin={handleAuthLogin}
            initialName={sacredName}
            theme={theme}
          />
        );

      case AppMode.DASHBOARD:
        return (
          <div className="min-h-screen bg-gradient-to-b from-slate-950 to-black text-white flex items-center justify-center">
            <div className="text-center">
              <h1 className="text-2xl mb-4">Dashboard</h1>
              <p className="text-slate-400">Welcome to your sacred space</p>
