                >
                  Reset & Start Over
                </button>
              </div>
            </div>
          </div>
        );

      default:
        return (
          <div className="min-h-screen flex items-center justify-center">
            <p>Screen not found: {currentMode}</p>
            <button
              onClick={() => setCurrentMode(AppMode.SPLASH)}
              className="ml-4 px-4 py-2 bg-amber-500 text-black rounded-lg"
            >
              Restart
            </button>
          </div>
        );
    }
  };

  return (
    <div className="App">
      {renderScreen()}
    </div>
  );
}

export default App;
