import { getSoundscapes, Soundscape } from './services/audioService';

class AudioManager {
  private soundscapes: Soundscape[] = [];
  private currentTrack: HTMLAudioElement | null = null;

  async initialize() {
    try {
      console.log('AudioManager: Fetching soundscapes from API...');
      this.soundscapes = await getSoundscapes();
      console.log(`AudioManager: Loaded ${this.soundscapes.length} soundscapes`);

      // Auto-play default ambience if available
      const defaultAmbience = this.getAmbienceTrack();
      if (defaultAmbience) {
        this.playTrack(defaultAmbience);
      }
    } catch (error) {
      console.error('AudioManager: Failed to initialize:', error);
    }
  }

  getAmbienceTrack(): Soundscape | null {
    const ambienceTracks = this.soundscapes.filter(
      track => track.usage_purpose === 'ambience'
    );
    return ambienceTracks[0] || null;
  }

  getPracticeTrack(practiceType: 'iam' | 'ilove'): Soundscape | null {
    const purpose = practiceType === 'iam' ? 'iam_practice' : 'ilove_practice';
    const practiceTracks = this.soundscapes.filter(
      track => track.usage_purpose === purpose
    );

    // Prefer 1-2 minute tracks for practices
    const practiceLengthTracks = practiceTracks.filter(track =>
      track.duration_seconds && 
      track.duration_seconds >= 55 && 
      track.duration_seconds <= 125
    );

    return practiceLengthTracks[0] || practiceTracks[0] || null;
  }

  playTrack(track: Soundscape) {
    if (!track || !track.audio_url) {
      console.error('AudioManager: No track or audio_url provided');
      return;
    }

    // Stop current track
    if (this.currentTrack) {
      this.currentTrack.pause();
      this.currentTrack = null;
    }

    console.log(`AudioManager: Playing ${track.name} from ${track.audio_url}`);

    // Create and play new audio
    this.currentTrack = new Audio(track.audio_url);

    // Set loop if track is loopable
    if (track.is_loopable) {
      this.currentTrack.loop = true;
    }

    this.currentTrack.play()
      .then(() => console.log(`AudioManager: Now playing ${track.name}`))
      .catch(error => console.error(`AudioManager: Failed to play ${track.name}:`, error));
  }

  stop() {
    if (this.currentTrack) {
      this.currentTrack.pause();
      this.currentTrack = null;
    }
  }

  // Get all tracks for library display
  getAllTracks(): Soundscape[] {
    return this.soundscapes;
  }

  // Get tracks grouped by purpose for UI
  getTracksGroupedByPurpose(): Record<string, Soundscape[]> {
    const groups: Record<string, Soundscape[]> = {};

    this.soundscapes.forEach(track => {
      const purpose = track.usage_purpose;
      if (!groups[purpose]) {
        groups[purpose] = [];
      }
      groups[purpose].push(track);
    });

    return groups;
  }
}

