// Audio Service for Abundance Alchemy
import { apiService } from './apiService';

export interface Soundscape {
  id: string;
  label: string;
  category: string;
  url: string;
  usage_purpose?: string;
  duration_formatted?: string | null;
  bpm?: number | null;
  energy_level?: string;
  is_loopable?: boolean;
  is_public?: boolean;
  is_user_upload?: boolean;
  is_practice_length?: boolean;
}

export interface AudioSettings {
  masterVolume: number;
  backgroundVolume: number;
  effectsVolume: number;
  voiceVolume: number;
  ambientEnabled: boolean;
}

// Default settings
const defaultSettings: AudioSettings = {
  masterVolume: 0.7,
  backgroundVolume: 0.5,
  effectsVolume: 0.8,
  voiceVolume: 1.0,
  ambientEnabled: true,
};

// Get settings from localStorage
const getStoredSettings = (): AudioSettings => {
  try {
    const stored = localStorage.getItem('audioSettings');
    if (stored) {
      return { ...defaultSettings, ...JSON.parse(stored) };
    }
  } catch (e) {
    console.error('Failed to load audio settings:', e);
  }
  return defaultSettings;
};

// Singleton Audio Manager
class AudioManager {
  private settings: AudioSettings = getStoredSettings();
  private backgroundAudio: HTMLAudioElement | null = null;
  private currentSoundscape: Soundscape | null = null;
  private soundscapes: Soundscape[] = [];
  private isInitialized = false;

  constructor() {
    this.loadSoundscapes();
  }

  private async loadSoundscapes() {
    try {
      this.soundscapes = await apiService.getSoundscapes();
      this.isInitialized = true;
      console.log(`AudioManager: Loaded ${this.soundscapes.length} soundscapes`);
    } catch (error) {
      console.error('AudioManager: Failed to load soundscapes:', error);
    }
  }

  // Get audio settings
  getAudioSettings(): AudioSettings {
    return { ...this.settings };
  }

  // Update audio settings
  setAudioSettings(newSettings: Partial<AudioSettings>) {
    this.settings = { ...this.settings, ...newSettings };

    // Apply volume changes immediately
    if (this.backgroundAudio && newSettings.backgroundVolume !== undefined) {
      this.backgroundAudio.volume = this.settings.masterVolume * this.settings.backgroundVolume;
    }

    // Save to localStorage
    try {
      localStorage.setItem('audioSettings', JSON.stringify(this.settings));
    } catch (e) {
      console.error('Failed to save audio settings:', e);
    }
  }

  // Update specific volume
  updateVolume(type: keyof AudioSettings, value: number) {
    this.setAudioSettings({ [type]: value });
  }

  // Start background ambience
  async startAmbience(trackId?: string) {
    if (!this.settings.ambientEnabled) return;

    // Stop current ambience
    this.stopAmbience();

    // Get ambience track
    let track: Soundscape | undefined;

    if (trackId) {
      track = this.soundscapes.find(t => t.id === trackId);
    } else {
      // Get first ambience track
      const ambienceTracks = this.soundscapes.filter(t => 
        t.usage_purpose === 'ambience' || t.category.toLowerCase().includes('ambient')
      );
      track = ambienceTracks[0];
    }

    if (!track || !track.url) {
      console.warn('No ambience track found');
      return;
    }

    this.currentSoundscape = track;

    // Create and play audio
    this.backgroundAudio = new Audio(track.url);
    this.backgroundAudio.loop = track.is_loopable !== false;
    this.backgroundAudio.volume = this.settings.masterVolume * this.settings.backgroundVolume;

    try {
      await this.backgroundAudio.play();
      console.log('Ambience started:', track.label);
    } catch (error) {
      console.error('Failed to play ambience:', error);
    }
  }

  // Stop background ambience
  stopAmbience() {
    if (this.backgroundAudio) {
      this.backgroundAudio.pause();
      this.backgroundAudio = null;
      this.currentSoundscape = null;
    }
  }

  // Preview a soundscape
  async previewSoundscape(track: Soundscape) {
    if (!track.url) return;

    const previewAudio = new Audio(track.url);
    previewAudio.volume = this.settings.masterVolume * this.settings.backgroundVolume;

    try {
      await previewAudio.play();
      // Auto-stop after 10 seconds
      setTimeout(() => {
        if (!previewAudio.paused) previewAudio.pause();
      }, 10000);
    } catch (error) {
      console.error('Failed to preview soundscape:', error);
    }
  }

  // Play a sound effect
  playSoundEffect(url: string) {
    const effect = new Audio(url);
    effect.volume = this.settings.masterVolume * this.settings.effectsVolume;
    effect.play().catch(e => console.error('Failed to play effect:', e));
  }

  // Play completion sound
  playCompletionSound() {
    // You can add a specific completion sound here
    // For now, use a simple beep
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    oscillator.frequency.value = 880;
    oscillator.type = 'sine';

    gainNode.gain.setValueAtTime(0.3 * this.settings.masterVolume, ctx.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

    oscillator.start(ctx.currentTime);
    oscillator.stop(ctx.currentTime + 0.5);
  }

  // Get all soundscapes
  getAllSoundscapes(): Soundscape[] {
    return [...this.soundscapes];
  }

  // Get soundscapes by purpose
  getSoundscapesByPurpose(purpose: string): Soundscape[] {
    return this.soundscapes.filter(t => t.usage_purpose === purpose);
  }

  // Get soundscapes by category
  getSoundscapesByCategory(category: string): Soundscape[] {
    return this.soundscapes.filter(t => t.category === category);
  }

  // Check if initialized
  isReady(): boolean {
    return this.isInitialized;
  }
}

