import { audioManager } from './audioService';

// Button sound URLs - update these to your actual sound files
const BUTTON_SOUNDS = {
  click: './assets/audio/effects/click.mp3',
  confirm: './assets/audio/effects/confirm.mp3',
  back: './assets/audio/effects/back.mp3',
  toggle: './assets/audio/effects/toggle.mp3',
};

// Fallback sounds if files don't exist
const createFallbackSound = (frequency: number, duration: number = 0.1) => {
  try {
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    oscillator.frequency.value = frequency;
    oscillator.type = 'sine';

    gainNode.gain.setValueAtTime(0.2, ctx.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + duration);

    oscillator.start(ctx.currentTime);
    oscillator.stop(ctx.currentTime + duration);
  } catch (error) {
    console.warn('Web Audio API not supported for fallback sounds');
  }
};

export const playButtonSound = (type: keyof typeof BUTTON_SOUNDS = 'click') => {
  try {
    // Try to play the actual sound file
    audioManager.playSoundEffect(BUTTON_SOUNDS[type]);
  } catch (error) {
    console.warn(`Button sound ${type} not available, using fallback`);

    // Fallback frequencies for different button types
    const frequencies = {
      click: 800,
      confirm: 1200,
      back: 600,
      toggle: 1000,
    };

    createFallbackSound(frequencies[type] || 800);
  }
};

