            border: 1px solid var(--color-copper);
            padding: 9px 18px;
            border-radius: 6px;
            font-size: 0.85em;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .btn-secondary:hover {
            background: var(--color-accent);
            color: #000;
            border-color: var(--color-accent-light);
        }

        .btn-remove {
            background: rgba(212, 145, 92, 0.15);
            color: var(--color-copper-light);
            border: 1px solid var(--color-copper);
            padding: 6px 12px;
            border-radius: 4px;
            font-size: 0.85em;
            cursor: pointer;
            transition: all 0.2s;
        }

        .btn-remove:hover {
            background: rgba(212, 145, 92, 0.25);
            color: var(--color-copper-light);
        }

        .hidden {
            display: none !important;
        }

        .memorial-view {
            display: none !important;
        }

        .memorial-view.active {
            display: block !important;
        }

        .memorial-card {
            background: linear-gradient(135deg, var(--color-bg-secondary) 0%, var(--color-bg-secondary) 100%);
            border-radius: 12px;
            padding: 40px 30px;
            box-shadow: var(--shadow-md);
            text-align: center;
            margin-bottom: 30px;
            border: 1px solid var(--color-border);
        }

        .memorial-header {
            margin-bottom: 30px;
        }

        .memorial-name {
            font-size: 1.85em;
            font-weight: 600;
            color: white;
            margin-bottom: 10px;
        }

        .memorial-dates {
            font-size: 1.1em;
            color: var(--color-accent-light);
            font-style: italic;
        }

        .memorial-photo {
            width: 200px;
            height: 200px;
            border-radius: 100%;
            object-fit: cover;
            border: 5px solid var(--color-copper);
            margin: 0 auto 20px;
            display: block;
            box-shadow: 0 0 30px rgba(212, 145, 92, 0.3);
        }

        .memorial-section {
            background: var(--color-bg-secondary);
            border-radius: 12px;
            padding: 25px;
            margin-bottom: 20px;
            border-left: 5px solid var(--color-copper);
            text-align: left;
            border: 1px solid var(--color-border);
        }

        .memorial-section h3 {
            color: white;
            margin-bottom: 15px;
            font-size: 1.1em;
        }

        .timeline-item {
            display: flex;
            margin-bottom: 20px;
            padding-bottom: 20px;
            border-bottom: 1px solid var(--color-border);
        }

        .timeline-item:last-child {
            border-bottom: none;
        }

        .timeline-date {
            min-width: 100px;
            font-weight: 600;
            color: var(--color-accent);
        }

        .timeline-content {
            flex: 1;
            margin-left: 20px;
        }

        .memory-item {
            background: rgba(190, 81, 3, 0.08);
            padding: 15px;
            border-radius: 8px;
            margin-bottom: 12px;
            border-left: 4px solid var(--color-copper);
        }

        .memory-item strong {
            display: block;
            color: var(--color-copper-light);
            margin-bottom: 5px;
        }

        .memory-gallery {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
            gap: 12px;
            margin-top: 15px;
        }

        .gallery-item {
            position: relative;
            overflow: hidden;
            border-radius: 8px;
            box-shadow: var(--shadow-sm);
        }

        .gallery-item img {
            width: 100%;
            height: 150px;
            object-fit: cover;
            transition: transform 0.3s ease;
        }

        .gallery-item:hover img {
            transform: scale(1.05);
        }

        .voice-messages {
            margin-top: 15px;
        }

        .voice-item {
            background: rgba(190, 81, 3, 0.08);
            padding: 12px;
            border-radius: 6px;
            margin-bottom: 10px;
            display: flex;
            align-items: center;
            gap: 10px;
            border: 1px solid var(--color-border);
        }

        .voice-item audio {
            flex: 1;
            height: 30px;
        }

        .empty-state {
            text-align: center;
            padding: 40px 20px;
            color: var(--color-text-secondary);
        }

        .music-library-section {
            background: var(--color-bg-secondary);
            border-radius: 12px;
            padding: 30px;
            margin-bottom: 24px;
            box-shadow: var(--shadow-md);
            border-left: 5px solid var(--color-copper);
            border: 1px solid var(--color-border);
        }

        .music-library-section h2 {
            font-size: 1.2em;
            margin-bottom: 20px;
            color: white;
        }

        .music-item {
            background: rgba(190, 81, 3, 0.08);
            padding: 15px;
            border-radius: 8px;
            margin-bottom: 12px;
            border-left: 4px solid var(--color-copper);
            border: 1px solid var(--color-border);
        }

        .music-item strong {
            display: block;
            color: var(--color-copper-light);
            margin-bottom: 8px;
        }

        .music-item p {
            color: var(--color-text-secondary);
            font-size: 0.95em;
            margin: 5px 0;
        }

        .music-player {
            margin-top: 10px;
            width: 100%;
        }

        .music-display {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 15px;
            margin-top: 20px;
        }

        .music-card {
            background: rgba(190, 81, 3, 0.12);
            padding: 15px;
            border-radius: 8px;
            border: 1px solid var(--color-border);
            text-align: center;
        }

        .music-card-title {
            color: var(--color-copper-light);
            font-weight: 600;
            margin-bottom: 8px;
        }

        .music-card-artist {
            color: var(--color-text-secondary);
            font-size: 0.9em;
            margin-bottom: 10px;
        }

        .music-card audio {
            width: 100%;
            height: 30px;
            margin-top: 8px;
        }

        .empty-state p {
            font-size: 1.1em;
            margin-bottom: 20px;
        }

        .input-list {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .input-row {
            display: flex;
            gap: 10px;
            align-items: flex-end;
        }

        .input-row input {
            flex: 1;
        }

        .input-row textarea {
            flex: 1;
        }

        .contact-info-display {
            background: rgba(190, 81, 3, 0.08);
            padding: 20px;
            border-radius: 8px;
            margin-bottom: 20px;
            border: 1px solid var(--color-border);
        }

        .contact-info-display p {
            margin-bottom: 8px;
            display: flex;
            align-items: center;
            gap: 10px;
            color: var(--color-text-primary);
        }

        .contact-info-display strong {
            color: var(--color-copper-light);
            min-width: 120px;
        }

        @media (max-width: 768px) {
            header h1 {
                font-size: 1.4em;
            }

            .memorial-name {
                font-size: 1.5em;
            }

            .form-section,
            .memorial-card {
                padding: 20px;
            }

            .view-toggle {
                flex-wrap: wrap;
            }

            .memory-gallery {
                grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1><span class="emoji-glow">✨</span> Contact Memorial</h1>
            <p>Preserving and honoring the memory of someone special</p>
            <p class="privacy-note">This memorializes the contact information of someone we love who has gone to walk with the Ancestors. It only keeps information on your device. It does not and will never store it in any online database.</p>
        </header>

        <div class="view-toggle">
            <button class="btn active" onclick="toggleView('home')">Home</button>
            <button class="btn" onclick="toggleView('form')">Create Memorial</button>
            <button class="btn" onclick="toggleView('memorial')">View Memorial</button>
        </div>

        <!-- HOME VIEW -->
        <div id="home-view" class="home-view active">
            <div class="home-content">
                <img src="http://abundantthought.com/contactmemorial/images/memorial_1.png" alt="Memorial" class="home-image">

                <div class="home-section home-section-compact">
                    <p>This memorial space is for you to honor those who have gone to walk with the ancestors. It is a sacred digital sanctuary for you to preserve contact information, share memories, capture voices, even journal ongoing conversations between you and them—all in celebration of the lives of those you love.</p>
                </div>

                <div class="home-section home-section-compact">
                    <p>All information you add to this memorial stays on your device only. Nothing is ever uploaded to any online database or server. This is your private space to remember and honor your loved ones.</p>
                </div>

                <div style="text-align: center; margin-top: 40px;">
                    <button class="btn-primary" onclick="toggleView('form')" style="margin-right: 12px;">✨ Create a Memorial</button>
                    <button class="btn-secondary" onclick="toggleView('memorial')">View Existing Memorial</button>
                </div>
            </div>
        </div>

        <!-- FOOTER -->
        <div class="footer-credit">
            <p>This app is created under the <a href="http://abundantthought.com" target="_blank">abundantthought.com</a> umbrella for public use free of charge by <strong>Michael Soaries</strong> and <strong>Perplexity AI</strong>.</p>
            <p>© 2026 Michael Soaries. All Rights Reserved.</p>
        </div>

        <!-- FORM VIEW -->
        <div id="form-view" style="display: none !important;">
            <div class="form-section">
                <h2>Contact Information</h2>
                <div class="form-group">
                    <label>Full Name *</label>
                    <input type="text" id="memorialName" placeholder="Enter their name" required>
                </div>
                <div class="form-group">
                    <label>Email (Optional)</label>
                    <input type="email" id="memorialEmail" placeholder="email@example.com">
                </div>
                <div class="form-group">
                    <label>Phone (Optional)</label>
                    <input type="tel" id="memorialPhone" placeholder="+1 (555) 000-0000">
                </div>
                <div class="form-group">
                    <label>Birth Date (Optional)</label>
                    <input type="date" id="memorialBirthDate">
                </div>
                <div class="form-group">
                    <label>Passing Date (Optional)</label>
                    <input type="date" id="memorialPassingDate">
                </div>
                <div class="form-group">
                    <label>Profile Photo (Optional)</label>
                    <div style="display: flex; gap: 12px; margin-bottom: 12px;">
                        <button type="button" class="btn-secondary" onclick="document.getElementById('mainPhotoUpload').click()" style="flex: 1;">📱 Upload from Phone</button>
                        <button type="button" class="btn-secondary" onclick="togglePhotoUrlInput()" style="flex: 1;">🔗 Use URL</button>
                    </div>
                    <input type="file" id="mainPhotoUpload" accept="image/*" style="display: none;" onchange="handleMainPhotoUpload(event)">
                    <input type="text" id="memorialPhotoUrl" placeholder="https://example.com/photo.jpg" style="display: none;">
                    <div id="mainPhotoPreview" style="margin-top: 12px;"></div>
                </div>
            </div>

            <div class="form-section">
                <h2>📸 Photo Gallery</h2>
                <p style="color: var(--color-text-secondary); margin-bottom: 15px;">Add up to 20 photos</p>
                <div style="margin-bottom: 15px;">
                    <button type="button" class="btn-secondary" onclick="document.getElementById('galleryPhotosUpload').click()" style="width: 100%;">📱 Upload Photos from Phone</button>
                    <input type="file" id="galleryPhotosUpload" accept="image/*" multiple style="display: none;" onchange="handleGalleryUpload(event)">
                </div>
                <p style="color: var(--color-text-secondary); margin-bottom: 10px; text-align: center;">— OR —</p>
                <div class="form-group">
                    <textarea id="photoUrls" placeholder="https://example.com/photo1.jpg&#10;https://example.com/photo2.jpg" oninput="updatePhotoCount()"></textarea>
                </div>
                <div id="galleryPhotoCount" style="color: var(--color-text-secondary); font-size: 0.85em; margin-top: 8px;"></div>
                <div id="galleryPreview" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(100px, 1fr)); gap: 10px; margin-top: 15px;"></div>
            </div>

            <div class="form-section">
                <h2>📖 Memories & Stories</h2>
                <div id="memoriesList" class="input-list"></div>
                <button class="btn-secondary" onclick="addMemory()">+ Add Memory</button>
            </div>

            <div class="form-section">
                <h2>📅 Important Dates & Events</h2>
                <div id="datesList" class="input-list"></div>
                <button class="btn-secondary" onclick="addDate()">+ Add Date</button>
            </div>

            <div class="form-section">
                <h2>🎙️ Voice Messages</h2>
                <p style="color: var(--color-text-secondary); margin-bottom: 15px;">Upload audio or add audio URLs</p>
                <div style="margin-bottom: 15px;">
                    <button type="button" class="btn-secondary" onclick="addVoiceMessageUpload()" style="width: 100%;">🎤 Add Audio File</button>
                </div>
                <div id="voiceList" class="input-list"></div>
                <button class="btn-secondary" onclick="addVoiceMessageUrl()">+ Add Audio URL</button>
            </div>

            <div class="music-library-section">
                <h2>🎵 Music Library</h2>
                <div style="margin-bottom: 15px;">
                    <button type="button" class="btn-secondary" onclick="addMusicTrack()" style="width: 100%;">🎶 Add Song</button>
                </div>
                <div id="musicList" class="input-list"></div>
                <p style="color: var(--color-text-secondary); margin-bottom: 0; margin-top: 15px; font-size: 0.85em;">Add meaningful songs or music selections to their memorial. This information is stored only on your device and never in any online database.</p>
            </div>

            <div class="form-section">
                <h2>💝 Personal Note</h2>
                <div class="form-group">
                    <textarea id="personalNote" placeholder="Write a heartfelt tribute or personal message..."></textarea>
                </div>
            </div>

            <div style="text-align: center; margin-top: 30px;">
                <button class="btn-primary" onclick="saveMemorial()">Save Memorial</button>
            </div>
        </div>

        <!-- MEMORIAL VIEW -->
        <div id="memorial-view" class="memorial-view">
            <div id="memorialContent"></div>
            <div style="text-align: center; margin-top: 30px;">
                <button class="btn-primary" onclick="toggleView('form')">Edit Memorial</button>
                <button class="btn-secondary" onclick="downloadMemorial()" style="margin-left: 12px;">Download Memorial</button>
                <button class="btn-secondary" onclick="toggleView('home')" style="margin-left: 12px;">Return Home</button>
            </div>
        </div>
    </div>

    <script>
        let memorialData = {
            galleryPhotos: [],
            voiceFiles: [],
            musicTracks: []
        };

        function togglePhotoUrlInput() {
            const urlInput = document.getElementById('memorialPhotoUrl');
            const uploadBtn = event.target;
            urlInput.style.display = urlInput.style.display === 'none' ? 'block' : 'none';
            if (urlInput.style.display === 'block') {
                uploadBtn.textContent = '📱 Upload from Phone';
                uploadBtn.onclick = () => document.getElementById('mainPhotoUpload').click();
            }
        }

        function handleMainPhotoUpload(event) {
            const file = event.target.files[0];
            if (file) {
                alert(`Selected: ${file.name}\n\nTo save storage space, upload this photo to:\n• Imgur.com\n• Google Photos\n• Dropbox\n\nThen paste the image URL in the "Use URL" field below.`);
            }
        }

        function handleGalleryUpload(event) {
            const files = event.target.files;
            if (!files || files.length === 0) return;

            const textarea = document.getElementById('photoUrls');
            const currentUrls = textarea.value.split('\n').filter(url => url.trim());
            const MAX_PHOTOS = 20;
            const remainingSpace = MAX_PHOTOS - currentUrls.length;

            if (remainingSpace <= 0) {
                alert('You\'ve reached the maximum of 20 photos. Remove some photos before adding more.');
                return;
            }

            const filesToProcess = Math.min(files.length, remainingSpace);
            const fileNames = Array.from(files).slice(0, filesToProcess).map(f => f.name).join(', ');
            alert(`✓ Files selected: ${fileNames}\n\nNote: To save storage space, images are stored as URLs only.\n\nAfter uploading photos to a free service like:\n• Imgur.com\n• Google Photos\n• Dropbox\n\nPaste the image URLs in the text box below.\n\nYou have space for ${remainingSpace} more photo${remainingSpace !== 1 ? 's' : ''}.`);

            // Reset file input to prevent issues on repeated uploads
            event.target.value = '';
        }

        // Gallery photo removal is now handled by textarea
        function removeGalleryPhoto(index) {
            // No longer needed - users edit URLs directly in textarea
        }

        function addVoiceMessageUpload() {
            const list = document.getElementById('voiceList');
            const id = 'voice-' + Date.now();
            const item = document.createElement('div');
            item.className = 'input-row';
            item.id = id;
            item.style.flexDirection = 'column';
            item.style.alignItems = 'stretch';
            item.innerHTML = `
                <div style="margin-bottom: 8px;">
                    <button type="button" class="btn-secondary" onclick="document.getElementById('voiceFile-${id}').click()" style="width: 100%;">📤 Choose Audio File</button>
                    <input type="file" id="voiceFile-${id}" accept="audio/*" style="display: none;" onchange="handleVoiceUpload(event, '${id}')">
                </div>
                <input type="text" class="voice-label" placeholder="Label (e.g., Mom's voice message)">
                <div id="voicePreview-${id}" style="margin-top: 8px; padding: 8px; background: var(--color-bg-secondary); border-radius: 6px; display: none;"></div>
                <button type="button" class="btn-remove" onclick="document.getElementById('${id}').remove()" style="margin-top: 8px;">Remove</button>
            `;
            list.appendChild(item);
        }

        function handleVoiceUpload(event, id) {
            const file = event.target.files[0];
            if (file) {
                const reader = new FileReader();
                reader.onload = function(e) {
                    const preview = document.getElementById(`voicePreview-${id}`);
                    preview.style.display = 'block';
                    preview.innerHTML = `
                        <strong>${file.name}</strong>
                        <audio controls style="width: 100%; margin-top: 8px; height: 30px;">
                            <source src="${e.target.result}">
                        </audio>
                    `;
                    const row = document.getElementById(id);
                    row.dataset.voiceData = e.target.result;
                    row.dataset.isFile = 'true';
                };
                reader.readAsDataURL(file);
            }
        }

        function addVoiceMessageUrl() {
            const list = document.getElementById('voiceList');
            const id = 'voice-' + Date.now();
            const item = document.createElement('div');
            item.className = 'input-row';
            item.id = id;
            item.dataset.isFile = 'false';
            item.innerHTML = `
                <input type="text" class="voice-url" placeholder="Audio URL">
                <input type="text" class="voice-label" placeholder="Label (e.g., Mom reading my favorite poem)">
                <button type="button" class="btn-remove" onclick="document.getElementById('${id}').remove()">Remove</button>
            `;
            list.appendChild(item);
        }

        function addMusicTrack() {
            const list = document.getElementById('musicList');
            const id = 'music-' + Date.now();
            const item = document.createElement('div');
            item.className = 'input-row';
            item.id = id;
            item.innerHTML = `
                <input type="text" class="music-title" placeholder="Song Title *" required>
                <input type="text" class="music-artist" placeholder="Artist Name">
                <input type="text" class="music-url" placeholder="Audio URL or Spotify/YouTube link">
                <input type="text" class="music-note" placeholder="Why this song? (optional)">
                <button class="btn-remove" onclick="document.getElementById('${id}').remove()">Remove</button>
            `;
            list.appendChild(item);
        }

        function toggleView(view) {
            const homeView = document.getElementById('home-view');
            const formView = document.getElementById('form-view');
            const memorialView = document.getElementById('memorial-view');
            const buttons = document.querySelectorAll('.view-toggle .btn');

            buttons.forEach(btn => btn.classList.remove('active'));
            homeView.classList.remove('active');
            formView.style.display = 'none';
            memorialView.classList.remove('active');

            if (view === 'home') {
                homeView.classList.add('active');
                buttons[0].classList.add('active');
            } else if (view === 'form') {
                formView.style.display = 'block';
                buttons[1].classList.add('active');
                loadFormData();
            } else if (view === 'memorial') {
                memorialView.classList.add('active');
                buttons[2].classList.add('active');
                displayMemorial();
            }
        }

        function addMemory() {
            const list = document.getElementById('memoriesList');
            const id = 'memory-' + Date.now();
            const item = document.createElement('div');
            item.className = 'input-row';
            item.id = id;
            item.innerHTML = `
                <input type="text" class="memory-title" placeholder="Memory title (e.g., First time we met)">
                <textarea class="memory-content" placeholder="Tell the story..."></textarea>
                <button class="btn-remove" onclick="document.getElementById('${id}').remove()">Remove</button>
            `;
            list.appendChild(item);
        }

        function addDate() {
            const list = document.getElementById('datesList');
            const id = 'date-' + Date.now();
            const item = document.createElement('div');
            item.className = 'input-row';
            item.id = id;
            item.innerHTML = `
                <input type="date" class="date-value">
                <input type="text" class="date-description" placeholder="Event (e.g., Birthday, Anniversary)">
                <button class="btn-remove" onclick="document.getElementById('${id}').remove()">Remove</button>
            `;
            list.appendChild(item);
        }

        function addVoiceMessage() {
            const list = document.getElementById('voiceList');
            const id = 'voice-' + Date.now();
            const item = document.createElement('div');
            item.className = 'input-row';
            item.id = id;
            item.innerHTML = `
                <input type="text" class="voice-url" placeholder="Audio URL or paste audio data">
                <input type="text" class="voice-label" placeholder="Label (e.g., Mom reading my favorite poem)">
                <button class="btn-remove" onclick="document.getElementById('${id}').remove()">Remove</button>
            `;
            list.appendChild(item);
        }

        function saveMemorial() {
            const name = document.getElementById('memorialName').value;
            if (!name.trim()) {
                alert('Please enter a name for the memorial.');
                return;
            }

            memorialData.name = name;
            memorialData.email = document.getElementById('memorialEmail').value;
            memorialData.phone = document.getElementById('memorialPhone').value;
            memorialData.birthDate = document.getElementById('memorialBirthDate').value;
            memorialData.passingDate = document.getElementById('memorialPassingDate').value;
            memorialData.mainPhotoUrl = document.getElementById('memorialPhotoUrl').value;
            memorialData.personalNote = document.getElementById('personalNote').value;
            memorialData.memories = [];
            memorialData.dates = [];
            memorialData.voices = [];

            // Store photo URLs only (not base64 data) - saves storage space
            const photoUrlsText = document.getElementById('photoUrls').value.split('\n').filter(url => url.trim());
            memorialData.photoUrls = photoUrlsText;
            memorialData.galleryPhotos = []; // Don't store base64 images
            memorialData.mainPhotoData = null; // Don't store base64 profile photo

            document.querySelectorAll('.memory-title').forEach((el, i) => {
                const title = el.value;
                const content = el.parentElement.querySelector('.memory-content').value;
                if (title.trim() || content.trim()) {
                    memorialData.memories.push({ title, content });
                }
            });

            document.querySelectorAll('.date-value').forEach((el, i) => {
                const date = el.value;
                const desc = el.parentElement.querySelector('.date-description').value;
                if (date || desc.trim()) {
                    memorialData.dates.push({ date, description: desc });
                }
            });

            document.querySelectorAll('#voiceList > .input-row').forEach((row) => {
                const isFile = row.dataset.isFile === 'true';
                const label = row.querySelector('.voice-label').value;

                if (isFile && row.dataset.voiceData) {
                    memorialData.voices.push({ 
                        data: row.dataset.voiceData, 
                        label: label || 'Voice message',
                        isFile: true
                    });
                } else if (!isFile) {
                    const url = row.querySelector('.voice-url').value;
                    if (url.trim()) {
                        memorialData.voices.push({ 
                            url, 
                            label: label || 'Voice message',
                            isFile: false
                        });
                    }
                }
            });

            try {
                localStorage.setItem('memorialData', JSON.stringify(memorialData));
                console.log('✓ Memorial saved successfully to localStorage');
