function validateAndCleanData(data) {
    // Clean URLs
    if (data.photoUrls) {
        data.photoUrls = data.photoUrls
            .map(url => url.trim())
            .filter(url => {
                // Basic URL validation
                return url && (url.startsWith('http://') || url.startsWith('https://'));
            })
            .slice(0, 20); // Enforce limit
    }

    // Estimate storage size
    const jsonString = JSON.stringify(data);
    const sizeInMB = (new Blob([jsonString]).size / 1024 / 1024).toFixed(2);

    if (sizeInMB > 5) {
        alert(`⚠️ Warning: Memorial data is ${sizeInMB}MB\n\nTo prevent crashes:\n1. Use image URLs instead of uploading\n2. Use audio URLs instead of files\n3. Reduce number of photos`);
        return false;
    }

    return true;
}

