            margin-bottom: 20px;
            cursor: pointer;
            transition: all 0.3s ease;
            border: 1px solid var(--color-border);
            position: relative;
            overflow: hidden;
        }

        .memorial-card:hover {
            transform: translateY(-2px);
            box-shadow: var(--shadow-md);
            border-color: var(--color-accent);
        }

        .memorial-card.active {
            border-left: 5px solid var(--color-accent);
            background: var(--color-bg-tertiary);
        }

        .memorial-card.active::before {
            content: '🕯️';
            position: absolute;
            right: 20px;
            top: 50%;
            transform: translateY(-50%);
            font-size: 1.5em;
            opacity: 0.7;
        }

        .memorial-name {
            font-size: 1.4em;
            font-weight: 500;
            color: white;
            margin-bottom: 8px;
        }

        .memorial-dates {
            font-size: 0.9em;
            color: var(--color-text-secondary);
            margin-bottom: 15px;
        }

        .memorial-stats {
            display: flex;
            gap: 15px;
            font-size: 0.85em;
            color: var(--color-text-muted);
        }

        .stat-item {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .action-buttons {
            display: flex;
            gap: 10px;
            margin-top: 20px;
            flex-wrap: wrap;
        }

        .btn {
            padding: 12px 24px;
            border: none;
            border-radius: var(--radius-sm);
            font-family: inherit;
            font-size: 0.95em;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s ease;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            min-width: 120px;
        }

        .btn-primary {
            background: linear-gradient(135deg, var(--color-accent) 0%, var(--color-accent-light) 100%);
            color: white;
            border: 1px solid var(--color-accent);
            flex: 1;
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 4px 12px rgba(190, 81, 3, 0.3);
        }

        .btn-secondary {
            background: var(--color-bg-tertiary);
            color: var(--color-text-primary);
            border: 1px solid var(--color-border);
            flex: 1;
        }

        .btn-secondary:hover {
            background: var(--color-bg-secondary);
            border-color: var(--color-accent-light);
        }

        .btn-ritual {
            background: linear-gradient(135deg, #4a6fa5 0%, #6b93d6 100%);
            color: white;
            border: 1px solid #4a6fa5;
        }

        .btn-icon {
            width: 44px;
            height: 44px;
            border-radius: 50%;
            padding: 0;
            min-width: auto;
            font-size: 1.2em;
        }

        /* Form Elements */
        .form-section {
            background: var(--color-bg-secondary);
            border-radius: var(--radius-md);
            padding: 25px;
            margin-bottom: 20px;
            border: 1px solid var(--color-border);
        }

        .form-title {
            font-size: 1.2em;
            color: white;
            margin-bottom: 20px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-label {
            display: block;
            margin-bottom: 8px;
            color: var(--color-text-secondary);
            font-size: 0.95em;
            font-weight: 500;
        }

        .form-input {
            width: 100%;
            padding: 14px;
            background: var(--color-bg-primary);
            border: 1px solid var(--color-border);
            border-radius: var(--radius-sm);
            color: var(--color-text-primary);
            font-family: inherit;
            font-size: 1em;
            transition: border-color 0.2s;
        }

        .form-input:focus {
            outline: none;
            border-color: var(--color-accent);
            box-shadow: 0 0 0 3px rgba(190, 81, 3, 0.1);
        }

        .form-textarea {
            min-height: 120px;
            resize: vertical;
            line-height: 1.5;
        }

        /* Photo Options */
        .photo-options {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 15px;
            margin-top: 20px;
        }

        .photo-option {
            background: var(--color-bg-tertiary);
            border-radius: var(--radius-sm);
            padding: 20px;
            border: 2px solid transparent;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .photo-option.selected {
            border-color: var(--color-accent);
            background: rgba(190, 81, 3, 0.05);
        }

        .photo-option:hover {
            transform: translateY(-2px);
        }

        .option-icon {
            font-size: 1.8em;
            margin-bottom: 10px;
        }

        .option-title {
            font-size: 1.1em;
            color: white;
            margin-bottom: 8px;
        }

        .option-desc {
            font-size: 0.9em;
            color: var(--color-text-secondary);
            line-height: 1.5;
        }

        /* Photo Upload Area */
        .photo-upload-area {
            border: 2px dashed var(--color-border);
            border-radius: var(--radius-md);
            padding: 40px 20px;
            text-align: center;
            cursor: pointer;
            transition: all 0.3s ease;
            margin-top: 20px;
        }

        .photo-upload-area:hover {
            border-color: var(--color-accent);
            background: rgba(190, 81, 3, 0.02);
        }

        .upload-icon {
            font-size: 2.5em;
            margin-bottom: 15px;
            opacity: 0.7;
        }

        .upload-text {
            color: var(--color-text-secondary);
            margin-bottom: 10px;
        }

        .upload-hint {
            font-size: 0.85em;
            color: var(--color-text-muted);
        }

        /* Photo Preview */
        .photo-preview-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
            gap: 10px;
            margin-top: 20px;
        }

        .photo-preview {
            position: relative;
            border-radius: var(--radius-sm);
            overflow: hidden;
            aspect-ratio: 1;
        }

        .photo-preview img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .photo-remove {
            position: absolute;
            top: 5px;
            right: 5px;
            background: rgba(0, 0, 0, 0.7);
            color: white;
            border: none;
            border-radius: 50%;
            width: 24px;
            height: 24px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.8em;
        }

        /* Memorial View */
        .memorial-header {
            background: linear-gradient(135deg, var(--color-bg-tertiary) 0%, var(--color-bg-secondary) 100%);
            border-radius: var(--radius-md);
            padding: 30px;
            margin-bottom: 30px;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .memorial-header::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 4px;
            background: linear-gradient(90deg, var(--color-accent) 0%, var(--color-accent-light) 100%);
        }

        .profile-photo {
            width: 150px;
            height: 150px;
            border-radius: 50%;
            object-fit: cover;
            margin: 0 auto 20px;
            border: 5px solid rgba(190, 81, 3, 0.3);
            box-shadow: var(--shadow-md);
        }

        .memorial-display-name {
            font-size: 1.8em;
            font-weight: 400;
            color: white;
            margin-bottom: 10px;
        }

        /* Ritual Mode */
        .ritual-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(10, 12, 8, 0.95);
            z-index: 1000;
            display: none;
            animation: fade-in 0.3s ease-out;
        }

        .ritual-overlay.active {
            display: block;
        }

        .ritual-container {
            max-width: 600px;
            margin: 0 auto;
            padding: 30px;
            height: 100%;
            display: flex;
            flex-direction: column;
        }

        .ritual-header {
            text-align: center;
            margin-bottom: 30px;
        }

        .ritual-candle {
            font-size: 3em;
            animation: candle-flicker 2s infinite ease-in-out;
            margin-bottom: 20px;
        }

        .ritual-prompt {
            font-size: 1.2em;
            color: white;
            line-height: 1.6;
            margin-bottom: 30px;
            text-align: center;
            min-height: 100px;
        }

        .ritual-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 30px;
        }

        .ritual-photo {
            max-width: 300px;
            max-height: 300px;
            border-radius: var(--radius-md);
            object-fit: cover;
            box-shadow: var(--shadow-lg);
        }

        .ritual-memory {
            background: rgba(255, 255, 255, 0.05);
            border-radius: var(--radius-md);
            padding: 25px;
            border-left: 4px solid var(--color-accent);
            max-width: 500px;
        }

        .ritual-controls {
            display: flex;
            gap: 15px;
            margin-top: 30px;
            justify-content: center;
            flex-wrap: wrap;
        }

        .ritual-timer {
            font-size: 3em;
            font-weight: 300;
            color: var(--color-accent-light);
            margin: 20px 0;
            font-variant-numeric: tabular-nums;
        }

        /* Soundscapes */
        .soundscape-controls {
            position: fixed;
            bottom: 20px;
            right: 20px;
            background: var(--color-bg-tertiary);
            border-radius: var(--radius-lg);
            padding: 15px;
            display: flex;
            flex-direction: column;
            gap: 10px;
            z-index: 100;
            border: 1px solid var(--color-border);
            box-shadow: var(--shadow-md);
        }

        .soundscape-btn {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            background: var(--color-bg-secondary);
            border: 1px solid var(--color-border);
            color: white;
            font-size: 1.2em;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s ease;
        }

        .soundscape-btn:hover {
            background: var(--color-accent);
            transform: scale(1.1);
        }

        .soundscape-btn.active {
            background: var(--color-accent);
            box-shadow: 0 0 20px rgba(190, 81, 3, 0.3);
        }

        /* Music Guidance */
        .music-guidance {
            background: linear-gradient(135deg, rgba(74, 111, 165, 0.1) 0%, rgba(107, 147, 214, 0.1) 100%);
            border-radius: var(--radius-md);
            padding: 25px;
            border: 1px solid rgba(74, 111, 165, 0.3);
            margin-bottom: 20px;
        }

        .music-guidance-title {
            color: #6b93d6;
            font-size: 1.1em;
            margin-bottom: 15px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        /* Backup Section */
        .backup-section {
            background: var(--color-bg-secondary);
            border-radius: var(--radius-md);
            padding: 25px;
            margin-top: 40px;
            border: 1px solid var(--color-border);
        }

        .backup-options {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 15px;
            margin-top: 20px;
        }

        .backup-option {
            background: var(--color-bg-tertiary);
            border-radius: var(--radius-sm);
            padding: 20px;
            text-align: center;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .backup-option:hover {
            background: var(--color-bg-secondary);
            transform: translateY(-2px);
        }

        /* Empty States */
        .empty-state {
            text-align: center;
            padding: 60px 20px;
            color: var(--color-text-secondary);
        }

        .empty-icon {
            font-size: 3em;
            margin-bottom: 20px;
            opacity: 0.5;
        }

        /* Navigation */
        .nav-bar {
            position: fixed;
            bottom: 0;
            left: 0;
            right: 0;
            background: var(--color-bg-tertiary);
            border-top: 1px solid var(--color-border);
            padding: 10px 20px;
            display: flex;
            justify-content: space-around;
            z-index: 100;
        }

        .nav-btn {
            background: none;
            border: none;
            color: var(--color-text-secondary);
            padding: 10px;
            font-size: 0.9em;
            cursor: pointer;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 5px;
            transition: all 0.2s ease;
            min-width: 70px;
        }

        .nav-btn.active {
            color: var(--color-accent-light);
        }

        .nav-btn:hover {
            color: white;
            transform: translateY(-2px);
        }

        .nav-icon {
            font-size: 1.2em;
        }

        /* Toast Notifications */
        .toast {
            position: fixed;
            bottom: 80px;
            left: 50%;
            transform: translateX(-50%) translateY(100px);
            background: var(--color-bg-tertiary);
            color: white;
            padding: 15px 25px;
            border-radius: var(--radius-md);
            box-shadow: var(--shadow-lg);
            z-index: 1000;
            display: flex;
            align-items: center;
            gap: 10px;
            border-left: 4px solid var(--color-accent);
            transition: transform 0.3s ease;
            max-width: 90%;
        }

        .toast.show {
            transform: translateX(-50%) translateY(0);
        }

        /* Responsive */
        @media (max-width: 768px) {
            .app-container {
                padding: 15px;
                padding-bottom: 80px; /* Space for nav bar */
            }

            .photo-options {
                grid-template-columns: 1fr;
            }

            .action-buttons {
                flex-direction: column;
            }

            .btn {
                width: 100%;
            }

            .install-steps {
                flex-direction: column;
            }
        }

        @media (max-width: 480px) {
            .app-header {
                padding: 20px 10px;
            }

            .form-section {
                padding: 20px 15px;
            }

            .memorial-card {
                padding: 20px;
            }
        }
    </style>
</head>
<body>
    <div class="app-container">
        <!-- Install Prompt -->
        <div id="installPrompt" class="install-prompt">
            <h3>📱 Install Sacred Spaces</h3>
            <p>For the best experience, install this app to your home screen. Your memorials will be safe and accessible anytime.</p>
            <div class="install-steps">
                <div class="install-step">
                    <div class="install-step-number">1</div>
                    <div>Tap Share button</div>
                </div>
                <div class="install-step">
                    <div class="install-step-number">2</div>
                    <div>Find "Add to Home Screen"</div>
                </div>
                <div class="install-step">
                    <div class="install-step-number">3</div>
                    <div>Open from home screen</div>
                </div>
            </div>
        </div>

        <!-- Header -->
        <header class="app-header">
            <div class="candle-icon">🕯️</div>
            <h1 class="app-title">Sacred Spaces</h1>
            <p class="app-subtitle">A gentle place to honor those who walk with the ancestors</p>
        </header>

        <!-- Home View -->
        <div id="homeView" class="view active">
            <div id="memorialsList" class="memorials-list">
                <!-- Memorial cards will be added here dynamically -->
            </div>

            <div class="action-buttons">
                <button class="btn btn-primary" onclick="showView('create')">
                    <span>+</span> Create Sacred Space
                </button>
                <button class="btn btn-secondary" onclick="showBackupRestore()">
                    📂 Backup & Restore
                </button>
            </div>

            <div class="empty-state" id="emptyState">
                <div class="empty-icon">🕯️</div>
                <h3>Welcome to Sacred Spaces</h3>
                <p>This is a gentle place to create memorials for loved ones. All information stays on your device - private and secure.</p>
                <button class="btn btn-primary" onclick="showView('create')" style="margin-top: 20px;">
                    Create Your First Sacred Space
                </button>
            </div>
        </div>

        <!-- Create/Edit Memorial View -->
        <div id="createView" class="view">
            <div class="form-section">
                <h2 class="form-title">🕯️ Create Sacred Space</h2>

                <div class="form-group">
                    <label class="form-label">Their Name *</label>
                    <input type="text" id="memorialName" class="form-input" placeholder="Enter their name" required>
                </div>

                <div class="form-group">
                    <label class="form-label">Dates (Optional)</label>
                    <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
                        <input type="date" id="birthDate" class="form-input" placeholder="Birth date">
                        <input type="date" id="passingDate" class="form-input" placeholder="Passing date">
                    </div>
                </div>
            </div>

            <!-- Photo Options -->
            <div class="form-section">
                <h2 class="form-title">📸 Photos</h2>
                <p style="color: var(--color-text-secondary); margin-bottom: 20px;">Choose how you'd like to add photos</p>

                <div class="photo-options">
                    <div class="photo-option" onclick="selectPhotoOption('simple')">
                        <div class="option-icon">🌸</div>
                        <div class="option-title">Simple (Recommended)</div>
                        <div class="option-desc">Add 5 special photos. We'll compress them to save space on your device.</div>
                    </div>

                    <div class="photo-option" onclick="selectPhotoOption('full')">
                        <div class="option-icon">📷</div>
                        <div class="option-title">Full Gallery</div>
                        <div class="option-desc">Add up to 20 photos. We'll optimize them for your device storage.</div>
                    </div>

                    <div class="photo-option" onclick="selectPhotoOption('unlimited')">
                        <div class="option-icon">🌐</div>
                        <div class="option-title">Unlimited (Online)</div>
                        <div class="option-desc">Use image links for unlimited photos. We'll guide you through free hosting.</div>
                    </div>
                </div>

                <!-- Photo Upload Area -->
                <div id="photoUploadArea" class="photo-upload-area" onclick="triggerPhotoUpload()" style="display: none;">
                    <div class="upload-icon">📱</div>
                    <div class="upload-text">Tap to add photos from your device</div>
                    <div class="upload-hint" id="photoLimitHint">You can add up to 5 photos</div>
                </div>

                <!-- URL Input for Unlimited Option -->
                <div id="urlInputArea" style="display: none;">
                    <textarea id="photoUrls" class="form-input form-textarea" 
                              placeholder="Paste image URLs here (one per line)&#10;Example:&#10;https://example.com/photo1.jpg&#10;https://example.com/photo2.jpg"></textarea>
                    <div style="margin-top: 10px; font-size: 0.9em; color: var(--color-text-muted);">
                        💡 Need help? <a href="#" onclick="showImageHostingGuide()" style="color: var(--color-accent-light);">Learn about free image hosting</a>
                    </div>
                </div>

                <!-- Photo Preview -->
                <div id="photoPreview" class="photo-preview-grid"></div>
            </div>

            <!-- Memories -->
            <div class="form-section">
                <h2 class="form-title">📖 Memories & Stories</h2>
                <div id="memoriesList"></div>
                <button class="btn btn-secondary" onclick="addMemoryField()" style="margin-top: 15px;">
                    + Add Memory
                </button>
            </div>

            <!-- Music Guidance -->
            <div class="music-guidance">
                <div class="music-guidance-title">🎵 Music for Sacred Moments</div>
                <p style="color: var(--color-text-secondary); margin-bottom: 15px;">
                    When spending time in this sacred space, you can play meaningful music from your own music app. We'll guide you through creating a special playlist.
                </p>
                <button class="btn btn-secondary" onclick="showMusicGuide()">
                    Learn How to Add Music
                </button>
            </div>

            <!-- Save Button -->
            <div style="margin: 40px 0;">
                <button class="btn btn-primary" onclick="saveMemorial()" style="width: 100%; padding: 18px;">
                    Save Sacred Space
                </button>
            </div>
        </div>

        <!-- Memorial View -->
        <div id="memorialView" class="view">
            <div id="memorialContent">
                <!-- Memorial content will be loaded here -->
            </div>
        </div>

        <!-- Backup/Restore View -->
        <div id="backupView" class="view">
            <div class="form-section">
                <h2 class="form-title">📂 Backup & Restore</h2>
                <p style="color: var(--color-text-secondary); margin-bottom: 20px;">
                    Your memorials are stored on this device only. Back them up regularly to keep them safe.
                </p>

                <div class="backup-options">
                    <div class="backup-option" onclick="exportBackup()">
                        <div style="font-size: 2em; margin-bottom: 10px;">💾</div>
                        <div style="font-weight: 500; margin-bottom: 5px;">Backup All</div>
                        <div style="font-size: 0.9em; color: var(--color-text-secondary);">Save all memorials to a file</div>
                    </div>

                    <div class="backup-option" onclick="importBackup()">
                        <div style="font-size: 2em; margin-bottom: 10px;">📥</div>
                        <div style="font-weight: 500; margin-bottom: 5px;">Restore</div>
                        <div style="font-size: 0.9em; color: var(--color-text-secondary);">Load memorials from backup</div>
                    </div>

                    <div class="backup-option" onclick="printMemorial()">
                        <div style="font-size: 2em; margin-bottom: 10px;">🖨️</div>
                        <div style="font-weight: 500; margin-bottom: 5px;">Print</div>
                        <div style="font-size: 0.9em; color: var(--color-text-secondary);">Create a printable memorial</div>
                    </div>
                </div>

                <div style="margin-top: 30px; padding: 20px; background: rgba(190, 81, 3, 0.05); border-radius: var(--radius-sm);">
                    <div style="color: var(--color-accent-light); margin-bottom: 10px;">⚠️ Important</div>
                    <div style="font-size: 0.9em; color: var(--color-text-secondary);">
                        If you clear browser data or switch devices, your memorials will be lost unless you have a backup. Please back up regularly.
                    </div>
                </div>
            </div>
        </div>
    </div>

    <!-- Ritual Mode Overlay -->
    <div id="ritualOverlay" class="ritual-overlay">
        <div class="ritual-container">
            <div class="ritual-header">
                <div class="ritual-candle">🕯️</div>
                <div id="ritualPrompt" class="ritual-prompt">
                    Take a deep breath. You're entering a sacred space.
                </div>
            </div>

            <div class="ritual-content">
                <img id="ritualPhoto" class="ritual-photo" src="" alt="" style="display: none;">
                <div id="ritualMemory" class="ritual-memory" style="display: none;"></div>
                <div id="ritualTimer" class="ritual-timer">05:00</div>
            </div>

            <div class="ritual-controls">
                <button class="btn btn-secondary" onclick="skipRitualItem()">
                    Next
                </button>
                <button class="btn btn-primary" onclick="startPauseTimer()" id="timerControl">
                    Start (5 min)
                </button>
                <button class="btn btn-secondary" onclick="exitRitual()">
                    Exit
                </button>
            </div>
        </div>
    </div>

    <!-- Soundscape Controls -->
    <div class="soundscape-controls">
        <button class="soundscape-btn" onclick="toggleSoundscape('rain')" title="Rain">
            🌧️
        </button>
        <button class="soundscape-btn" onclick="toggleSoundscape('waves')" title="Ocean">
            🌊
        </button>
        <button class="soundscape-btn" onclick="toggleSoundscape('forest')" title="Forest">
            🌳
        </button>
        <button class="soundscape-btn" onclick="toggleSoundscape('none')" title="Silence">
            🔇
        </button>
    </div>

    <!-- Navigation Bar -->
    <div class="nav-bar">
        <button class="nav-btn active" onclick="showView('home')">
            <span class="nav-icon">🏠</span>
            <span>Home</span>
        </button>
        <button class="nav-btn" onclick="showView('create')">
            <span class="nav-icon">+</span>
            <span>Create</span>
        </button>
        <button class="nav-btn" onclick="enterRitualMode()">
            <span class="nav-icon">💭</span>
            <span>Quiet Time</span>
        </button>
        <button class="nav-btn" onclick="showView('backup')">
            <span class="nav-icon">⚙️</span>
            <span>Backup</span>
        </button>
    </div>

    <!-- Toast Notification -->
    <div id="toast" class="toast">
        <span id="toastMessage">Notification message</span>
    </div>

    <!-- Hidden File Inputs -->
    <input type="file" id="photoUpload" accept="image/*" multiple style="display: none;" onchange="handlePhotoUpload(event)">
    <input type="file" id="backupUpload" accept=".json" style="display: none;" onchange="handleBackupUpload(event)">

    <!-- Soundscape Audio Elements -->
    <audio id="rainSound" loop preload="metadata">
        <source src="https://assets.mixkit.co/sfx/preview/mixkit-rain-loop-1249.mp3" type="audio/mpeg">
    </audio>
    <audio id="wavesSound" loop preload="metadata">
        <source src="https://assets.mixkit.co/sfx/preview/mixkit-waves-loop-1251.mp3" type="audio/mpeg">
    </audio>
    <audio id="forestSound" loop preload="metadata">
        <source src="https://assets.mixkit.co/sfx/preview/mixkit-forest-ambience-1227.mp3" type="audio/mpeg">
    </audio>

    <script>
        // ==================== APP STATE ====================
        let appState = {
            currentView: 'home',
            currentMemorialId: null,
            memorials: [],
            currentPhotoOption: 'simple',
            uploadedPhotos: [],
            ritualActive: false,
            currentSoundscape: null,
            isTimerRunning: false,
            timerInterval: null,
            timerSeconds: 300 // 5 minutes
        };

        // ==================== PWA INSTALLATION ====================
        window.addEventListener('load', () => {
            // Check if PWA is installable
            if (window.matchMedia('(display-mode: standalone)').matches) {
                console.log('Running as PWA');
            } else {
                // Show install prompt for first-time visitors
                setTimeout(() => {
                    const installPrompt = document.getElementById('installPrompt');
                    installPrompt.classList.add('show');

                    // Hide after 15 seconds
                    setTimeout(() => {
                        installPrompt.classList.remove('show');
                    }, 15000);
                }, 3000);
            }

            // Load memorials from storage
            loadMemorials();

            // Initialize database
            initDatabase();
        });

        // Service Worker Registration for PWA
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.register('sw.js').catch(error => {
                console.log('Service Worker registration failed:', error);
            });
        }

        // ==================== DATABASE (IndexedDB) ====================
        let db;
        const DB_NAME = 'SacredSpacesDB';
        const DB_VERSION = 1;

        function initDatabase() {
            const request = indexedDB.open(DB_NAME, DB_VERSION);

            request.onerror = (event) => {
                console.error('Database error:', event.target.error);
                showToast('⚠️ Could not initialize storage', 'error');
            };

            request.onsuccess = (event) => {
                db = event.target.result;
                console.log('Database opened successfully');
                // Load memorials from IndexedDB
                loadMemorialsFromDB();
            };

            request.onupgradeneeded = (event) => {
                db = event.target.result;

                // Create object store for memorials
                if (!db.objectStoreNames.contains('memorials')) {
                    const store = db.createObjectStore('memorials', { keyPath: 'id' });
                    store.createIndex('createdAt', 'createdAt', { unique: false });
                }
            };
        }

        // ==================== VIEW MANAGEMENT ====================
        function showView(viewName) {
            // Hide all views
            document.querySelectorAll('.view').forEach(view => {
                view.classList.remove('active');
            });

            // Update active nav button
            document.querySelectorAll('.nav-btn').forEach(btn => {
                btn.classList.remove('active');
            });

            // Show requested view
            document.getElementById(viewName + 'View').classList.add('active');

            // Set active nav button
            const navBtn = document.querySelector(`.nav-btn[onclick*="${viewName}"]`);
            if (navBtn) navBtn.classList.add('active');

            // Special handling for each view
            if (viewName === 'home') {
                renderMemorialsList();
            } else if (viewName === 'create') {
                // Reset form for new memorial
                if (!appState.currentMemorialId) {
                    resetCreateForm();
                }
            } else if (viewName === 'memorial') {
                // Load memorial if one is selected
                if (appState.currentMemorialId) {
                    loadMemorialView(appState.currentMemorialId);
                }
            }

            appState.currentView = viewName;
        }

        function showBackupRestore() {
            showView('backup');
        }

        // ==================== MEMORIAL MANAGEMENT ====================
        function renderMemorialsList() {
            const container = document.getElementById('memorialsList');
            const emptyState = document.getElementById('emptyState');

            if (appState.memorials.length === 0) {
                container.innerHTML = '';
                emptyState.style.display = 'block';
                return;
            }

            emptyState.style.display = 'none';

            container.innerHTML = appState.memorials.map(memorial => `
                <div class="memorial-card ${memorial.id === appState.currentMemorialId ? 'active' : ''}" 
                     onclick="selectMemorial('${memorial.id}')">
                    <div class="memorial-name">${escapeHtml(memorial.name)}</div>
                    <div class="memorial-dates">
                        ${memorial.birthDate ? formatDate(memorial.birthDate) : 'Unknown'} — 
                        ${memorial.passingDate ? formatDate(memorial.passingDate) : 'Present'}
                    </div>
                    <div class="memorial-stats">
                        <div class="stat-item">📸 ${memorial.photos?.length || 0} photos</div>
                        <div class="stat-item">📖 ${memorial.memories?.length || 0} memories</div>
                        <div class="stat-item">🕯️ ${formatRelativeTime(memorial.lastVisited)}</div>
                    </div>
                    <div class="action-buttons">
                        <button class="btn btn-primary" onclick="selectMemorial('${memorial.id}'); event.stopPropagation();">
                            Visit Space
                        </button>
                        <button class="btn btn-secondary" onclick="editMemorial('${memorial.id}'); event.stopPropagation();">
                            Edit
                        </button>
                        <button class="btn btn-secondary" onclick="deleteMemorial('${memorial.id}'); event.stopPropagation();">
                            Remove
                        </button>
                    </div>
                </div>
            `).join('');
        }

        function selectMemorial(id) {
            appState.currentMemorialId = id;

            // Update last visited time
            const memorial = appState.memorials.find(m => m.id === id);
            if (memorial) {
                memorial.lastVisited = new Date().toISOString();
                saveMemorialToDB(memorial);
            }

            showView('memorial');
        }

        function editMemorial(id) {
            appState.currentMemorialId = id;
            loadMemorialForEditing(id);
            showView('create');
        }

        // ==================== PHOTO MANAGEMENT ====================
        function selectPhotoOption(option) {
            appState.currentPhotoOption = option;

            // Update UI
            document.querySelectorAll('.photo-option').forEach(el => {
                el.classList.remove('selected');
            });
            event.target.closest('.photo-option').classList.add('selected');

            // Show appropriate interface
            const uploadArea = document.getElementById('photoUploadArea');
            const urlArea = document.getElementById('urlInputArea');

            if (option === 'unlimited') {
                uploadArea.style.display = 'none';
                urlArea.style.display = 'block';
            } else {
                uploadArea.style.display = 'block';
                urlArea.style.display = 'none';

                // Update limit hint
                const limit = option === 'simple' ? 5 : 20;
                document.getElementById('photoLimitHint').textContent = 
                    `You can add up to ${limit} photos`;
            }

            // Clear existing photos
            appState.uploadedPhotos = [];
            renderPhotoPreview();
        }

        function triggerPhotoUpload() {
            document.getElementById('photoUpload').click();
        }

        async function handlePhotoUpload(event) {
            const files = Array.from(event.target.files);
            const limit = appState.currentPhotoOption === 'simple' ? 5 : 20;

            // Check limit
            if (appState.uploadedPhotos.length + files.length > limit) {
                showToast(`Maximum ${limit} photos allowed for this option`, 'warning');
                files.splice(limit - appState.uploadedPhotos.length);
            }

            for (const file of files) {
                try {
                    // Compress image
                    const compressed = await compressImage(file);
                    appState.uploadedPhotos.push({
                        id: Date.now() + Math.random(),
                        name: file.name,
                        data: compressed,
                        size: compressed.length,
                        type: file.type
                    });
                } catch (error) {
                    console.error('Error processing image:', error);
                    showToast(`Error processing ${file.name}`, 'error');
                }
            }

            renderPhotoPreview();
            event.target.value = ''; // Reset input
        }

        function compressImage(file) {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.readAsDataURL(file);

                reader.onload = (e) => {
                    const img = new Image();
                    img.src = e.target.result;

                    img.onload = () => {
                        const canvas = document.createElement('canvas');
                        const ctx = canvas.getContext('2d');

                        // Calculate new dimensions (max 1200px on longest side)
                        let width = img.width;
                        let height = img.height;
                        const maxSize = 1200;

                        if (width > height && width > maxSize) {
                            height = (height * maxSize) / width;
                            width = maxSize;
                        } else if (height > maxSize) {
                            width = (width * maxSize) / height;
                            height = maxSize;
                        }

                        canvas.width = width;
                        canvas.height = height;

                        // Draw and compress
                        ctx.drawImage(img, 0, 0, width, height);
                        const compressedData = canvas.toDataURL('image/jpeg', 0.7);
                        resolve(compressedData);
                    };

                    img.onerror = reject;
                };

                reader.onerror = reject;
            });
        }

        function renderPhotoPreview() {
            const container = document.getElementById('photoPreview');

            if (appState.uploadedPhotos.length === 0) {
                container.innerHTML = '';
                return;
            }

            container.innerHTML = appState.uploadedPhotos.map((photo, index) => `
                <div class="photo-preview">
                    <img src="${photo.data}" alt="Preview ${index + 1}">
                    <button class="photo-remove" onclick="removePhoto(${index})">×</button>
                </div>
            `).join('');
        }

        function removePhoto(index) {
            appState.uploadedPhotos.splice(index, 1);
            renderPhotoPreview();
        }

        // ==================== MEMORY MANAGEMENT ====================
        function addMemoryField() {
            const container = document.getElementById('memoriesList');
            const id = 'memory-' + Date.now();

            const memoryDiv = document.createElement('div');
            memoryDiv.className = 'form-group';
            memoryDiv.innerHTML = `
                <input type="text" class="form-input memory-title" placeholder="Memory title (e.g., Our last Christmas together)">
                <textarea class="form-input form-textarea memory-content" placeholder="Tell the story..."></textarea>
                <button type="button" class="btn btn-secondary" onclick="this.parentElement.remove()" style="margin-top: 10px;">
                    Remove Memory
                </button>
            `;

            container.appendChild(memoryDiv);
        }

        // ==================== SAVE MEMORIAL ====================
        async function saveMemorial() {
            const name = document.getElementById('memorialName').value.trim();
            if (!name) {
                showToast('Please enter a name for this sacred space', 'warning');
                return;
            }

            // Collect photos based on selected option
            let photos = [];
            if (appState.currentPhotoOption === 'unlimited') {
                const urls = document.getElementById('photoUrls').value
                    .split('\n')
                    .map(url => url.trim())
                    .filter(url => url);
                photos = urls.map(url => ({ url }));
            } else {
                photos = appState.uploadedPhotos.map(photo => ({
                    data: photo.data,
                    name: photo.name
                }));
            }

            // Collect memories
            const memories = [];
            document.querySelectorAll('#memoriesList .form-group').forEach(group => {
                const title = group.querySelector('.memory-title').value.trim();
                const content = group.querySelector('.memory-content').value.trim();
                if (title || content) {
                    memories.push({ title, content });
                }
            });

            // Create memorial object
            const memorial = {
                id: appState.currentMemorialId || generateId(),
                name: name,
                birthDate: document.getElementById('birthDate').value || null,
                passingDate: document.getElementById('passingDate').value || null,
                photos: photos,
                memories: memories,
                photoOption: appState.currentPhotoOption,
                createdAt: new Date().toISOString(),
                lastVisited: new Date().toISOString(),
                soundscape: appState.currentSoundscape
            };

            // Save to IndexedDB
            await saveMemorialToDB(memorial);

            // Update app state
            if (!appState.currentMemorialId) {
                appState.memorials.push(memorial);
            } else {
                const index = appState.memorials.findIndex(m => m.id === memorial.id);
                if (index !== -1) {
                    appState.memorials[index] = memorial;
                }
            }

            appState.currentMemorialId = memorial.id;

            showToast('Sacred space saved successfully', 'success');

            // Return to home view
            showView('home');
        }

        // ==================== RITUAL MODE ====================
        function enterRitualMode() {
            if (!appState.currentMemorialId) {
                showToast('Please select a sacred space first', 'warning');
                return;
            }

            const memorial = appState.memorials.find(m => m.id === appState.currentMemorialId);
            if (!memorial) return;

            appState.ritualActive = true;
            appState.timerSeconds = 300; // Reset to 5 minutes

            // Start with a random prompt
            const prompts = [
                "Take a deep breath. You're entering a sacred space.",
                "Breathe in peace, breathe out tension.",
                "Let your heart remember. Let your soul connect.",
                "In this moment, you are together in spirit.",
                "Honor the love that never leaves you.",
                "Sit with the memories. Let them surround you.",
                "Feel their presence in the silence between breaths."
            ];

            document.getElementById('ritualPrompt').textContent = 
                prompts[Math.floor(Math.random() * prompts.length)];

            // Prepare ritual items
            prepareRitualItems(memorial);

            // Show overlay
            document.getElementById('ritualOverlay').classList.add('active');

            // Update timer display
            updateTimerDisplay();
        }

        function prepareRitualItems(memorial) {
            // Clear previous items
            document.getElementById('ritualPhoto').style.display = 'none';
            document.getElementById('ritualMemory').style.display = 'none';

            // Randomly select what to show
            const showPhoto = memorial.photos?.length > 0 && Math.random() > 0.3;
            const showMemory = memorial.memories?.length > 0 && Math.random() > 0.3;

            if (showPhoto && memorial.photos.length > 0) {
                const randomPhoto = memorial.photos[Math.floor(Math.random() * memorial.photos.length)];
                const img = document.getElementById('ritualPhoto');
                img.src = randomPhoto.data || randomPhoto.url;
                img.style.display = 'block';
            } else if (showMemory && memorial.memories.length > 0) {
                const randomMemory = memorial.memories[Math.floor(Math.random() * memorial.memories.length)];
                const memoryDiv = document.getElementById('ritualMemory');
                memoryDiv.innerHTML = `
                    <div style="font-size: 1.1em; margin-bottom: 10px; color: var(--color-accent-light);">
                        ${escapeHtml(randomMemory.title || 'A Memory')}
                    </div>
                    <div style="line-height: 1.6;">
                        ${escapeHtml(randomMemory.content).replace(/\n/g, '<br>')}
                    </div>
                `;
                memoryDiv.style.display = 'block';
            }
        }

        function startPauseTimer() {
            const button = document.getElementById('timerControl');

            if (!appState.isTimerRunning) {
                // Start timer
                appState.isTimerRunning = true;
                button.textContent = 'Pause';

                appState.timerInterval = setInterval(() => {
                    appState.timerSeconds--;
                    updateTimerDisplay();

                    if (appState.timerSeconds <= 0) {
                        clearInterval(appState.timerInterval);
                        appState.isTimerRunning = false;
                        button.textContent = 'Start (5 min)';
                        showToast('Time for reflection is complete', 'success');

                        // Show new prompt
                        const prompts = [
                            "Thank you for this time of remembrance.",
                            "Carry this peace with you throughout your day.",
                            "Their love remains with you always.",
                            "Take a final breath before returning.",
                            "May their memory be a blessing that walks with you."
                        ];

                        document.getElementById('ritualPrompt').textContent = 
                            prompts[Math.floor(Math.random() * prompts.length)];
                    }
                }, 1000);
            } else {
                // Pause timer
                clearInterval(appState.timerInterval);
                appState.isTimerRunning = false;
                button.textContent = 'Resume';
            }
        }

        function updateTimerDisplay() {
            const minutes = Math.floor(appState.timerSeconds / 60);
            const seconds = appState.timerSeconds % 60;
            document.getElementById('ritualTimer').textContent = 
                `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
        }

        function skipRitualItem() {
            const memorial = appState.memorials.find(m => m.id === appState.currentMemorialId);
            if (memorial) {
                prepareRitualItems(memorial);
            }
        }

        function exitRitual() {
            appState.ritualActive = false;
            clearInterval(appState.timerInterval);
            appState.isTimerRunning = false;
            document.getElementById('ritualOverlay').classList.remove('active');
        }

        // ==================== SOUNDSCAPES ====================
        function toggleSoundscape(type) {
            // Stop current soundscape
            if (appState.currentSoundscape) {
                const currentAudio = document.getElementById(appState.currentSoundscape + 'Sound');
                if (currentAudio) {
                    currentAudio.pause();
                    currentAudio.currentTime = 0;
                }

                // Update button
                document.querySelector(`.soundscape-btn[onclick*="${appState.currentSoundscape}"]`)
                    ?.classList.remove('active');
            }

            // Start new soundscape
            if (type !== 'none') {
                const audio = document.getElementById(type + 'Sound');
                if (audio) {
                    audio.volume = 0.3;
                    audio.play().catch(e => console.log('Audio play failed:', e));

                    // Update button
                    document.querySelector(`.soundscape-btn[onclick*="${type}"]`)
                        ?.classList.add('active');

                    appState.currentSoundscape = type;
                }
            } else {
                appState.currentSoundscape = null;
            }
        }

        // ==================== BACKUP & RESTORE ====================
        function exportBackup() {
            const backup = {
                app: 'SacredSpaces',
                version: '1.0',
                exportedAt: new Date().toISOString(),
                memorials: appState.memorials
            };

            const dataStr = JSON.stringify(backup, null, 2);
            const dataBlob = new Blob([dataStr], { type: 'application/json' });

            const url = URL.createObjectURL(dataBlob);
            const link = document.createElement('a');
            link.href = url;
            link.download = `sacred-spaces-backup-${new Date().toISOString().split('T')[0]}.json`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            URL.revokeObjectURL(url);

            showToast('Backup exported successfully', 'success');
        }

        function importBackup() {
            document.getElementById('backupUpload').click();
        }

        async function handleBackupUpload(event) {
            const file = event.target.files[0];
            if (!file) return;

            const reader = new FileReader();
            reader.onload = async (e) => {
                try {
                    const backup = JSON.parse(e.target.result);

                    // Validate backup
                    if (!backup.app || backup.app !== 'SacredSpaces') {
                        throw new Error('Invalid backup file');
                    }

                    // Clear existing data
                    await clearDatabase();

                    // Import memorials
                    for (const memorial of backup.memorials) {
                        await saveMemorialToDB(memorial);
                    }

                    // Reload memorials
                    await loadMemorialsFromDB();

                    showToast(`Imported ${backup.memorials?.length || 0} sacred spaces`, 'success');
                    showView('home');

                } catch (error) {
                    console.error('Backup import error:', error);
                    showToast('Error importing backup file', 'error');
                }
            };

            reader.readAsText(file);
            event.target.value = ''; // Reset input
        }

        // ==================== HELPER FUNCTIONS ====================
        function showToast(message, type = 'info') {
            const toast = document.getElementById('toast');
            const toastMessage = document.getElementById('toastMessage');

            toastMessage.textContent = message;
            toast.className = 'toast';
            toast.classList.add('show');

            // Add type class for styling
            if (type === 'error') {
                toast.style.borderLeftColor = '#e74c3c';
            } else if (type === 'warning') {
                toast.style.borderLeftColor = '#f39c12';
            } else if (type === 'success') {
                toast.style.borderLeftColor = '#2ecc71';
            }

            // Auto-hide
            setTimeout(() => {
                toast.classList.remove('show');
            }, 3000);
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        function formatDate(dateString) {
            if (!dateString) return '';
            const date = new Date(dateString);
            return date.toLocaleDateString('en-US', { 
                month: 'short', 
                day: 'numeric', 
                year: 'numeric' 
            });
        }

        function formatRelativeTime(dateString) {
            if (!dateString) return 'Never';
            const date = new Date(dateString);
            const now = new Date();
            const diffMs = now - date;
            const diffMins = Math.floor(diffMs / 60000);
            const diffHours = Math.floor(diffMs / 3600000);
            const diffDays = Math.floor(diffMs / 86400000);

            if (diffMins < 60) return `${diffMins}m ago`;
            if (diffHours < 24) return `${diffHours}h ago`;
            if (diffDays < 7) return `${diffDays}d ago`;
            return `${Math.floor(diffDays / 7)}w ago`;
        }

        function generateId() {
            return Date.now().toString(36) + Math.random().toString(36).substr(2);
        }

        // ==================== DATABASE OPERATIONS ====================
        async function saveMemorialToDB(memorial) {
            return new Promise((resolve, reject) => {
                if (!db) {
                    reject('Database not initialized');
                    return;
                }

                const transaction = db.transaction(['memorials'], 'readwrite');
                const store = transaction.objectStore('memorials');
                const request = store.put(memorial);

                request.onsuccess = () => resolve();
                request.onerror = () => reject(request.error);
            });
        }

        async function loadMemorialsFromDB() {
            return new Promise((resolve, reject) => {
                if (!db) {
                    reject('Database not initialized');
                    return;
                }

                const transaction = db.transaction(['memorials'], 'readonly');
                const store = transaction.objectStore('memorials');
                const request = store.getAll();

                request.onsuccess = () => {
                    appState.memorials = request.result || [];
                    renderMemorialsList();
                    resolve();
                };

                request.onerror = () => reject(request.error);
            });
        }

        async function deleteMemorial(id) {
            if (!confirm('Are you sure you want to remove this sacred space? This cannot be undone.')) {
                return;
            }

            return new Promise((resolve, reject) => {
                if (!db) {
                    reject('Database not initialized');
                    return;
                }

                const transaction = db.transaction(['memorials'], 'readwrite');
                const store = transaction.objectStore('memorials');
                const request = store.delete(id);

                request.onsuccess = () => {
                    // Remove from app state
                    appState.memorials = appState.memorials.filter(m => m.id !== id);
                    if (appState.currentMemorialId === id) {
                        appState.currentMemorialId = null;
                    }

                    renderMemorialsList();
                    showToast('Sacred space removed', 'success');
                    resolve();
                };

                request.onerror = () => reject(request.error);
            });
        }

        async function clearDatabase() {
            return new Promise((resolve, reject) => {
                if (!db) {
                    reject('Database not initialized');
                    return;
                }

                const transaction = db.transaction(['memorials'], 'readwrite');
                const store = transaction.objectStore('memorials');
                const request = store.clear();

                request.onsuccess = () => resolve();
                request.onerror = () => reject(request.error);
            });
        }

        // ==================== INITIALIZATION ====================
        function loadMemorials() {
            // Try to load from localStorage first (for backward compatibility)
            const saved = localStorage.getItem('sacredSpacesMemorials');
            if (saved) {
                try {
                    appState.memorials = JSON.parse(saved);
                    renderMemorialsList();

                    // Migrate to IndexedDB
                    migrateToIndexedDB();
                } catch (error) {
                    console.error('Error loading from localStorage:', error);
                }
            }
        }

        async function migrateToIndexedDB() {
            if (!db || appState.memorials.length === 0) return;

            for (const memorial of appState.memorials) {
                await saveMemorialToDB(memorial);
            }

            // Clear localStorage after migration
            localStorage.removeItem('sacredSpacesMemorials');
        }

        function resetCreateForm() {
            appState.currentMemorialId = null;
            appState.uploadedPhotos = [];
            appState.currentPhotoOption = 'simple';

            document.getElementById('memorialName').value = '';
