        function displayMemorial() {
            // If we have multiple memorials system, use that
            if (appState.currentMemorialId) {
                const memorial = appState.memorials.find(m => m.id === appState.currentMemorialId);
                if (memorial) {
                    memorialData = memorial;
                }
            }

            const saved = localStorage.getItem('memorialData');
            if (!saved && !memorialData.name) {
                document.getElementById('memorialContent').innerHTML = '<div class="empty-state"><p>No memorial created yet. Create one to get started.</p></div>';
                return;
            }

            if (saved && !memorialData.name) {
                const data = JSON.parse(saved);
                memorialData = {
                    ...memorialData,
                    ...data
                };
            }

            let html = `<div class="memorial-card">`;

            if (memorialData.mainPhotoData) {
                html += `<img src="${memorialData.mainPhotoData}" alt="${memorialData.name}" class="memorial-photo" onerror="this.style.display='none'">`;
            } else if (memorialData.mainPhotoUrl) {
                html += `<img src="${memorialData.mainPhotoUrl}" alt="${memorialData.name}" class="memorial-photo" onerror="this.style.display='none'">`;
            }

            html += `<div class="memorial-header">
                <div class="memorial-name">${memorialData.name}</div>`;

            if (memorialData.birthDate || memorialData.passingDate) {
                const birth = memorialData.birthDate ? new Date(memorialData.birthDate).toLocaleDateString() : '---';
                const passing = memorialData.passingDate ? new Date(memorialData.passingDate).toLocaleDateString() : '---';
                html += `<div class="memorial-dates">${birth} — ${passing}</div>`;
            }

            html += `</div></div>`;

            // Contact info
            if (memorialData.phone || memorialData.email) {
                html += `<div class="memorial-section">
                    <h3>Contact Information</h3>
                    <div class="contact-info-display">`;
                if (memorialData.phone) html += `<p><strong>Phone:</strong> ${memorialData.phone}</p>`;
                if (memorialData.email) html += `<p><strong>Email:</strong> ${memorialData.email}</p>`;
                html += `</div></div>`;
            }

            // Personal note
            if (memorialData.personalNote) {
                html += `<div class="memorial-section">
                    <h3>💝 Tribute</h3>
                    <p>${memorialData.personalNote.replace(/\n/g, '<br>')}</p>
                </div>`;
            }

            // Photo gallery
            const allGalleryPhotos = [];
            if (memorialData.photos && memorialData.photos.length > 0) {
                memorialData.photos.forEach(photo => {
                    if (photo.data) {
                        allGalleryPhotos.push(photo.data);
                    } else if (photo.url) {
                        allGalleryPhotos.push(photo.url);
                    }
                });
            }
            if (memorialData.galleryPhotos && memorialData.galleryPhotos.length > 0) {
                allGalleryPhotos.push(...memorialData.galleryPhotos);
            }
            if (memorialData.photoUrls && memorialData.photoUrls.length > 0) {
                allGalleryPhotos.push(...memorialData.photoUrls);
            }

            if (allGalleryPhotos.length > 0) {
                html += `<div class="memorial-section">
                    <h3>📸 Gallery</h3>
                    <div class="memory-gallery">`;
                allGalleryPhotos.forEach(photo => {
                    html += `<div class="gallery-item"><img src="${photo}" alt="Memory" onerror="this.parentElement.style.display='none'"></div>`;
                });
                html += `</div></div>`;
            }

            // Memories
            if (memorialData.memories && memorialData.memories.length > 0) {
                html += `<div class="memorial-section">
                    <h3>📖 Memories & Stories</h3>`;
                memorialData.memories.forEach(memory => {
                    html += `<div class="memory-item">
                        <strong>${memory.title}</strong>
                        ${memory.content.replace(/\n/g, '<br>')}
                    </div>`;
                });
                html += `</div>`;
            }

            // Important dates
            if (memorialData.dates && memorialData.dates.length > 0) {
                html += `<div class="memorial-section">
                    <h3>📅 Important Dates</h3>
                    <div class="timeline-item">`;
                memorialData.dates.forEach(date => {
                    const dateStr = date.date ? new Date(date.date).toLocaleDateString() : 'No date';
