                </button>
            </div>

            <div style="text-align: center; margin-top: 30px;">
                <button class="btn-primary" onclick="toggleView('form')">Edit Memorial</button>
                <button class="btn-secondary" onclick="downloadMemorial()" style="margin-left: 12px;">Download Memorial</button>
                <button class="btn-secondary" onclick="toggleView('home')" style="margin-left: 12px;">Return Home</button>
            </div>
        </div>
