                const title = el.value;
                const content = el.parentElement.querySelector('.memory-content').value;
                if (title.trim() || content.trim()) {
                    memorialData.memories.push({ title, content });
                }
            });

            document.querySelectorAll('.date-value').forEach((el, i) => {
                const date = el.value;
                const desc = el.parentElement.querySelector('.date-description').value;
                if (date || desc.trim()) {
                    memorialData.dates.push({ date, description: desc });
                }
            });

            document.querySelectorAll('#voiceList > .input-row').forEach((row) => {
                const isFile = row.dataset.isFile === 'true';
                const label = row.querySelector('.voice-label').value;

                if (isFile && row.dataset.voiceData) {
                    memorialData.voices.push({ 
                        data: row.dataset.voiceData, 
                        label: label || 'Voice message',
                        isFile: true
                    });
                } else if (!isFile) {
                    const url = row.querySelector('.voice-url').value;
                    if (url.trim()) {
                        memorialData.voices.push({ 
                            url, 
                            label: label || 'Voice message',
                            isFile: false
                        });
                    }
                }
            });

            // Save to multiple memorials system
            const memorialId = appState.currentMemorialId || 'memorial-' + Date.now();
            memorialData.id = memorialId;
            memorialData.createdAt = new Date().toISOString();
            memorialData.lastVisited = new Date().toISOString();

            // Add or update in memorials array
            const existingIndex = appState.memorials.findIndex(m => m.id === memorialId);
            if (existingIndex !== -1) {
                appState.memorials[existingIndex] = memorialData;
            } else {
                appState.memorials.push(memorialData);
            }

            appState.currentMemorialId = memorialId;

            // Reset photo state for next memorial
            appState.uploadedPhotos = [];
            appState.selectedPhotoOption = null;

            // Save both systems for compatibility
            try {
                localStorage.setItem('memorialData', JSON.stringify(memorialData));
                saveAllMemorials();

                console.log('✓ Memorial saved successfully');
                showToast('✓ Memorial saved successfully! Your memorial is safe on this device.', 'success');
                toggleView('memorial');
            } catch (error) {
                console.error('✗ localStorage failed:', error);
                alert('⚠️ WARNING: Could not save to device storage.\n\nOn iPhone Safari: Go to Settings > Safari > Privacy > Block All Cookies OFF\n\nOr use Chrome/Firefox app instead.\n\nError: ' + error.message);
