            const countDisplay = document.getElementById('galleryPhotoCount');
            const MAX_PHOTOS = 20;
            countDisplay.textContent = `${photoCount}/${MAX_PHOTOS} photos`;
            if (photoCount >= MAX_PHOTOS) {
                countDisplay.style.color = 'var(--color-accent-light)';
