        function loadFormData() {
            const saved = localStorage.getItem('memorialData');
            if (!saved) return;

            const data = JSON.parse(saved);
            memorialData = {
                ...memorialData,
                ...data
            };

            document.getElementById('memorialName').value = memorialData.name || '';
            document.getElementById('memorialEmail').value = memorialData.email || '';
            document.getElementById('memorialPhone').value = memorialData.phone || '';
            document.getElementById('memorialBirthDate').value = memorialData.birthDate || '';
            document.getElementById('memorialPassingDate').value = memorialData.passingDate || '';
            document.getElementById('memorialPhotoUrl').value = memorialData.mainPhotoUrl || '';
