                item.className = 'input-row';
                item.id = id;
                item.dataset.isFile = voice.isFile ? 'true' : 'false';
                if (voice.isFile && voice.data) {
                    item.dataset.voiceData = voice.data;
                    item.innerHTML = `
                        <div style="flex: 1;">
                            <input type="text" class="voice-label" value="${voice.label}" placeholder="Label">
                            <audio controls style="width: 100%; margin-top: 8px; height: 30px;">
                                <source src="${voice.data}">
                            </audio>
                        </div>
                        <button type="button" class="btn-remove" onclick="document.getElementById('${id}').remove()">Remove</button>
                    `;
                } else {
                    item.innerHTML = `
                        <input type="text" class="voice-url" value="${voice.url || ''}" placeholder="Audio URL">
                        <input type="text" class="voice-label" value="${voice.label}" placeholder="Label">
