    <!-- IMPROVED Sacred Time Modal -->
    <div id="sacredTimeModal" class="modal-overlay sacred-time-modal">
        <div class="modal-content">
            <div class="modal-title">🕯️ Sacred Time with <span id="sacredTimeName">[Name]</span></div>

            <div class="photo-selection">
                <p style="color: var(--color-text-secondary); margin-bottom: 10px; text-align: center;">
                    Select a photo to sit with during this time:
                </p>
                <div class="photo-grid" id="sacredTimePhotos">
                    <!-- Photos will be loaded here -->
                </div>
            </div>

            <div class="sacred-time-content">
                <div class="sacred-time-instructions">
                    <p><strong>When you're ready:</strong></p>
                    <ol>
                        <li>Find a comfortable, quiet space</li>
                        <li>Look at the photo you've selected</li>
                        <li>Allow feelings, memories, thoughts to come and go as they please</li>
                        <li>This is a good time to journal if you wish</li>
                        <li>Write your thoughts, things you may want to say to <span id="journalName">[Name]</span></li>
                        <li>Sit for as long as you like</li>
                        <li>When ready, return to the memorial and walk into the rest of your day</li>
                    </ol>
                </div>
            </div>

