    <!-- Toast Notification -->
    <div id="toast" class="toast">
        <span id="toastMessage">Notification message</span>
    </div>

    <!-- Hidden File Inputs -->
    <input type="file" id="photoUpload" accept="image/*" multiple style="display: none;" onchange="handlePhotoUpload(event)">
    <input type="file" id="backupUpload" accept=".json" style="display: none;" onchange="handleBackupUpload(event)">

    <script>
        // ==================== ENHANCED APP STATE ====================
        let memorialData = {
            name: "",
            email: "",
            phone: "",
            birthDate: "",
            passingDate: "",
            mainPhotoUrl: "",
            mainPhotoData: "",
            personalNote: "",
            memories: [],
            dates: [],
            voices: [],
            musicTracks: [],
            galleryPhotos: [],
            photoUrls: []
        };

        let appState = {
            memorials: [],
            currentMemorialId: null,
            selectedPhotoOption: null,
            uploadedPhotos: [],
            profilePhotoData: null,
            tempFiles: null,
            isPWA: window.matchMedia('(display-mode: standalone)').matches,
            selectedSacredTimePhoto: null
        };

        // ==================== IMPROVED PWA FUNCTIONALITY ====================
        let deferredPrompt;

        window.addEventListener('beforeinstallprompt', (e) => {
            e.preventDefault();
            deferredPrompt = e;

            // Show install prompt after a short delay
            setTimeout(() => {
                if (!appState.isPWA && /Android|iPhone|iPad|iPod/i.test(navigator.userAgent)) {
                    document.getElementById('pwaInstallPrompt').classList.add('show');
                }
            }, 1000);
        });

        function installPWA() {
            if (deferredPrompt) {
                deferredPrompt.prompt();
                deferredPrompt.userChoice.then((choiceResult) => {
                    if (choiceResult.outcome === 'accepted') {
                        showToast('✓ Added to home screen! Open from your home screen anytime.', 'success');
                    }
                    deferredPrompt = null;
                    document.getElementById('pwaInstallPrompt').classList.remove('show');
                });
            } else {
                // Show manual instructions
                showToast('Look for "Add to Home Screen" in your browser menu', 'info');
            }
        }

        function dismissPWA() {
            document.getElementById('pwaInstallPrompt').classList.remove('show');
            localStorage.setItem('pwaDismissed', 'true');
        }

        // ==================== IMPROVED PROFILE PHOTO HANDLING ====================
        function selectProfilePhoto() {
            document.getElementById('profilePhotoUpload').click();
        }

        function toggleProfilePhotoUrl() {
            const urlInput = document.getElementById('profilePhotoUrl');
            urlInput.style.display = urlInput.style.display === 'none' ? 'block' : 'none';

            if (urlInput.style.display === 'block') {
                urlInput.focus();
            }
        }

        function handleProfilePhotoUpload(event) {
            const file = event.target.files[0];
            if (!file) return;

            // Check if it's an image
            if (!file.type.startsWith('image/')) {
                showToast('Please select an image file', 'warning');
                return;
            }

            const reader = new FileReader();
            reader.onload = (e) => {
                appState.profilePhotoData = e.target.result;
                updateProfilePhotoPreview();
                showToast('Profile photo selected', 'success');
            };
            reader.readAsDataURL(file);
        }

        function updateProfilePhotoPreview() {
            const preview = document.getElementById('profilePhotoPreview');
            if (appState.profilePhotoData) {
                preview.innerHTML = `<img src="${appState.profilePhotoData}" alt="Profile" class="profile-photo-preview">`;
            } else if (document.getElementById('profilePhotoUrl').value) {
                const url = document.getElementById('profilePhotoUrl').value;
                preview.innerHTML = `<img src="${url}" alt="Profile" class="profile-photo-preview" onerror="this.onerror=null; this.parentElement.innerHTML='👤';">`;
            } else {
                preview.innerHTML = '👤';
                preview.className = 'profile-photo-placeholder';
            }
        }

        // ==================== IMPROVED SACRED TIME ====================
        function startSacredTime() {
            if (!memorialData.photos || memorialData.photos.length === 0) {
                showToast('Add photos first to use sacred time', 'warning');
                return;
            }

            // Update name in modal
            document.getElementById('sacredTimeName').textContent = memorialData.name || '[Name]';
            document.getElementById('journalName').textContent = memorialData.name || '[Name]';

            // Load photos into selection grid
            const photosContainer = document.getElementById('sacredTimePhotos');
            photosContainer.innerHTML = '';

            memorialData.photos.forEach((photo, index) => {
                const photoSrc = photo.data || photo.url || photo;
                const photoDiv = document.createElement('div');
                photoDiv.className = 'selectable-photo';
                photoDiv.onclick = () => selectSacredTimePhoto(index);
                photoDiv.innerHTML = `<img src="${photoSrc}" alt="Photo ${index + 1}">`;
                photosContainer.appendChild(photoDiv);
            });

            // Show modal
            document.getElementById('sacredTimeModal').classList.add('active');
            appState.selectedSacredTimePhoto = null;
            updateBeginButtonState();
        }

        function selectSacredTimePhoto(index) {
            // Remove selection from all photos
            document.querySelectorAll('.selectable-photo').forEach(photo => {
                photo.classList.remove('selected');
            });

            // Add selection to clicked photo
            const photos = document.querySelectorAll('.selectable-photo');
            if (photos[index]) {
                photos[index].classList.add('selected');
                appState.selectedSacredTimePhoto = index;
            }

            updateBeginButtonState();
        }

        function updateBeginButtonState() {
            const beginBtn = document.getElementById('beginMeditationBtn');
            beginBtn.disabled = appState.selectedSacredTimePhoto === null;
            beginBtn.textContent = appState.selectedSacredTimePhoto === null ? 
                'Select a Photo First' : 'Begin Meditation';
        }

        function beginMeditation() {
            if (appState.selectedSacredTimePhoto === null) {
                showToast('Please select a photo first', 'warning');
                return;
            }

            const selectedPhoto = memorialData.photos[appState.selectedSacredTimePhoto];
            const photoSrc = selectedPhoto.data || selectedPhoto.url || selectedPhoto;

            // Create meditation view
            const meditationHtml = `
                <div class="memorial-card" style="text-align: center;">
                    <div style="font-size: 2em; margin-bottom: 20px; animation: breathing-glow 3s ease-in-out infinite;">🕯️</div>
                    <h2 style="color: white; margin-bottom: 20px;">Sacred Time with ${memorialData.name}</h2>

                    <div style="max-width: 400px; margin: 0 auto 30px;">
                        <img src="${photoSrc}" alt="${memorialData.name}" 
                             style="width: 100%; border-radius: 12px; border: 3px solid var(--color-copper);">
                    </div>

                    <div style="background: rgba(190, 81, 3, 0.08); padding: 25px; border-radius: 12px; margin: 30px 0; border-left: 4px solid var(--color-copper);">
                        <p style="color: var(--color-text-primary); font-size: 1.1em; line-height: 1.6; margin-bottom: 15px;">
                            <strong>Sit here for a moment.</strong>
                        </p>
                        <p style="color: var(--color-text-secondary); line-height: 1.6; margin-bottom: 15px;">
                            Look at the photo you've selected and allow the feelings, memories, thoughts to come and go as they please.
                        </p>
                        <p style="color: var(--color-text-secondary); line-height: 1.6; margin-bottom: 15px;">
                            This would also be a good time to journal. Write your thoughts, things you may want to say to ${memorialData.name}.
                        </p>
                        <p style="color: var(--color-text-secondary); line-height: 1.6;">
                            Sit for as long as you like and when you are ready, go back to the home page and walk into the rest of your day.
                        </p>
                    </div>

                    <div style="margin-top: 30px;">
                        <button class="btn-primary" onclick="toggleView('memorial')">
                            Return to Memorial
                        </button>
                        <button class="btn-secondary" onclick="toggleView('home')" style="margin-left: 12px;">
                            Go Home
                        </button>
                    </div>
                </div>
            `;

            // Hide modal and show meditation
            hideSacredTime();
            document.getElementById('memorialContent').innerHTML = meditationHtml;
            showToast('Sacred time begins. Breathe deeply.', 'success');
        }

        function hideSacredTime() {
            document.getElementById('sacredTimeModal').classList.remove('active');
        }

        // ==================== PHOTO OPTIONS SYSTEM ====================
        function showPhotoOptions() {
            document.getElementById('photoOptionsModal').classList.add('active');
        }

        function hidePhotoOptions() {
            document.getElementById('photoOptionsModal').classList.remove('active');
            appState.tempFiles = null;
        }

        function selectPhotoOption(option) {
            appState.selectedPhotoOption = option;

            document.querySelectorAll('.photo-option').forEach(el => {
                el.classList.remove('selected');
            });
            event.target.closest('.photo-option').classList.add('selected');

            const confirmBtn = document.getElementById('confirmPhotoButton');
            if (confirmBtn && appState.tempFiles) {
                confirmBtn.textContent = `Add ${appState.tempFiles.length} Photos`;
            } else {
                confirmBtn.textContent = 'Continue';
            }
        }

        function confirmPhotoOption() {
            if (!appState.selectedPhotoOption) {
                showToast('Please select a photo option', 'warning');
                return;
            }

            hidePhotoOptions();

            const uploadArea = document.getElementById('photoUploadArea');
            const previewArea = document.getElementById('photoPreviewArea');
            uploadArea.style.display = 'block';
            previewArea.style.display = 'block';

            let html = '';
            if (appState.selectedPhotoOption === 'simple') {
                const limit = 5;
                const remaining = limit - appState.uploadedPhotos.length;
                html = `
                    <h3 style="color: white; margin-bottom: 15px; font-size: 1.1em;">🌸 Simple Photos (${limit} maximum)</h3>
                    <p style="color: var(--color-text-secondary); margin-bottom: 15px;">
                        Upload up to ${limit} meaningful photos. We'll compress them automatically to save space on your device.
                    </p>
                    <div style="text-align: center; margin: 20px 0;">
                        <button class="btn-primary" onclick="uploadPhotos(${limit})" style="padding: 12px 30px;">
                            📱 ${appState.tempFiles ? `Upload ${appState.tempFiles.length} Selected` : 'Select Photos'}
                        </button>
                        ${appState.tempFiles ? '' : '<p style="color: var(--color-text-muted); font-size: 0.9em; margin-top: 10px;">Select photos from your device</p>'}
                    </div>
                    <p style="color: var(--color-text-muted); font-size: 0.85em; margin-top: 15px; text-align: center;">
                        Photos will be compressed to save space. You can add ${remaining} more.
                    </p>
                `;

                if (appState.tempFiles) {
                    setTimeout(() => processPhotoUpload(appState.tempFiles, limit), 100);
                }

            } else if (appState.selectedPhotoOption === 'full') {
                const limit = 20;
                const remaining = limit - appState.uploadedPhotos.length;
                html = `
                    <h3 style="color: white; margin-bottom: 15px; font-size: 1.1em;">📷 Full Gallery (${limit} maximum)</h3>
                    <p style="color: var(--color-text-secondary); margin-bottom: 15px;">
                        Upload up to ${limit} photos. We'll optimize them for your device storage.
                    </p>
                    <div style="text-align: center; margin: 20px 0;">
                        <button class="btn-primary" onclick="uploadPhotos(${limit})" style="padding: 12px 30px;">
                            📱 ${appState.tempFiles ? `Upload ${appState.tempFiles.length} Selected` : 'Select Photos'}
                        </button>
                        ${appState.tempFiles ? '' : '<p style="color: var(--color-text-muted); font-size: 0.9em; margin-top: 10px;">Select photos from your device</p>'}
                    </div>
                    <p style="color: var(--color-text-muted); font-size: 0.85em; margin-top: 15px; text-align: center;">
                        Photos will be optimized. You can add ${remaining} more.
                    </p>
                `;

                if (appState.tempFiles) {
                    setTimeout(() => processPhotoUpload(appState.tempFiles, limit), 100);
                }

            } else if (appState.selectedPhotoOption === 'unlimited') {
                html = `
                    <h3 style="color: white; margin-bottom: 15px; font-size: 1.1em;">🌐 Unlimited Photos (URLs)</h3>
                    <p style="color: var(--color-text-secondary); margin-bottom: 15px;">
                        Use image links from free hosting services. No limits on number of photos.
                    </p>
                    <div class="form-group">
                        <textarea id="unlimitedPhotoUrls" class="form-input form-textarea" 
                                  placeholder="Paste image URLs here (one per line)&#10;Example:&#10;https://example.com/photo1.jpg&#10;https://example.com/photo2.jpg"
                                  oninput="updateUnlimitedPhotoCount()"></textarea>
                    </div>
                    <div id="unlimitedPhotoCount" style="color: var(--color-text-secondary); font-size: 0.85em; margin-top: 8px;"></div>
                    <div style="margin-top: 15px; padding: 15px; background: rgba(190, 81, 3, 0.05); border-radius: 8px;">
                        <p style="color: var(--color-text-secondary); margin-bottom: 10px; font-size: 0.9em;">
                            💡 <strong>How to get image URLs:</strong>
                        </p>
                        <ul style="color: var(--color-text-secondary); font-size: 0.85em; padding-left: 20px;">
                            <li><strong>On iPhone:</strong> Upload to Imgur.com from Safari, then copy the image link</li>
                            <li><strong>On Android:</strong> Use Google Photos → Share → Copy link</li>
                            <li><strong>Any device:</strong> Dropbox → Create shared link</li>
                        </ul>
                        <p style="color: var(--color-text-secondary); font-size: 0.85em; margin-top: 10px;">
                            Once you have the URLs, paste them above (one per line).
                        </p>
                    </div>
                `;
            }

            uploadArea.innerHTML = html;
            appState.tempFiles = null;
            renderSelectedPhotosPreview();
        }

        function uploadPhotos(limit) {
            if (appState.tempFiles) {
                processPhotoUpload(appState.tempFiles, limit);
                appState.tempFiles = null;
            } else {
                document.getElementById('photoUpload').setAttribute('data-limit', limit);
                document.getElementById('photoUpload').click();
            }
        }

        async function processPhotoUpload(files, limit) {
            if (appState.uploadedPhotos.length + files.length > limit) {
                showToast(`Maximum ${limit} photos allowed for this option`, 'warning');
                files.splice(limit - appState.uploadedPhotos.length);
            }

            let processedCount = 0;

            for (const file of files) {
                try {
                    const compressed = await compressImage(file);
                    appState.uploadedPhotos.push({
                        id: Date.now() + Math.random(),
                        name: file.name,
                        data: compressed,
                        size: compressed.length,
                        type: file.type
                    });
                    processedCount++;
                } catch (error) {
                    console.error('Error processing image:', error);
                    showToast(`Error processing ${file.name}`, 'error');
                }
            }

            if (processedCount > 0) {
                showToast(`Added ${processedCount} photo${processedCount > 1 ? 's' : ''}`, 'success');
                renderSelectedPhotosPreview();
            }
        }

        async function compressImage(file) {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.readAsDataURL(file);

                reader.onload = (e) => {
                    const img = new Image();
                    img.src = e.target.result;

                    img.onload = () => {
                        const canvas = document.createElement('canvas');
                        const ctx = canvas.getContext('2d');

                        let width = img.width;
                        let height = img.height;
                        const maxSize = appState.selectedPhotoOption === 'simple' ? 800 : 1200;

                        if (width > height && width > maxSize) {
                            height = (height * maxSize) / width;
                            width = maxSize;
                        } else if (height > maxSize) {
                            width = (width * maxSize) / height;
                            height = maxSize;
                        }

                        canvas.width = width;
                        canvas.height = height;

                        ctx.drawImage(img, 0, 0, width, height);
                        const quality = appState.selectedPhotoOption === 'simple' ? 0.6 : 0.7;
                        const compressedData = canvas.toDataURL('image/jpeg', quality);
                        resolve(compressedData);
                    };

                    img.onerror = reject;
                };

                reader.onerror = reject;
            });
        }

        function renderSelectedPhotosPreview() {
            const container = document.getElementById('selectedPhotosPreview');

            if (appState.uploadedPhotos.length === 0) {
                container.innerHTML = '<p style="color: var(--color-text-secondary); text-align: center; padding: 20px;">No photos added yet</p>';
                return;
            }

            container.innerHTML = appState.uploadedPhotos.map((photo, index) => `
                <div class="photo-preview">
                    <img src="${photo.data}" alt="Photo ${index + 1}">
                    <button class="photo-remove" onclick="removeUploadedPhoto(${index})">×</button>
                </div>
            `).join('');
        }

        function removeUploadedPhoto(index) {
            appState.uploadedPhotos.splice(index, 1);
            renderSelectedPhotosPreview();
            showToast('Photo removed', 'info');
        }

        function updateUnlimitedPhotoCount() {
            const textarea = document.getElementById('unlimitedPhotoUrls');
            if (!textarea) return;

            const photoCount = textarea.value.split('\n').filter(url => url.trim()).length;
            const countDisplay = document.getElementById('unlimitedPhotoCount');
            if (countDisplay) {
                countDisplay.textContent = `${photoCount} photos added`;
            }
        }

        // ==================== UPDATED EXISTING FUNCTIONS ====================
        function toggleView(view) {
            const homeView = document.getElementById('home-view');
            const formView = document.getElementById('form-view');
            const memorialView = document.getElementById('memorial-view');
            const buttons = document.querySelectorAll('.view-toggle .btn');

            buttons.forEach(btn => btn.classList.remove('active'));
            homeView.classList.remove('active');
            formView.style.display = 'none';
            memorialView.classList.remove('active');

            if (view === 'home') {
                homeView.classList.add('active');
                buttons[0].classList.add('active');
                loadAllMemorials();
            } else if (view === 'form') {
                formView.style.display = 'block';
                buttons[1].classList.add('active');
                loadFormData();
            } else if (view === 'memorial') {
                memorialView.classList.add('active');
                buttons[2].classList.add('active');
                displayMemorial();
            }
        }

        function loadAllMemorials() {
            const saved = localStorage.getItem('sacredSpacesMemorials');
            if (saved) {
                try {
                    appState.memorials = JSON.parse(saved);
                    updateMemorialsList();
                } catch (error) {
                    console.error('Error loading memorials:', error);
                }
            }
        }

        function updateMemorialsList() {
            const container = document.getElementById('memorialsContainer');
            const listSection = document.getElementById('sacredSpacesList');

            if (appState.memorials.length === 0) {
                listSection.style.display = 'none';
                return;
            }

            listSection.style.display = 'block';

            container.innerHTML = appState.memorials.map(memorial => `
                <div class="memorial-item ${memorial.id === appState.currentMemorialId ? 'active' : ''}" 
                     onclick="switchToMemorial('${memorial.id}')">
                    <div>
                        <div class="memorial-item-name">
                            ${memorial.id === appState.currentMemorialId ? '<span class="active-indicator">🕯️</span>' : ''}
                            ${escapeHtml(memorial.name)}
                        </div>
                        <div class="memorial-item-dates">
                            ${memorial.birthDate ? formatDate(memorial.birthDate) : ''} 
                            ${memorial.birthDate && memorial.passingDate ? '—' : ''}
                            ${memorial.passingDate ? formatDate(memorial.passingDate) : ''}
                        </div>
                    </div>
                    <div style="color: var(--color-text-secondary); font-size: 0.85em;">
                        ${memorial.photos?.length || 0} 📸
                    </div>
                </div>
            `).join('');
        }

        function switchToMemorial(id) {
            appState.currentMemorialId = id;
            const memorial = appState.memorials.find(m => m.id === id);
            if (memorial) {
                memorial.lastVisited = new Date().toISOString();
                saveAllMemorials();
                Object.assign(memorialData, memorial);
                toggleView('memorial');
            }
        }

        function saveMemorial() {
            const name = document.getElementById('memorialName').value;
            if (!name.trim()) {
                showToast('Please enter a name for the memorial.', 'warning');
                return;
            }

            // Collect photos
            let photos = [];
            if (appState.selectedPhotoOption === 'unlimited') {
                const urls = document.getElementById('unlimitedPhotoUrls')?.value
                    .split('\n')
                    .map(url => url.trim())
                    .filter(url => url) || [];
                photos = urls.map(url => ({ url }));
            } else {
                photos = appState.uploadedPhotos.map(photo => ({
                    data: photo.data,
                    name: photo.name
                }));
            }

            // Update memorialData
            memorialData.name = name;
            memorialData.email = document.getElementById('memorialEmail').value;
            memorialData.phone = document.getElementById('memorialPhone').value;
            memorialData.birthDate = document.getElementById('memorialBirthDate').value;
            memorialData.passingDate = document.getElementById('memorialPassingDate').value;
            memorialData.mainPhotoData = appState.profilePhotoData;
            memorialData.mainPhotoUrl = document.getElementById('profilePhotoUrl').value;
            memorialData.personalNote = document.getElementById('personalNote').value;
            memorialData.photos = photos;
            memorialData.photoOption = appState.selectedPhotoOption;

            // Clear and rebuild memories
            memorialData.memories = [];
            document.querySelectorAll('.memory-title').forEach((el, i) => {
                const title = el.value;
                const content = el.parentElement.querySelector('.memory-content').value;
                if (title.trim() || content.trim()) {
                    memorialData.memories.push({ title, content });
                }
            });

            // Save to multiple memorials system
            const memorialId = appState.currentMemorialId || 'memorial-' + Date.now();
            memorialData.id = memorialId;
            memorialData.createdAt = new Date().toISOString();
            memorialData.lastVisited = new Date().toISOString();

            // Add or update in memorials array
            const existingIndex = appState.memorials.findIndex(m => m.id === memorialId);
            if (existingIndex !== -1) {
                appState.memorials[existingIndex] = memorialData;
            } else {
                appState.memorials.push(memorialData);
            }

            appState.currentMemorialId = memorialId;

            // Reset form state
            appState.uploadedPhotos = [];
            appState.selectedPhotoOption = null;
            appState.profilePhotoData = null;

            try {
                localStorage.setItem('memorialData', JSON.stringify(memorialData));
                saveAllMemorials();

                showToast('✓ Memorial saved successfully! Your memorial is safe on this device.', 'success');
                toggleView('memorial');
            } catch (error) {
                console.error('✗ localStorage failed:', error);
                alert('⚠️ WARNING: Could not save to device storage.\n\nOn iPhone Safari: Go to Settings > Safari > Privacy > Block All Cookies OFF\n\nOr use Chrome/Firefox app instead.\n\nError: ' + error.message);
            }
        }

        // ==================== HELPER FUNCTIONS ====================
        function showToast(message, type = 'info') {
            const toast = document.getElementById('toast');
            const toastMessage = document.getElementById('toastMessage');

            toastMessage.textContent = message;
            toast.className = 'toast';
            toast.classList.add('show');

            if (type === 'error') {
                toast.style.borderLeftColor = '#e74c3c';
            } else if (type === 'warning') {
                toast.style.borderLeftColor = '#f39c12';
            } else if (type === 'success') {
                toast.style.borderLeftColor = '#2ecc71';
            }

            setTimeout(() => {
                toast.classList.remove('show');
            }, 3000);
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        function formatDate(dateString) {
            if (!dateString) return '';
            const date = new Date(dateString);
            return date.toLocaleDateString('en-US', { 
                month: 'short', 
                day: 'numeric', 
                year: 'numeric' 
            });
        }

        // ==================== INITIALIZATION ====================
        window.addEventListener('load', () => {
            const saved = localStorage.getItem('memorialData');
            if (saved) {
                try {
                    memorialData = JSON.parse(saved);
                } catch (error) {
                    console.error('Error loading memorial data:', error);
                }
            }

            loadAllMemorials();

            // Hide PWA prompt if already installed or dismissed
            if (appState.isPWA || localStorage.getItem('pwaDismissed')) {
                document.getElementById('pwaInstallPrompt').style.display = 'none';
            }
        });

    </script>
</body>
</html>
