function openPhotoUploader(limit) {
    // Create a file input
    const fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = 'image/*';
    fileInput.multiple = true;
    fileInput.style.display = 'none';

    fileInput.onchange = (e) => {
        const files = Array.from(e.target.files);
        processPhotoUpload(files, limit);
    };

    document.body.appendChild(fileInput);
    fileInput.click();
    setTimeout(() => {
        document.body.removeChild(fileInput);
    }, 1000);
}

function handlePhotoUpload(event) {
    const files = Array.from(event.target.files);
    const limit = parseInt(event.target.getAttribute('data-limit')) || 20;
    processPhotoUpload(files, limit);
}

async function processPhotoUpload(files, limit) {
    if (appState.uploadedPhotos.length + files.length > limit) {
        showToast(`Maximum ${limit} photos allowed for this option`, 'warning');
        files.splice(limit - appState.uploadedPhotos.length);
    }

    let processedCount = 0;

    for (const file of files) {
        try {
            const compressed = await compressImage(file);
            appState.uploadedPhotos.push({
                id: Date.now() + Math.random(),
                name: file.name,
                data: compressed,
                size: compressed.length,
                type: file.type
            });
            processedCount++;
        } catch (error) {
            console.error('Error processing image:', error);
            showToast(`Error processing ${file.name}`, 'error');
        }
    }

    if (processedCount > 0) {
        showToast(`Added ${processedCount} photo${processedCount > 1 ? 's' : ''}`, 'success');
        renderSelectedPhotosPreview();
    }
}

async function compressImage(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);

        reader.onload = (e) => {
            const img = new Image();
            img.src = e.target.result;

            img.onload = () => {
                const canvas = document.createElement('canvas');
                const ctx = canvas.getContext('2d');

                let width = img.width;
                let height = img.height;
                const maxSize = appState.selectedPhotoOption === 'simple' ? 800 : 1200;

                if (width > height && width > maxSize) {
                    height = (height * maxSize) / width;
                    width = maxSize;
                } else if (height > maxSize) {
                    width = (width * maxSize) / height;
                    height = maxSize;
                }

                canvas.width = width;
                canvas.height = height;

                ctx.drawImage(img, 0, 0, width, height);
                const quality = appState.selectedPhotoOption === 'simple' ? 0.6 : 0.7;
                const compressedData = canvas.toDataURL('image/jpeg', quality);
                resolve(compressedData);
            };

            img.onerror = reject;
        };

        reader.onerror = reject;
    });
}

