## **1. Fix Profile Image Resizing & Optimization**

Add this to your `app.js` file. Find the `handleProfilePhotoUpload` function and replace it with this optimized version:

```javascript
function handleProfilePhotoUpload(event) {
    const file = event.target.files[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
        showToast('Please select an image file', 'warning');
        return;
    }

    // Check file size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
        showToast('Image too large. Please select an image under 5MB.', 'warning');
        return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
        // Resize and compress the image
        optimizeProfileImage(e.target.result, 300, 300, 0.8).then(optimizedImage => {
            appState.profilePhotoData = optimizedImage;
            updateProfilePhotoPreview();
            showToast('Profile photo optimized and added', 'success');
        }).catch(error => {
            console.error('Error optimizing image:', error);
            // Fallback to original if optimization fails
            appState.profilePhotoData = e.target.result;
            updateProfilePhotoPreview();
            showToast('Profile photo added', 'success');
        });
    };
    reader.readAsDataURL(file);
}

// New function to optimize profile images
function optimizeProfileImage(dataUrl, maxWidth, maxHeight, quality) {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.src = dataUrl;

        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');

            // Calculate new dimensions maintaining aspect ratio
            let width = img.width;
            let height = img.height;

            if (width > height) {
                if (width > maxWidth) {
                    height = (height * maxWidth) / width;
                    width = maxWidth;
                }
            } else {
                if (height > maxHeight) {
                    width = (width * maxHeight) / height;
                    height = maxHeight;
                }
            }

            canvas.width = width;
            canvas.height = height;

            // Draw and compress
            ctx.drawImage(img, 0, 0, width, height);
            const optimizedData = canvas.toDataURL('image/jpeg', quality);
            resolve(optimizedData);
        };

        img.onerror = reject;
    });
}
```

