}

function updateTimer() {
    if (appState.timeRemaining > 0) {
        appState.timeRemaining--;

        // Update display
        const timerTime = document.getElementById('timerTime');
        if (timerTime) {
            timerTime.textContent = formatTime(appState.timeRemaining);
        }

        // Update progress bar
        const totalSeconds = appState.selectedTimerMinutes * 60;
        const progressPercent = (appState.timeRemaining / totalSeconds) * 100;
        const progressFill = document.getElementById('timerProgress');
        if (progressFill) {
            progressFill.style.width = `${progressPercent}%`;
        }

        // Gentle reminder at 1 minute remaining
        if (appState.timeRemaining === 60) {
            showToast('One minute remaining in your sacred time', 'info');
        }
    } else {
        // Timer completed
        clearInterval(appState.meditationTimer);
        appState.timerRunning = false;

        // Play gentle sound
        const timerSound = document.getElementById('timerSound');
        if (timerSound) {
