                    <button class="btn-primary" onclick="toggleView('memorial')">Return to Memorial</button>
                </div>
            `;
        }

        showToast('Your sacred time is complete. Continue sitting or return when ready.', 'success');
    }
}

function pauseResumeTimer() {
    if (appState.timerRunning) {
        clearInterval(appState.meditationTimer);
        appState.timerRunning = false;
        document.getElementById('timerPauseBtn').textContent = 'Resume';

        // Pause progress animation
        const progressFill = document.getElementById('timerProgress');
        if (progressFill) {
            progressFill.style.animationPlayState = 'paused';
        }
    } else {
        appState.timerRunning = true;
        appState.meditationTimer = setInterval(updateTimer, 1000);
        document.getElementById('timerPauseBtn').textContent = 'Pause';

        // Resume progress animation
        const progressFill = document.getElementById('timerProgress');
        if (progressFill) {
            progressFill.style.animationPlayState = 'running';
        }
    }
}

function stopTimer() {
    clearInterval(appState.meditationTimer);
    appState.timerRunning = false;

    const timerDisplay = document.querySelector('.timer-display');
    if (timerDisplay) {
        timerDisplay.remove();
    }

    showToast('Timer stopped', 'info');
}

function addTime(minutes) {
    appState.timeRemaining += minutes * 60;
    appState.selectedTimerMinutes += minutes;

    // Update progress bar animation
    const progressFill = document.getElementById('timerProgress');
    if (progressFill) {
        const totalSeconds = appState.selectedTimerMinutes * 60;
        progressFill.style.animationDuration = `${totalSeconds}s`;
    }

    showToast(`Added ${minutes} minutes`, 'success');
}

function formatTime(seconds) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
}
