function saveMemorial() {
    try {
        // Test if localStorage is available
        localStorage.setItem('test', 'test');
        localStorage.removeItem('test');

        const firstName = document.getElementById('memorialFirstName').value.trim();
        const lastName = document.getElementById('memorialLastName').value.trim();
        const middleName = document.getElementById('memorialMiddleName').value.trim();

        if (!firstName || !lastName) {
            showToast('Please enter first and last name.', 'warning');
            return;
        }

        // Collect photos
        let photos = [];
        if (appState.selectedPhotoOption === 'unlimited') {
            const urls = document.getElementById('unlimitedPhotoUrls')?.value
                .split('\n')
                .map(url => url.trim())
                .filter(url => url) || [];
            photos = urls.map(url => ({ url }));
        } else {
            photos = appState.uploadedPhotos.map(photo => ({
                data: photo.data,
                name: photo.name
            }));
        }

        // Update memorialData
        memorialData.firstName = firstName;
        memorialData.middleName = middleName;
        memorialData.lastName = lastName;
        memorialData.name = `${firstName} ${middleName ? middleName + ' ' : ''}${lastName}`;
        memorialData.email = document.getElementById('memorialEmail').value;
        memorialData.phone = document.getElementById('memorialPhone').value;
        memorialData.birthDate = document.getElementById('memorialBirthDate').value;
        memorialData.passingDate = document.getElementById('memorialPassingDate').value;
        memorialData.mainPhotoData = appState.profilePhotoData;
        memorialData.mainPhotoUrl = document.getElementById('profilePhotoUrl').value;
        memorialData.personalNote = document.getElementById('personalNote').value;
        memorialData.photos = photos;
        memorialData.photoOption = appState.selectedPhotoOption;

        // Save to multiple memorials system
        const memorialId = appState.currentMemorialId || 'memorial-' + Date.now();
        memorialData.id = memorialId;
        memorialData.createdAt = new Date().toISOString();
        memorialData.lastVisited = new Date().toISOString();

        // Add or update in memorials array
        const existingIndex = appState.memorials.findIndex(m => m.id === memorialId);
        if (existingIndex !== -1) {
            appState.memorials[existingIndex] = memorialData;
        } else {
            appState.memorials.push(memorialData);
        }

        appState.currentMemorialId = memorialId;

        // Save everything
        localStorage.setItem('memorialData', JSON.stringify(memorialData));
        saveAllMemorials();

        // Reset form state
        appState.uploadedPhotos = [];
        appState.selectedPhotoOption = null;
        appState.profilePhotoData = null;

        showToast('✓ Memorial saved successfully!', 'success');
        toggleView('memorial');

    } catch (error) {
        console.error('Save error:', error);

        // Fallback: Download as file
        const dataStr = JSON.stringify(memorialData, null, 2);
        const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
        const fileName = `memorial-${memorialData.name.toLowerCase().replace(/\s+/g, '-')}.json`;

        const link = document.createElement('a');
        link.setAttribute('href', dataUri);
        link.setAttribute('download', fileName);
        link.click();

        showToast('⚠️ Saved as backup file due to storage restrictions. Please download it.', 'warning');
    }
}

function saveAllMemorials() {
    try {
        localStorage.setItem('sacredSpacesMemorials', JSON.stringify(appState.memorials));
    } catch (error) {
        console.error('Error saving memorials:', error);
        showToast('Error saving memorials', 'error');
