    margin-bottom: 15px !important;
}

.home-section-compact p {
    margin: 0;
    font-size: 0.9em;
    line-height: 1.5;
}

.home-image {
    width: 100%;
    max-width: 280px;
    height: auto;
    border-radius: 10px;
    margin: 15px auto;
    display: block;
    box-shadow: var(--shadow-md);
    object-fit: cover;
    aspect-ratio: 6/5;
    background: linear-gradient(135deg, #8B3A02 0%, #BE5103 100%);
    transition: opacity 0.3s ease;
}

/* Forms */
.form-section {
    background: var(--color-bg-secondary);
    border-radius: 12px;
    padding: 15px;
    /* Reduced padding */
    margin-bottom: 15px;
    box-shadow: var(--shadow-md);
    border-left: 4px solid var(--color-copper);
    max-width: 480px;
    margin-left: auto;
    margin-right: auto;
}

.form-section h2 {
    font-size: 1.1em;
    /* Kept similar but ensure alignment */
    margin-bottom: 15px;
    color: white;
    text-align: center;
}

.form-group {
    margin-bottom: 15px;
}

label {
    display: block;
    margin-bottom: 6px;
    font-weight: 500;
    color: #D3D3D3;
    font-size: 0.9em;
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="date"],
textarea,
select {
    width: 100%;
    padding: 10px;
    border: 1px solid var(--color-border);
    border-radius: 8px;
    font-family: inherit;
    font-size: 0.95em;
    color: var(--color-text-primary);
    background-color: var(--color-bg-primary);
    transition: border-color 0.3s;
}

input:focus,
textarea:focus,
select:focus {
    outline: none;
    border-color: var(--color-copper);
    box-shadow: 0 0 0 3px rgba(190, 81, 3, 0.2);
}

textarea {
    resize: vertical;
    min-height: 100px;
    font-family: inherit;
}

/* Memorials List */
.sacred-spaces-list {
    background: var(--color-bg-secondary);
    border-radius: 12px;
    padding: 15px;
    margin: 25px auto 20px auto;
    border-left: 4px solid var(--color-copper);
    border: 1px solid var(--color-border);
    max-width: 500px;
}

.sacred-spaces-list h3 {
    color: white;
    margin-bottom: 15px;
    font-size: 1em;
    /* Reduced from 1.05em */
    text-align: center;
}

.memorials-container {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.memorial-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px;
    background: rgba(190, 81, 3, 0.08);
    border-radius: 8px;
    border: 1px solid var(--color-border);
    cursor: pointer;
    transition: all 0.2s ease;
}

.memorial-item:hover {
    background: rgba(190, 81, 3, 0.12);
    transform: translateX(5px);
}

.memorial-item.active {
    background: rgba(190, 81, 3, 0.15);
    border-left: 3px solid var(--color-accent);
}

.memorial-item-name {
    font-weight: 500;
    color: var(--color-text-primary);
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.95em;
}

.active-indicator {
    color: var(--color-accent-light);
    font-size: 0.85em;
    animation: breathing-glow 2s ease-in-out infinite;
}

.memorial-item-dates {
    font-size: 0.8em;
    color: var(--color-text-secondary);
}

/* Memorial View Components */
.memorial-card {
    background: linear-gradient(135deg, var(--color-bg-secondary) 0%, var(--color-bg-secondary) 100%);
    border-radius: 12px;
    padding: 20px 15px;
    /* Reduced vertical padding */
    box-shadow: var(--shadow-md);
    text-align: center;
    margin-bottom: 20px;
    border: 1px solid var(--color-border);
    max-width: 480px;
    margin-left: auto;
    margin-right: auto;
}

.memorial-header {
    margin-bottom: 25px;
}

.memorial-name {
    font-size: 1.3em;
    /* Reduced from 1.5em */
    font-weight: 600;
    color: white;
    margin-bottom: 6px;
}

.memorial-dates {
    font-size: 1em;
    color: var(--color-accent-light);
    font-style: italic;
}

.memorial-photo {
    width: 180px;
    height: 180px;
    border-radius: 100%;
    object-fit: cover;
    border: 4px solid var(--color-copper);
    margin: 0 auto 15px;
    display: block;
    box-shadow: 0 0 25px rgba(212, 145, 92, 0.3);
    max-width: 100%;
    max-height: 100%;
}

.memorial-section {
    background: var(--color-bg-secondary);
    border-radius: 12px;
    padding: 15px;
    margin-bottom: 12px;
    border-left: 4px solid var(--color-copper);
    text-align: center;
    border: 1px solid var(--color-border);
}

.memorial-section h3 {
    color: white;
    margin-bottom: 12px;
    font-size: 1.0em;
    /* Reduced */
}

.memory-item {
    background: rgba(190, 81, 3, 0.08);
    padding: 12px;
    border-radius: 8px;
    margin-bottom: 10px;
    border-left: 3px solid var(--color-copper);
}

.memory-item strong {
    display: block;
    color: var(--color-copper-light);
    margin-bottom: 4px;
    font-size: 0.95em;
}

/* Gallery ambience strip */
.gallery-ambience {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  margin-bottom: 10px;
}
.gallery-music-choices {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 10px;
  flex-wrap: wrap;
}

.audio-choice-btn {
  padding: 3px 10px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.25);
  background: rgba(0,0,0,0.35);
  color: var(--color-text-primary);
  font-size: 0.8rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.audio-choice-btn.active {
  background: var(--color-accent-light);
  border-color: var(--color-accent-light);
  color: #000;
}

/* Tile wall gallery */
.memory-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 8px;
  margin-top: 8px;
}

.memory-gallery-tile {
  position: relative;
  border-radius: 10px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.08), transparent 55%);
  cursor: pointer;
  isolation: isolate;
}

.memory-gallery-tile::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(0,0,0,0.18),
    rgba(0,0,0,0.4)
  );
  opacity: 0;
  transition: opacity 0.3s ease;
}

.memory-gallery-tile img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transform: scale(1.02);
  transition: transform 0.4s ease, filter 0.4s ease;
}

.memory-gallery-tile:hover img {
  transform: scale(1.06);
  filter: saturate(1.05);
}

.memory-gallery-tile:hover::after {
  opacity: 1;
}
.memory-gallery-tile.selected {
  box-shadow: 0 0 20px rgba(190, 81, 3, 0.6);
}

/* Optional: keep photo-preview grid used in the form previews */
.photo-preview-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(70px, 1fr));
  gap: 8px;
  margin-top: 8px;
}

.photo-preview {
  position: relative;
  overflow: hidden;
  border-radius: 8px;
  box-shadow: var(--shadow-sm);
  aspect-ratio: 1;
}

.photo-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.photo-preview:hover img {
  transform: scale(1.05);
}

.photo-remove {
  position: absolute;
  top: 5px;
  right: 5px;
  background: rgba(0, 0, 0, 0.7);
  color: white;
  border: none;
  border-radius: 50%;
  width: 22px;
  height: 22px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75em;
}

/* Small-screen tweak */
@media (max-width: 768px) {
  .memory-gallery {
    grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
    gap: 10px;
  }
}

/* Modals */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(10, 12, 8, 0.95);
    z-index: 1000;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 15px;
    animation: fade-in 0.3s ease-out;
}

.modal-overlay.active {
    display: flex;
}

.modal-content {
    background: var(--color-bg-secondary);
    border-radius: 12px;
    padding: 25px;
    max-width: 480px;
    width: 100%;
    border: 1px solid var(--color-border);
    box-shadow: var(--shadow-lg);
    border-left: 4px solid var(--color-copper);
}

.modal-title {
    color: white;
    font-size: 1.25em;
    margin-bottom: 15px;
    text-align: center;
}

/* Photo Options */
.photo-options-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 12px;
    margin-bottom: 20px;
}

.photo-option {
    padding: 15px;
    background: var(--color-bg-primary);
    border-radius: 8px;
    border: 2px solid var(--color-border);
    cursor: pointer;
    transition: all 0.3s ease;
}

.photo-option:hover {
    border-color: var(--color-accent-light);
    transform: translateY(-2px);
}

.photo-option.selected {
    border-color: var(--color-accent);
    background: rgba(190, 81, 3, 0.05);
}

.option-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 8px;
}

.option-icon {
    font-size: 1.4em;
}

.option-title {
    font-weight: 500;
    color: white;
    font-size: 1.05em;
}

.option-desc {
    color: var(--color-text-secondary);
    font-size: 0.85em;
    line-height: 1.5;
}

/* Sacred Time */
.ritual-section {
    background: var(--color-bg-secondary);
    border-radius: 12px;
    padding: 20px;
    margin: 25px 0;
    border-left: 4px solid var(--color-copper);
    text-align: center;
    border: 1px solid var(--color-border);
}

.ritual-section h3 {
    color: white;
    margin-bottom: 12px;
    font-size: 1.05em;
}

.ritual-description {
    color: var(--color-text-secondary);
    margin-bottom: 15px;
    line-height: 1.5;
    font-size: 0.95em;
}

.sacred-time-modal .modal-content {
    max-width: 550px;
    max-height: 85vh;
    display: flex;
    flex-direction: column;
}

.photo-selection {
    margin: 15px 0;
}

.photo-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(90px, 1fr));
    gap: 8px;
    margin-top: 12px;
    max-height: 180px;
    overflow-y: auto;
    padding: 8px;
    background: var(--color-bg-primary);
    border-radius: 8px;
    border: 1px solid var(--color-border);
}

.selectable-photo {
    position: relative;
    border-radius: 8px;
    overflow: hidden;
    aspect-ratio: 1;
    cursor: pointer;
    border: 2px solid transparent;
    transition: all 0.2s ease;
}

.selectable-photo:hover {
    transform: scale(1.05);
}

.selectable-photo.selected {
    border-color: var(--color-accent);
    box-shadow: 0 0 15px rgba(190, 81, 3, 0.3);
}

.selectable-photo img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Sacred Time Revamp */
.sacred-view {
    display: none;
    animation: fade-in 0.4s ease-out;
}

.sacred-view.active {
    display: block;
}

.sacred-guidance-box {
    background: rgba(190, 81, 3, 0.05);
    border: 1px solid rgba(190, 81, 3, 0.2);
    border-radius: 12px;
    padding: 20px;
    margin: 20px 0;
    text-align: left;
}

.sacred-guidance-title {
    color: var(--color-copper);
    font-weight: 600;
    margin-bottom: 15px;
    font-size: 1.1rem;
    text-align: center;
}

.sacred-guidance-list {
    padding-left: 20px;
    color: var(--color-text-secondary);
    line-height: 1.7;
    font-size: 0.95em;
}

.sacred-guidance-list li {
    margin-bottom: 8px;
}

.sacred-guidance-list li::marker {
    color: var(--color-copper);
    font-weight: bold;
}

.focus-photo-container {
    text-align: center;
    margin: 15px 0;
}

.focus-photo {
    width: 180px;
    height: 180px;
    border-radius: 50%;
    object-fit: cover;
    box-shadow: 0 0 35px rgba(190, 81, 3, 0.3);
    border: 3px solid rgba(255, 255, 255, 0.1);
}

.meditation-timer {
    font-size: 3em;
    font-weight: 200;
    color: white;
    text-align: center;
    margin: 15px 0;
    font-feature-settings: "tnum";
    font-variant-numeric: tabular-nums;
}

.meditation-controls {
    display: flex;
    justify-content: center;
    gap: 12px;
    margin-top: 25px;
}

.control-btn {
    width: 45px;
    height: 45px;
    border-radius: 50%;
    border: none;
    background: rgba(255, 255, 255, 0.1);
    color: white;
    font-size: 1.1em;
    cursor: pointer;
    transition: all 0.2s;
    display: flex;
    align-items: center;
    justify-content: center;
}

.control-btn:hover {
    background: rgba(255, 255, 255, 0.2);
    transform: scale(1.1);
}

.control-btn.primary {
    background: #BE5103;
}

.control-btn.primary:hover {
    background: #D96B1F;
}

/* Photo Grid Selection */
.photo-selection-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(70px, 1fr));
    gap: 8px;
    margin: 12px 0 20px 0;
    max-height: 160px;
    overflow-y: auto;
}

.selection-item {
    aspect-ratio: 1;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    border: 2px solid transparent;
    opacity: 0.6;
    transition: all 0.2s;
}

.selection-item.selected {
    border-color: #BE5103;
    opacity: 1;
    transform: scale(1.05);
}

.selection-item img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Backup & Install */
/* --- Memorial Tabs --- */
.memorial-tabs {
    display: flex;
    gap: 10px;
    margin-bottom: 20px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    padding-bottom: 10px;
    overflow-x: auto;
}

.mem-tab {
    background: transparent;
    border: none;
    color: var(--color-text-secondary);
    font-family: inherit;
    font-size: 1rem;
    padding: 8px 15px;
    position: relative;
    cursor: pointer;
    transition: color 0.3s;
    white-space: nowrap;
}

.mem-tab:hover {
    color: var(--color-text-primary);
}

.mem-tab.active {
    color: var(--color-copper);
    font-weight: 600;
}

.mem-tab.active::after {
    content: '';
    position: absolute;
    bottom: -11px;
    /* Overlap border */
    left: 0;
    width: 100%;
    height: 2px;
    background: var(--color-copper);
}

.mem-tab-content {
    display: none;
    animation: fadeIn 0.3s ease;
}

.mem-tab-content.active {
    display: block;
}

/* --- Sacred Timer Redesign --- */
.sacred-timer-buttons {
    display: flex;
    justify-content: center;
    gap: 15px;
    flex-wrap: wrap;
    margin: 20px 0;
}

.btn-timer-option {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.2);
    color: var(--color-text-primary);
    padding: 10px 20px;
    border-radius: 20px;
    cursor: pointer;
    font-family: inherit;
    font-size: 0.95rem;
    transition: all 0.3s ease;
    min-width: 80px;
}

.btn-timer-option:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: var(--color-copper);
    transform: translateY(-2px);
}

.install-section {
    background: var(--color-bg-secondary);
    /* Match other cards */
    border-radius: 12px;
    padding: 15px;
    margin: 0 auto 20px auto;
    max-width: 480px;
    border: 1px solid var(--color-border);
    border-left: 4px solid var(--color-copper);
    box-shadow: var(--shadow-md);
}

.install-modal .modal-content {
    max-width: 480px;
}

.install-step {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 8px;
    padding: 8px;
    background: rgba(255, 255, 255, 0.05);
    border-radius: 6px;
}

.step-number {
    width: 25px;
    height: 25px;
    background: var(--color-accent);
    color: white;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.8em;
}

.step-text {
    color: var(--color-text-primary);
    font-size: 0.9em;
    line-height: 1.4;
}

.backup-footer {
    background: rgba(190, 81, 3, 0.08);
    border-radius: 12px;
    padding: 15px;
    margin-top: 15px;
    border: 1px solid var(--color-border);
    border-top: 3px solid var(--color-accent);
}

.backup-message {
    color: var(--color-text-secondary);
    font-size: 0.85em;
    margin-bottom: 12px;
    line-height: 1.4;
    text-align: center;
}

.backup-buttons {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    justify-content: center;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%) translateY(100px);
    background: var(--color-bg-secondary);
    color: white;
    padding: 12px 20px;
    border-radius: 8px;
    box-shadow: var(--shadow-lg);
    z-index: 1000;
    display: flex;
    align-items: center;
    gap: 8px;
    border-left: 4px solid var(--color-accent);
    transition: transform 0.3s ease;
    max-width: 90%;
    font-size: 0.9em;
}

.toast.show {
    transform: translateX(-50%) translateY(0);
}

/* Actions */
.memorial-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 12px;
    margin-top: 25px;
    margin-bottom: 25px;
}

.memorial-actions button {
    padding: 8px 16px;
    border: none;
    background: transparent;
    color: var(--color-accent-light);
    border-radius: 15px;
    cursor: pointer;
    font-size: 0.85em;
    font-weight: 500;
    transition: all 0.3s ease;
    min-width: 120px;
    border: 1px solid rgba(255, 255, 255, 0.2);
}

.memorial-actions button:hover {
    background: var(--color-accent-light);
    color: #fff;
    border-color: var(--color-accent-light);
}

.return-to-home-container {
    text-align: center;
    margin: 25px 0 20px 0;
    padding-top: 20px;
    border-top: 1px solid var(--color-border);
}

.return-to-home-btn {
    background: transparent;
    color: var(--color-copper-light);
    border: 1px solid var(--color-copper);
    padding: 8px 24px;
    border-radius: 6px;
    font-size: 0.85em;
    cursor: pointer;
    transition: all 0.3s ease;
}

.return-to-home-btn:hover {
    background: var(--color-accent);
    color: #000;
    border-color: var(--color-accent-light);
}

/* Profile Photo additions */
.profile-photo-container {
    text-align: center;
    margin: 20px 0;
}

.profile-photo-preview {
    width: 150px;
    height: 150px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid var(--color-copper);
    margin: 0 auto 15px;
    display: block;
    box-shadow: var(--shadow-md);
    max-width: 100%;
    max-height: 100%;
}

.profile-photo-placeholder {
    width: 150px;
    height: 150px;
    border-radius: 50%;
    background: var(--color-bg-primary);
    border: 3px dashed var(--color-border);
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 15px;
    color: var(--color-text-secondary);
    font-size: 3em;
}

/* Error state for inputs */
input.error,
textarea.error {
    border-color: #d16666 !important;
    box-shadow: 0 0 0 3px rgba(209, 102, 102, 0.3) !important;
    animation: shake 0.4s cubic-bezier(.36, .07, .19, .97) both;
}

@keyframes shake {

    10%,
    90% {
        transform: translate3d(-1px, 0, 0);
    }

    20%,
    80% {
        transform: translate3d(2px, 0, 0);
    }

    30%,
    50%,
    70% {
        transform: translate3d(-4px, 0, 0);
    }

    40%,
    60% {
        transform: translate3d(4px, 0, 0);
    }
}

/* Confirmation Modal Specifics */
#confirmModal .modal-content {
    max-width: 400px;
    text-align: center;
}

#confirmModal .btn-primary {
    background: linear-gradient(135deg, #BE5103 0%, #D96B1F 100%);
    min-width: 100px;
}

#confirmModal .btn-secondary {
    min-width: 100px;
}

/* ========================================== */
/* LIGHTBOX STYLES (ADDED) */
/* ========================================== */

.lightbox-content {
    max-width: 95%;
    position: relative;
    text-align: center;
    background: rgba(10, 12, 8, 0.95);
    border: 2px solid var(--color-copper);
}

.lightbox-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    background: rgba(0, 0, 0, 0.7);
    color: white;
    border: none;
    border-radius: 50%;
    width: 50px;
    height: 50px;
    font-size: 1.5em;
    cursor: pointer;
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
