                                .sort((a, b) => new Date(b.date) - new Date(a.date))
                                .map(
                                    (entry) => `
                                <div class="journal-entry" style="background: rgba(255,255,255,0.05); padding: 15px; border-radius: 8px; margin-bottom: 10px;">
                                    <div style="font-size: 0.8em; color: var(--color-accent); margin-bottom: 5px;">
                                        ${new Date(entry.date).toLocaleString()}
                                    </div>
                                    <div style="white-space: pre-wrap;">${escapeHtml(entry.text)}</div>
                                </div>
                            `
                                )
                                .join('')}
                            ${
                                !memorial.journalEntries || memorial.journalEntries.length === 0
                                    ? '<p style="font-style:italic; color:#888;">No entries yet.</p>'
                                    : ''
                            }
                        </div>
                    </div>
                </div>

                <div class="mem-tab-content" id="tab-sacred">
                    <div class="ritual-section">
                        <h3>A Moment of Remembrance</h3>
                        <p class="ritual-description">
                            Take a moment to honor and remember ${escapeHtml(memorial.firstName || memorial.name)}.
                        </p>

                        <!-- Sacred Time Selection Preview -->
                        <div id="sacredTimePreview" style="margin: 20px 0; text-align: center;">
                            ${
                                selectedSacredPhoto
                                    ? `
                                    <div style="margin-bottom: 15px;">
                                        <div style="font-weight: bold; color: var(--color-copper); margin-bottom: 8px; font-size: 0.9em;">Selected Image for Sacred Time</div>
                                        <img src="${selectedSacredPhoto}" style="width: 120px; height: 120px; object-fit: cover; border-radius: 8px; border: 2px solid var(--color-copper);">
                                    </div>
                                    `
                                    : profilePhotoUrl
                                    ? `
                                    <div style="margin-bottom: 15px;">
                                        <div style="font-weight: bold; color: var(--color-text-secondary); margin-bottom: 8px; font-size: 0.9em;">Profile Image will be used</div>
                                        <img src="${profilePhotoUrl}" style="width: 120px; height: 120px; object-fit: cover; border-radius: 8px; border: 2px solid var(--color-border);">
                                    </div>
                                    `
                                    : `
                                    <div style="margin-bottom: 15px; color: var(--color-text-secondary); font-style: italic; font-size: 0.9em;">
                                        No image selected. Visit the Gallery tab to choose an image for Sacred Time.
                                    </div>
                                    `
                            }
                        </div>

                        <div style="text-align:center; padding: 20px 0;">
                            <div style="margin-bottom:15px; font-weight:bold; color:var(--color-copper);">Set Duration</div>
                            <div class="sacred-timer-buttons">
                                <button class="btn-timer-option" data-time="5">5 Min</button>
                                <button class="btn-timer-option" data-time="15">15 Min</button>
                                <button class="btn-timer-option" data-time="30">30 Min</button>
                                <button class="btn-timer-option" data-time="custom">Custom</button>
                            </div>
                        </div>

                        <div style="margin-top:20px; text-align:center;">
                            <p>This will open a dedicated focus view for your meditation.</p>
                        </div>
                    </div>
                </div>

            </div>
        `;

        this.container.innerHTML = html;

        const grid = this.container.querySelector('#galleryGrid');
        const emptyState = this.container.querySelector('#galleryEmptyState');
        if (grid) {
            grid.innerHTML = '';

            if (galleryPhotos.length > 0) {
                // Store gallery data globally for lightbox navigation
                currentGalleryData.photos = galleryPhotos.map((blob, index) => ({
                    blob,
                    url: URL.createObjectURL(blob),
                    index
                }));
                currentGalleryData.memorialId = memorial.id;

                galleryPhotos.forEach((blob, index) => {
                    const url = URL.createObjectURL(blob);
                    const fig = document.createElement('figure');
                    fig.className = 'memory-gallery-tile';
                    fig.dataset.index = String(index);

                    // Check if this is the selected Sacred Time photo
                    const isSelectedForSacredTime = selectedSacredPhoto === url;
                    if (isSelectedForSacredTime) {
                        fig.classList.add('selected');
                    }

                    fig.innerHTML = `
                        <img src="${url}" alt="Photo ${index + 1}" loading="lazy" />
                        ${isSelectedForSacredTime ? '<div class="sacred-time-badge">⏱️</div>' : ''}
                    `;
                    grid.appendChild(fig);
                });

                if (emptyState) emptyState.style.display = 'none';

                // Add click handlers to gallery tiles
                grid.querySelectorAll('.memory-gallery-tile').forEach((tile, index) => {
                    tile.addEventListener('click', () => {
                        // Update selection state
                        grid.querySelectorAll('.memory-gallery-tile').forEach((t) => {
                            t.classList.remove('selected');
                            // Remove any existing badges
                            const badge = t.querySelector('.sacred-time-badge');
                            if (badge) badge.remove();
                        });

                        // Add selected class and badge
                        tile.classList.add('selected');
                        const badge = document.createElement('div');
                        badge.className = 'sacred-time-badge';
                        badge.textContent = '⏱️';
                        badge.style.cssText = 'position:absolute; top:5px; right:5px; background:var(--color-copper); color:white; border-radius:50%; width:20px; height:20px; font-size:10px; display:flex; align-items:center; justify-content:center;';
                        tile.appendChild(badge);

                        // Set selected photo for Sacred Time
                        const selectedUrl = currentGalleryData.photos[index].url;
                        if (window.app && app.state) {
                            app.state.sacredPhotoByMemorial[memorial.id] = selectedUrl;
                        }

                        // Update the selection indicator
                        const selectionIndicator = document.getElementById('sacredTimeSelection');
                        if (selectionIndicator) {
                            selectionIndicator.style.display = 'block';
                        }

                        // Show success message
                        showToast('Image selected for Sacred Time', 'success');

                        // Show lightbox
                        showLightbox(index);
                    });
                });
            } else {
                if (emptyState) emptyState.style.display = 'block';
            }
        }

        setTimeout(() => {
            const tabs = this.container.querySelectorAll('.mem-tab');
            tabs.forEach((tab) => {
                tab.addEventListener('click', () => {
                    tabs.forEach((t) => t.classList.remove('active'));
                    this.container
                        .querySelectorAll('.mem-tab-content')
                        .forEach((c) => c.classList.remove('active'));

                    tab.classList.add('active');
                    const targetId = `tab-${tab.dataset.tab}`;
                    const target = document.getElementById(targetId);
                    if (target) target.classList.add('active');
                });
            });

            // Sacred Time timer buttons - ONLY use the ones in the Sacred tab
            const sacredTabButtons = this.container.querySelectorAll('#tab-sacred .btn-timer-option');
            sacredTabButtons.forEach((btn) => {
                btn.addEventListener('click', () => {
                    const time = btn.dataset.time;
                    let mins = 0;
                    if (time === 'custom') {
                        const input = prompt('Enter minutes for Sacred Time:');
                        if (input) mins = parseInt(input);
                    } else {
                        mins = parseInt(time);
                    }

                    if (mins && mins > 0) {
                        const activeTitle = $('#activeSacredTitle');
                        const focusPhoto = $('#activeFocusPhoto');

                        if (activeTitle)
                            activeTitle.textContent = `Sacred Time with ${
                                memorial.firstName || memorial.name
                            }`;

                        // Use selected gallery photo or fall back to profile photo
                        let selectedPhotoUrl = null;
                        if (app.state.sacredPhotoByMemorial[memorial.id]) {
                            selectedPhotoUrl = app.state.sacredPhotoByMemorial[memorial.id];
                        } else if (profilePhotoUrl) {
                            selectedPhotoUrl = profilePhotoUrl;
                        }

                        if (focusPhoto && selectedPhotoUrl) {
                            focusPhoto.src = selectedPhotoUrl;
                        } else if (focusPhoto) {
                            focusPhoto.src = profilePhotoUrl || '';
                        }

                        $$('.sacred-view').forEach((el) => el.classList.remove('active'));
                        $('#sacredStepActive').classList.add('active');
                        $('#sacredTimeModal').classList.add('active');

                        document.dispatchEvent(
                            new CustomEvent('start-sacred-timer', { detail: mins })
                        );
                    }
                });
            });

            const backBtn = $('#backToDashBtn');
            if (backBtn)
                backBtn.addEventListener('click', () => {
                    document.dispatchEvent(new CustomEvent('navigate', { detail: 'dashboard' }));
                });

            const editBtn = $('#editMemorialBtn');
            if (editBtn) {
                editBtn.addEventListener('click', () => {
                    document.dispatchEvent(
                        new CustomEvent('edit-memorial', { detail: memorial.id })
                    );
                });
            }

            const saveJournalBtn = $('#saveJournalBtn');
            if (saveJournalBtn) {
                saveJournalBtn.addEventListener('click', async () => {
                    const input = $('#journalEntryInput');
                    const text = input.value.trim();
                    if (!text) return;

                    if (!memorial.journalEntries) memorial.journalEntries = [];
                    memorial.journalEntries.push({
                        id: generateId(),
                        date: new Date().toISOString(),
                        text
                    });

                    try {
                        await storage.saveMemorial(memorial);
                        showToast('Journal entry saved', 'success');
                        this.render(memorial);
                    } catch (e) {
                        console.error(e);
                        showToast('Failed to save journal', 'error');
                    }
                });
            }
        }, 0);
    }
}

// ==========================================
// LIGHTBOX FUNCTIONS
// ==========================================

function showLightbox(index) {
    if (!currentGalleryData.photos || currentGalleryData.photos.length === 0) return;

    currentGalleryData.currentIndex = index;
    const photo = currentGalleryData.photos[index];

    const modalImg = $('#imageLightboxImg');
    const counter = $('#lightboxCounter');
    const modal = $('#imageLightboxModal');

    if (modalImg && photo) {
        modalImg.src = photo.url;
        counter.textContent = `${index + 1} / ${currentGalleryData.photos.length}`;
        modal.classList.add('active');
    }
}

function navigateLightbox(direction) {
    if (!currentGalleryData.photos || currentGalleryData.photos.length === 0) return;

    let newIndex = currentGalleryData.currentIndex + direction;

    // Wrap around
    if (newIndex < 0) newIndex = currentGalleryData.photos.length - 1;
    if (newIndex >= currentGalleryData.photos.length) newIndex = 0;

    showLightbox(newIndex);
}

function setCurrentPhotoForSacredTime() {
    if (!currentGalleryData.photos || currentGalleryData.photos.length === 0) return;

    const photo = currentGalleryData.photos[currentGalleryData.currentIndex];
    if (photo && window.app && app.state && currentGalleryData.memorialId) {
        app.state.sacredPhotoByMemorial[currentGalleryData.memorialId] = photo.url;
        showToast('Image selected for Sacred Time', 'success');

        // Update UI to show selection
        const selectionIndicator = document.getElementById('sacredTimeSelection');
        if (selectionIndicator) {
            selectionIndicator.style.display = 'block';
        }

        // Close lightbox
        const modal = $('#imageLightboxModal');
        if (modal) modal.classList.remove('active');

        // Refresh the memorial view to show updated selection
        if (window.app && app.state.activeId) {
            setTimeout(() => {
                app.renderActiveMemorial();
            }, 300);
        }
    }
}

// ==========================================
// SACRED TIME MANAGER
// ==========================================

class SacredTimeManager {
    constructor() {
        this.interval = null;
        this.timeRemaining = 0;
        this.selectedMinutes = 0;
    }

    start(minutes) {
        this.selectedMinutes = minutes;
        this.timeRemaining = minutes * 60;
        this.updateDisplay();

        if (this.interval) clearInterval(this.interval);
        showToast('Sacred Time Started', 'info');
        this.interval = setInterval(() => this.tick(), 1000);
    }

    stop() {
        if (this.interval) clearInterval(this.interval);
        this.interval = null;
    }

    tick() {
        this.timeRemaining--;
        if (this.timeRemaining <= 0) {
            this.stop();
            showToast('Sacred Time Complete', 'success');
        }
        this.updateDisplay();
    }

    updateDisplay() {
        const timeEl = $('#meditationTimerDisplay');
        const progressEl = $('#timerProgress');

        if (timeEl) timeEl.textContent = formatTime(this.timeRemaining);
        if (progressEl) {
            const total = this.selectedMinutes * 60;
            const percent = (this.timeRemaining / total) * 100;
            progressEl.style.width = `${percent}%`;
        }
    }
}

// ==========================================
// MAIN APP
// ==========================================

class App {
    constructor() {
        this.router = new Router();
        this.formManager = new FormManager({
            onSave: (memorial) => this.handleMemorialSave(memorial)
        });
        this.memorialCard = new MemorialCard('#memorialDisplay');
        this.sacredTime = new SacredTimeManager();
        this.deferredPrompt = null;
        this.state = {
            memorials: [],
            activeId: null,
            sacredPhotoByMemorial: {}
        };

        document.addEventListener('navigate', (e) => {
            this.router.navigate(e.detail);
            if (e.detail === 'dashboard') this.renderMemorialList();
        });

        document.addEventListener('start-sacred-timer', (e) => {
            const mins = e.detail;
            if (mins && mins > 0) {
                this.sacredTime.start(mins);
            }
        });
    }

    async init() {
        console.log('Initializing App...');

        await storage.initDB();
        this.state.memorials = await storage.getAllMemorials();
        console.log(`Loaded ${this.state.memorials.length} memorials`);

        this.router.init();
        this.bindEvents();
        this.renderMemorialList();
    }

    bindEvents() {
        const homeBtn = $('#homeBtn');
        const createNavBtn = $('#createNavBtn');
        const dashboardBtn = $('#dashboardBtn');
        const createBtn = $('#showCreateFormBtn');
        const cancelBtn = $('#cancelCreateBtn');
        const saveBtn = $('#saveMemorialBtn');
        const fileInput = $('#fileInput');

        if (homeBtn)
            homeBtn.addEventListener('click', () => {
                this.router.navigate('home');
                $$('.view-toggle .btn').forEach((b) => b.classList.remove('active'));
                homeBtn.classList.add('active');
            });

        if (dashboardBtn)
            dashboardBtn.addEventListener('click', () => {
                this.router.navigate('dashboard');
                this.renderMemorialList();

                $('#createFormSection').style.display = 'none';
                if (createBtn) createBtn.style.display = 'inline-block';

                $$('.view-toggle .btn').forEach((b) => b.classList.remove('active'));
                dashboardBtn.classList.add('active');
            });

        if (createNavBtn)
            createNavBtn.addEventListener('click', () => {
                this.router.navigate('dashboard');
                this.renderMemorialList();

                $('#createFormSection').style.display = 'block';
                if (createBtn) createBtn.style.display = 'none';

                $$('.view-toggle .btn').forEach((b) => b.classList.remove('active'));
                createNavBtn.classList.add('active');
            });

        if (createBtn)
            createBtn.addEventListener('click', () => {
                $('#createFormSection').style.display = 'block';
                createBtn.style.display = 'none';
            });

        if (cancelBtn)
            cancelBtn.addEventListener('click', () => {
                $('#createFormSection').style.display = 'none';
                if (createBtn) createBtn.style.display = 'inline-block';
                this.formManager.reset();
            });

        if (saveBtn) saveBtn.addEventListener('click', () => this.formManager.handleSave());

        const deleteBtn = $('#btnDeleteMemorial');
        if (deleteBtn)
            deleteBtn.addEventListener('click', async () => {
                if (
                    confirm(
                        'Are you sure you want to delete this memorial? This cannot be undone.'
                    )
                ) {
                    if (this.formManager.editingId) {
                        await storage.deleteMemorial(this.formManager.editingId);
                        showToast('Memorial deleted', 'success');
                        $('#createFormSection').style.display = 'none';
                        $('#showCreateFormBtn').style.display = 'inline-block';
                        this.state.memorials = await storage.getAllMemorials();
                        this.renderMemorialList();
                        this.router.navigate('dashboard');
                    }
                }
            });

        if (fileInput)
            fileInput.addEventListener('change', async (e) => {
                const file = e.target.files[0];
                if (file) {
                    const resized = await resizeImage(file);
                    this.formManager.setProfilePhoto(resized);
                }
            });

        const galleryInput = $('#galleryInput');
        if (galleryInput)
            galleryInput.addEventListener('change', async (e) => {
                if (e.target.files.length > 0) {
                    const files = Array.from(e.target.files);
                    const resizedFiles = await Promise.all(
                        files.map((f) => resizeImage(f))
                    );
                    this.formManager.addGalleryPhotos(resizedFiles);
                }
            });

        const list = $('#memorialsList');
        if (list)
            list.addEventListener('click', (e) => {
                const item = e.target.closest('.memorial-item');
                if (item) {
                    const id = item.dataset.id;
                    this.setActiveMemorial(id);
                    this.router.navigate('memorial');
                }
            });

        // REMOVED: Duplicate timer button event listener that was conflicting

        const btnSacredStop = $('#btnSacredStop');
        const btnSacredPause = $('#btnSacredPause');
        const btnSacredAdd5 = $('#btnSacredAdd5');
        const btnSacredExit = $('#btnSacredExit');
        const btnSacredCancel = $('#btnSacredCancel');
        const btnSacredBegin = $('#btnSacredBegin');

        if (btnSacredStop)
            btnSacredStop.addEventListener('click', () => {
                this.sacredTime.stop();
                $('#sacredTimeModal').classList.remove('active');
            });

        if (btnSacredPause)
            btnSacredPause.addEventListener('click', () => {
                if (this.sacredTime.interval) {
                    this.sacredTime.stop();
                    btnSacredPause.textContent = '▶';
                } else {
                    this.sacredTime.start(this.sacredTime.timeRemaining / 60);
                    btnSacredPause.textContent = '❚❚';
                }
            });

        if (btnSacredAdd5)
            btnSacredAdd5.addEventListener('click', () => {
                this.sacredTime.timeRemaining += 300;
                this.sacredTime.updateDisplay();
            });

        if (btnSacredExit)
            btnSacredExit.addEventListener('click', () => {
                $('#sacredTimeModal').classList.remove('active');
            });

        if (btnSacredCancel)
            btnSacredCancel.addEventListener('click', () => {
                $('#sacredTimeModal').classList.remove('active');
            });

        if (btnSacredBegin) {
            btnSacredBegin.addEventListener('click', () => {
                const memorial = this.state.memorials.find((m) => m.id === this.state.activeId);
                if (!memorial) return;

                // Use the first timer button's value (5 min) as default
                let mins = 5;

                // Get the selected photo for Sacred Time
                let selectedPhotoUrl = null;
                if (app.state.sacredPhotoByMemorial[memorial.id]) {
                    selectedPhotoUrl = app.state.sacredPhotoByMemorial[memorial.id];
                }

                // Get profile photo as fallback
                let profilePhotoUrl = '';
                if (memorial.profilePhoto) {
                    // Simplified - in reality you'd need to fetch this
                    profilePhotoUrl = 'https://abundantthought.com/contactmemorial/images/dove.png';
                }

                const activeTitle = $('#activeSacredTitle');
                const focusPhoto = $('#activeFocusPhoto');

                if (activeTitle) {
                    activeTitle.textContent = `Sacred Time with ${memorial.firstName || memorial.name}`;
                }

                if (focusPhoto) {
                    if (selectedPhotoUrl) {
                        focusPhoto.src = selectedPhotoUrl;
                    } else if (profilePhotoUrl) {
                        focusPhoto.src = profilePhotoUrl;
                    }
                }

                $$('.sacred-view').forEach((el) => el.classList.remove('active'));
                $('#sacredStepActive').classList.add('active');
                $('#sacredTimeModal').classList.add('active');

                this.sacredTime.start(mins);
            });
        }

        document.addEventListener('edit-memorial', async (e) => {
            const id = e.detail;
            const memorial = this.state.memorials.find((m) => m.id === id);
            if (memorial) {
                await this.formManager.populate(memorial);
                this.router.navigate('dashboard');
                $('#createFormSection').style.display = 'block';
                $('#showCreateFormBtn').style.display = 'none';
            }
        });

        const installBtnFooter = $('#installBtnFooter');
        const requestInstall = async () => {
            if (this.deferredPrompt) {
                this.deferredPrompt.prompt();
                await this.deferredPrompt.userChoice;
                this.deferredPrompt = null;
            } else {
                showToast('Install not available (check browser)', 'info');
            }
        };
        if (installBtnFooter) installBtnFooter.addEventListener('click', requestInstall);

        window.addEventListener('beforeinstallprompt', (e) => {
            e.preventDefault();
            this.deferredPrompt = e;
        });

        const backupBtn = $('#createBackupBtn');
        const restoreBtn = $('#restoreBackupBtn');
        if (backupBtn) backupBtn.addEventListener('click', () => this.handleBackup());
        if (restoreBtn) restoreBtn.addEventListener('click', () => this.handleRestore());

        // Lightbox controls
        const closeImageLightboxBtn = $('#closeImageLightboxBtn');
        if (closeImageLightboxBtn) {
            closeImageLightboxBtn.addEventListener('click', () => {
                const modal = $('#imageLightboxModal');
                if (modal) modal.classList.remove('active');
            });
        }

        const useForSacredBtn = $('#btnUseForSacredTime');
        if (useForSacredBtn) {
            useForSacredBtn.addEventListener('click', () => {
                setCurrentPhotoForSacredTime();
            });
        }

        const lightboxPrevBtn = $('.lightbox-prev');
        const lightboxNextBtn = $('.lightbox-next');
        if (lightboxPrevBtn) {
            lightboxPrevBtn.addEventListener('click', () => navigateLightbox(-1));
        }
        if (lightboxNextBtn) {
            lightboxNextBtn.addEventListener('click', () => navigateLightbox(1));
        }

        // Keyboard navigation for lightbox
        document.addEventListener('keydown', (e) => {
            const modal = $('#imageLightboxModal');
            if (modal.classList.contains('active')) {
                if (e.key === 'ArrowLeft') navigateLightbox(-1);
                if (e.key === 'ArrowRight') navigateLightbox(1);
                if (e.key === 'Escape') modal.classList.remove('active');
            }
        });
    }

    async handleMemorialSave(memorial) {
        await storage.saveMemorial(memorial);
        this.state.memorials = await storage.getAllMemorials();

        $('#createFormSection').style.display = 'none';
        $('#showCreateFormBtn').style.display = 'inline-block';

        this.setActiveMemorial(memorial.id);
        this.renderMemorialList();
        this.router.navigate('memorial');
    }

    setActiveMemorial(id) {
        this.state.activeId = id;
        this.renderActiveMemorial();
        this.renderMemorialList();
    }

    async renderActiveMemorial() {
        const memorial = this.state.memorials.find((m) => m.id === this.state.activeId);
        await this.memorialCard.render(memorial);
    }

    renderMemorialList() {
        const container = $('#memorialsList');
        if (!container) return;

        if (this.state.memorials.length === 0) {
            container.innerHTML =
                '<p style="text-align:center;color:#999;font-style:italic;">No memorials yet. Create one to begin.</p>';
            return;
        }

        container.innerHTML = this.state.memorials
            .map(
                (m) => `
            <div class="memorial-item ${m.id === this.state.activeId ? 'active' : ''}" data-id="${m.id}">
                <div class="memorial-item-name">
                    ${escapeHtml(m.name)}
                </div>
            </div>
        `
            )
            .join('');
    }

    async handleBackup() {
        try {
            const data = await storage.createBackup();
            const blob = new Blob([JSON.stringify(data, null, 2)], {
                type: 'application/json'
            });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `memorial-backup-${new Date().toISOString().split('T')[0]}.json`;
            a.click();
            showToast('Backup created', 'success');
        } catch (e) {
            console.error(e);
            showToast('Backup failed', 'error');
        }
    }

    handleRestore() {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = '.json';
        input.onchange = (e) => {
            const file = e.target.files[0];
            const reader = new FileReader();
            reader.onload = async (ev) => {
                try {
                    const data = JSON.parse(ev.target.result);
                    if (
                        confirm(
                            'This will replace all current memorials with the backup. Continue?'
                        )
                    ) {
                        await storage.restoreBackup(data);
                        location.reload();
                    }
                } catch (err) {
                    showToast('Invalid Backup File', 'error');
                }
            };
            reader.readAsText(file);
        };
        input.click();
    }
}

