(function setupGalleryAmbience() {
  let galleryAudio;
  let galleryOn = false;
  let currentTrack = 1;

  function trackUrl(n) {
    return `https://abundantthought.com/contactmemorial/audio/gallery-ambience${n}.mp3`;
  }

  function ensureAudio() {
    if (!galleryAudio) {
      galleryAudio = new Audio();
      galleryAudio.loop = true;
      galleryAudio.preload = 'none';
      galleryAudio.volume = 0.3;
    }
    return galleryAudio;
  }

  function updateToggleLabel() {
    const btn = document.getElementById('galleryAudioToggle');
    if (!btn) return;
    btn.textContent = galleryOn ? 'On' : 'Off';
  }

  function updateChoiceActive() {
    const buttons = document.querySelectorAll('.audio-choice-btn');
    buttons.forEach(btn => {
      const n = parseInt(btn.dataset.track, 10);
      if (n === currentTrack) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    });
  }

  async function playCurrentTrack(auto = false) {
    const audio = ensureAudio();
    audio.src = trackUrl(currentTrack);
    try {
      await audio.play();
      galleryOn = true;
      updateToggleLabel();
    } catch (err) {
      if (!auto) {
        console.warn('Gallery background play blocked', err);
      }
      galleryOn = false;
      updateToggleLabel();
    }
  }

  function stopPlayback() {
    if (galleryAudio) {
      galleryAudio.pause();
    }
    galleryOn = false;
    updateToggleLabel();
  }

  document.addEventListener('click', async (e) => {
    const toggle = e.target.closest('#galleryAudioToggle');
    if (toggle) {
      if (galleryOn) {
        stopPlayback();
      } else {
        await playCurrentTrack(false);
      }
    }

    const choice = e.target.closest('.audio-choice-btn');
    if (choice) {
      const n = parseInt(choice.dataset.track, 10);
      if (!isNaN(n)) {
        currentTrack = n;
        updateChoiceActive();
        if (galleryOn) {
          await playCurrentTrack(false);
        }
      }
    }
  });

  document.addEventListener('navigate', (e) => {
    if (e.detail !== 'memorial' && galleryAudio) {
      stopPlayback();
    }
  });

  document.addEventListener('click', (e) => {
    const tabBtn = e.target.closest('.mem-tab[data-tab="gallery"]');
    if (tabBtn && !galleryOn) {
      playCurrentTrack(true);
    }
  });

  updateChoiceActive();
  updateToggleLabel();
})();
