// --- forms.js ---
class FormManager {
    constructor(callbacks) {
        this.onSave = callbacks.onSave;
        this.selectedPhotoBlob = null;
        this.selectedDefaultPhoto = null;
        this.additionalPhotos = [];
        this.reset();
    }

    reset() {
        this.editingId = null;
        $('#firstName').value = '';
        $('#middleName').value = '';
        $('#lastName').value = '';
        $('#relationship').value = '';
        $('#birthDate').value = '';
        $('#passingDate').value = '';
        $('#phoneNumber').value = '';
        $('#emailAddress').value = '';
        $('#homeAddress').value = '';
        $('#favoriteMemory').value = '';
        $('#specialQualities').value = '';

        this.selectedPhotoBlob = null;
        this.selectedDefaultPhoto = null;
        this.additionalPhotos = [];

        $('#profilePhotoPreview').style.display = 'none';
        $('#profilePhotoPlaceholder').style.display = 'flex';

        this.galleryPhotos = [];
        this.renderGalleryPreview();

        const title = $('#createFormSection h2');
        if (title) title.textContent = 'Create a Memorial';

        const deleteBtn = $('#btnDeleteMemorial');
        if (deleteBtn) deleteBtn.style.display = 'none';
    }

    async populate(memorial) {
        this.reset();
        this.editingId = memorial.id;

        $('#firstName').value = memorial.firstName || '';
        $('#middleName').value = memorial.middleName || '';
        $('#lastName').value = memorial.lastName || '';
        $('#relationship').value = memorial.relationship || '';
        $('#birthDate').value = memorial.birthDate || '';
        $('#passingDate').value = memorial.passingDate || '';
        $('#phoneNumber').value = memorial.phone || '';
        $('#emailAddress').value = memorial.email || '';
        $('#homeAddress').value = memorial.address || '';
        $('#favoriteMemory').value = memorial.favoriteMemory || '';
        $('#specialQualities').value = memorial.specialQualities || '';

        if (memorial.profilePhoto) {
            if (memorial.profilePhoto.startsWith('default')) {
                this.setProfilePhoto(null, memorial.profilePhoto);
            } else {
                const blob = await storage.getPhoto(memorial.profilePhoto);
                if (blob) this.setProfilePhoto(blob);
            }
        }

        if (memorial.additionalPhotos && memorial.additionalPhotos.length > 0) {
            this.galleryPhotos = [];
            for (const id of memorial.additionalPhotos) {
                const blob = await storage.getPhoto(id);
                if (blob) {
                    this.galleryPhotos.push({ blob, existingId: id });
                }
            }
            this.renderGalleryPreview();
        }

        const title = $('#createFormSection h2');
        if (title) title.textContent = 'Edit Memorial';

        const deleteBtn = $('#btnDeleteMemorial');
        if (deleteBtn) deleteBtn.style.display = 'inline-block';
    }

    setProfilePhoto(blob, defaultId = null) {
        this.selectedPhotoBlob = null;
        this.selectedDefaultPhoto = defaultId;

        const preview = $('#profilePhotoPreview');
        const placeholder = $('#profilePhotoPlaceholder');

        if (blob) {
            preview.src = URL.createObjectURL(blob);
        } else if (defaultId) {
            const map = {
                default1: 'images/dove.png',
                default2: 'images/sunset.png'
            };
            preview.src = map[defaultId] || '';
        }

        preview.style.display = 'block';
        placeholder.style.display = 'none';
    }

    addGalleryPhotos(files) {
        if (this.galleryPhotos.length + files.length > 10) {
            showToast('Max 10 photos allowed', 'warning');
            return;
        }

        Array.from(files).forEach((file) => {
            this.galleryPhotos.push({ blob: file });
        });
        this.renderGalleryPreview();
    }

    renderGalleryPreview() {
        const container = $('#galleryPreview');
        if (!container) return;

        container.innerHTML = this.galleryPhotos
            .map(
                (p, index) => `
            <div class="gallery-preview-item" style="position:relative; width:60px; height:60px; display:inline-block; margin:5px;">
                <img src="${URL.createObjectURL(p.blob)}" style="width:100%; height:100%; object-fit:cover; border-radius:4px;">
                <button type="button" class="btn-remove-photo" data-index="${index}" 
                    style="position:absolute; top:-5px; right:-5px; background:red; color:white; border:none; border-radius:50%; width:18px; height:18px; font-size:12px; cursor:pointer;">&times;</button>
            </div>
        `
            )
            .join('');

        container.querySelectorAll('.btn-remove-photo').forEach((btn) => {
            btn.addEventListener('click', (e) => {
                const idx = parseInt(e.target.dataset.index);
                this.galleryPhotos.splice(idx, 1);
                this.renderGalleryPreview();
            });
        });
    }

    async handleSave() {
        const firstName = $('#firstName').value.trim();
        const middleName = $('#middleName').value.trim();
        const lastName = $('#lastName').value.trim();

        const nameParts = [firstName, middleName, lastName].filter((part) => part !== '');
        const name = nameParts.join(' ');

        const relationship = $('#relationship').value.trim();
        const birthDate = $('#birthDate').value;
        const passingDate = $('#passingDate').value;

        $('#firstName').classList.remove('error');
        $('#lastName').classList.remove('error');
        $('#birthDate').classList.remove('error');

        if (!firstName) {
            $('#firstName').classList.add('error');
            showToast('Please enter at least a First Name', 'warning');
            return;
        }

        if (!birthDate) {
            $('#birthDate').classList.add('error');
            showToast('Please select a Date of Birth', 'warning');
            return;
        }

        try {
            let profilePhotoId = this.selectedDefaultPhoto;
            if (this.selectedPhotoBlob) {
                profilePhotoId = await storage.savePhoto(this.selectedPhotoBlob);
            }

            const galleryIds = [];
            for (const item of this.galleryPhotos) {
                const id = await storage.savePhoto(item.blob);
                galleryIds.push(id);
            }

            let memorial = {
                id: this.editingId || generateId(),
                name,
                firstName,
                middleName,
                lastName,
                relationship,
                birthDate,
                passingDate,
                phone: $('#phoneNumber').value.trim(),
                email: $('#emailAddress').value.trim(),
                address: $('#homeAddress').value.trim(),
                favoriteMemory: $('#favoriteMemory').value.trim(),
                specialQualities: $('#specialQualities').value.trim(),
                profilePhoto: profilePhotoId,
                additionalPhotos: galleryIds,
                memories: [],
                journalEntries: [],
                createdAt: new Date().toISOString()
            };

            if (this.editingId) {
                const existing = await storage.getMemorial(this.editingId);
                if (existing) {
                    memorial = { ...existing, ...memorial };
                }
            }

            if (this.onSave) {
                await this.onSave(memorial);
            }

            this.reset();
            showToast('Memorial saved', 'success');
        } catch (e) {
            console.error(e);
            showToast('Error saving memorial', 'error');
        }
    }
}

