        this.container.innerHTML = html;

        const grid = this.container.querySelector('#galleryGrid');
        const emptyState = this.container.querySelector('#galleryEmptyState');
        if (grid) {
            grid.innerHTML = '';

            if (galleryPhotos.length > 0) {
                // Store gallery data globally for lightbox navigation
                currentGalleryData.photos = galleryPhotos.map((blob, index) => ({
                    blob,
                    url: URL.createObjectURL(blob),
                    index
                }));
                currentGalleryData.memorialId = memorial.id;

                galleryPhotos.forEach((blob, index) => {
                    const url = URL.createObjectURL(blob);
                    const fig = document.createElement('figure');
                    fig.className = 'memory-gallery-tile';
                    fig.dataset.index = String(index);

                    // Check if this is the selected Sacred Time photo
                    const isSelectedForSacredTime = selectedSacredPhoto === url;
                    if (isSelectedForSacredTime) {
                        fig.classList.add('selected');
                    }

                    fig.innerHTML = `
                        <img src="${url}" alt="Photo ${index + 1}" loading="lazy" />
                        ${isSelectedForSacredTime ? '<div class="sacred-time-badge">⏱️</div>' : ''}
                    `;
                    grid.appendChild(fig);
                });

                if (emptyState) emptyState.style.display = 'none';

                // Add click handlers to gallery tiles
                grid.querySelectorAll('.memory-gallery-tile').forEach((tile, index) => {
                    tile.addEventListener('click', () => {
                        // Update selection state
                        grid.querySelectorAll('.memory-gallery-tile').forEach((t) => {
                            t.classList.remove('selected');
                            // Remove any existing badges
                            const badge = t.querySelector('.sacred-time-badge');
                            if (badge) badge.remove();
                        });

                        // Add selected class and badge
                        tile.classList.add('selected');
                        const badge = document.createElement('div');
                        badge.className = 'sacred-time-badge';
                        badge.textContent = '⏱️';
                        badge.style.cssText = 'position:absolute; top:5px; right:5px; background:var(--color-copper); color:white; border-radius:50%; width:20px; height:20px; font-size:10px; display:flex; align-items:center; justify-content:center;';
