                        if (window.app && app.state) {
                            app.state.sacredPhotoByMemorial[memorial.id] = selectedUrl;
                        }

                        // Update the selection indicator
                        const selectionIndicator = document.getElementById('sacredTimeSelection');
                        if (selectionIndicator) {
                            selectionIndicator.style.display = 'block';
                        }

                        // Show success message
                        showToast('Image selected for Sacred Time', 'success');

                        // IMPORTANT: Update the Sacred Time tab preview IMMEDIATELY
                        const sacredPreview = document.getElementById('sacredTimePreview');
                        if (sacredPreview) {
                            sacredPreview.innerHTML = `
                                <div style="margin-bottom: 15px;">
                                    <div style="font-weight: bold; color: var(--color-copper); margin-bottom: 8px; font-size: 0.9em;">Selected Image for Sacred Time</div>
                                    <img src="${selectedUrl}" style="width: 120px; height: 120px; object-fit: cover; border-radius: 8px; border: 2px solid var(--color-copper);">
                                </div>
                            `;
                        }

                        // Show lightbox
                        showLightbox(index);
                    });
                });
            } else {
                if (emptyState) emptyState.style.display = 'block';
            }
        }

        setTimeout(() => {
            const tabs = this.container.querySelectorAll('.mem-tab');
            tabs.forEach((tab) => {
                tab.addEventListener('click', () => {
                    tabs.forEach((t) => t.classList.remove('active'));
                    this.container
                        .querySelectorAll('.mem-tab-content')
                        .forEach((c) => c.classList.remove('active'));

                    tab.classList.add('active');
                    const targetId = `tab-${tab.dataset.tab}`;
                    const target = document.getElementById(targetId);
                    if (target) target.classList.add('active');
                });
            });

            // SACRED TIME TIMER BUTTONS - CRITICAL FIX
            const sacredTabButtons = this.container.querySelectorAll('#tab-sacred .btn-timer-option');
            sacredTabButtons.forEach((btn) => {
                btn.addEventListener('click', async () => {
                    const time = btn.dataset.time;
                    let mins = 0;
                    if (time === 'custom') {
                        const input = prompt('Enter minutes for Sacred Time:');
                        if (input) mins = parseInt(input);
                    } else {
                        mins = parseInt(time);
                    }

                    if (mins && mins > 0) {
                        const activeTitle = $('#activeSacredTitle');
                        const focusPhoto = $('#activeFocusPhoto');

                        if (activeTitle) {
                            activeTitle.textContent = `Sacred Time with ${memorial.firstName || memorial.name}`;
                        }

                        // CRITICAL FIX: ALWAYS get the FRESH selected image
                        let selectedPhotoUrl = app.state.sacredPhotoByMemorial[memorial.id];

                        // If no selected image, try to get profile photo
                        if (!selectedPhotoUrl) {
                            // Get fresh profile photo URL
                            if (memorial.profilePhoto) {
                                if (memorial.profilePhoto.startsWith('default')) {
                                    const map = {
                                        'default1': 'https://abundantthought.com/contactmemorial/images/dove.png',
                                        'default2': 'https://abundantthought.com/contactmemorial/images/sunset.png'
                                    };
                                    selectedPhotoUrl = map[memorial.profilePhoto] || map.default1;
                                } else {
                                    const blob = await storage.getPhoto(memorial.profilePhoto);
                                    if (blob) {
                                        selectedPhotoUrl = URL.createObjectURL(blob);
                                    }
                                }
                            }
                        }

                        console.log('SACRED TIME DEBUG:');
                        console.log('- Selected URL:', selectedPhotoUrl);
                        console.log('- Has state:', !!app.state.sacredPhotoByMemorial[memorial.id]);
                        console.log('- Focus photo element:', focusPhoto);

                        // SET THE IMAGE - THIS IS THE CRITICAL LINE
                        if (focusPhoto && selectedPhotoUrl) {
                            focusPhoto.src = selectedPhotoUrl;
                            console.log('✅ Image set successfully');
                        } else if (focusPhoto) {
                            focusPhoto.src = 'https://abundantthought.com/contactmemorial/images/dove.png';
                            console.log('⚠️ Using fallback image');
                        }

                        $$('.sacred-view').forEach((el) => el.classList.remove('active'));
                        $('#sacredStepActive').classList.add('active');
                        $('#sacredTimeModal').classList.add('active');

                        // Start timer
                        if (window.app && app.sacredTime) {
                            app.sacredTime.start(mins);
                        }
                    }
                });
            });

            const backBtn = $('#backToDashBtn');
            if (backBtn)
                backBtn.addEventListener('click', () => {
                    document.dispatchEvent(new CustomEvent('navigate', { detail: 'dashboard' }));
                });

            const editBtn = $('#editMemorialBtn');
            if (editBtn) {
                editBtn.addEventListener('click', () => {
                    document.dispatchEvent(
                        new CustomEvent('edit-memorial', { detail: memorial.id })
                    );
                });
            }

            const saveJournalBtn = $('#saveJournalBtn');
            if (saveJournalBtn) {
                saveJournalBtn.addEventListener('click', async () => {
                    const input = $('#journalEntryInput');
                    const text = input.value.trim();
                    if (!text) return;

                    if (!memorial.journalEntries) memorial.journalEntries = [];
                    memorial.journalEntries.push({
                        id: generateId(),
                        date: new Date().toISOString(),
                        text
                    });

                    try {
                        await storage.saveMemorial(memorial);
                        showToast('Journal entry saved', 'success');
                        this.render(memorial);
                    } catch (e) {
                        console.error(e);
                        showToast('Failed to save journal', 'error');
                    }
                });
            }
        }, 0);
    }
}

// ==========================================
// LIGHTBOX FUNCTIONS
// ==========================================

function showLightbox(index) {
    if (!currentGalleryData.photos || currentGalleryData.photos.length === 0) return;

    currentGalleryData.currentIndex = index;
    const photo = currentGalleryData.photos[index];

    const modalImg = $('#imageLightboxImg');
    const counter = $('#lightboxCounter');
    const modal = $('#imageLightboxModal');

    if (modalImg && photo) {
        modalImg.src = photo.url;
        counter.textContent = `${index + 1} / ${currentGalleryData.photos.length}`;
        modal.classList.add('active');
    }
}

function navigateLightbox(direction) {
    if (!currentGalleryData.photos || currentGalleryData.photos.length === 0) return;

    let newIndex = currentGalleryData.currentIndex + direction;

    // Wrap around
    if (newIndex < 0) newIndex = currentGalleryData.photos.length - 1;
    if (newIndex >= currentGalleryData.photos.length) newIndex = 0;

    showLightbox(newIndex);
}

function setCurrentPhotoForSacredTime() {
    if (!currentGalleryData.photos || currentGalleryData.photos.length === 0) return;

    const photo = currentGalleryData.photos[currentGalleryData.currentIndex];
    if (photo && window.app && app.state && currentGalleryData.memorialId) {
