// --- storage.js ---
const DB_NAME = 'ContactMemorialDB';
const DB_VERSION = 1;
const STORE_MEMORIALS = 'memorials';
const STORE_PHOTOS = 'photos';

class StorageService {
    constructor() {
        this.db = null;
        this.dbPromise = this.initDB();
    }

    initDB() {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(DB_NAME, DB_VERSION);

            request.onerror = (event) => {
                console.error('IndexedDB error:', event.target.error);
                reject('Could not open database');
            };

            request.onupgradeneeded = (event) => {
                const db = event.target.result;

                if (!db.objectStoreNames.contains(STORE_MEMORIALS)) {
                    db.createObjectStore(STORE_MEMORIALS, { keyPath: 'id' });
                }

                if (!db.objectStoreNames.contains(STORE_PHOTOS)) {
                    db.createObjectStore(STORE_PHOTOS, { keyPath: 'id' });
                }
            };

            request.onsuccess = (event) => {
                this.db = event.target.result;
                console.log('StorageService: DB Initialized');
                resolve(this.db);
            };
        });
    }

    async getDB() {
        if (!this.db) {
            await this.dbPromise;
        }
        return this.db;
    }

    async saveMemorial(memorial) {
        const db = await this.getDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([STORE_MEMORIALS], 'readwrite');
            const store = transaction.objectStore(STORE_MEMORIALS);

            const dataToSave = { ...memorial };
            dataToSave.updatedAt = new Date().toISOString();

            const request = store.put(dataToSave);

            request.onsuccess = () => resolve(dataToSave);
            request.onerror = () => reject(request.error);
        });
    }

    async getAllMemorials() {
        const db = await this.getDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([STORE_MEMORIALS], 'readonly');
            const store = transaction.objectStore(STORE_MEMORIALS);
            const request = store.getAll();

            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error);
        });
    }

    async getMemorial(id) {
        const db = await this.getDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([STORE_MEMORIALS], 'readonly');
            const store = transaction.objectStore(STORE_MEMORIALS);
            const request = store.get(id);

            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error);
        });
    }

    async deleteMemorial(id) {
        const db = await this.getDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([STORE_MEMORIALS], 'readwrite');
            const store = transaction.objectStore(STORE_MEMORIALS);
            const request = store.delete(id);

            request.onsuccess = () => resolve(true);
            request.onerror = () => reject(request.error);
        });
    }

    async savePhoto(blob, explicitId = null) {
        const db = await this.getDB();
        const id = explicitId || `photo_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

        return new Promise((resolve, reject) => {
            const transaction = db.transaction([STORE_PHOTOS], 'readwrite');
            const store = transaction.objectStore(STORE_PHOTOS);
            const request = store.put({ id, blob });

            request.onsuccess = () => resolve(id);
            request.onerror = () => reject(request.error);
        });
    }

    async getPhoto(id) {
        const db = await this.getDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([STORE_PHOTOS], 'readonly');
            const store = transaction.objectStore(STORE_PHOTOS);
            const request = store.get(id);

            request.onsuccess = () => {
                if (request.result) {
                    resolve(request.result.blob);
                } else {
                    resolve(null);
                }
            };
            request.onerror = () => reject(request.error);
        });
    }

    async createBackup() {
        const memorials = await this.getAllMemorials();
        const db = await this.getDB();
        const transaction = db.transaction([STORE_PHOTOS], 'readonly');
        const photoStore = transaction.objectStore(STORE_PHOTOS);

        const allPhotos = await new Promise((resolve) => {
            const req = photoStore.getAll();
            req.onsuccess = () => resolve(req.result);
        });

        const photosBase64 = await Promise.all(
            allPhotos.map(async (p) => {
                const base64 = await this.blobToBase64(p.blob);
                return { id: p.id, data: base64 };
            })
        );

        return {
            version: '2.0',
            timestamp: new Date().toISOString(),
            memorials,
            photos: photosBase64
        };
    }

    async restoreBackup(backupData) {
        if (!backupData || !backupData.memorials) {
            throw new Error('Invalid backup data');
        }

        const db = await this.getDB();
        const transaction = db.transaction([STORE_MEMORIALS, STORE_PHOTOS], 'readwrite');

        transaction.objectStore(STORE_MEMORIALS).clear();
        transaction.objectStore(STORE_PHOTOS).clear();

        if (backupData.photos) {
            const photoStore = transaction.objectStore(STORE_PHOTOS);
            for (const p of backupData.photos) {
                const blob = await this.base64ToBlob(p.data);
                photoStore.put({ id: p.id, blob });
            }
        }

        const memoStore = transaction.objectStore(STORE_MEMORIALS);
        for (const m of backupData.memorials) {
            memoStore.put(m);
        }

        return new Promise((resolve, reject) => {
            transaction.oncomplete = () => resolve(true);
            transaction.onerror = () => reject(transaction.error);
        });
    }

    blobToBase64(blob) {
        return new Promise((resolve, _) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result);
            reader.readAsDataURL(blob);
        });
    }

    async base64ToBlob(base64) {
        const res = await fetch(base64);
        return await res.blob();
    }
}

