                        // THIS IS THE CRITICAL LINE - SET THE IMAGE
                        if (focusPhoto) {
                            focusPhoto.src = selectedPhotoUrl;
                            console.log('✅ Image set in Sacred Time modal');
                        }

                        $$('.sacred-view').forEach((el) => el.classList.remove('active'));
