                });

            const editBtn = $('#editMemorialBtn');
            if (editBtn) {
                editBtn.addEventListener('click', () => {
                    document.dispatchEvent(
                        new CustomEvent('edit-memorial', { detail: memorial.id })
                    );
                });
            }

            const saveJournalBtn = $('#saveJournalBtn');
            if (saveJournalBtn) {
                saveJournalBtn.addEventListener('click', async () => {
                    const input = $('#journalEntryInput');
                    const text = input.value.trim();
                    if (!text) return;

                    if (!memorial.journalEntries) memorial.journalEntries = [];
                    memorial.journalEntries.push({
                        id: generateId(),
                        date: new Date().toISOString(),
                        text
                    });

                    try {
                        await storage.saveMemorial(memorial);
                        showToast('Journal entry saved', 'success');
                        this.render(memorial);
                    } catch (e) {
                        console.error(e);
                        showToast('Failed to save journal', 'error');
                    }
                });
            }
        }, 0);
    }
}

// ==========================================
// LIGHTBOX FUNCTIONS
// ==========================================

function showLightbox(index) {
    if (!currentGalleryData.photos || currentGalleryData.photos.length === 0) return;

    currentGalleryData.currentIndex = index;
    const photo = currentGalleryData.photos[index];

    const modalImg = $('#imageLightboxImg');
    const counter = $('#lightboxCounter');
    const modal = $('#imageLightboxModal');

    if (modalImg && photo) {
        modalImg.src = photo.url;
        counter.textContent = `${index + 1} / ${currentGalleryData.photos.length}`;
        modal.classList.add('active');
    }
}

function navigateLightbox(direction) {
    if (!currentGalleryData.photos || currentGalleryData.photos.length === 0) return;

    let newIndex = currentGalleryData.currentIndex + direction;

    // Wrap around
    if (newIndex < 0) newIndex = currentGalleryData.photos.length - 1;
    if (newIndex >= currentGalleryData.photos.length) newIndex = 0;

    showLightbox(newIndex);
}

function setCurrentPhotoForSacredTime() {
    if (!currentGalleryData.photos || currentGalleryData.photos.length === 0) return;

    const photo = currentGalleryData.photos[currentGalleryData.currentIndex];
    if (photo && window.app && app.state && currentGalleryData.memorialId) {
        app.state.sacredPhotoByMemorial[currentGalleryData.memorialId] = photo.url;
        showToast('Image selected for Sacred Time', 'success');

        // Update UI to show selection
        const selectionIndicator = document.getElementById('sacredTimeSelection');
        if (selectionIndicator) {
            selectionIndicator.style.display = 'block';
        }

        // Close lightbox
        const modal = $('#imageLightboxModal');
        if (modal) modal.classList.remove('active');

        // Refresh the memorial view to show updated selection
        if (window.app && app.state.activeId) {
            setTimeout(() => {
                app.renderActiveMemorial();
            }, 300);
        }
    }
}

// ==========================================
// SACRED TIME MANAGER
// ==========================================

class SacredTimeManager {
    constructor() {
        this.interval = null;
        this.timeRemaining = 0;
        this.selectedMinutes = 0;
    }

    start(minutes) {
        this.selectedMinutes = minutes;
        this.timeRemaining = minutes * 60;
        this.updateDisplay();

        if (this.interval) clearInterval(this.interval);
        showToast('Sacred Time Started', 'info');
        this.interval = setInterval(() => this.tick(), 1000);
    }

    stop() {
        if (this.interval) clearInterval(this.interval);
        this.interval = null;
    }

    tick() {
        this.timeRemaining--;
        if (this.timeRemaining <= 0) {
            this.stop();
            showToast('Sacred Time Complete', 'success');
        }
        this.updateDisplay();
    }

    updateDisplay() {
        const timeEl = $('#meditationTimerDisplay');
        const progressEl = $('#timerProgress');

        if (timeEl) timeEl.textContent = formatTime(this.timeRemaining);
        if (progressEl) {
            const total = this.selectedMinutes * 60;
            const percent = (this.timeRemaining / total) * 100;
            progressEl.style.width = `${percent}%`;
        }
    }
}

