class App {
    constructor() {
        this.router = new Router();
        this.formManager = new FormManager({
            onSave: (memorial) => this.handleMemorialSave(memorial)
        });
        this.memorialCard = new MemorialCard('#memorialDisplay');
        this.sacredTime = new SacredTimeManager();
        this.deferredPrompt = null;

        // CRITICAL: Initialize state with empty object for sacred photos
        this.state = {
            memorials: [],
            activeId: null,
            sacredPhotoByMemorial: {} // THIS MUST BE AN OBJECT
        };

        document.addEventListener('navigate', (e) => {
            this.router.navigate(e.detail);
            if (e.detail === 'dashboard') this.renderMemorialList();
        });

        document.addEventListener('start-sacred-timer', (e) => {
            const mins = e.detail;
            if (mins && mins > 0) {
                this.sacredTime.start(mins);
            }
        });
    }

    async init() {
        console.log('Initializing App...');

        await storage.initDB();
        this.state.memorials = await storage.getAllMemorials();
        console.log(`Loaded ${this.state.memorials.length} memorials`);

        this.router.init();
        this.bindEvents();
        this.renderMemorialList();
    }

    bindEvents() {
