        if (saveBtn) saveBtn.addEventListener('click', () => this.formManager.handleSave());

        const deleteBtn = $('#btnDeleteMemorial');
        if (deleteBtn)
            deleteBtn.addEventListener('click', async () => {
                if (
                    confirm(
                        'Are you sure you want to delete this memorial? This cannot be undone.'
                    )
                ) {
                    if (this.formManager.editingId) {
                        await storage.deleteMemorial(this.formManager.editingId);
                        showToast('Memorial deleted', 'success');
                        $('#createFormSection').style.display = 'none';
                        $('#showCreateFormBtn').style.display = 'inline-block';
                        this.state.memorials = await storage.getAllMemorials();
                        this.renderMemorialList();
                        this.router.navigate('dashboard');
                    }
