                        // If no gallery image selected, use profile photo
                        if (!selectedPhotoUrl && profilePhotoUrl) {
                            selectedPhotoUrl = profilePhotoUrl;
                            console.log('🟡 Using profile photo:', selectedPhotoUrl);
                        }

                        // If still no image, use default dove
                        if (!selectedPhotoUrl) {
                            selectedPhotoUrl = 'https://abundantthought.com/contactmemorial/images/dove.png';
                            console.log('🔴 Using default dove image');
                        }

                        console.log('🟢 FINAL selected photo URL:', selectedPhotoUrl);

                        // THIS IS THE CRITICAL LINE - SET THE IMAGE
                        if (focusPhoto) {
                            focusPhoto.src = selectedPhotoUrl;
                            focusPhoto.alt = `Sacred Time with ${memorial.firstName || memorial.name}`;
                            focusPhoto.style.display = 'block';
                            console.log('✅ Image set in Sacred Time modal');
                            console.log('✅ focusPhoto.src after setting:', focusPhoto.src);
                        } else {
                            console.error('❌ focusPhoto element not found!');
                            // Try alternative selector
                            const altFocusPhoto = document.getElementById('activeFocusPhoto');
                            if (altFocusPhoto) {
                                altFocusPhoto.src = selectedPhotoUrl;
                                console.log('✅ Found with alternative selector and set image');
                            }
                        }

                        $$('.sacred-view').forEach((el) => el.classList.remove('active'));
                        $('#sacredStepActive').classList.add('active');
                        $('#sacredTimeModal').classList.add('active');

                        // Start timer
                        if (window.app && app.sacredTime) {
                            app.sacredTime.start(mins);
                        }
                    }
                });
            });

            const backBtn = $('#backToDashBtn');
            if (backBtn)
                backBtn.addEventListener('click', () => {
                    document.dispatchEvent(new CustomEvent('navigate', { detail: 'dashboard' }));
                });

            const editBtn = $('#editMemorialBtn');
            if (editBtn) {
                editBtn.addEventListener('click', () => {
                    document.dispatchEvent(
                        new CustomEvent('edit-memorial', { detail: memorial.id })
                    );
                });
            }

            const saveJournalBtn = $('#saveJournalBtn');
            if (saveJournalBtn) {
                saveJournalBtn.addEventListener('click', async () => {
                    const input = $('#journalEntryInput');
                    const text = input.value.trim();
                    if (!text) return;

                    if (!memorial.journalEntries) memorial.journalEntries = [];
                    memorial.journalEntries.push({
                        id: generateId(),
                        date: new Date().toISOString(),
                        text
                    });

                    try {
                        await storage.saveMemorial(memorial);
                        showToast('Journal entry saved', 'success');
                        this.render(memorial);
                    } catch (e) {
                        console.error(e);
                        showToast('Failed to save journal', 'error');
                    }
                });
            }
        }, 0);
    }
}

