class Router {
    constructor() {
        this.currentView = 'home';
    }

    init() {
        this.navigate('home');
    }

    navigate(viewName) {
        this.currentView = viewName;

        $$('.home-view, .memorial-view, .dashboard-view').forEach((el) => {
            el.classList.remove('active');
            el.style.display = 'none';
        });
        $$('.view-toggle .btn').forEach((el) => el.classList.remove('active'));

        if (viewName === 'home') {
            const homeView = $('#homeView');
            if (homeView) {
                homeView.classList.add('active');
                homeView.style.display = 'block';
            }
            const homeBtn = $('#homeBtn');
            if (homeBtn) homeBtn.classList.add('active');
        } else if (viewName === 'dashboard') {
            const dashView = $('#dashboardView');
            if (dashView) {
                dashView.classList.add('active');
                dashView.style.display = 'block';
            }
            const dashBtn = $('#dashboardBtn');
            if (dashBtn) dashBtn.classList.add('active');
        } else if (viewName === 'memorial') {
            const memView = $('#memorialView');
            if (memView) {
                memView.classList.add('active');
                memView.style.display = 'block';
            }
        }
    }
}

