// ==========================================

class SacredSelectionManager {
    constructor() {
        this.STORAGE_KEY_PREFIX = 'sacred_selection_';
    }

    // Get selected photo ID for a memorial
    getSelectedPhotoId(memorialId) {
        try {
            // Try localStorage first (persistent)
            const stored = localStorage.getItem(this.STORAGE_KEY_PREFIX + memorialId);
            if (stored) return stored;

            // Fall back to app state (session-only)
            if (window.app && window.app.state && window.app.state.sacredPhotoIdByMemorial) {
                return window.app.state.sacredPhotoIdByMemorial[memorialId];
            }
        } catch (e) {
            console.warn('Could not read sacred selection:', e.message);
        }
        return null;
    }

    // Set selected photo ID for a memorial
    setSelectedPhotoId(memorialId, photoId) {
        try {
            // Save to localStorage for persistence
            localStorage.setItem(this.STORAGE_KEY_PREFIX + memorialId, photoId);
        } catch (e) {
            console.warn('Could not save to localStorage:', e.message);
        }

        // Also save to app state for current session
        if (window.app && window.app.state) {
            if (!window.app.state.sacredPhotoIdByMemorial) {
                window.app.state.sacredPhotoIdByMemorial = {};
            }
            window.app.state.sacredPhotoIdByMemorial[memorialId] = photoId;
        }
    }

    // Clear selection for a memorial
    clearSelection(memorialId) {
        try {
            localStorage.removeItem(this.STORAGE_KEY_PREFIX + memorialId);
        } catch (e) {
            console.warn('Could not remove from localStorage:', e.message);
        }

        if (window.app && window.app.state && window.app.state.sacredPhotoIdByMemorial) {
            delete window.app.state.sacredPhotoIdByMemorial[memorialId];
        }
    }

    // Get blob URL for selected photo (async)
    async getSelectedPhotoUrl(memorialId, photoId = null) {
        const selectedId = photoId || this.getSelectedPhotoId(memorialId);
        if (!selectedId) return null;

        try {
            const blob = await storage.getPhoto(selectedId);
            if (blob) {
                // Create object URL with cache key
                const cacheKey = `sacred_${memorialId}_${selectedId}`;
                return createObjectUrl(blob, cacheKey);
            }
        } catch (e) {
            console.error('Error loading sacred photo:', e);
        }
        return null;
    }
}

