    width: 50px;
    height: 50px;
    font-size: 1.5em;
    cursor: pointer;
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}

.lightbox-nav:hover {
    background: rgba(190, 81, 3, 0.8);
    transform: translateY(-50%) scale(1.1);
}

.lightbox-prev {
    left: 15px;
}

.lightbox-next {
    right: 15px;
}

.lightbox-image {
    max-width: 100%;
    max-height: 75vh;
    border-radius: 12px;
    box-shadow: 0 0 30px rgba(0, 0, 0, 0.7);
    margin: 20px 0;
}

.lightbox-counter {
    margin-top: 10px;
    color: #aaa;
    font-size: 0.9em;
}

.lightbox-actions {
    margin-top: 20px;
    display: flex;
    justify-content: center;
    gap: 15px;
    flex-wrap: wrap;
