        max-width: 200px;
    }
}

/* =========================================================
   PATCH: Gallery selection badge + centering overrides (2026-01-14)
   ========================================================= */

/* Fix badge positioning in gallery grid context */
.memory-gallery-tile {
    position: relative; /* Ensure badge positioning context */
}

.memory-gallery-tile .sacred-time-badge {
    position: absolute;
    top: 8px;
    right: 8px;
    background: var(--color-copper);
    color: white;
    border-radius: 50%;
    width: 24px;
    height: 24px;
    font-size: 11px;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 10;
    box-shadow: 0 2px 8px rgba(0,0,0,0.4);
    pointer-events: none; /* Don't interfere with clicks */
    opacity: 0;
    transform: scale(0.8);
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* Show badge with smooth animation */
.memory-gallery-tile.selected .sacred-time-badge {
    opacity: 1;
    transform: scale(1);
