## **5. app.js** (Updated - Critical fixes for timer and rendering)

```javascript
/**
 * Contact Memorial App
 * Consolidated JavaScript for Local File System Support
 *
 * FIXED: Background flickering by adding permanent background container
 * FIXED: Redundant custom timer button with inline custom input
 * FIXED: Timer functionality with proper event handling
 * ADDED: Smooth transitions and respectful animations
 */

// ==========================================
// UTILS
// ==========================================

// --- dom.js ---
const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => document.querySelectorAll(selector);

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
}

function showToast(message, type = 'info') {
    const toast = document.getElementById('toast');
    const toastMessage = document.getElementById('toastMessage');

    if (!toast || !toastMessage) return;

    toastMessage.textContent = message;

    const colors = {
        success: '#6ba388',
        error: '#d16666',
        warning: '#d1a566',
        info: '#4A90E2'
    };

    toast.style.borderLeftColor = colors[type] || colors.info;
    toast.classList.add('show');

    // iPhone Safari: allow tap to dismiss immediately (prevents "stuck" perception)
    toast.onclick = () => toast.classList.remove('show');

    setTimeout(() => {
        toast.classList.remove('show');
    }, 3000);
}

// --- formatters.js ---
function formatDate(dateString) {
    if (!dateString) return 'Unknown';

    const date = new Date(dateString);
    if (isNaN(date.getTime())) return dateString;

    return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'long',
        day: 'numeric'
    });
}

function formatTime(seconds) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
