                        ${isSelectedForSacredTime ? '<div class="sacred-time-badge">⏱️</div>' : ''}
                    `;
                    grid.appendChild(fig);
                });

                if (emptyState) emptyState.style.display = 'none';

                grid.querySelectorAll('.memory-gallery-tile').forEach((tile) => {
                    tile.addEventListener('click', async () => {
                        const index = parseInt(tile.dataset.index, 10);
                        const photoId = tile.dataset.photoId;
                        if (Number.isNaN(index) || !photoId) return;

                        setSelectedSacredPhotoId(memorial.id, photoId);

                        grid.querySelectorAll('.memory-gallery-tile').forEach((t) => {
                            t.classList.remove('selected');
                            const badge = t.querySelector('.sacred-time-badge');
                            if (badge) badge.remove();
                        });

                        tile.classList.add('selected');
                        const badge = document.createElement('div');
                        badge.className = 'sacred-time-badge';
                        badge.textContent = '⏱️';
                        badge.style.cssText =
                            'position:absolute; top:5px; right:5px; background:var(--color-copper); color:white; border-radius:50%; width:20px; height:20px; font-size:10px; display:flex; align-items:center; justify-content:center;';
                        tile.appendChild(badge);

                        const selectionIndicator = document.getElementById('sacredTimeSelection');
                        if (selectionIndicator) selectionIndicator.style.display = 'block';

                        showToast('Image selected for Sacred Time', 'success');
                        showLightbox(index);
                    });
                });
            } else {
                if (emptyState) emptyState.style.display = 'block';
            }
        }

        // Set up timer functionality
        setTimeout(() => {
            // Tab switching
            const tabs = this.container.querySelectorAll('.mem-tab');
            tabs.forEach((tab) => {
                tab.addEventListener('click', () => {
                    tabs.forEach((t) => t.classList.remove('active'));
                    this.container.querySelectorAll('.mem-tab-content').forEach((c) => c.classList.remove('active'));

                    tab.classList.add('active');
                    const targetId = `tab-${tab.dataset.tab}`;
                    const target = document.getElementById(targetId);
                    if (target) target.classList.add('active');
                });
            });

            // Helper function to start sacred time
            const startSacredTimeWithMinutes = async (minutes) => {
                if (!minutes || minutes <= 0) return;

                const activeTitle = $('#activeSacredTitle');
                const focusPhoto = $('#activeFocusPhoto');

                if (activeTitle) {
                    activeTitle.textContent = `Sacred Time with ${memorial.firstName || memorial.name}`;
                }

                const { url } = await resolveSacredFocusImage(
                    memorial,
                    profilePhotoUrl,
                    window.app?._sacredModalUrlPool
                );

                if (focusPhoto) {
                    focusPhoto.src = url;
                    focusPhoto.alt = `Sacred Time with ${memorial.firstName || memorial.name}`;
                    focusPhoto.style.display = 'block';
                }

                $$('.sacred-view').forEach((el) => el.classList.remove('active'));
                $('#sacredStepSetup').classList.remove('active');
                $('#sacredStepActive').classList.add('active');
                $('#sacredTimeModal').classList.add('active');

                showToast(`Beginning ${Math.floor(minutes)} minute${Math.floor(minutes) !== 1 ? 's' : ''} of sacred time`, 'info');

                if (window.app?.sacredTime) {
                    // Convert minutes to seconds for the timer
                    window.app.sacredTime.start(minutes);
                }
            };

            // Set up preset timer buttons
            const sacredTabButtons = this.container.querySelectorAll('#tab-sacred .btn-timer-option');
            sacredTabButtons.forEach((btn) => {
                btn.addEventListener('click', async () => {
                    const time = parseInt(btn.dataset.time, 10);
                    if (time > 0) startSacredTimeWithMinutes(time);
                });
            });

            // Set up custom timer
            const manualMinutes = this.container.querySelector('#manualMinutes');
            const manualSeconds = this.container.querySelector('#manualSeconds');
            const startCustomBtn = this.container.querySelector('#startCustomTimer');

            if (startCustomBtn) {
                startCustomBtn.addEventListener('click', () => {
                    const mins = parseInt(manualMinutes?.value || '0', 10);
                    const secs = parseInt(manualSeconds?.value || '0', 10);

                    if ((mins > 0 || secs > 0) && mins <= 120 && secs <= 59) {
                        const totalMinutes = mins + (secs / 60);
                        if (totalMinutes > 0) {
                            startSacredTimeWithMinutes(totalMinutes);
                        } else {
                            showToast('Please enter a valid time (1-120 minutes)', 'warning');
                        }
                    } else {
                        showToast('Please enter a valid time (1-120 minutes, 0-59 seconds)', 'warning');
                    }
                });
            }

            // Allow Enter key in custom inputs
            if (manualMinutes) {
                manualMinutes.addEventListener('keypress', (e) => {
                    if (e.key === 'Enter') {
                        if (startCustomBtn) startCustomBtn.click();
                    }
                });
            }

            if (manualSeconds) {
                manualSeconds.addEventListener('keypress', (e) => {
                    if (e.key === 'Enter') {
                        if (startCustomBtn) startCustomBtn.click();
                    }
                });
            }

            // Back and Edit buttons
            const backBtn = $('#backToDashBtn');
            if (backBtn) backBtn.addEventListener('click', () => {
                document.dispatchEvent(new CustomEvent('navigate', { detail: 'dashboard' }));
            });

            const editBtn = $('#editMemorialBtn');
            if (editBtn) editBtn.addEventListener('click', () => {
                document.dispatchEvent(new CustomEvent('edit-memorial', { detail: memorial.id }));
            });

            // Journal functionality
            const saveJournalBtn = $('#saveJournalBtn');
            if (saveJournalBtn) saveJournalBtn.addEventListener('click', async () => {
                const input = $('#journalEntryInput');
                const text = input.value.trim();
                if (!text) return;

                if (!memorial.journalEntries) memorial.journalEntries = [];
                memorial.journalEntries.push({ id: generateId(), date: new Date().toISOString(), text });

                try {
                    await storage.saveMemorial(memorial);
                    showToast('Journal entry saved', 'success');
                    this.render(memorial);
                } catch (e) {
                    console.error(e);
                    showToast('Failed to save journal', 'error');
                }
            });
        }, 0);
    }
}

