```javascript
// js/ImageManager.js
/**
 * ImageManager v2.0
 * Lazy loading with blur-up placeholders and progressive loading
 * 100% backward compatible with existing data structure
 */

class ImageManager {
    constructor(options = {}) {
        this.options = {
            rootMargin: '50px 0px',
            threshold: 0.01,
            placeholderColor: '#353839',
            placeholderBlur: '20px',
            maxSimultaneousLoads: 3,
            enableBlurUp: true,
            debug: false,
            ...options
        };

        this.observer = null;
        this.observedElements = new Map();
        this.loadingQueue = [];
        this.currentLoads = 0;
        this.performanceMetrics = {
            totalImages: 0,
            lazyLoaded: 0,
            cachedHits: 0,
            loadTimes: []
        };

        this.init();
    }

    init() {
        // Check if IntersectionObserver is supported
        if ('IntersectionObserver' in window) {
            this.initObserver();
        } else {
            this.loadPolyfill();
        }

        // Performance monitoring hook
        this.setupPerformanceMonitoring();
    }

    initObserver() {
        this.observer = new IntersectionObserver(
            (entries) => {
                entries.forEach((entry) => {
                    if (entry.isIntersecting) {
                        const img = entry.target;
                        this.observer.unobserve(img);
                        this.loadImage(img);
                    }
                });
            },
            {
                rootMargin: this.options.rootMargin,
                threshold: this.options.threshold
            }
        );
    }

    async loadPolyfill() {
        if (!window.IntersectionObserver) {
            try {
                await import('https://cdn.jsdelivr.net/npm/intersection-observer@0.12.0/intersection-observer.js');
                this.initObserver();
                this.log('IntersectionObserver polyfill loaded');
            } catch (error) {
                console.warn('IntersectionObserver polyfill failed, falling back to eager loading');
            }
        }
    }

    /**
     * Register an image for lazy loading
     * @param {HTMLImageElement} img - Image element
     * @param {Object} options - Image-specific options
     */
    registerImage(img, options = {}) {
        const imageOptions = {
            src: img.dataset.src || img.getAttribute('data-src'),
            placeholder: img.dataset.placeholder || null,
            blurUp: 'blurUp' in img.dataset ? img.dataset.blurUp === 'true' : this.options.enableBlurUp,
            priority: img.dataset.priority === 'true',
            ...options
        };

        if (!imageOptions.src) {
            this.log('No data-src found for image', img);
            return;
        }

        // Store original attributes
        const original = {
            src: img.src,
            srcset: img.srcset,
            sizes: img.sizes,
            loading: img.loading
        };

        this.observedElements.set(img, { options: imageOptions, original });

        // Apply placeholder
        this.applyPlaceholder(img, imageOptions);

        // Set up error handling
        img.onerror = () => this.handleImageError(img, imageOptions);

        if (imageOptions.priority) {
            // Load priority images immediately
            this.loadImage(img);
        } else if (this.observer) {
            this.observer.observe(img);
        } else {
            // Fallback for browsers without IntersectionObserver
            this.loadImage(img);
        }

        this.performanceMetrics.totalImages++;
    }

    /**
     * Apply blur-up or color placeholder
     */
    applyPlaceholder(img, options) {
        const parent = img.parentElement;
        if (!parent) return;

        // Create container for progressive loading effect
        if (!parent.classList.contains('lazy-image-container')) {
            parent.classList.add('lazy-image-container');
        }

        // Set placeholder background
        if (options.placeholder) {
            // Use tiny placeholder image for blur-up effect
            img.style.backgroundImage = `url('${options.placeholder}')`;
            img.style.backgroundSize = 'cover';
            img.style.backgroundPosition = 'center';
            img.style.filter = 'blur(10px)';
            img.style.transition = 'filter 0.3s ease-out';
        } else {
            // Solid color placeholder
            img.style.backgroundColor = this.options.placeholderColor;
        }

        // Apply loading class for skeleton animation
        img.classList.add('lazy-loading');
    }

    /**
     * Load actual image with queue management
     */
    async loadImage(img) {
        const data = this.observedElements.get(img);
        if (!data) return;

        // Check if already loaded
        if (img.classList.contains('lazy-loaded')) return;

        // Queue management
        if (this.currentLoads >= this.options.maxSimultaneousLoads) {
            this.loadingQueue.push(img);
            return;
        }

        this.currentLoads++;
        const startTime = performance.now();

        try {
            await this.loadImageData(img, data.options);

            const loadTime = performance.now() - startTime;
            this.performanceMetrics.loadTimes.push(loadTime);
            this.performanceMetrics.lazyLoaded++;

            this.log(`Image loaded in ${loadTime.toFixed(2)}ms`, data.options.src);

            // Process next in queue
            this.currentLoads--;
            this.processQueue();
        } catch (error) {
            this.currentLoads--;
            this.handleImageError(img, data.options);
            this.processQueue();
        }
    }

    /**
     * Load image data with progressive enhancement
     */
    async loadImageData(img, options) {
        return new Promise((resolve, reject) => {
            const imageLoader = new Image();

            // Set up loading
            imageLoader.onload = () => {
                // Apply loaded image
                img.src = options.src;
                img.classList.remove('lazy-loading');
                img.classList.add('lazy-loaded');

                // Remove blur effect for blur-up
                if (options.blurUp) {
                    setTimeout(() => {
                        img.style.filter = 'blur(0)';
                        setTimeout(() => {
                            img.style.backgroundImage = 'none';
                            img.style.filter = '';
                        }, 300);
                    }, 100);
                } else {
                    img.style.backgroundColor = '';
                }

                // Emit custom event
                img.dispatchEvent(new CustomEvent('lazyloaded', {
                    detail: { src: options.src }
                }));

                resolve();
            };

            imageLoader.onerror = reject;

            // Start loading
            imageLoader.src = options.src;

            // Timeout for stalled loads
            setTimeout(() => {
                if (!img.classList.contains('lazy-loaded')) {
                    reject(new Error('Image load timeout'));
                }
            }, 10000);
        });
    }

    /**
     * Process loading queue
     */
    processQueue() {
        while (this.loadingQueue.length > 0 && this.currentLoads < this.options.maxSimultaneousLoads) {
            const nextImg = this.loadingQueue.shift();
            this.loadImage(nextImg);
        }
    }

    /**
     * Handle image loading errors
     */
    handleImageError(img, options) {
        console.warn('Failed to load image:', options.src);

        // Fallback to placeholder or error image
        img.classList.remove('lazy-loading');
        img.classList.add('lazy-error');

        // Show error icon
        img.style.backgroundImage = `url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="%23777777"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"/></svg>')`;
        img.style.backgroundSize = '30%';
        img.style.backgroundRepeat = 'no-repeat';
        img.style.backgroundPosition = 'center';

        // Emit error event
        img.dispatchEvent(new CustomEvent('lazyerror', {
            detail: { src: options.src }
        }));
    }

    /**
     * Generate tiny placeholder for blur-up effect
     * @param {string} src - Original image URL
     * @returns {Promise<string>} - Base64 placeholder
     */
    async generateBlurPlaceholder(src) {
        // For local images, we can create a tiny version
        // For external URLs, we can use a service or fallback
        // This is a simplified version - in production you'd want to implement properly

        return new Promise((resolve) => {
            // Create a tiny canvas with average color
            const canvas = document.createElement('canvas');
            canvas.width = 10;
            canvas.height = 10;
            const ctx = canvas.getContext('2d');

            // Default placeholder color based on your theme
            ctx.fillStyle = this.options.placeholderColor;
            ctx.fillRect(0, 0, 10, 10);

            resolve(canvas.toDataURL('image/jpeg', 0.1));
        });
    }

    /**
     * Setup performance monitoring
     */
    setupPerformanceMonitoring() {
        // Report performance every 30 seconds in debug mode
        if (this.options.debug) {
            setInterval(() => {
                this.reportPerformance();
            }, 30000);
        }

        // Listen for page visibility changes
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'hidden') {
                this.reportPerformance();
            }
        });
    }

    /**
     * Report performance metrics
     */
    reportPerformance() {
        const metrics = this.performanceMetrics;
        if (metrics.loadTimes.length === 0) return;

        const avgLoadTime = metrics.loadTimes.reduce((a, b) => a + b, 0) / metrics.loadTimes.length;

        console.log('[ImageManager Performance Report]', {
            totalImages: metrics.totalImages,
            lazyLoaded: metrics.lazyLoaded,
            cachedHits: metrics.cachedHits,
            averageLoadTime: `${avgLoadTime.toFixed(2)}ms`,
            loadTimeDistribution: metrics.loadTimes.length
        });

        // Reset for next period
        metrics.loadTimes = [];
    }

    /**
     * Update configuration
     */
    updateConfig(newOptions) {
        this.options = { ...this.options, ...newOptions };

        if (this.observer && newOptions.rootMargin) {
            // Recreate observer with new rootMargin
            this.observer.disconnect();
            this.initObserver();

            // Re-observe all elements
            this.observedElements.forEach((_, img) => {
                this.observer.observe(img);
            });
        }
    }

    /**
     * Cleanup
     */
    destroy() {
        if (this.observer) {
            this.observer.disconnect();
        }

        this.observedElements.clear();
        this.loadingQueue = [];
        this.currentLoads = 0;
    }

    log(...args) {
        if (this.options.debug) {
            console.log('[ImageManager]', ...args);
        }
    }
}

// Global instance
