    MemorialCard.prototype.setupGalleryLazyLoading = async function(memorial) {
        const galleryGrid = this.container.querySelector('#galleryGrid');
        if (!galleryGrid) return;

        const images = galleryGrid.querySelectorAll('img[loading="lazy"]');

        for (const img of images) {
            // Ensure data-src is set
            if (img.src && !img.dataset.src) {
                img.dataset.src = img.src;
                img.src = ''; // Clear src to prevent eager loading
            }

            // Register with ImageManager
            if (img.dataset.src) {
                window.ImageManager.registerImage(img, {
                    priority: false, // Gallery images are low priority
                    blurUp: true
                });
            }
        }
    };

    // Monitor lightbox for lazy loading
    const originalShowLightbox = window.showLightbox;
    window.showLightbox = function(index) {
        originalShowLightbox(index);

        // Ensure lightbox image is loaded with priority
        setTimeout(() => {
            const lightboxImg = document.getElementById('imageLightboxImg');
