/**
 * LazyLoader Service v2.0
 * Integration bridge between app and ImageManager
 * Progressive enhancement with fallbacks
 */

class LazyLoaderService {
    constructor() {
        this.imageManager = null;
        this.isSupported = this.checkSupport();
        this.isEnabled = false;
        this.performance = {
            startTime: null,
            metrics: {
                imagesProcessed: 0,
                lazyLoaded: 0,
                eagerLoaded: 0,
                errors: 0
            }
        };

        this.init();
    }

    checkSupport() {
        // Feature detection, not browser sniffing
        const checks = {
            // Basic ES6 support
            es6: typeof Promise !== 'undefined' && 
                  typeof Map !== 'undefined' && 
                  typeof Set !== 'undefined',

            // IntersectionObserver support
            intersectionObserver: 'IntersectionObserver' in window &&
                                  'IntersectionObserverEntry' in window &&
                                  'intersectionRatio' in window.IntersectionObserverEntry.prototype,

            // Blob URLs support
            blobUrls: 'URL' in window && 
                      typeof URL.createObjectURL === 'function' &&
                      typeof URL.revokeObjectURL === 'function',

            // Performance API (for metrics)
            performance: 'performance' in window && 
                         typeof performance.mark === 'function',

            // Safari-specific check for passive events
            passiveEvents: (() => {
                let supportsPassive = false;
                try {
                    const opts = Object.defineProperty({}, 'passive', {
                        get: function() {
                            supportsPassive = true;
                            return true;
                        }
                    });
                    window.addEventListener('test', null, opts);
                    window.removeEventListener('test', null, opts);
                } catch (e) {}
                return supportsPassive;
            })()
        };

        // Minimum requirements
        return checks.es6 && checks.blobUrls;
    }

    async init() {
        this.performance.startTime = performance.now();

        if (!this.isSupported) {
            console.warn('LazyLoader: Browser lacks required features, falling back to eager loading');
            this.setupFallback();
            return;
        }

        try {
            // Load ImageManager dynamically
            await this.loadImageManager();
            this.isEnabled = true;
            this.setupEventListeners();
            this.injectStyles();

            console.log('LazyLoader: Initialized successfully');

            // Performance mark
            if (window.performance) {
                performance.mark('lazyLoader-ready');
                performance.measure('lazyLoader-init', 'lazyLoader-start', 'lazyLoader-ready');
            }
        } catch (error) {
            console.error('LazyLoader: Failed to initialize', error);
            this.setupFallback();
        }
    }

    async loadImageManager() {
        // Check if ImageManager is already loaded
        if (window.ImageManager) {
            this.imageManager = window.ImageManager;
            return;
        }

        // Try to load it
        return new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = 'js/ImageManager.js';
            script.async = true;

            script.onload = () => {
                if (window.ImageManager) {
                    this.imageManager = window.ImageManager;

                    // Configure for mobile Safari
                    this.imageManager.updateConfig({
                        rootMargin: '100px 0px', // Larger margin for Safari
                        threshold: 0.01,
                        maxSimultaneousLoads: 2, // Conservative for mobile
                        enableBlurUp: this.supportsCSSFilter(),
                        debug: window.location.hostname === 'localhost' || 
                               window.location.hostname === '127.0.0.1'
                    });

                    resolve();
                } else {
                    reject(new Error('ImageManager not found after load'));
                }
            };

            script.onerror = () => {
                reject(new Error('Failed to load ImageManager.js'));
            };

            document.head.appendChild(script);
        });
    }

    supportsCSSFilter() {
        // Check if CSS filter is supported (for blur-up)
        const el = document.createElement('div');
        el.style.cssText = 'filter: blur(2px); -webkit-filter: blur(2px);';
        return !!el.style.length && 
               (el.style.filter.includes('blur') || 
                el.style.webkitFilter.includes('blur'));
    }

    setupEventListeners() {
        // Listen for gallery creation
        document.addEventListener('gallery-created', (e) => {
            this.processGallery(e.detail.container, e.detail.memorialId);
        });

        // Listen for memorial view
        document.addEventListener('memorial-view-loaded', (e) => {
            this.processMemorialView(e.detail.container);
        });

        // Listen for lightbox open
        document.addEventListener('lightbox-opened', (e) => {
            this.processLightbox(e.detail.imageElement);
        });

        // Handle page visibility changes (important for mobile Safari)
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'hidden' && this.imageManager) {
                // Pause loading when tab is backgrounded
                this.imageManager.updateConfig({ maxSimultaneousLoads: 0 });
            } else if (document.visibilityState === 'visible' && this.imageManager) {
                // Resume loading when tab is foregrounded
                this.imageManager.updateConfig({ maxSimultaneousLoads: 2 });
            }
        });
    }

    setupFallback() {
        // Fallback: Convert data-src back to src for eager loading
        document.addEventListener('DOMContentLoaded', () => {
            setTimeout(() => {
                const lazyImages = document.querySelectorAll('img[data-src]');
                lazyImages.forEach(img => {
                    if (img.dataset.src && !img.src) {
                        img.src = img.dataset.src;
                    }
                });
            }, 100);
        });

        // Add fallback CSS class
        document.documentElement.classList.add('lazy-loading-fallback');
    }

    injectStyles() {
        // Inject critical styles for loading states
        const styleId = 'lazy-loader-styles';
        if (document.getElementById(styleId)) return;

        const style = document.createElement('style');
        style.id = styleId;
        style.textContent = `
            /* Critical loading styles - injected for immediate paint */
            .lazy-loading {
                background: linear-gradient(
                    90deg,
                    rgba(255,255,255,0.05) 25%,
                    rgba(255,255,255,0.1) 50%,
                    rgba(255,255,255,0.05) 75%
                );
                background-size: 200% 100%;
                animation: lazy-shimmer 1.5s infinite;
            }

            @keyframes lazy-shimmer {
                0% { background-position: -200% 0; }
                100% { background-position: 200% 0; }
            }

            .lazy-loaded {
                animation: lazy-fade-in 0.3s ease-out;
            }

            @keyframes lazy-fade-in {
                from { opacity: 0.5; }
                to { opacity: 1; }
            }

            /* Mobile Safari optimizations */
            .memory-gallery-tile img {
                -webkit-backface-visibility: hidden;
                -webkit-transform: translateZ(0);
                transform: translateZ(0);
            }

            /* Fallback mode */
            .lazy-loading-fallback .memory-gallery-tile img {
                transition: opacity 0.3s;
            }
        `;

        document.head.appendChild(style);
    }

    processGallery(container, memorialId) {
        if (!this.isEnabled || !this.imageManager) {
            this.setupGalleryFallback(container);
            return;
        }

        try {
            const images = container.querySelectorAll('img:not(.lazy-processed)');

            images.forEach((img, index) => {
                img.classList.add('lazy-processed');

                // Mark as loading immediately for paint
                img.classList.add('lazy-loading');

                // Set data attributes for ImageManager
                if (img.src && !img.dataset.src) {
                    img.dataset.src = img.src;
                    img.removeAttribute('src');
                }

                // Generate tiny placeholder for blur-up
                this.generatePlaceholder(img).then(placeholder => {
                    if (placeholder) {
                        img.dataset.placeholder = placeholder;
                    }

                    // Register with ImageManager
                    this.imageManager.registerImage(img, {
                        priority: index < 3, // First 3 images are priority
                        blurUp: true
                    });

                    this.performance.metrics.imagesProcessed++;
                });
            });

            console.log(`LazyLoader: Processed ${images.length} gallery images`);
        } catch (error) {
            console.error('LazyLoader: Failed to process gallery', error);
            this.setupGalleryFallback(container);
        }
    }

    async generatePlaceholder(img) {
        // Create a tiny 4x4 pixel placeholder
        return new Promise(resolve => {
            // For existing loaded images, extract dominant color
            if (img.complete && img.naturalWidth > 0) {
                try {
                    const canvas = document.createElement('canvas');
                    const ctx = canvas.getContext('2d');
                    canvas.width = 4;
                    canvas.height = 4;

                    ctx.drawImage(img, 0, 0, 4, 4);
                    const data = ctx.getImageData(0, 0, 4, 4).data;

                    // Calculate average color
                    let r = 0, g = 0, b = 0;
                    for (let i = 0; i < data.length; i += 4) {
                        r += data[i];
                        g += data[i + 1];
                        b += data[i + 2];
                    }

                    const count = data.length / 4;
                    const color = `rgb(${Math.round(r/count)}, ${Math.round(g/count)}, ${Math.round(b/count)})`;

                    canvas.width = 1;
                    canvas.height = 1;
                    ctx.fillStyle = color;
                    ctx.fillRect(0, 0, 1, 1);

                    resolve(canvas.toDataURL('image/jpeg', 0.1));
                } catch (e) {
                    resolve(null);
                }
            } else {
                // Return theme-based color
                const color = getComputedStyle(document.documentElement)
                    .getPropertyValue('--color-bg-secondary') || '#353839';

                const canvas = document.createElement('canvas');
                canvas.width = 1;
                canvas.height = 1;
                const ctx = canvas.getContext('2d');
                ctx.fillStyle = color;
                ctx.fillRect(0, 0, 1, 1);

                resolve(canvas.toDataURL('image/jpeg', 0.1));
            }
        });
    }

    setupGalleryFallback(container) {
        // Fallback for unsupported browsers
        const images = container.querySelectorAll('img[data-src]');
        images.forEach(img => {
            if (img.dataset.src && !img.src) {
                img.src = img.dataset.src;
                img.classList.remove('lazy-loading');
                img.classList.add('lazy-loading-fallback');
            }
        });
    }

    processMemorialView(container) {
        if (!this.isEnabled) return;

        // Process profile photo
        const profileImg = container.querySelector('.memorial-photo, .profile-photo-preview');
        if (profileImg && !profileImg.classList.contains('lazy-processed')) {
            this.processProfilePhoto(profileImg);
        }

        // Process any other images in memorial view
        const otherImages = container.querySelectorAll('img:not(.lazy-processed):not(.memorial-photo):not(.profile-photo-preview)');
        otherImages.forEach(img => {
            this.processGenericImage(img);
        });
    }

    processProfilePhoto(img) {
        if (!this.isEnabled || !this.imageManager) {
            if (img.dataset.src && !img.src) {
                img.src = img.dataset.src;
            }
            return;
        }

        try {
            img.classList.add('lazy-processed', 'lazy-loading');

            if (img.src && !img.dataset.src) {
                img.dataset.src = img.src;
                img.removeAttribute('src');
            }

            // Profile photos are high priority
            this.imageManager.registerImage(img, {
                priority: true,
                blurUp: false
            });

            this.performance.metrics.imagesProcessed++;
        } catch (error) {
            console.error('LazyLoader: Failed to process profile photo', error);
            if (img.dataset.src && !img.src) {
                img.src = img.dataset.src;
            }
        }
    }

    processLightbox(imageElement) {
        if (!this.isEnabled || !this.imageManager) return;

        try {
            // Lightbox images are highest priority
            this.imageManager.registerImage(imageElement, {
                priority: true,
                blurUp: false
            });

            this.performance.metrics.imagesProcessed++;
        } catch (error) {
            console.error('LazyLoader: Failed to process lightbox image', error);
        }
    }

    processGenericImage(img) {
        if (!this.isEnabled || !this.imageManager) {
            if (img.dataset.src && !img.src) {
                img.src = img.dataset.src;
            }
            return;
        }

        try {
            img.classList.add('lazy-processed');

            if (img.src && !img.dataset.src) {
                img.dataset.src = img.src;
                img.removeAttribute('src');
                img.classList.add('lazy-loading');
            }

            this.imageManager.registerImage(img, {
                priority: false,
                blurUp: true
            });

            this.performance.metrics.imagesProcessed++;
        } catch (error) {
            console.error('LazyLoader: Failed to process image', error);
            if (img.dataset.src && !img.src) {
                img.src = img.dataset.src;
            }
        }
    }

    getPerformanceMetrics() {
        const totalTime = performance.now() - this.performance.startTime;
        return {
            ...this.performance.metrics,
            totalTime: `${totalTime.toFixed(2)}ms`,
            enabled: this.isEnabled,
            supported: this.isSupported
        };
    }

    // Public API
    enable() {
        this.isEnabled = true;
    }

    disable() {
        this.isEnabled = false;
        // Convert all data-src back to src
        document.querySelectorAll('img[data-src]').forEach(img => {
            if (img.dataset.src && !img.src) {
                img.src = img.dataset.src;
                img.classList.remove('lazy-loading');
            }
        });
    }
}

// Create global instance with error boundary
