try {
    lazyLoaderInstance = new LazyLoaderService();
    window.LazyLoader = lazyLoaderInstance;

    // Export for module systems if available
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = lazyLoaderInstance;
    }

    // Add to global app namespace
    if (window.app) {
        window.app.lazyLoader = lazyLoaderInstance;
    }
} catch (error) {
    console.error('Failed to initialize LazyLoader:', error);
