### **FILE 2: `js/core/AppState.js`** - State Management
```javascript
/**
 * AppState Manager v2.0
 * Centralized state management with persistence
 * Error boundary protected
 */

class AppStateManager {
    constructor() {
        this.state = {
            memorials: [],
            activeMemorialId: null,
            sacredPhotoSelections: {},
            ui: {
                currentView: 'home',
                isLoading: false,
                lastBackup: null
            },
            performance: {
                imageLoadTimes: [],
                renderTimes: [],
                memoryUsage: []
            }
        };

        this.listeners = new Map();
        this.errorBoundary = this.createErrorBoundary();
        this.init();
    }

    createErrorBoundary() {
        return {
            catch: (fn) => {
                return (...args) => {
                    try {
                        return fn(...args);
                    } catch (error) {
                        console.error('AppState Error Boundary:', error);
                        this.emit('error', { error, context: 'AppState' });
                        return null;
                    }
                };
            }
        };
    }

    init() {
        this.loadFromStorage();
        this.setupPerformanceMonitoring();
        this.setupMemoryWatchdog();
    }

    // State management
    setState(updates) {
        const safeUpdate = this.errorBoundary.catch(() => {
            const oldState = { ...this.state };
            this.state = { ...this.state, ...updates };
            this.emit('stateChange', { oldState, newState: this.state, updates });

            // Auto-save certain state parts
            if (updates.memorials || updates.sacredPhotoSelections) {
                this.saveToStorage();
            }

            return this.state;
        });

        return safeUpdate() || this.state;
    }

    getState() {
        return { ...this.state };
    }

    // Memorial management
    setMemorials(memorials) {
        return this.setState({ memorials });
    }

    addMemorial(memorial) {
        const safeAdd = this.errorBoundary.catch(() => {
            const memorials = [...this.state.memorials];
            const existingIndex = memorials.findIndex(m => m.id === memorial.id);

            if (existingIndex >= 0) {
                memorials[existingIndex] = memorial;
            } else {
                memorials.push(memorial);
            }

            return this.setState({ memorials });
        });

        return safeAdd() || this.state;
    }

    removeMemorial(id) {
        const safeRemove = this.errorBoundary.catch(() => {
            const memorials = this.state.memorials.filter(m => m.id !== id);
            return this.setState({ memorials });
        });

        return safeRemove() || this.state;
    }

    getMemorial(id) {
        return this.state.memorials.find(m => m.id === id) || null;
    }

    setActiveMemorial(id) {
        return this.setState({ activeMemorialId: id });
    }

    getActiveMemorial() {
        return this.getMemorial(this.state.activeMemorialId);
    }

    // Sacred photo selections
    setSacredPhoto(memorialId, photoId) {
        const safeSet = this.errorBoundary.catch(() => {
            const sacredPhotoSelections = { ...this.state.sacredPhotoSelections };
            sacredPhotoSelections[memorialId] = photoId;
            return this.setState({ sacredPhotoSelections });
        });

        return safeSet() || this.state;
    }

    getSacredPhoto(memorialId) {
        return this.state.sacredPhotoSelections[memorialId] || null;
    }

    clearSacredPhoto(memorialId) {
        const safeClear = this.errorBoundary.catch(() => {
            const sacredPhotoSelections = { ...this.state.sacredPhotoSelections };
            delete sacredPhotoSelections[memorialId];
            return this.setState({ sacredPhotoSelections });
        });

        return safeClear() || this.state;
    }

    // UI state
    setCurrentView(view) {
        return this.setState({ 
            ui: { ...this.state.ui, currentView: view }
        });
    }

    setLoading(isLoading) {
        return this.setState({
            ui: { ...this.state.ui, isLoading }
        });
    }

    // Performance tracking
    trackImageLoad(timeMs) {
        const safeTrack = this.errorBoundary.catch(() => {
            const performance = { ...this.state.performance };
            performance.imageLoadTimes.push(timeMs);

            // Keep only last 100 entries
            if (performance.imageLoadTimes.length > 100) {
                performance.imageLoadTimes = performance.imageLoadTimes.slice(-100);
            }

            return this.setState({ performance });
        });

        safeTrack();
    }

    trackRenderTime(timeMs) {
        const safeTrack = this.errorBoundary.catch(() => {
            const performance = { ...this.state.performance };
            performance.renderTimes.push(timeMs);

            if (performance.renderTimes.length > 50) {
                performance.renderTimes = performance.renderTimes.slice(-50);
            }

            return this.setState({ performance });
        });

        safeTrack();
    }

    // Event system
    on(event, callback) {
        if (!this.listeners.has(event)) {
            this.listeners.set(event, new Set());
        }
        this.listeners.get(event).add(callback);

        // Return unsubscribe function
        return () => {
            const callbacks = this.listeners.get(event);
            if (callbacks) {
                callbacks.delete(callback);
            }
        };
    }

    emit(event, data) {
        const callbacks = this.listeners.get(event);
        if (callbacks) {
            callbacks.forEach(callback => {
                try {
                    callback(data);
                } catch (error) {
                    console.error(`AppState listener error for ${event}:`, error);
                }
            });
        }
    }

    // Storage
    loadFromStorage() {
        try {
            const saved = localStorage.getItem('contactMemorial_state');
            if (saved) {
                const parsed = JSON.parse(saved);

                // Merge with defaults (safely)
                if (parsed.sacredPhotoSelections) {
                    this.state.sacredPhotoSelections = parsed.sacredPhotoSelections;
                }

                if (parsed.ui && parsed.ui.lastBackup) {
                    this.state.ui.lastBackup = parsed.ui.lastBackup;
                }

                console.log('AppState: Loaded from storage');
            }
        } catch (error) {
            console.warn('AppState: Failed to load from storage', error);
            // Clear corrupted data
            try {
                localStorage.removeItem('contactMemorial_state');
            } catch (e) {}
        }
    }

    saveToStorage() {
        try {
            const toSave = {
                sacredPhotoSelections: this.state.sacredPhotoSelections,
                ui: {
                    lastBackup: this.state.ui.lastBackup
                },
                version: '2.0',
                timestamp: new Date().toISOString()
            };

            localStorage.setItem('contactMemorial_state', JSON.stringify(toSave));
        } catch (error) {
            console.warn('AppState: Failed to save to storage', error);
        }
    }

    // Performance monitoring
    setupPerformanceMonitoring() {
        // Track memory if available
        if (performance.memory) {
            setInterval(() => {
                this.state.performance.memoryUsage.push(performance.memory.usedJSHeapSize);
                if (this.state.performance.memoryUsage.length > 60) {
                    this.state.performance.memoryUsage = this.state.performance.memoryUsage.slice(-60);
                }
            }, 1000);
        }
    }

    setupMemoryWatchdog() {
        // Warn if memory usage is consistently high
        setInterval(() => {
            if (performance.memory) {
                const usedMB = performance.memory.usedJSHeapSize / 1024 / 1024;
                const limitMB = performance.memory.jsHeapSizeLimit / 1024 / 1024;

                if (usedMB > limitMB * 0.8) {
                    console.warn(`High memory usage: ${usedMB.toFixed(2)}MB / ${limitMB.toFixed(2)}MB`);
                    this.emit('memoryWarning', { usedMB, limitMB });
                }
            }
        }, 30000);
    }

    // Debug/development
    getMetrics() {
        const perf = this.state.performance;

        const avgImageLoad = perf.imageLoadTimes.length > 0 
            ? perf.imageLoadTimes.reduce((a, b) => a + b, 0) / perf.imageLoadTimes.length
            : 0;

        const avgRenderTime = perf.renderTimes.length > 0
            ? perf.renderTimes.reduce((a, b) => a + b, 0) / perf.renderTimes.length
            : 0;

        return {
            memorialsCount: this.state.memorials.length,
            sacredPhotoSelections: Object.keys(this.state.sacredPhotoSelections).length,
            avgImageLoadTime: `${avgImageLoad.toFixed(2)}ms`,
            avgRenderTime: `${avgRenderTime.toFixed(2)}ms`,
            memorySamples: perf.memoryUsage.length
        };
    }

    reset() {
        this.state = {
            memorials: [],
            activeMemorialId: null,
            sacredPhotoSelections: {},
            ui: {
                currentView: 'home',
                isLoading: false,
                lastBackup: null
            },
            performance: {
                imageLoadTimes: [],
                renderTimes: [],
                memoryUsage: []
            }
        };

        try {
            localStorage.removeItem('contactMemorial_state');
        } catch (e) {}

        this.emit('reset', {});
    }
}

// Global instance with error protection
let appStateInstance = null;

try {
    appStateInstance = new AppStateManager();
    window.AppState = appStateInstance;

    // Export for module systems
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = appStateInstance;
    }

    // Add to global app namespace
    if (window.app) {
        window.app.state = appStateInstance;
    }
} catch (error) {
    console.error('Failed to initialize AppState:', error);
    // Fallback minimal state
    window.AppState = {
        getState: () => ({ memorials: [], ui: { currentView: 'home' } }),
        setState: () => {},
        on: () => () => {}
    };
}

// Make available immediately
if (!window.appStateInstance && document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        if (!appStateInstance) {
            try {
                appStateInstance = new AppStateManager();
                window.AppState = appStateInstance;
            } catch (e) {
                // Silent fail
            }
        }
    });
}
