/**
 * Contact Memorial App v2.0 - Main Entry Point
 * Modularized with error boundaries and progressive enhancement
 */

// Global error handler
window.addEventListener('error', function(e) {
    console.error('Global error caught:', e.error);
    // Don't break the app - just log
});

window.addEventListener('unhandledrejection', function(e) {
    console.error('Unhandled promise rejection:', e.reason);
});

// Feature detection for critical APIs
const FEATURE_SUPPORT = {
    indexedDB: 'indexedDB' in window,
    serviceWorker: 'serviceWorker' in navigator,
    fetch: 'fetch' in window,
    promise: typeof Promise !== 'undefined',
    classList: 'classList' in document.createElement('div')
};

// Check minimum requirements
if (!FEATURE_SUPPORT.indexedDB || !FEATURE_SUPPORT.promise || !FEATURE_SUPPORT.classList) {
    document.body.innerHTML = `
        <div style="padding: 40px; text-align: center; color: white;">
            <h2>Browser Compatibility Issue</h2>
            <p>Your browser doesn't support all required features for this app.</p>
            <p>Please try using a modern browser like Chrome, Firefox, or Safari.</p>
            <p>Contact Memorial requires IndexedDB and ES6 support.</p>
        </div>
    `;
    throw new Error('Browser lacks required features');
}

// Main App Class
class ContactMemorialApp {
    constructor() {
        this.modules = {};
        this.isInitialized = false;
        this.initPromise = null;

        // Bind methods
        this.init = this.init.bind(this);
        this.loadModule = this.loadModule.bind(this);
        this.safeCall = this.safeCall.bind(this);
    }

    async init() {
        if (this.initPromise) return this.initPromise;

        this.initPromise = (async () => {
            try {
                console.log('Contact Memorial App v2.0 - Initializing...');

                // Load core modules
                await this.loadCoreModules();

                // Initialize modules in order
                await this.initializeModules();

                // Setup event listeners
                this.setupEventListeners();

                // Check for existing data migration
                await this.checkDataMigration();

                this.isInitialized = true;

                console.log('App initialized successfully');

                // Dispatch ready event
                document.dispatchEvent(new CustomEvent('app:ready'));

                return this;
            } catch (error) {
                console.error('App initialization failed:', error);
                this.showErrorUI(error);
                throw error;
            }
        })();

        return this.initPromise;
    }

    async loadCoreModules() {
        // Load critical modules first
        const modulesToLoad = [
            { name: 'StorageService', path: 'js/core/StorageService.js' },
            { name: 'AppState', path: 'js/core/AppState.js' },
            { name: 'Router', path: 'js/core/Router.js' },
            { name: 'LazyLoader', path: 'js/services/lazyLoader.js' }
        ];

        for (const module of modulesToLoad) {
            await this.loadModule(module.name, module.path);
        }
    }

    async loadModule(name, path) {
        try {
            // Check if already loaded globally
            if (window[name]) {
                this.modules[name] = window[name];
                console.log(`Module ${name} already loaded`);
                return;
            }

            // Load script dynamically
            await new Promise((resolve, reject) => {
                const script = document.createElement('script');
                script.src = path;
                script.async = false; // Load in order for dependencies

                script.onload = () => {
                    if (window[name]) {
                        this.modules[name] = window[name];
                        resolve();
                    } else {
                        reject(new Error(`Module ${name} not found after loading ${path}`));
                    }
                };

                script.onerror = () => {
                    reject(new Error(`Failed to load module ${name} from ${path}`));
                };

                document.head.appendChild(script);
            });

            console.log(`Module ${name} loaded successfully`);
        } catch (error) {
            console.error(`Failed to load module ${name}:`, error);

            // Provide fallback for critical modules
            if (name === 'StorageService') {
                this.modules.StorageService = this.createStorageFallback();
            } else if (name === 'Router') {
                this.modules.Router = this.createRouterFallback();
            }

            throw error;
        }
    }

    async initializeModules() {
        // Initialize AppState first (it has no dependencies)
        if (this.modules.AppState) {
            await this.safeCall(() => this.modules.AppState.init?.());
        }

        // Initialize StorageService
        if (this.modules.StorageService) {
            await this.safeCall(() => this.modules.StorageService.initDB?.());
        }

        // Load memorial data
        await this.loadMemorialData();

        // Initialize UI components
        await this.initializeUIComponents();

        // Initialize LazyLoader last
        if (this.modules.LazyLoader) {
            await this.safeCall(() => this.modules.LazyLoader.init?.());
        }
    }

