        try {
            if (this.modules.StorageService) {
                const memorials = await this.modules.StorageService.getAllMemorials();

                if (this.modules.AppState) {
                    this.modules.AppState.setMemorials(memorials);
                }

                // Store in global for backward compatibility
                if (!window.app?.state?.memorials) {
                    if (!window.app) window.app = {};
                    if (!window.app.state) window.app.state = {};
                    window.app.state.memorials = memorials;
                }

                console.log(`Loaded ${memorials.length} memorials`);
            }
        } catch (error) {
            console.error('Failed to load memorial data:', error);
