            const memorials = await this.getAllMemorials();

            // Estimate photo count by checking references
            const photoRefs = new Set();
            memorials.forEach(m => {
                if (m.profilePhoto && !m.profilePhoto.startsWith('http') && 
                    !m.profilePhoto.startsWith('default')) {
                    photoRefs.add(m.profilePhoto);
                }
                if (m.additionalPhotos) {
                    m.additionalPhotos.forEach(id => {
                        if (id && !id.startsWith('http') && !id.startsWith('default')) {
                            photoRefs.add(id);
                        }
                    });
                }
            });

            return {
                memorialCount: memorials.length,
                photoCount: photoRefs.size,
                storage: 'indexedDB'
            };
        } catch (error) {
            return { error: error.message };
        }
    }
}

// Create global instance with error protection
let storageInstance = null;

try {
    storageInstance = new StorageService();
    window.StorageService = storageInstance;
    window.storage = storageInstance; // Legacy global

    // Export for module systems
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = storageInstance;
    }
} catch (error) {
    console.error('Failed to initialize StorageService:', error);

    // Create minimal fallback
    window.StorageService = {
        useFallback: true,
        isInitialized: false,
        getAllMemorials: async () => [],
        saveMemorial: async () => ({ id: 'error' }),
        getMemorial: async () => null,
        deleteMemorial: async () => true,
        savePhoto: async () => 'error',
        getPhoto: async () => null
    };
    window.storage = window.StorageService;
}

// Make available immediately
if (!storageInstance && document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        if (!storageInstance) {
            try {
                storageInstance = new StorageService();
                window.StorageService = storageInstance;
                window.storage = storageInstance;
            } catch (e) {
