        const instanceNames = ['AppState', 'StorageService', 'LazyLoader'];
        if (instanceNames.includes(name) && window[name]) {
            this.modules[name] = window[name];
            console.log(`Instance ${name} already loaded`);
            return;
        }

        // Load script dynamically (only if not already loaded)
        const scriptId = `module-${name}`;
        if (document.getElementById(scriptId)) {
            // Script already loading or loaded
            return new Promise((resolve) => {
                const checkInterval = setInterval(() => {
                    if (window[name]) {
                        clearInterval(checkInterval);
                        if (instanceNames.includes(name)) {
                            this.modules[name] = window[name];
                        } else if (name === 'Router') {
                            this.modules[name] = new window.Router();
                        }
                        resolve();
                    }
                }, 100);

                // Timeout after 5 seconds
                setTimeout(() => {
                    clearInterval(checkInterval);
                    console.warn(`Timeout waiting for ${name}`);
                    resolve();
                }, 5000);
            });
        }

        return new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = path;
            script.id = scriptId;
            script.async = false; // Load in order for dependencies

            script.onload = () => {
                setTimeout(() => {
                    if (instanceNames.includes(name) && window[name]) {
                        this.modules[name] = window[name];
                        resolve();
                    } else if (name === 'Router' && window.Router) {
                        this.modules[name] = new window.Router();
                        resolve();
                    } else {
                        console.warn(`${name} not found in window after loading`);
                        resolve(); // Don't reject - allow app to continue
                    }
                }, 100);
            };

            script.onerror = () => {
                console.warn(`Failed to load script: ${path}`);
                resolve(); // Don't reject - allow app to continue with fallback
            };

            document.head.appendChild(script);
        });

    } catch (error) {
        console.error(`Failed to load module ${name}:`, error);

        // Provide fallback for critical modules
        if (name === 'Router') {
            this.modules.Router = this.createRouterFallback();
        } else if (name === 'StorageService') {
            this.modules.StorageService = this.createStorageFallback();
        }

        return Promise.resolve(); // Always resolve, never reject
    }
}
