            { name: 'AppState', path: 'js/core/AppState.js', type: 'instance' },
            { name: 'Router', path: 'js/core/Router.js', type: 'class' },
            { name: 'LazyLoader', path: 'js/services/lazyLoader.js', type: 'instance' }
