            // Load script dynamically
            return new Promise((resolve) => {
                const script = document.createElement('script');
                script.src = path;
                script.async = false;

                script.onload = () => {
                    setTimeout(() => {
                        if (type === 'instance' && window[name]) {
                            this.modules[name] = window[name];
                            console.log(`Loaded instance ${name}`);
                        } else if (type === 'class' && window[name]) {
                            this.modules[name] = new window[name]();
                            console.log(`Instantiated class ${name}`);
                        } else {
                            console.warn(`${name} not found in window after loading`);
                        }
                        resolve();
