            }
        } catch (error) {
            console.warn('Data migration failed:', error);
        }
    }

    // Utility methods
    escapeHtml(text) {
        if (!text) return '';
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    showToast(message, type = 'info') {
        const toast = document.getElementById('toast');
        const toastMessage = document.getElementById('toastMessage');

        if (toast && toastMessage) {
            toastMessage.textContent = message;

            const colors = {
                success: '#6ba388',
                error: '#d16666',
                warning: '#d1a566',
                info: '#4A90E2'
            };

            toast.style.borderLeftColor = colors[type] || colors.info;
            toast.classList.add('show');

            setTimeout(() => {
                toast.classList.remove('show');
            }, 3000);
        }
    }

    showErrorUI(error) {
        console.error('Showing error UI:', error);
        // Don't break the UI - just log for now
    }

    safeCall(fn) {
        try {
            return fn();
        } catch (error) {
            console.error('Safe call failed:', error);
            return null;
        }
    }

    createStorageFallback() {
        console.warn('Using storage fallback - data may not persist');
        return {
            async getAllMemorials() { return []; },
            async saveMemorial(memorial) { 
                console.log('Fallback: saving memorial', memorial.id);
                return memorial; 
            },
            async getMemorial(id) { return null; },
            async deleteMemorial(id) { return true; },
            async savePhoto() { return 'fallback'; },
            async getPhoto() { return null; }
        };
    }

    createRouterFallback() {
        console.warn('Using router fallback');
        return {
            navigate(view) {
                const views = ['home', 'dashboard', 'memorial'];
                views.forEach(v => {
                    const el = document.getElementById(v + 'View');
                    if (el) {
                        el.classList.remove('active');
                        el.style.display = 'none';
                    }
                });

                const target = document.getElementById(view + 'View');
                if (target) {
                    target.classList.add('active');
                    target.style.display = 'block';
                }

                // Update buttons
                document.querySelectorAll('.view-toggle .btn').forEach(btn => {
                    btn.classList.remove('active');
                });

                const activeBtn = document.getElementById(view + 'Btn');
                if (activeBtn) {
                    activeBtn.classList.add('active');
                }
            },
            init() {
                this.navigate('home');
            }
        };
    }

    // Debug methods
    debug() {
        return {
            modules: Object.keys(this.modules),
            state: this.modules.AppState ? this.modules.AppState.getState() : null,
            features: FEATURE_SUPPORT,
            lazyLoader: this.modules.LazyLoader ? this.modules.LazyLoader.getPerformanceMetrics() : null
        };
    }
}

