/**
 * ImageManager v2.0 - Fixed for regular script tags
 * Lazy loading with blur-up placeholders and progressive loading
 * 100% backward compatible with existing data structure
 */

class ImageManager {
    constructor(options = {}) {
        this.options = {
            rootMargin: '50px 0px',
            threshold: 0.01,
            placeholderColor: '#353839',
            placeholderBlur: '20px',
            maxSimultaneousLoads: 3,
            enableBlurUp: true,
            debug: false,
            ...options
        };

        this.observer = null;
        this.observedElements = new Map();
        this.loadingQueue = [];
        this.currentLoads = 0;
        this.performanceMetrics = {
            totalImages: 0,
            lazyLoaded: 0,
            cachedHits: 0,
            loadTimes: []
        };

        this.init();
    }

    init() {
        // Check if IntersectionObserver is supported
        if ('IntersectionObserver' in window) {
            this.initObserver();
        } else {
            this.loadPolyfill();
