        metrics.loadTimes = [];
    }

    /**
     * Pause loading when tab is backgrounded
     */
    pauseLoading() {
        this.options.maxSimultaneousLoads = 0;
        this.loadingQueue = [];
    }

    /**
     * Resume loading when tab is foregrounded
     */
    resumeLoading() {
        this.options.maxSimultaneousLoads = 3;
        this.processQueue();
    }

    /**
     * Update configuration
     */
    updateConfig(newOptions) {
        this.options = { ...this.options, ...newOptions };

        if (this.observer && newOptions.rootMargin) {
            // Recreate observer with new rootMargin
            this.observer.disconnect();
            this.initObserver();

            // Re-observe all elements
            this.observedElements.forEach((_, img) => {
                this.observer.observe(img);
            });
        }
    }

    /**
     * Cleanup
     */
    destroy() {
        if (this.observer) {
            this.observer.disconnect();
        }

        this.observedElements.clear();
        this.loadingQueue = [];
        this.currentLoads = 0;
    }

    log(...args) {
        if (this.options.debug) {
            console.log('[ImageManager]', ...args);
        }
    }
}

