 * Works on all platforms with proper fallbacks
 */

class PWAInstaller {
    constructor() {
        this.deferredPrompt = null;
        this.isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
        this.isStandalone = window.matchMedia('(display-mode: standalone)').matches || 
                           window.navigator.standalone === true;

        this.init();
    }

    init() {
        // Listen for install prompt
        window.addEventListener('beforeinstallprompt', this.handleBeforeInstallPrompt.bind(this));

        // Check if already installed
        this.checkIfInstalled();

        // Setup button listeners with error boundaries
        this.setupButtonListeners();

        // Log initialization
        console.log('PWAInstaller: Initialized', {
            isIOS: this.isIOS,
            isStandalone: this.isStandalone,
            deferredPrompt: !!this.deferredPrompt
        });
    }

    handleBeforeInstallPrompt(e) {
        console.log('PWAInstaller: beforeinstallprompt fired');

        // Prevent Chrome 67 and earlier from automatically showing the prompt
        e.preventDefault();

        // Stash the event so it can be triggered later
        this.deferredPrompt = e;

        // Update UI to show install button
        this.showInstallButton();

        // Dispatch event for other components (optional)
        document.dispatchEvent(new CustomEvent('pwa:install-available'));
    }

    checkIfInstalled() {
        if (this.isStandalone) {
            console.log('PWAInstaller: App is already installed as PWA');
            this.hideInstallButton();
        }
    }

    showInstallButton() {
        // Find ALL install buttons and show them
        const installButtons = document.querySelectorAll('[id*="install"], [class*="install"], button:contains("Install")');

        installButtons.forEach(button => {
            button.style.display = 'block';
            button.setAttribute('data-pwa-install', 'available');
        });

        // Also show the specific footer button if it exists
        const footerBtn = document.getElementById('installBtnFooter');
        if (footerBtn) {
            footerBtn.style.display = 'block';
        }
    }

    hideInstallButton() {
        // Hide ALL install buttons
        const installButtons = document.querySelectorAll('[id*="install"], [class*="install"], button:contains("Install")');

        installButtons.forEach(button => {
            button.style.display = 'none';
            button.removeAttribute('data-pwa-install');
        });
    }

    setupButtonListeners() {
        // Use event delegation to catch ALL install button clicks
        document.addEventListener('click', (e) => {
            // Check if click is on or inside an install button
            const installButton = e.target.closest('[id*="install"], [class*="install"], [data-pwa-install]');

            if (installButton) {
                e.preventDefault();
                e.stopPropagation();
                this.handleInstallClick();
            }
        });

        // Also explicitly listen to the known install button
        const footerBtn = document.getElementById('installBtnFooter');
        if (footerBtn) {
            // Remove any existing listeners to prevent duplicates
            const newFooterBtn = footerBtn.cloneNode(true);
            footerBtn.parentNode.replaceChild(newFooterBtn, footerBtn);

            newFooterBtn.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();
                this.handleInstallClick();
            });
        }
    }

    async handleInstallClick() {
        console.log('PWAInstaller: Install button clicked');

        // If already installed, hide button and return
        if (this.isStandalone) {
            console.log('PWAInstaller: Already installed, hiding button');
            this.hideInstallButton();
            return;
        }

        // If we have a deferred prompt (Chrome, Edge, etc.)
        if (this.deferredPrompt) {
            try {
                // Show the install prompt
                this.deferredPrompt.prompt();

                // Wait for the user to respond to the prompt
                const { outcome } = await this.deferredPrompt.userChoice;

                console.log(`PWAInstaller: User ${outcome}ed the install`);

                if (outcome === 'accepted') {
                    // Hide install button since PWA was installed
                    this.hideInstallButton();
                    document.dispatchEvent(new CustomEvent('pwa:installed'));
                }

                // Clear the deferred prompt
                this.deferredPrompt = null;

            } catch (error) {
                console.error('PWAInstaller: Error during install prompt', error);
                this.showIOSInstructions();
            }
        } else {
            // No deferred prompt - show platform-specific instructions
            if (this.isIOS) {
                this.showIOSInstructions();
            } else {
                this.showGenericInstructions();
            }
        }
    }

