// Self-check: Verify the installer is working
setTimeout(() => {
    if (!window.PWAInstaller) {
        console.error('PWAInstaller failed to initialize!');
        // Create fallback
        window.PWAInstaller = {
            showInstallPrompt: () => alert('Install not available'),
            isInstallable: () => false
        };
    } else {
        console.log('PWAInstaller: Self-check passed');
    }
}, 1000);
