        <script>
            // These listeners fix common issues and won't break
            document.addEventListener('DOMContentLoaded', function() {
                console.log('Setting up self-healing event listeners...');

                // 1. File input handling (works even if formManager doesn't exist)
                const fileInput = $('#fileInput');
                const galleryInput = $('#galleryInput');

                if (fileInput) {
                    fileInput.addEventListener('change', async function(e) {
                        const file = e.target.files[0];
                        if (file && window.formManager?.setProfilePhoto) {
                            try {
                                const resized = await resizeImage(file);
                                window.formManager.setProfilePhoto(resized);
                            } catch (error) {
                                console.log('Image resize failed, using original');
                                window.formManager.setProfilePhoto(file);
                            }
                        }
                    });
                }

                if (galleryInput) {
                    galleryInput.addEventListener('change', async function(e) {
                        if (e.target.files.length > 0 && window.formManager?.addGalleryPhotos) {
                            const files = Array.from(e.target.files);
                            try {
                                const resizedFiles = await Promise.all(files.map(f => resizeImage(f)));
                                window.formManager.addGalleryPhotos(resizedFiles);
                            } catch (error) {
                                console.log('Batch resize failed, adding originals');
                                window.formManager.addGalleryPhotos(files);
                            }
                        }
                    });
                }

                // 2. Image resize utility (always available)
                if (!window.resizeImage) {
                    window.resizeImage = function(file, maxWidth = 1024) {
                        return new Promise((resolve) => {
                            const reader = new FileReader();
                            reader.onload = (e) => {
                                const img = new Image();
                                img.onload = () => {
                                    const canvas = document.createElement('canvas');
                                    let width = img.width;
                                    let height = img.height;

                                    if (width > maxWidth) {
                                        height *= maxWidth / width;
                                        width = maxWidth;
                                    }

                                    canvas.width = width;
                                    canvas.height = height;
                                    const ctx = canvas.getContext('2d');
                                    ctx.drawImage(img, 0, 0, width, height);

                                    canvas.toBlob((blob) => resolve(blob), file.type, 0.85);
                                };
                                img.src = e.target.result;
                            };
                            reader.readAsDataURL(file);
                        });
                    };
                }

                // 3. Navigation buttons (always work)
