/**
 * ImageUploadManager.js - Handles all image uploads for memorials
 * Works independently of other modules
 */

class ImageUploadManager {
    constructor() {
        this.profilePhoto = null;
        this.galleryPhotos = [];
        this.maxGalleryPhotos = 10;

        this.init();
    }

    init() {
        console.log('ImageUploadManager: Initializing');
        this.setupFileInputs();
        this.setupEventListeners();
    }

    setupFileInputs() {
        // Profile photo click handler
        const profileContainer = document.querySelector('.profile-photo-container');
        const fileInput = document.getElementById('fileInput');

        if (profileContainer && fileInput) {
            profileContainer.addEventListener('click', () => {
                fileInput.click();
            });

            fileInput.addEventListener('change', (e) => {
                this.handleProfilePhotoSelect(e);
            });
        }

        // Gallery input
        const galleryInput = document.getElementById('galleryInput');
        if (galleryInput) {
            galleryInput.addEventListener('change', (e) => {
                this.handleGalleryPhotosSelect(e);
            });
        }
    }

    setupEventListeners() {
        // Listen for when we need to clear images
        document.addEventListener('memorial:saved', () => {
            this.clearAllImages();
        });

        document.addEventListener('memorial:edit-started', () => {
            // Reset when starting new memorial
            this.profilePhoto = null;
            this.galleryPhotos = [];
            this.updateProfilePreview();
            this.updateGalleryPreview();
        });
    }

    async handleProfilePhotoSelect(event) {
        const file = event.target.files[0];
        if (!file) return;

        if (!file.type.startsWith('image/')) {
            showToast('Please select an image file', 'error');
            return;
        }

        try {
            // Resize image for performance
            const resized = await this.resizeImage(file, 400, 400);
            this.profilePhoto = resized;
            this.updateProfilePreview();
            showToast('Profile photo selected', 'success');

            // Clear the input so same file can be selected again
            event.target.value = '';
        } catch (error) {
            console.error('Error processing profile photo:', error);
            showToast('Failed to process image', 'error');
        }
    }

    async handleGalleryPhotosSelect(event) {
        const files = Array.from(event.target.files);
        if (files.length === 0) return;

        // Check if adding these would exceed limit
        const totalAfterAdd = this.galleryPhotos.length + files.length;
        if (totalAfterAdd > this.maxGalleryPhotos) {
            showToast(`Maximum ${this.maxGalleryPhotos} gallery photos allowed`, 'warning');
            files.splice(this.maxGalleryPhotos - this.galleryPhotos.length);
        }

        try {
            const imageFiles = files.filter(f => f.type.startsWith('image/'));

            if (imageFiles.length === 0) {
                showToast('Please select image files only', 'error');
                return;
            }

            // Process images in batches to avoid blocking UI
            const processedImages = [];
            for (const file of imageFiles) {
                try {
                    const resized = await this.resizeImage(file, 800, 800);
                    processedImages.push(resized);
                } catch (error) {
                    console.warn('Failed to process image:', file.name, error);
                }
            }

            this.galleryPhotos.push(...processedImages);
            this.updateGalleryPreview();

            showToast(`Added ${processedImages.length} photo(s) to gallery`, 'success');

            // Clear the input
            event.target.value = '';
        } catch (error) {
            console.error('Error processing gallery photos:', error);
            showToast('Failed to process some images', 'error');
        }
    }

    resizeImage(file, maxWidth, maxHeight) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();

            reader.onload = (e) => {
                const img = new Image();
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    let width = img.width;
                    let height = img.height;

                    // Calculate new dimensions
                    if (width > height) {
                        if (width > maxWidth) {
                            height *= maxWidth / width;
                            width = maxWidth;
                        }
                    } else {
                        if (height > maxHeight) {
                            width *= maxHeight / height;
                            height = maxHeight;
                        }
                    }

                    canvas.width = width;
                    canvas.height = height;

                    const ctx = canvas.getContext('2d');
                    ctx.drawImage(img, 0, 0, width, height);

                    canvas.toBlob(
                        (blob) => {
                            if (!blob) {
                                reject(new Error('Canvas toBlob failed'));
                                return;
                            }
                            // Create a new file with the resized blob
                            const resizedFile = new File([blob], file.name, {
                                type: 'image/jpeg',
                                lastModified: Date.now()
                            });
                            resolve(resizedFile);
                        },
                        'image/jpeg',
                        0.85 // Quality
                    );
                };

                img.onerror = () => reject(new Error('Failed to load image'));
                img.src = e.target.result;
            };

            reader.onerror = () => reject(new Error('Failed to read file'));
            reader.readAsDataURL(file);
        });
    }

    updateProfilePreview() {
        const placeholder = document.getElementById('profilePhotoPlaceholder');
        const preview = document.getElementById('profilePhotoPreview');

        if (!placeholder || !preview) return;

        if (this.profilePhoto) {
            const url = URL.createObjectURL(this.profilePhoto);
            preview.src = url;
            preview.style.display = 'block';
            placeholder.style.display = 'none';

            // Revoke URL when preview changes
            setTimeout(() => URL.revokeObjectURL(url), 1000);
        } else {
            preview.style.display = 'none';
            placeholder.style.display = 'flex';
        }
    }

    updateGalleryPreview() {
        const container = document.getElementById('galleryPreview');
        if (!container) return;

        // Clear existing previews
        container.innerHTML = '';

        // Add current gallery photos
        this.galleryPhotos.forEach((photo, index) => {
            const url = URL.createObjectURL(photo);
            const item = document.createElement('div');
            item.className = 'gallery-preview-item';
            item.innerHTML = `
                <img src="${url}" alt="Gallery ${index + 1}" loading="lazy">
                <button class="remove-photo" data-index="${index}" title="Remove">×</button>
            `;
            container.appendChild(item);

            // Set up remove button
            item.querySelector('.remove-photo').addEventListener('click', (e) => {
                e.stopPropagation();
                this.removeGalleryPhoto(index);
            });

            // Revoke URL after a bit
            setTimeout(() => URL.revokeObjectURL(url), 1000);
        });

        // Show count
        if (this.galleryPhotos.length > 0) {
            const count = document.createElement('div');
            count.style.cssText = `
                width: 100%;
                text-align: center;
                font-size: 0.9em;
                color: var(--color-text-secondary);
                margin-top: 5px;
            `;
            count.textContent = `${this.galleryPhotos.length} of ${this.maxGalleryPhotos} photos`;
            container.appendChild(count);
        }
    }

    removeGalleryPhoto(index) {
        if (index >= 0 && index < this.galleryPhotos.length) {
            this.galleryPhotos.splice(index, 1);
            this.updateGalleryPreview();
            showToast('Photo removed from gallery', 'info');
        }
    }

    clearAllImages() {
        this.profilePhoto = null;
        this.galleryPhotos = [];
        this.updateProfilePreview();
        this.updateGalleryPreview();
    }

    // Public API for getting images
    getProfilePhoto() {
        return this.profilePhoto;
    }

    getGalleryPhotos() {
        return [...this.galleryPhotos]; // Return copy
    }

    // Load existing images when editing
    loadExistingImages(profileBlob, galleryBlobs) {
        if (profileBlob) {
            this.profilePhoto = new File([profileBlob], 'profile.jpg', { type: 'image/jpeg' });
            this.updateProfilePreview();
        }

        if (galleryBlobs && Array.isArray(galleryBlobs)) {
            this.galleryPhotos = galleryBlobs.map((blob, i) => 
                new File([blob], `gallery-${i}.jpg`, { type: 'image/jpeg' })
            );
            this.updateGalleryPreview();
        }
    }
}

// Initialize globally
window.ImageUploadManager = new ImageUploadManager();
