// Convert images to base64 for storage
async function saveMemorialWithImages(memorialData) {
    const memorial = { ...memorialData };

    // Convert profile photo to base64
    if (profilePhoto) {
        memorial.profilePhoto = await blobToBase64(profilePhoto);
    }

    // Convert gallery photos to base64 array
    if (galleryPhotos.length > 0) {
        memorial.galleryPhotos = [];
        for (const photo of galleryPhotos) {
            const base64 = await blobToBase64(photo);
            memorial.galleryPhotos.push(base64);
        }
    }

    // Save memorial with images
    await StorageService.saveMemorial(memorial);

    // Clear images after save
    window.ImageUploadManager.clearAllImages();
}

// Helper function
function blobToBase64(blob) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(blob);
    });
}
