        // 2. Listen for Chrome/Edge install prompt (NOT on iOS)
        if (!this.isIOS) {
            window.addEventListener('beforeinstallprompt', this.handleBeforeInstallPrompt.bind(this));
        }

        // 3. Setup button click handler
        this.setupInstallButton();

        // 4. On iOS, show the button immediately (it will show instructions)
        if (this.isIOS) {
            this.showInstallButton();
        }
    }

    handleBeforeInstallPrompt(e) {
        console.log('PWAInstaller: Chrome/Edge install prompt available');
        e.preventDefault();
        this.deferredPrompt = e;
        this.showInstallButton();
    }

    setupInstallButton() {
        const installBtn = document.getElementById('installBtnFooter');

        if (!installBtn) {
            console.error('PWAInstaller: Install button not found!');
            return;
        }

        // Remove any existing listeners
        const newBtn = installBtn.cloneNode(true);
        installBtn.parentNode.replaceChild(newBtn, installBtn);

        // Add click handler
        newBtn.addEventListener('click', (e) => {
            e.preventDefault();
            this.handleInstallClick();
        });

        // Show button (will be hidden if already installed)
        newBtn.style.display = 'block';
    }

    showInstallButton() {
        const btn = document.getElementById('installBtnFooter');
        if (btn) {
            btn.style.display = 'block';
            btn.style.opacity = '1';
        }
    }

    hideInstallButton() {
        const btn = document.getElementById('installBtnFooter');
        if (btn) {
            btn.style.display = 'none';
        }
    }

    async handleInstallClick() {
        console.log('PWAInstaller: Install clicked');

        // Already installed? Hide and return
        if (this.isStandalone) {
            this.hideInstallButton();
            return;
        }

        // Handle based on platform
        if (this.isIOS) {
            this.showIOSInstructions();
        } else if (this.deferredPrompt) {
            // Chrome/Edge
            await this.showChromeInstallPrompt();
        } else {
            // Other browsers or prompt not available yet
            this.showGenericInstructions();
        }
    }

    async showChromeInstallPrompt() {
        try {
            this.deferredPrompt.prompt();
            const { outcome } = await this.deferredPrompt.userChoice;

            if (outcome === 'accepted') {
                console.log('PWAInstaller: User accepted install');
                this.hideInstallButton();
            }

            this.deferredPrompt = null;
        } catch (error) {
            console.error('PWAInstaller: Chrome install failed', error);
            this.showGenericInstructions();
        }
