import './SplashScreen.css';

interface SplashScreenProps {
  theme: 'light' | 'dark';
  onComplete?: () => void;
}

const SplashScreen: React.FC<SplashScreenProps> = ({ theme, onComplete }) => {
  const navigate = useNavigate();
  const [progress, setProgress] = useState(0);
  const [currentMessage, setCurrentMessage] = useState(0);
  const [isComplete, setIsComplete] = useState(false);

  const transitionMessages = [
    "Initializing Sacred Space...",
    "Connecting to Abundance Frequency...",
    "Preparing Your Journey...",
    "Harmonizing Energies...",
    "Activating Inner Alchemy..."
  ];

  // Initialize with button sound
  useEffect(() => {
    buttonSoundService.play('enter');
  }, []);

  // Progress simulation
  useEffect(() => {
    const interval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(interval);
          setIsComplete(true);
          return 100;
        }
        return prev + 1;
      });
    }, 40);

    return () => clearInterval(interval);
  }, []);

  // Message rotation
  useEffect(() => {
    if (progress >= 100) return;

    const messageInterval = setInterval(() => {
      setCurrentMessage(prev => (prev + 1) % transitionMessages.length);
    }, 1500);

    return () => clearInterval(messageInterval);
  }, [progress]);

  // Auto-transition on completion
  useEffect(() => {
    if (isComplete) {
      const timer = setTimeout(() => {
        buttonSoundService.play('confirm');
        if (onComplete) {
          onComplete();
        } else {
          navigate('/auth');
        }
      }, 800);

      return () => clearTimeout(timer);
    }
