import React, { useEffect, useState, useRef } from 'react';
import { startAmbience } from '../services/audioService';
import { buttonSoundService } from '../services/buttonSoundService';

interface SplashScreenProps {
  theme: 'light' | 'dark';
  onComplete: () => void;
}

const SplashScreen: React.FC<SplashScreenProps> = ({ theme, onComplete }) => {
  const [progress, setProgress] = useState(0);
  const [isReady, setIsReady] = useState(false);
  const animationFrameId = useRef<number>(0);
  const startTime = useRef<number>(0);

  // SACRED ELEMENT - Breathing Orb Animation (DO NOT MODIFY STRUCTURE)
  const renderBreathingOrb = () => (
    <div className="breathing-orb-container mb-8">
      <div className="breathing-orb">
        <div className="orb-core"></div>
        <div className="orb-inner-glow"></div>
        <div className="fire-ring">
          <div className="fire-layer fire-orange"></div>
          <div className="fire-layer fire-gold"></div>
          <div className="fire-layer fire-blue"></div>
          <div className="fire-layer fire-white"></div>
        </div>
      </div>
    </div>
  );

  // Start background music and animation
  useEffect(() => {
    // Start background music (as in original)
    startAmbience('OM', 50);

    // Play subtle enter sound
    buttonSoundService.play('confirm');

    // Smooth animation using requestAnimationFrame (as in original)
    const animate = (timestamp: number) => {
      if (!startTime.current) startTime.current = timestamp;
      const elapsed = timestamp - startTime.current;
      const duration = 4000; // 4 seconds total

      const newProgress = Math.min((elapsed / duration) * 100, 100);
      setProgress(newProgress);

      if (elapsed < duration) {
        animationFrameId.current = requestAnimationFrame(animate);
      } else {
        setIsReady(true);
        // Auto-complete after showing ready state for a moment
        setTimeout(() => {
          onComplete();
        }, 800);
      }
    };

    animationFrameId.current = requestAnimationFrame(animate);

    return () => {
